// ==== Cleanup.gs
/**
 * Cleanup.gs v1
 * クラブサッカー大会運営システム｜不要なタブの整理
 *
 * システムが使っているタブ（下の SYS_KEEP_SHEETS）以外を「削除候補」として一覧表示し、
 * 確認のうえでまとめて削除する。
 *
 * 使い方（スプレッドシートのメニュー「大会運営」から）
 *  1. 「不要なタブを確認」… 削除候補と残すタブを表示するだけ（何も消さない）
 *  2. 「不要なタブを削除」… 確認ダイアログで「はい」を押すと削除候補をまとめて削除
 *
 * 誤って消した場合は「ファイル」→「変更履歴」→「変更履歴を表示」から削除前の版に戻せる。
 */

// システムが読み書きしているタブ。ここにあるものは絶対に削除しない。
var SYS_KEEP_SHEETS = [
  // マスター
  'システム設定', '入力候補マスター', '大会マスター', 'チームマスター', 'チームスタッフマスター', '選手マスター', '選手登録', '選手登録申請',
  '試合マスター', '日程変更履歴', '結果取込の確認', '選手名寄せの確認', '導入チェック', '選手名簿の照合', '一括登録の明細', 'スタメン提出', '審判連絡先', '審判員マスター', '全体テスト結果', 'テスト送信ログ', '連携リーグ', 'LINE送信待ち', 'ライブ記録', 'チーム通知先', 'Discord送信待ち', 'クラブの連絡先', '全体リンク台帳', 'チームページ台帳', 'リンク集', '処分通知の連絡先', '処分通知', '公式記録の下書き',
  // 公式記録・承認
  '公式記録データ', '公式記録承認', 'チーム記録', '選手試合記録', '得点記録', '得点経過', 'PK戦記録', '試合イベント',
  // 審判報告
  '審判報告書', '審判報告警告退場', '審判報告重要事項',
  // 処分
  '警告・退場記録', '処分管理', '処分対象試合', '処分通知', '問題事項報告', '問題事項の処分', '始末書の提出', '処分一覧（これまで）', '処分一覧（今シーズン）', 'MC報告書',
  // 集計・運営
  '順位表', '星取表', '得点ランキング', 'アシストランキング', 'トーナメント結果', '運営ダッシュボード',
  // 履歴
  '通知履歴', '操作履歴', '公式記録の下書き',
  // PDFテンプレート
  '公式記録PDFテンプレート_正方形', '審判報告書PDFテンプレート', '審判報告書重要事項テンプレート',
  'MC報告書テンプレート1', 'MC報告書テンプレート2', 'MC緊急報告書テンプレート'
];

/** 削除候補の理由（名前のパターン） */
function sysCleanupReason_(name) {
  if (/_旧_\d{8}_\d{4}$/.test(name)) return 'スクリプト導入時のバックアップ';
  if (/^PDF_.+_v\d+_\d+$/.test(name)) return '公式記録PDF作成時の作業用（残骸）';
  if (/^審判報告書_作業用_/.test(name)) return '審判報告書PDF作成時の作業用（残骸）';
  if (/のコピー$|^Copy of /.test(name)) return 'コピーされたタブ';
  return 'システムから参照されていない';
}

function sysCleanupPlan_() {
  var ss = typeof ss_ === 'function' ? ss_() : SpreadsheetApp.getActiveSpreadsheet();
  var keep = [], remove = [], skipped = [];
  ss.getSheets().forEach(function (sh) {
    var name = sh.getName();
    if (SYS_KEEP_SHEETS.indexOf(name) >= 0) { keep.push(name); return; }
    var formUrl = '';
    try { formUrl = sh.getFormUrl() || ''; } catch (e) {}
    if (formUrl) { skipped.push(name + '（Googleフォームの回答先のため残します）'); return; }
    remove.push({ sheet: sh, name: name, reason: sysCleanupReason_(name) });
  });
  var missing = SYS_KEEP_SHEETS.filter(function (n) { return !ss.getSheetByName(n); });
  return { ss: ss, keep: keep, remove: remove, skipped: skipped, missing: missing };
}

function sysCleanupText_(plan) {
  var lines = [];
  lines.push('■ 削除候補（' + plan.remove.length + '）');
  if (!plan.remove.length) lines.push('　なし');
  plan.remove.forEach(function (x) { lines.push('　・' + x.name + '　… ' + x.reason); });
  if (plan.skipped.length) {
    lines.push('', '■ 残すもの（フォームとつながっているタブ）');
    plan.skipped.forEach(function (n) { lines.push('　・' + n); });
  }
  lines.push('', '■ システムが使うタブ（' + plan.keep.length + '）は残します');
  if (plan.missing.length) {
    lines.push('', '（参考）まだ存在しないタブ：' + plan.missing.join('、'), '　※必要になった時点で自動で作成されます');
  }
  return lines.join('\n');
}

/** メニュー：削除候補を表示するだけ */
function previewUnusedSheets() {
  var plan = sysCleanupPlan_();
  SpreadsheetApp.getUi().alert('不要なタブの確認', sysCleanupText_(plan), SpreadsheetApp.getUi().ButtonSet.OK);
}

/** メニュー：確認のうえ削除 */
function deleteUnusedSheets() {
  var ui = SpreadsheetApp.getUi();
  var plan = sysCleanupPlan_();
  if (!plan.remove.length) {
    ui.alert('不要なタブはありません', sysCleanupText_(plan), ui.ButtonSet.OK);
    return;
  }
  var ans = ui.alert(
    '次のタブを削除します。よろしいですか？',
    sysCleanupText_(plan) + '\n\n誤って消した場合は「ファイル」→「変更履歴」から戻せます。',
    ui.ButtonSet.YES_NO
  );
  if (ans !== ui.Button.YES) return;

  var done = [], failed = [];
  plan.remove.forEach(function (x) {
    try {
      if (plan.ss.getSheets().length <= 1) throw new Error('最後の1枚は削除できません');
      plan.ss.deleteSheet(x.sheet);
      done.push(x.name);
    } catch (e) {
      failed.push(x.name + '（' + (e && e.message || e) + '）');
    }
  });
  try {
    if (typeof log_ === 'function') log_('不要タブ削除', 'シート', '', null, { deleted: done }, failed.join(' / '));
  } catch (e) {}
  ui.alert('削除しました',
    '削除：' + done.length + '件' + (failed.length ? '\n削除できなかったもの：\n・' + failed.join('\n・') : ''),
    ui.ButtonSet.OK);
}

;
// ==== Clubs.gs
/**
 * Clubs.gs v1
 * 社会人リーグ版：クラブの一覧と、大会にクラブを入れる（チームマスターの行を作る）
 *
 *  ・CLUBS：クラブコード・正式名・略称（2026年度の公式記録から。略称は仮。連盟への届け出に合わせて直す）
 *    クラブコードは、どの大会でも同じ（ホームページでクラブのページを1つにまとめるため）
 *  ・チームIDは「クラブコード-大会の末尾」（例：ASC-TOP、SABAS-SD）
 *  ・監督名・連絡先は入れない。各クラブがチームのページから登録する
 *  ・新しいクラブ（地区リーグからの昇格など）は、正式名を入れれば CLUBS になくても作れる（コードは自動）
 */
var CLUBS = [
  ['ASC', 'ASC北海道', 'ASC北海道'],
  ['NORBRITZ', 'ノルブリッツ北海道FC', 'ノルブリッツ'],
  ['SKYEARTH', '北海道十勝スカイアース', '十勝スカイアース'],
  ['BTOP', 'BTOP北海道', 'BTOP北海道'],
  ['SATSUDAI-GP', '札大GP', '札大GP'],
  ['SAPPORO-SHUKYU', '札幌蹴球団', '札幌蹴球団'],
  ['HOKUSHUKAI', '北蹴会岩見沢', '北蹴会岩見沢'],
  ['SABAS', 'sabas', 'sabas'],
  ['FORTUNA', '北海道フォルトゥナフットボールクラブ', '北海道フォルトゥナ'],
  ['VANKEI', 'アンフィニVANKEI.FC', 'アンフィニVANKEI'],
  ['SOCC10TH', 'SOCC.10th', 'SOCC.10th'],
  ['CANALE', 'CANALE小樽', 'CANALE小樽'],
  ['YUTO', 'YUTO.SC', 'YUTO.SC'],
  ['AMIGO', 'アミーゴ千歳', 'アミーゴ千歳'],
  ['OTARU-YF', '小樽YF', '小樽YF'],
  ['TOYOTA', 'トヨタ自動車北海道サッカー部', 'トヨタ北海道'],
  ['VAIN', 'VAIN FC 伊達', 'VAIN FC伊達'],
  ['NACHARO', 'FC函館ナチャーロ', 'FC函館ナチャーロ'],
  ['TOMAKOMAI-CITY', '苫小牧市役所', '苫小牧市役所'],
  ['ROF', 'R・O・F', 'R・O・F'],
  ['FCPOOL', 'FCPOOL', 'FC POOL'],
  ['SHINTOKU', '新得フットボールクラブ', '新得FC'],
  ['KEMARI', '蹴鞠会', '蹴鞠会'],
  ['OBIHIRO-SHUKYU', '帯広蹴球団', '帯広蹴球団'],
  ['ABASHIRI', 'FC網走', 'FC網走'],
  ['COPAN', 'FCコパン', 'FCコパン'],
  ['KAMUI', 'KAMUI FC HIGASHIKAWA', 'KAMUI FC'],
  ['KYOKUSHUKAI', '旭蹴会', '旭蹴会'],
  ['HOKUDAI-CLUB', '札幌北大クラブ', '札幌北大クラブ'],
  ['REUSSIR', 'réussir', 'réussir'],
  ['TOKAI-SAPPORO', '東海大学札幌校舎サッカー部', '東海大札幌'],
  ['SAPPORO-UNIV', '札幌大学サッカー部', '札幌大学']
];

function clubFind_(s) {
  s = String(s || '').trim();
  if (!s) return null;
  var norm = function (x) { return String(x || '').replace(/[\s　]/g, '').normalize('NFKC').toLowerCase(); };
  var n = norm(s);
  for (var i = 0; i < CLUBS.length; i++) {
    var c = CLUBS[i];
    if (norm(c[0]) === n || norm(c[1]) === n || norm(c[2]) === n) return { code: c[0], name: c[1], short: c[2] };
  }
  // 一覧にないクラブでも、もうチームマスターにいれば同じクラブとして扱う（コードをそろえる）
  try {
    var hit = null;
    objs_('チームマスター').some(function (t) {
      var code = rgTeamCode_(t['チームID']);
      if (norm(code) === n || norm(t['クラブ名']) === n || norm(t['略称']) === n) { hit = { code: code, name: String(t['クラブ名'] || t['チーム名'] || s), short: String(t['略称'] || t['クラブ名'] || s) }; return true; }
      return false;
    });
    if (hit) return hit;
  } catch (e) {}
  return null;
}

/** 新しいクラブのコード：英数字の名前はそのまま、日本語の名前は名前から作る（ほかのクラブと重ならない） */
function clubNewCode_(name) {
  var used = {};
  CLUBS.forEach(function (c) { used[c[0]] = 1; });
  try { objs_('チームマスター').forEach(function (t) { used[rgTeamCode_(t['チームID'])] = 1; }); } catch (e) {}
  var ascii = String(name).normalize('NFKC');
  var code = /^[\x20-\x7E]+$/.test(ascii) ? ascii.toUpperCase().replace(/[^A-Z0-9]+/g, '-').replace(/^-|-$/g, '') : '';
  if (!code || code.length < 3 || /^(FC|SC|CLUB|FOOTBALL-CLUB|SOCCER-CLUB)$/.test(code)) {
    var h = Utilities.computeDigest(Utilities.DigestAlgorithm.MD5, String(name), Utilities.Charset.UTF_8)
      .map(function (b) { return ('0' + (b & 255).toString(16)).slice(-2); }).join('').slice(0, 6).toUpperCase();
    code = 'CLUB' + h;
  }
  var base = code, i = 2;
  while (used[code]) code = base + '-' + (i++);
  return code;
}

/** メニューから：大会IDと、クラブ名（1行に1つ、または「、」で区切る）を聞いて、チームマスターに入れる */
function addClubsToCompetition() {
  var ui = SpreadsheetApp.getUi();
  var r1 = ui.prompt('大会にクラブを入れる（1/2）', '大会IDを入れてください（例：2027-TOP）', ui.ButtonSet.OK_CANCEL);
  if (r1.getSelectedButton() !== ui.Button.OK) return;
  var comp = String(r1.getResponseText() || '').trim();
  var r2 = ui.prompt('大会にクラブを入れる（2/2）',
    'クラブ名を「、」で区切るか、1行に1つずつ貼り付けてください（正式名・略称・クラブコードのどれでも）。\n' +
    '一覧にない新しいクラブは、正式名で入れれば新しく作ります。', ui.ButtonSet.OK_CANCEL);
  if (r2.getSelectedButton() !== ui.Button.OK) return;
  var names = String(r2.getResponseText() || '').split(/[\n、,，]+/).map(function (x) { return x.trim(); }).filter(String);
  var msg = addClubsToCompetition_(comp, names);
  ui.alert('大会にクラブを入れる', msg, ui.ButtonSet.OK);
}

function addClubsToCompetition_(comp, names) {
  if (!/^\d{4}-[A-Z]+$/.test(comp)) throw new Error('大会IDの形が違います（例：2027-TOP）');
  if (!objs_('大会マスター').some(function (c) { return String(c['大会ID']) === comp; })) throw new Error('大会マスターに「' + comp + '」がありません。先に大会を入れてください');
  var suffix = comp.split('-').pop();
  var lock = LockService.getScriptLock();
  lock.waitLock(30000);
  try {
    ensureHeader_('チームマスター', ['チームID', '大会ID', 'クラブ名', 'チーム名', '略称']);
    var have = {};
    objs_('チームマスター').forEach(function (t) { have[String(t['チームID'])] = true; });
    var added = [], skipped = [], made = [];
    names.forEach(function (s) {
      var c = clubFind_(s);
      if (!c) {
        var code = clubNewCode_(s);
        c = { code: code, name: s, short: s.length <= 10 ? s : s.slice(0, 10) };
        made.push(s + '（コード ' + code + '）');
      }
      var id = c.code + '-' + suffix;
      if (have[id]) { skipped.push(c.name); return; }
      append_('チームマスター', { 'チームID': id, '大会ID': comp, 'クラブ名': c.name, 'チーム名': c.name, '略称': c.short });
      have[id] = true;
      added.push(c.short);
    });
    if (typeof SHEET_CACHE_ !== 'undefined') SHEET_CACHE_ = {};
    if (typeof READ_MEMO_ !== 'undefined') READ_MEMO_ = null;
    return comp + ' に入れたクラブ：' + (added.length ? added.length + '（' + added.join('、') + '）' : 'なし') +
      (skipped.length ? '\nもう入っていたクラブ：' + skipped.join('、') : '') +
      (made.length ? '\n一覧になかったので新しく作ったクラブ：' + made.join('、') + '\n（略称は10文字までに切ってあります。チームマスターで直してください）' : '') +
      '\n\n続けて「リンク集を作成」をすると、各クラブの専用リンクができます。';
  } finally { lock.releaseLock(); }
}

