function setList_(form,title,values){
  const x=form
    .getItems(FormApp.ItemType.LIST)
    .map(i=>i.asListItem())
    .find(i=>i.getTitle()===title);

  if(x&&values.length){
    x.setChoiceValues(values);
  }
}


