// =====================================================
// 試合 / チーム / 選手
// =====================================================

function findMatch_(id){
  const r=objs_(シート.試合)
    .find(x=>String(x['試合ID'])===String(id));

  if(!r) throw new Error('試合なし:'+id);

  return r;
}


function findTeam_(id){
  const r=objs_(シート.チーム)
    .find(x=>String(x['チームID'])===String(id));

  if(!r) throw new Error('チームなし:'+id);

  return r;
}


function eligible_(tid,date){
  const ps=Object.fromEntries(
    objs_(シート.選手)
      .map(p=>[
        String(p['選手ID']),
        p
      ])
  );

  // 上位大会でエントリーを出したチームは、エントリーした選手だけ（Entry.gs）
  const ent=typeof entPlayerSet_==='function' ? entPlayerSet_(tid) : null;
  return objs_(シート.選手登録)
    .filter(r=>
      String(r['チームID'])===String(tid) &&
      String(r['登録状態'])==='有効' &&
      (
        !r['登録開始日'] ||
        ymd_(r['登録開始日'])<=String(date)
      ) &&
      (
        !r['登録終了日'] ||
        ymd_(r['登録終了日'])>=String(date)
      ) &&
      (!ent || ent[String(r['選手ID'])])
    )
    .map(r=>({
      playerId:String(r['選手ID']),
      name:String(
        (
          ps[String(r['選手ID'])]||{}
        )['氏名']||r['選手ID']
      ),
      number:r['背番号']||'',
      grade:r['生年月日']||''
    }));
}


function matchDateYmd_(m){
  const actual=m['実施日'];

  if(
    Object.prototype.toString.call(actual)==='[object Date]' &&
    !isNaN(actual)
  ){
    return Utilities.formatDate(
      actual,
      Session.getScriptTimeZone()||'Asia/Tokyo',
      'yyyy-MM-dd'
    );
  }

  const actualText=String(actual||'').trim();

  if(/^\d{4}-\d{2}-\d{2}/.test(actualText)){
    return actualText.slice(0,10);
  }

  const planned=m['開催予定日'];

  if(
    Object.prototype.toString.call(planned)==='[object Date]' &&
    !isNaN(planned)
  ){
    return Utilities.formatDate(
      planned,
      Session.getScriptTimeZone()||'Asia/Tokyo',
      'yyyy-MM-dd'
    );
  }

  const plannedText=String(planned||'').trim();

  if(/^\d{4}-\d{2}-\d{2}/.test(plannedText)){
    return plannedText.slice(0,10);
  }

  return ymd_(planned||actual||'');
}


/** 高速化：読むだけの処理は同じシートを1回だけ読む */
function getMatchList() {
  return withReadMemo_(function () { return getMatchListRead_(); });
}

function getMatchListRead_() {
  const tm=Object.fromEntries(
    objs_(シート.チーム)
      .map(t=>[
        String(t['チームID']),
        t['チーム名']||
        t['クラブ名']||
        t['チームID']
      ])
  );

  const cm=Object.fromEntries(
    objs_(シート.大会)
      .map(c=>[
        String(c['大会ID']),
        c['大会名']||
        c['大会ID']
      ])
  );

  return objs_(シート.試合)
    .filter(m=>
      String(m['試合状態']||'')!=='中止' &&
      String(m['ホームチームID']||'') &&
      String(m['アウェイチームID']||'')
    )
    .map(m=>({
      matchId:String(m['試合ID']),
      competitionId:String(m['大会ID']||''),
      competitionName:
        cm[String(m['大会ID'])]||
        String(m['大会ID']||''),
      round:String(m['節／ラウンド']||''),
      date:matchDateYmd_(m),
      homeId:String(m['ホームチームID']||''),
      awayId:String(m['アウェイチームID']||''),
      home:tm[String(m['ホームチームID'])]||'',
      away:tm[String(m['アウェイチームID'])]||'',
      status:String(m['試合状態']||'')
    }));
}


/** 高速化：読むだけの処理は同じシートを1回だけ読む */
function getMatchDetail(id) {
  return withReadMemo_(function () { return getMatchDetailRead_(id); });
}

function getMatchDetailRead_(id) {
  const m=findMatch_(id);
  const h=findTeam_(m['ホームチームID']);
  const a=findTeam_(m['アウェイチームID']);

  const d=matchDateYmd_(m);
  // 公式記録の承認者（スタメン提出で選んだ人）
  const hAp=typeof lnApproverFor_==='function'?lnApproverFor_(id,m['ホームチームID']):null;
  const aAp=typeof lnApproverFor_==='function'?lnApproverFor_(id,m['アウェイチームID']):null;

  return{
    match:{
      matchId:String(m['試合ID']),
      competitionId:String(m['大会ID']||''),
      round:String(m['節／ラウンド']||''),
      date:d,
      homeId:String(m['ホームチームID']),
      awayId:String(m['アウェイチームID']),
      home:String(h['チーム名']||h['クラブ名']),
      away:String(a['チーム名']||a['クラブ名']),
      homeShort:String(h['略称']||h['チーム名']||h['クラブ名']),
      awayShort:String(a['略称']||a['チーム名']||a['クラブ名']),
      homeCoach:String((hAp&&hAp.name)||h['監督名']||''),
      homeCoachEmail:String((hAp&&hAp.email)||h['監督メール']||''),
      awayCoach:String((aAp&&aAp.name)||a['監督名']||''),
      awayCoachEmail:String((aAp&&aAp.email)||a['監督メール']||''),
      venue:String(m['会場']||''),
      kickoff:kickoffText_(m['キックオフ'])
    },
    homePlayers:eligible_(m['ホームチームID'],d),
    awayPlayers:eligible_(m['アウェイチームID'],d),
    suspended:suspendedPlayersView_(id),
    record:typeof revRecordView_==='function'?revRecordView_(id):null,
    lineup:typeof lnForRecord_==='function'?lnForRecord_(id):null,
    live:typeof liveEventsForRecord_==='function'?liveEventsForRecord_(id):null,
    draft:typeof revDraftView_==='function'?revDraftView_(id):null
  };
}


/** v18：修正・訂正（Revision.gs）への対応済みの目印（SystemCheck.gs が確認） */
function codeHasRevisionHooks_(){ return true; }


/** 試合マスターのキックオフ（文字列・時刻どちらでも）を HH:mm にする */
function kickoffText_(v){
  if(v===''||v===null||v===undefined) return '';
  if(Object.prototype.toString.call(v)==='[object Date]' && !isNaN(v)){
    return Utilities.formatDate(v,Session.getScriptTimeZone()||'Asia/Tokyo','HH:mm');
  }
  const m=String(v).replace(/：/g,':').match(/(\d{1,2}):(\d{2})/);
  return m ? ('0'+m[1]).slice(-2)+':'+m[2] : '';
}


// =====================================================
// 出場停止チェック（v16）
// =====================================================

/** 画面表示用：この試合で出場停止の選手 */
function suspendedPlayersView_(matchId){
  if(typeof getSuspensionsForMatch_!=='function') return [];

  const names=Object.fromEntries(
    objs_(シート.選手).map(p=>[String(p['選手ID']),String(p['氏名']||'')])
  );

  return getSuspensionsForMatch_(matchId).map(x=>({
    playerId:x.playerId,
    name:names[x.playerId]||x.playerId,
    type:x.type,
    order:x.order,
    total:x.total,
    originMatchId:x.originMatchId,
    carried:x.carried,
    label:
      (x.type==='警告累積'?'累積警告':x.type==='一発退場'?'退場':'警告2枚退場')+
      '（'+x.originMatchId+'）'+
      (x.total>1?' '+x.order+'/'+x.total+'試合目':'')+
      (x.carried?'・他大会から持越':'')
  }));
}


/** 提出時チェック：出場停止の選手が先発・ベンチに入っていれば提出を止める */
function assertNoSuspendedPlayers_(matchId,players){
  const list=suspendedPlayersView_(matchId);
  if(!list.length) return;

  const byId=Object.fromEntries(list.map(x=>[x.playerId,x]));

  const hit=(players||[])
    .filter(x=>x&&byId[String(x.playerId||'')])
    .map(x=>byId[String(x.playerId)]);

  if(hit.length){
    throw new Error(
      '出場停止中の選手がメンバーに含まれています。先発・ベンチから外してください。\n'+
      hit.map(x=>'・'+x.name+'：'+x.label).join('\n')+
      '\n（出場停止の選手が出場すると没収試合になります）'
    );
  }
}


// =====================================================
// 旧 submitOfficialRecord
// =====================================================

function submitOfficialRecord(p){
  if(!p||!p.matchId){
    throw new Error('試合IDなし');
  }

  const m=findMatch_(p.matchId);

  const prev=objs_(シート.公式記録)
    .filter(r=>
      String(r['試合ID'])===String(p.matchId)
    );

  const ver=prev.reduce(
    (x,r)=>Math.max(x,Number(r['版'])||0),
    0
  )+1;

  const rid=id_('OR');

  delWhere_(
    シート.チーム記録,
    r=>String(r['試合ID'])===String(p.matchId)
  );

  delWhere_(
    シート.選手試合記録,
    r=>String(r['試合ID'])===String(p.matchId)
  );

  const og=objs_(シート.得点)
    .filter(r=>
      String(r['試合ID'])===String(p.matchId)
    )
    .map(r=>String(r['得点ID']));

  if(og.length){
    delWhere_(
      シート.得点経過,
      r=>og.includes(String(r['得点ID']))
    );
  }

  delWhere_(
    シート.得点,
    r=>String(r['試合ID'])===String(p.matchId)
  );

  delWhere_(
    シート.PK戦,
    r=>String(r['試合ID'])===String(p.matchId)
  );

  delWhere_(
    シート.試合イベント,
    r=>
      String(r['試合ID'])===String(p.matchId) &&
      String(r['イベント種別'])==='交代'
  );

  delWhere_(
    シート.警告退場,
    r=>
      String(r['試合ID'])===String(p.matchId) &&
      String(r['情報源']||'')==='公式記録'
  );

  append_(シート.公式記録,{
    '公式記録ID':rid,
    '試合ID':p.matchId,
    '版':ver,
    '前半キックオフ':p.firstKickoff||'',
    '前半ホーム得点':num_(p.score.firstHome),
    '前半アウェイ得点':num_(p.score.firstAway),
    '後半ホーム得点':num_(p.score.secondHome),
    '後半アウェイ得点':num_(p.score.secondAway),
    '延長ホーム得点':numBlank_(p.score.extraHome),
    '延長アウェイ得点':numBlank_(p.score.extraAway),
    'PK戦ホーム':numBlank_(p.pk.home),
    'PK戦アウェイ':numBlank_(p.pk.away),
    'PK戦先攻チームID':
      p.pk&&p.pk.firstTeamId
        ? p.pk.firstTeamId
        : '',
    '記録状態':'承認待ち',
    '提出日時':now_(),
    '日時':
      p.matchInfo.dateTime||
      m['実施日']||
      m['開催予定日']||
      '',
    '会場名':p.matchInfo.venue||'',
    '試合時間':p.matchInfo.duration||'90分',
    'ピッチ':p.matchInfo.pitch||'',
    'ピッチ状態':p.matchInfo.pitchCondition||'',
    'WBGT':p.matchInfo.wbgt||'',
    '天候':p.matchInfo.weather||'',
    '風':p.matchInfo.wind||'',
    '記録担当者':p.matchInfo.recorder||'',
    '記録担当クラブ':p.matchInfo.recorderUniversity||'',
    '主審':p.officials.referee||'',
    '副審1':p.officials.ar1||'',
    '副審2':p.officials.ar2||'',
    '第4の審判':p.officials.fourth||'',
    '後半キックオフ':p.secondKickoff||'',
    '主審メール':p.officials.refereeEmail||'',
    '確定PDF URL':''
  });

  saveTeam_(
    p.matchId,
    m['ホームチームID'],
    p.teamStats.home
  );

  saveTeam_(
    p.matchId,
    m['アウェイチームID'],
    p.teamStats.away
  );

  (p.players||[]).forEach(x=>
    append_(シート.選手試合記録,{
      '試合ID':p.matchId,
      '選手ID':x.playerId||'',
      'チームID':x.teamId||'',
      '先発':x.starter?'○':'',
      '出場':x.played?'○':'',
      'シュート計':
        num_(x.shots1)+num_(x.shots2),
      '得点':num_(x.goals),
      'アシスト':num_(x.assists),
      '背番号':x.number||'',
      '位置':x.position||'',
      '前半シュート':num_(x.shots1),
      '後半シュート':num_(x.shots2),
      '交代IN時間':x.inTime||'',
      '交代OUT時間':x.outTime||''
    })
  );

  (p.goals||[]).forEach(g=>{
    const gid=id_('G');

    append_(シート.得点,{
      '得点ID':gid,
      '試合ID':p.matchId,
      '時間':g.time||'',
      'チームID':g.teamId||'',
      '得点者選手ID':g.scorerId||'',
      'アシスト選手ID':g.assistId||'',
      '得点種別':g.goalType||'',
      '開始状況':g.startType||'',
      '得点前ホーム':num_(g.beforeHome),
      '得点前アウェイ':num_(g.beforeAway),
      '得点後ホーム':num_(g.afterHome),
      '得点後アウェイ':num_(g.afterAway)
    });

    String(g.sequence||'')
      .split(/\s*→\s*|\s*\|\s*/)
      .filter(Boolean)
      .forEach((z,i)=>
        append_(シート.得点経過,{
          '得点ID':gid,
          '順番':i+1,
          '経過内容':z
        })
      );
  });

  (p.substitutions||[]).forEach(s=>
    append_(シート.試合イベント,{
      'イベントID':id_('EV'),
      '試合ID':p.matchId,
      '時間':s.time||'',
      'チームID':s.teamId||'',
      'イベント種別':'交代',
      '選手ID':'',
      '交代OUT選手ID':s.outId||'',
      '交代IN選手ID':s.inId||'',
      '詳細':'',
      '登録日時':now_()
    })
  );

  (p.disciplinary||[]).forEach(d=>
    append_(シート.警告退場,{
      '事象ID':id_('DISC'),
      '試合ID':p.matchId,
      '大会ID':m['大会ID'],
      '選手ID':d.playerId||'',
      'チームID':d.teamId||'',
      '時間':d.time||'',
      '時間帯':d.period||'',
      '種別':d.type||'',
      '理由':d.reason||'',
      '確認状態':
        d.type==='一発退場'
          ?'要審査'
          :'確認待ち',
      '情報源':'公式記録'
    })
  );

  createApprovals_(
    rid,
    p.matchId,
    ver,
    p
  );

  return{
    ok:true,
    recordId:rid,
    version:ver,
    message:'公式記録を提出し、承認依頼を作成しました。'
  };
}


function saveTeam_(mid,tid,s){
  s=s||{};

  const cols=[
    ['シュート','shots'],
    ['GK','gk'],
    ['CK','ck'],
    ['直接FK','dfk'],
    ['間接FK','ifk'],
    ['オフサイド','off'],
    ['PK','pk']
  ];

  // 延長前半・延長後半の列（なければ自動追加）
  ensureHeader_(
    シート.チーム記録,
    cols.reduce((a,c)=>a.concat([c[0]+'延長前半',c[0]+'延長後半']),[])
  );

  const row={
    '試合ID':mid,
    'チームID':tid,
    '備考':s.note||''
  };

  cols.forEach(c=>{
    const j=c[0],k=c[1];
    const v1=num_(s[k+'1']);
    const v2=num_(s[k+'2']);
    const v3=num_(s[k+'3']);
    const v4=num_(s[k+'4']);

    row[j+'前半']=v1;
    row[j+'後半']=v2;
    row[j+'延長前半']=v3;
    row[j+'延長後半']=v4;
    row[j+'計']=v1+v2+v3+v4;
  });

  append_(シート.チーム記録,row);
}


// =====================================================
// 承認
// =====================================================

function createApprovals_(rid,mid,ver,p){
  objs_(シート.承認)
    .filter(r=>
      String(r['試合ID'])===String(mid) &&
      String(r['承認状態'])==='未承認'
    )
    .forEach(r=>
      update_(シート.承認,r._row,{
        '承認状態':'旧版無効'
      })
    );

  const m=findMatch_(mid);
  const h=findTeam_(m['ホームチームID']);
  const a=findTeam_(m['アウェイチームID']);

  // チームの承認者：スタメン提出で選んだ人（LineupFlow.gs）。なければチームマスターの監督
  const hAp=typeof lnApproverFor_==='function'?lnApproverFor_(mid,m['ホームチームID']):null;
  const aAp=typeof lnApproverFor_==='function'?lnApproverFor_(mid,m['アウェイチームID']):null;
  const people=[
    {
      role:'HOME監督',
      name:hAp?hAp.name:(h['監督名']||''),
      email:hAp?hAp.email:(h['監督メール']||''),
      chosen:!!hAp
    },
    {
      role:'AWAY監督',
      name:aAp?aAp.name:(a['監督名']||''),
      email:aAp?aAp.email:(a['監督メール']||''),
      chosen:!!aAp
    },
    {
      role:'主審',
      name:p.officials.referee||'',
      email:p.officials.refereeEmail||''
    }
  ];

  const exp=new Date();
  exp.setDate(exp.getDate()+7);

  people.forEach(x=>{
    const tok=Utilities.getUuid();

    append_(シート.承認,{
      '承認ID':id_('AP'),
      '試合ID':mid,
      '版':ver,
      '承認者区分':x.role,
      '承認者名':x.name,
      '承認状態':'未承認',
      '承認日時':'',
      'コメント':'',
      '承認者メール':x.email,
      '承認トークン':tok,
      'トークン期限':
        Utilities.formatDate(
          exp,
          Session.getScriptTimeZone(),
          'yyyy-MM-dd HH:mm:ss'
        ),
      '対象公式記録ID':rid
    });

    if(x.email){
      const base=webAppBaseUrl_();

      if(base){
        const approveUrl=
          base+
          '?page=approve&token='+
          encodeURIComponent(tok);

        const matchLine=
          htmlEsc_(
            [
              m['節／ラウンド']||'',
              (h['チーム名']||h['クラブ名']||'')+' vs '+(a['チーム名']||a['クラブ名']||''),
              matchDateYmd_(m)
            ].filter(Boolean).join('｜')
          );

        let body=
          '<p>'+htmlEsc_(x.name)+' 様</p>'+
          (typeof revApprovalNoteHtml_==='function'?revApprovalNoteHtml_(p):'')+
          (x.chosen?'<p>'+htmlEsc_(x.role==='HOME監督'?(h['チーム名']||h['クラブ名']||''):(a['チーム名']||a['クラブ名']||''))+' の公式記録の承認者として、スタメン提出で指定されました。</p>':'')+
          '<p>公式記録をご確認ください。</p>'+
          '<p>試合：'+matchLine+'</p>'+
          '<p><a href="'+approveUrl+'">承認画面を開く</a></p>';

        // 主審には審判報告書の入力ページも案内する
        if(x.role==='主審'){
          const refUrl=refereeReportUrlForMatch_(base,mid);

          body+=
            '<hr>'+
            '<p><b>審判報告書のご提出</b><br>'+
            '試合終了後、下記のページから審判報告書を入力・提出してください。<br>'+
            '（この試合が選択された状態で開きます）</p>'+
            '<p><a href="'+refUrl+'">審判報告書の入力ページを開く</a></p>'+
            '<p style="color:#64748b;font-size:12px">リンクが開けない場合は、次のURLをブラウザに貼り付けてください。<br>'+
            htmlEsc_(refUrl)+
            '</p>';
        }

        mail_(
          '公式記録承認依頼',
          x.email,
          (p&&p._correction?'【訂正版 承認依頼】':'【要対応】公式記録の承認依頼　')+(m['節／ラウンド']||'')+' '+(h['略称']||h['チーム名']||h['クラブ名']||'')+' vs '+(a['略称']||a['チーム名']||a['クラブ名']||'')+'（'+mid+'・版'+ver+'）',
          body,
          mid,
          '',
          'NONE' // 承認依頼は、スタメン提出で選んだ承認者だけ（チームのDiscordには投稿しない）
        );
      }
    }
  });
}


/** 高速化：読むだけの処理は同じシートを1回だけ読む */
function getApprovalContext(tok) {
  return withReadMemo_(function () { return apExtras_(tok, getApprovalContextRead_(tok)); });
}

/**
 * 承認ページに付ける情報（v4）
 *  ・lineup：スタメン提出と公式記録のメンバーの違い（チームごと。選手IDごとの印も）
 *  ・changes：前の版から変わったところ（版2以降）。revisionAsk：前の版で依頼された修正
 */
function apExtras_(tok, data) {
  if (!data || !data.ok) return data;
  try {
    var a = objs_(シート.承認).filter(function (r) { return String(r['承認トークン']) === String(tok); })[0];
    if (!a) return data;
    var m = findMatch_(a['試合ID']);
    data.lineup = {};
    if (typeof lnLatest_ === 'function') {
      var rows = lnRows_();
      [['home', String(m['ホームチームID'])], ['away', String(m['アウェイチームID'])]].forEach(function (x) {
        data.lineup[x[0]] = apLineupDiff_(lnLatest_(rows, a['試合ID'], x[1]), (data.report[x[0]] || {}).players || []);
      });
    }
    var v = num_(a['版']);
    if (v > 1 && typeof revHistory_ === 'function') {
      var hist = revHistory_(a['試合ID']);
      var cur = hist.filter(function (h) { return String(h.recordId) === String(a['対象公式記録ID']); })[0];
      data.changes = cur && cur.changes ? cur.changes.filter(function (c) { return c.items && c.items.length; }) : null;
      var prev = hist.filter(function (h) { return h.version < v; })[0];
      data.revisionAsk = prev ? prev.approvals.filter(function (x) { return x.status === '修正依頼' && x.comment; })
        .map(function (x) { return { role: x.role, name: x.name, comment: x.comment }; }) : [];
      if (cur && cur.reason) data.revisionReason = cur.reason;
    }
  } catch (e) { data.extraError = String(e && e.message || e); }
  return data;
}

function apLineupDiff_(row, players) {
  var c = row && typeof lnContent_ === 'function' ? lnContent_(row) : null;
  if (!c) return { submitted: false, items: [], flag: {} };
  var lab = function (no, name) { return (no ? 'No.' + no + ' ' : '') + (name || ''); };
  var sub = {}, rec = {}, items = [], flag = {};
  (c.starters || []).forEach(function (p) { sub[String(p.pid)] = { st: true, no: String(p.no || ''), name: p.name }; });
  (c.bench || []).forEach(function (p) { sub[String(p.pid)] = { st: false, no: String(p.no || ''), name: p.name }; });
  players.forEach(function (p) { rec[String(p.playerId)] = p; });
  var put = function (pid, msg) { items.push(msg); flag[pid] = (flag[pid] ? flag[pid] + '／' : '') + msg.replace(/^[^：]*：/, ''); };
  players.forEach(function (p) {
    var pid = String(p.playerId), s = sub[pid], L = lab(p.number, p.name);
    if (!s) put(pid, L + '：スタメン提出にいない選手です');
    else {
      if (p.starter && !s.st) put(pid, L + '：スタメン提出では控えです');
      if (!p.starter && s.st) put(pid, L + '：スタメン提出では先発です');
      if (s.no && String(p.number) !== s.no) put(pid, L + '：スタメン提出の背番号は ' + s.no + ' です');
    }
  });
  Object.keys(sub).forEach(function (pid) {
    if (!rec[pid]) items.push(lab(sub[pid].no, sub[pid].name) + '：スタメン提出にいるのに、公式記録のメンバーにいません');
  });
  return { submitted: true, version: num_(row['版']), status: String(row['状態'] || ''), items: items, flag: flag };
}

function getApprovalContextRead_(tok) {
  const a=objs_(シート.承認)
    .find(r=>
      String(r['承認トークン'])===String(tok)
    );

  if(!a){
    return{
      ok:false,
      message:'承認リンクが無効です。'
    };
  }

  if(String(a['承認状態'])!=='未承認'){
    return{
      ok:false,
      message:'この承認は既に処理済みです。'
    };
  }

  const rec=objs_(シート.公式記録)
    .find(r=>
      String(r['公式記録ID'])===
      String(a['対象公式記録ID'])
    );

  if(!rec){
    return{
      ok:false,
      message:'公式記録がありません。'
    };
  }

  const match=findMatch_(a['試合ID']);
  const home=findTeam_(match['ホームチームID']);
  const away=findTeam_(match['アウェイチームID']);

  const competition=
    objs_(シート.大会).find(r=>
      String(r['大会ID'])===
      String(match['大会ID'])
    )||{};

  const homeId=String(match['ホームチームID']||'');
  const awayId=String(match['アウェイチームID']||'');

  const extraTimeEnabled=
    rec['延長戦有無']!=='' &&
    rec['延長戦有無']!==null &&
    rec['延長戦有無']!==undefined
      ?String(rec['延長戦有無'])
      :(
        rec['延長ホーム得点']!=='' ||
        rec['延長アウェイ得点']!==''
          ?'あり'
          :'なし'
      );

  const pkEnabled=
    rec['PK戦有無']!=='' &&
    rec['PK戦有無']!==null &&
    rec['PK戦有無']!==undefined
      ?String(rec['PK戦有無'])
      :(
        rec['PK戦ホーム']!=='' &&
        rec['PK戦ホーム']!==null &&
        rec['PK戦ホーム']!==undefined
          ?'あり'
          :'なし'
      );

  const homeName=String(
    home['チーム名']||
    home['クラブ名']||
    homeId
  );

  const awayName=String(
    away['チーム名']||
    away['クラブ名']||
    awayId
  );

  const playersMaster=
    Object.fromEntries(
      objs_(シート.選手).map(p=>[
        String(p['選手ID']),
        p
      ])
    );

  const matchPlayers=
    objs_(シート.選手試合記録)
      .filter(r=>
        String(r['試合ID'])===
        String(a['試合ID'])
      );

  const approvalSubs=
    objs_(シート.試合イベント)
      .filter(r=>
        String(r['試合ID'])===
          String(a['試合ID']) &&
        String(r['イベント種別'])===
          '交代'
      );

  const approvalIncomingFromNumber={};

  approvalSubs.forEach(e=>{
    const outId=
      String(
        e['交代OUT選手ID']||''
      );

    const inId=
      String(
        e['交代IN選手ID']||''
      );

    if(!inId){
      return;
    }

    const outRow=
      matchPlayers.find(r=>
        String(r['選手ID'])===outId &&
        String(r['チームID'])===
          String(e['チームID']||'')
      ) ||
      matchPlayers.find(r=>
        String(r['選手ID'])===outId
      );

    approvalIncomingFromNumber[inId]=
      outRow
        ?String(outRow['背番号']||'')
        :'';
  });

  const homePlayers=
    sortPlayersForPdf_(
      matchPlayers.filter(r=>
        String(r['チームID'])===homeId
      )
    )
    .map(r=>approvalPlayerView_(r,playersMaster,approvalIncomingFromNumber));

  const awayPlayers=
    sortPlayersForPdf_(
      matchPlayers.filter(r=>
        String(r['チームID'])===awayId
      )
    )
    .map(r=>approvalPlayerView_(r,playersMaster,approvalIncomingFromNumber));

  const teamRows=
    objs_(シート.チーム記録)
      .filter(r=>
        String(r['試合ID'])===
        String(a['試合ID'])
      );

  const hs=teamRows.find(r=>
    String(r['チームID'])===homeId
  )||{};

  const as=teamRows.find(r=>
    String(r['チームID'])===awayId
  )||{};

  const disc=
    objs_(シート.警告退場)
      .filter(r=>
        String(r['試合ID'])===
          String(a['試合ID']) &&
        String(r['情報源']||'')===
          '公式記録'
      );

  const homeDisc=
    disc.filter(r=>
      String(r['チームID'])===homeId
    )
    .map(r=>approvalDiscView_(
      r,
      playersMaster,
      matchPlayers
    ));

  const awayDisc=
    disc.filter(r=>
      String(r['チームID'])===awayId
    )
    .map(r=>approvalDiscView_(
      r,
      playersMaster,
      matchPlayers
    ));

  const allGoalSeq=
    objs_(シート.得点経過);

  const goals=
    objs_(シート.得点)
      .filter(r=>
        String(r['試合ID'])===
        String(a['試合ID'])
      )
      .map(g=>{
        const scorer=
          playersMaster[
            String(g['得点者選手ID'])
          ]||{};

        const assist=
          playersMaster[
            String(g['アシスト選手ID'])
          ]||{};

        const scorerMatch=
          matchPlayers.find(r=>
            String(r['選手ID'])===
            String(g['得点者選手ID'])
          )||{};

        const assistMatch=
          matchPlayers.find(r=>
            String(r['選手ID'])===
            String(g['アシスト選手ID'])
          )||{};

        const sequence=
          allGoalSeq
            .filter(s=>
              String(s['得点ID'])===
              String(g['得点ID'])
            )
            .sort((x,y)=>
              Number(x['順番']||0)-
              Number(y['順番']||0)
            )
            .map(s=>
              String(s['経過内容']||'')
            )
            .filter(Boolean)
            .join(' ');

        return{
          time:officialEventTime_(
            g['時間帯'],
            g['時間'],
            g['時間入力方式']
          ),
          period:String(g['時間帯']||''),
          teamId:String(g['チームID']||''),
          teamName:
            String(g['チームID'])===homeId
              ?homeName
              :awayName,
          scorerNo:String(scorerMatch['背番号']||''),
          scorerName:
            String(g['得点種別']||'')==='オウンゴール'
              ?'OG'
              :String(scorer['氏名']||''),
          assistNo:String(assistMatch['背番号']||''),
          assistName:String(assist['氏名']||''),
          sequence
        };
      });

  const periodScores=
    getPeriodScoresForPdf_(
      String(a['試合ID']),
      rec,
      homeId,
      awayId
    );

  const pkRows=
    pkEnabled==='あり'
      ?objs_(シート.PK戦)
        .filter(r=>
          String(r['試合ID'])===
          String(a['試合ID'])
        )
      :[];

  const registrations=
    objs_(シート.選手登録);

  const pkFirstTeamId=
    String(rec['PK戦先攻チームID']||'');

  const pkOrders=[];

  for(let order=1;order<=18;order++){
    const h=pkRows.find(r=>
      Number(r['順番']||0)===order &&
      String(r['チームID']||'')===homeId
    );

    const w=pkRows.find(r=>
      Number(r['順番']||0)===order &&
      String(r['チームID']||'')===awayId
    );

    if(!h && !w) continue;

    pkOrders.push({
      order,
      home:h ? {
        no:String(
          getPkNumberForPdf_(
            String(h['選手ID']||''),
            homeId,
            String(match['大会ID']||''),
            matchPlayers,
            registrations
          )||''
        ),
        result:normalizePkResultForPdf_(h['結果'])
      } : null,
      away:w ? {
        no:String(
          getPkNumberForPdf_(
            String(w['選手ID']||''),
            awayId,
            String(match['大会ID']||''),
            matchPlayers,
            registrations
          )||''
        ),
        result:normalizePkResultForPdf_(w['結果'])
      } : null
    });
  }

  return{
    ok:true,

    approval:{
      role:String(a['承認者区分']||''),
      name:String(a['承認者名']||''),
      matchId:String(a['試合ID']||''),
      version:String(a['版']||'')
    },

    report:{
      rules:{
        extraTime:extraTimeEnabled,
        pk:pkEnabled
      },

      competitionName:String(
        competition['大会名']||
        match['大会ID']||
        ''
      ),
      round:String(match['節／ラウンド']||''),
      matchId:String(a['試合ID']||''),

      meta:{
        dateTime:formatMatchDateForPdf_(rec['日時']),
        venue:String(rec['会場名']||''),
        duration:String(rec['試合時間']||''),
        pitch:String(rec['ピッチ']||''),
        pitchCondition:String(rec['ピッチ状態']||''),
        wbgt:String(rec['WBGT']||''),
        weather:String(rec['天候']||''),
        wind:String(rec['風']||''),
        recorder:String(rec['記録担当者']||''),
        recorderUniversity:String(rec['記録担当クラブ']||'')
      },

      officials:{
        referee:String(rec['主審']||''),
        ar1:String(rec['副審1']||''),
        ar2:String(rec['副審2']||''),
        fourth:String(rec['第4の審判']||'')
      },

      home:{
        id:homeId,
        name:homeName,
        short:String(home['略称']||homeName),
        coach:String(home['監督名']||''),
        kickoff:
          String(rec['前半キックオフ']||'')===homeId,
        players:homePlayers
      },

      away:{
        id:awayId,
        name:awayName,
        short:String(away['略称']||awayName),
        coach:String(away['監督名']||''),
        kickoff:
          String(rec['前半キックオフ']||'')===awayId,
        players:awayPlayers
      },

      score:{
        totalHome:periodScores.totalHome,
        totalAway:periodScores.totalAway,
        firstHome:periodScores.firstHome,
        firstAway:periodScores.firstAway,
        secondHome:periodScores.secondHome,
        secondAway:periodScores.secondAway,
        extraFirstHome:
          extraTimeEnabled==='あり'
            ?periodScores.extraFirstHome
            :'',
        extraFirstAway:
          extraTimeEnabled==='あり'
            ?periodScores.extraFirstAway
            :'',
        extraSecondHome:
          extraTimeEnabled==='あり'
            ?periodScores.extraSecondHome
            :'',
        extraSecondAway:
          extraTimeEnabled==='あり'
            ?periodScores.extraSecondAway
            :'',
        pkHome:
          pkEnabled==='あり'
            ?valueOrBlank_(rec['PK戦ホーム'])
            :'',
        pkAway:
          pkEnabled==='あり'
            ?valueOrBlank_(rec['PK戦アウェイ'])
            :''
      },

      stats:{
        home:approvalStatsView_(hs),
        away:approvalStatsView_(as)
      },

      discipline:{
        home:homeDisc,
        away:awayDisc
      },

      goals,

      pk:{
        enabled:
          pkEnabled==='あり',
        firstTeamId:pkFirstTeamId,
        firstTeamName:
          pkFirstTeamId===homeId
            ?homeName
            :pkFirstTeamId===awayId
              ?awayName
              :'',
        homeScore:valueOrBlank_(rec['PK戦ホーム']),
        awayScore:valueOrBlank_(rec['PK戦アウェイ']),
        rows:pkOrders
      }
    }
  };
}


