/**
 * 承認ページから呼ぶ入口。承認は、確認のチェックが全部そろっていないと受け付けない
 * （チェックは承認ページで1つずつ付ける。運営の代理承認・自動テストは processApproval_ を直接使う）
 */
var AP_CHECKS = ['score', 'goals', 'cards', 'home_m', 'home_s', 'away_m', 'away_s', 'num'];
function processApproval(tok, action, comment, checks) {
  if (action === 'approve') {
    var got = (Array.isArray(checks) ? checks : []).map(String);
    var miss = AP_CHECKS.filter(function (k) { return got.indexOf(k) < 0; });
    if (miss.length) throw new Error('確認のチェックがすべて付いていません。ページを開き直して、各タブの確認にチェックしてください。');
  } else if (action !== 'revision') {
    throw new Error('操作が正しくありません');
  }
  var res = processApproval_(tok, action, comment);
  if (action === 'approve') {
    try { if (typeof log_ === 'function') log_('公式記録の承認', '承認', String(tok).slice(0, 6), null, { checks: checks }, '承認ページ（確認チェック済み）'); } catch (e) {}
  }
  return res;
}

function processApproval_(tok, action, comment) {
  const a = objs_(シート.承認).find(
    r => String(r['承認トークン']) === String(tok)
  );

  if (!a || String(a['承認状態']) !== '未承認') {
    throw new Error(
      '承認リンクが無効または処理済みです。'
    );
  }

  const rec = objs_(シート.公式記録).find(
    r =>
      String(r['公式記録ID']) ===
      String(a['対象公式記録ID'])
  );

  if (!rec) {
    throw new Error(
      '対象の公式記録が見つかりません。'
    );
  }

  // ---------------------------
  // 修正依頼
  // ---------------------------
  if (action === 'revision') {
    if (!String(comment || '').trim()) {
      throw new Error(
        '修正内容を入力してください。'
      );
    }

    update_(シート.承認, a._row, {
      '承認状態': '修正依頼',
      '承認日時': now_(),
      'コメント': comment
    });

    const sameVersion =
      objs_(シート.承認).filter(r =>
        String(r['試合ID']) ===
          String(a['試合ID']) &&
        String(r['版']) ===
          String(a['版']) &&
        String(r['対象公式記録ID']) ===
          String(a['対象公式記録ID'])
      );

    sameVersion.forEach(r => {
      if (r._row === a._row) return;

      const status =
        String(r['承認状態'] || '');

      if (status === '未承認') {
        update_(シート.承認, r._row, {
          '承認状態': '差戻し無効'
        });

      } else if (status === '承認') {
        update_(シート.承認, r._row, {
          '承認状態': '承認済・差戻し'
        });
      }
    });

    update_(シート.公式記録, rec._row, {
      '記録状態': '要修正'
    });

    const admin =
      cfg_('管理者メール');

    if (admin) {
      mail_(
        '公式記録修正依頼',
        admin,
        '【修正依頼】公式記録 '+
          a['試合ID']+
          '（版'+
          a['版']+
          '）',
        '<p><b>'+
          a['承認者区分']+
          '</b> から修正依頼がありました。</p>'+
        '<p>試合ID：'+
          a['試合ID']+
          '<br>版：'+
          a['版']+
          '<br>修正内容：'+
          String(comment)
            .replace(/\n/g, '<br>')+
          '</p>'+
        '<p>この版の残り承認リンクは無効化されています。修正後に再提出してください。</p>'+
        (typeof revAdminLinkHtml_==='function'?revAdminLinkHtml_(a['試合ID']):''),
        a['試合ID'],
        ''
      );
    }

    // 記録担当者にも通知（Revision.gs）
    if(typeof revNotifyRevision_==='function'){
      revNotifyRevision_(a,rec,comment);
    }

    // 「承認リンク無効」のお知らせは送らない（承認・入力のためのメールだけ送る運用）。修正版が出れば新しい承認依頼が届く
    [].forEach(r => {
      if (r._row === a._row) return;

      const email =
        String(r['承認者メール'] || '').trim();

      if (!email) return;

      mail_(
        '公式記録差戻し通知',
        email,
        '【承認リンク無効】公式記録 '+
          a['試合ID']+
          '（版'+
          a['版']+
          '）',
        '<p>公式記録に修正依頼が入ったため、版'+
          a['版']+
          'の承認リンクは無効になりました。</p>'+
        '<p>修正版が再提出されると、新しい承認メールが届きます。</p>',
        a['試合ID'],
        ''
      );
    });

    return {
      ok: true,
      message:
        '修正依頼を送信しました。この版の残り承認リンクは無効になりました。'
    };
  }

  // ---------------------------
  // 承認
  // ---------------------------
  update_(シート.承認, a._row, {
    '承認状態': '承認',
    '承認日時': now_(),
    'コメント': comment || ''
  });

  const sameVersion =
    objs_(シート.承認).filter(r =>
      String(r['試合ID']) ===
        String(a['試合ID']) &&
      String(r['版']) ===
        String(a['版']) &&
      String(r['対象公式記録ID']) ===
        String(a['対象公式記録ID'])
    );

  if (
    sameVersion.length >= 3 &&
    sameVersion.every(
      r => String(r['承認状態']) === '承認'
    )
  ) {
    finalize_(rec);
  }

  return {
    ok: true,
    message: '承認しました。'
  };
}


// =====================================================
// 確定
// =====================================================

function finalize_(r){
  // シーズン全体テスト中は公式記録のPDFを作らない（試合数が多く時間がかかるため）
  const pdf=(typeof seasonTestOn_==='function'&&seasonTestOn_())?'':makePdf_(
    r['試合ID'],
    r['版']
  );

  update_(シート.公式記録,r._row,{
    '記録状態':'確定',
    '確定PDF URL':pdf
  });

  // 訂正版の確定：以前の確定版を「旧版（訂正済み）」にする（Revision.gs）
  if(typeof revAfterFinalize_==='function'){
    revAfterFinalize_(r);
  }

  const m=findMatch_(r['試合ID']);

  const h=
    num_(r['前半ホーム得点'])+
    num_(r['後半ホーム得点'])+
    num_(r['延長ホーム得点']);

  const a=
    num_(r['前半アウェイ得点'])+
    num_(r['後半アウェイ得点'])+
    num_(r['延長アウェイ得点']);

  let hr='D';
  let ar='D';
  let hp=1;
  let ap=1;
  let win='DRAW';

  if(h>a){
    hr='W';
    ar='L';
    hp=3;
    ap=0;
    win=m['ホームチームID'];
  }

  if(h<a){
    hr='L';
    ar='W';
    hp=0;
    ap=3;
    win=m['アウェイチームID'];
  }

  if(
    h===a &&
    r['PK戦ホーム']!=='' &&
    r['PK戦アウェイ']!==''
  ){
    win=
      num_(r['PK戦ホーム'])>
      num_(r['PK戦アウェイ'])
        ?m['ホームチームID']
        :m['アウェイチームID'];
  }

  update_(シート.試合,m._row,{
    '実施日':
      ymd_(r['日時'])||
      m['実施日'],
    'ホーム得点':h,
    'アウェイ得点':a,
    '試合状態':'開催済',
    '結果確定':'確定',
    'ホーム結果':hr,
    'アウェイ結果':ar,
    'ホーム表示':
      (hr==='W'
        ?'○'
        :hr==='L'
          ?'×'
          :'△')+
      ' '+h+'-'+a,
    'アウェイ表示':
      (ar==='W'
        ?'○'
        :ar==='L'
          ?'×'
          :'△')+
      ' '+a+'-'+h,
    'ホーム勝点':hp,
    'アウェイ勝点':ap,
    '勝者チームID':win,
    'ホームPK':r['PK戦ホーム'],
    'アウェイPK':r['PK戦アウェイ']
  });

  // 両チーム・運営クラブのDiscordへ「公式記録が確定しました」（TeamNotify.gs）
  try{ if(typeof tnRecordConfirmed_==='function') tnRecordConfirmed_(m,h,a,r,pdf); }catch(e){}

  // 処分・順位表の再計算は約1分後にまとめて行う（承認した人を待たせない）
  scheduleRecalc_();
  bumpPublicVersion_();
}


// =====================================================
// 処分
// =====================================================

// 処分の生成は Discipline.gs の rebuildDiscipline() に一本化（v16）。
// 旧処理から呼ばれても処分管理を直接書き換えず、再計算だけを行う。
function rebuildDisciplineSafe_(){
  // v19：その場では再計算せず、約1分後にまとめて行う
  scheduleRecalc_();
}


function rebuildDisciplineNow_(){
  try{
    if(typeof rebuildDiscipline==='function'){
      rebuildDiscipline();
    }
  }catch(e){
    // 処分の再計算に失敗しても、公式記録の確定・審判報告の提出は止めない
    try{
      log_('処分再計算エラー','処分','',null,null,String(e&&e.message||e));
    }catch(_){}
  }
  // 一発退場があれば規律委員会へ通知（ReviewNotify.gs）
  if(typeof notifyReviewCasesSafe_==='function'){
    notifyReviewCasesSafe_();
  }
}


// 順位表・星取表・ランキングの再計算（Standings.gs）。失敗しても確定処理は止めない
function rebuildStandingsSafe_(){
  try{
    if(typeof rebuildStandings==='function'){
      rebuildStandings();
    }
  }catch(e){
    try{
      log_('順位表再計算エラー','順位表','',null,null,String(e&&e.message||e));
    }catch(_){}
  }
}


function ensureStraightRedSanction_(mid,pid,tid){
  rebuildDisciplineSafe_();
}


function recordHasExtraTime_(rec){
  if(
    rec['延長戦有無']!=='' &&
    rec['延長戦有無']!==null &&
    rec['延長戦有無']!==undefined
  ){
    return String(rec['延長戦有無'])==='あり';
  }

  return (
    rec['延長ホーム得点']!=='' &&
    rec['延長ホーム得点']!==null &&
    rec['延長ホーム得点']!==undefined
  ) || (
    rec['延長アウェイ得点']!=='' &&
    rec['延長アウェイ得点']!==null &&
    rec['延長アウェイ得点']!==undefined
  );
}


function recordHasPk_(rec){
  if(
    rec['PK戦有無']!=='' &&
    rec['PK戦有無']!==null &&
    rec['PK戦有無']!==undefined
  ){
    return String(rec['PK戦有無'])==='あり';
  }

  return (
    rec['PK戦ホーム']!=='' &&
    rec['PK戦ホーム']!==null &&
    rec['PK戦ホーム']!==undefined
  ) || (
    rec['PK戦アウェイ']!=='' &&
    rec['PK戦アウェイ']!==null &&
    rec['PK戦アウェイ']!==undefined
  );
}


// =====================================================
// 正方形テンプレートPDF
// =====================================================

function makePdf_(mid, ver) {
  const ss = ss_();

  const rec = objs_(シート.公式記録)
    .filter(r =>
      String(r['試合ID']) === String(mid) &&
      String(r['版']) === String(ver)
    )
    .sort((a,b) => b._row - a._row)[0];

  if (!rec) {
    throw new Error(
      '公式記録が見つかりません。'
    );
  }

  const match = findMatch_(mid);
  const home =
    findTeam_(match['ホームチームID']);
  const away =
    findTeam_(match['アウェイチームID']);

  const competition =
    objs_(シート.大会).find(r =>
      String(r['大会ID']) ===
      String(match['大会ID'])
    ) || {};

  const template =
    ss.getSheetByName(
      '公式記録PDFテンプレート_正方形'
    );

  if (!template) {
    throw new Error(
      '「公式記録PDFテンプレート_正方形」シートがありません。'
    );
  }

  const tmpName =
    'PDF_' +
    mid +
    '_v' +
    ver +
    '_' +
    Date.now();

  const sheet =
    template.copyTo(ss)
      .setName(tmpName);

  try {
    fillOfficialRecordPdfSheet_(
      sheet,
      rec,
      match,
      home,
      away,
      competition
    );

    SpreadsheetApp.flush();
    Utilities.sleep(500);

    const pdfBlob =
      exportOfficialRecordSheetAsPdf_(
        ss,
        sheet,
        mid,
        ver
      );

    const folderId =
      cfg_('公式記録PDF保存フォルダID');

    const pdfFile =
      folderId
        ? DriveApp
            .getFolderById(folderId)
            .createFile(pdfBlob)
        : DriveApp.createFile(pdfBlob);

    // 大会ごとのフォルダへ（DocFiling.gs）
    if (typeof fileOfficialRecordPdf_ === 'function') {
      return fileOfficialRecordPdf_(pdfFile, mid, ver);
    }
    return pdfFile.getUrl();

  } finally {
    ss.deleteSheet(sheet);
  }
}


function fillOfficialRecordPdfSheet_(
  sheet,
  rec,
  match,
  home,
  away,
  competition
) {
  const mid =
    String(rec['試合ID']);

  const ver =
    String(rec['版']);

  const homeId =
    String(
      match['ホームチームID']||''
    );

  const awayId =
    String(
      match['アウェイチームID']||''
    );

  const homeName =
    String(
      home['チーム名']||
      home['クラブ名']||
      homeId
    );

  const awayName =
    String(
      away['チーム名']||
      away['クラブ名']||
      awayId
    );

  const playersMaster =
    Object.fromEntries(
      objs_(シート.選手)
        .map(p=>[
          String(p['選手ID']),
          p
        ])
    );

  const allPlayerRows =
    objs_(シート.選手試合記録)
      .filter(r=>
        String(r['試合ID'])===mid
      );

  // ---------------------------------------------
  // 交代：
  // 入った選手の交代No.欄へ
  // 退いた選手の背番号を表示
  // ---------------------------------------------
  const substitutionEvents =
    objs_(シート.試合イベント)
      .filter(r=>
        String(r['試合ID'])===mid &&
        String(r['イベント種別'])==='交代'
      );

  const incomingFromNumber={};

  substitutionEvents.forEach(e=>{
    const outId=
      String(
        e['交代OUT選手ID']||''
      );

    const inId=
      String(
        e['交代IN選手ID']||''
      );

    if(!inId){
      return;
    }

    const outRow=
      allPlayerRows.find(r=>
        String(r['選手ID'])===outId &&
        String(r['チームID'])===
          String(e['チームID']||'')
      ) ||
      allPlayerRows.find(r=>
        String(r['選手ID'])===outId
      );

    incomingFromNumber[inId]=
      outRow
        ?String(outRow['背番号']||'')
        :'';
  });

  // ---------------------------------------------
  // タイトル：大会名 / 節 / マッチNo.
  // I1:AH3
  // ---------------------------------------------
  sheet.getRange('I1')
    .setValue(
      [
        String(
          competition['大会名']||''
        ),
        String(
          match['節／ラウンド']||''
        ),
        'マッチNo. '+mid
      ]
      .filter(Boolean)
      .join('\n')
    )
    .setWrap(true)
    .setHorizontalAlignment('center')
    .setVerticalAlignment('middle');

  // ---------------------------------------------
  // 電子承認
  // ---------------------------------------------
  const approvals =
    objs_(シート.承認)
      .filter(a=>
        String(a['試合ID'])===mid &&
        String(a['版'])===ver &&
        String(
          a['対象公式記録ID']
        )===
        String(rec['公式記録ID'])
      );

  const refereeApproval =
    approvals.find(a=>
      String(a['承認者区分'])==='主審'
    );

  const homeApproval =
    approvals.find(a=>
      String(a['承認者区分'])===
      'HOME監督'
    );

  const awayApproval =
    approvals.find(a=>
      String(a['承認者区分'])===
      'AWAY監督'
    );

  sheet.getRange('AI1')
    .setValue('電子承認');

  // 3行（主審／HOME／AWAY）に収め、欄の幅に合わせて文字サイズを自動調整
  fitLinesToCellForPdf_(
    sheet,
    'AI2',
    [
      '主審 '+
        formatApprovalForPdf_(
          refereeApproval
        ),
      'HOME '+
        formatApprovalForPdf_(
          homeApproval
        ),
      'AWAY '+
        formatApprovalForPdf_(
          awayApproval
        )
    ]
  );

  // ---------------------------------------------
  // 試合情報
  // ---------------------------------------------
  sheet.getRange('D4')
    .setValue(
      formatMatchDateForPdf_(
        rec['日時']
      )
    );

  const ruleText=[
    rec['試合時間']||'90分',
    recordHasExtraTime_(rec)
      ?'延長あり'
      :'延長なし',
    recordHasPk_(rec)
      ?'PKあり'
      :'PKなし'
  ].join(' / ');

  sheet.getRange('O4')
    .setValue(ruleText);

  sheet.getRange('X4')
    .setValue(
      rec['会場名']||''
    );

  sheet.getRange('D5')
    .setValue(
      rec['天候']||''
    );

  sheet.getRange('J5')
    .setValue(
      rec['WBGT']||''
    );

  sheet.getRange('P5')
    .setValue(
      rec['風']||''
    );

  sheet.getRange('V5')
    .setValue(
      [
        rec['ピッチ'],
        rec['ピッチ状態']
      ]
      .filter(Boolean)
      .join(' / ')
    );

  sheet.getRange('AB5')
    .setValue(
      rec['記録担当者']||''
    );

  sheet.getRange('AJ5')
    .setValue(
      rec['記録担当クラブ']||''
    );

  sheet.getRange('D6')
    .setValue(
      rec['主審']||''
    );

  sheet.getRange('N6')
    .setValue(
      rec['副審1']||''
    );

  sheet.getRange('X6')
    .setValue(
      rec['副審2']||''
    );

  sheet.getRange('AH6')
    .setValue(
      rec['第4の審判']||''
    );

  // ---------------------------------------------
  // チーム名
  // A7:P10 / Y7:AN10
  // ---------------------------------------------
  sheet.getRange('A7')
    .setValue(homeName)
    .setWrap(true)
    .setHorizontalAlignment('center')
    .setVerticalAlignment('middle');

  sheet.getRange('Y7')
    .setValue(awayName)
    .setWrap(true)
    .setHorizontalAlignment('center')
    .setVerticalAlignment('middle');

  // ---------------------------------------------
  // 前半KICK OFF
  // チーム名の下 A11:P11 / Y11:AN11
  // ---------------------------------------------
  const firstKickoff =
    String(
      rec['前半キックオフ']||''
    );

  sheet.getRange('A11')
    .setValue(
      firstKickoff===homeId
        ?'KICK OFF'
        :''
    );

  sheet.getRange('Y11')
    .setValue(
      firstKickoff===awayId
        ?'KICK OFF'
        :''
    );

  // ---------------------------------------------
  // スコア
  //
  // Q7:R11 = HOME総得点
  // S7:S11  = HOME各時間帯
  // T:U     = ラベル
  // V7:V11  = AWAY各時間帯
  // W7:X11 = AWAY総得点
  // ---------------------------------------------
  const periodScores =
    getPeriodScoresForPdf_(
      mid,
      rec,
      homeId,
      awayId
    );

  sheet.getRange('Q7')
    .setValue(
      periodScores.totalHome
    );

  sheet.getRange('W7')
    .setValue(
      periodScores.totalAway
    );

  sheet.getRange('S7')
    .setValue(
      periodScores.firstHome
    );

  sheet.getRange('V7')
    .setValue(
      periodScores.firstAway
    );

  sheet.getRange('S8')
    .setValue(
      periodScores.secondHome
    );

  sheet.getRange('V8')
    .setValue(
      periodScores.secondAway
    );

  const extraEnabled=
    recordHasExtraTime_(rec);

  const pkFormatEnabled=
    recordHasPk_(rec);

  sheet.getRange('T9')
    .setValue(
      extraEnabled
        ?'延長前半'
        :''
    );

  sheet.getRange('T10')
    .setValue(
      extraEnabled
        ?'延長後半'
        :''
    );

  sheet.getRange('T11')
    .setValue(
      pkFormatEnabled
        ?'PK'
        :''
    );

  sheet.getRange('S9')
    .setValue(
      extraEnabled
        ?valueOrBlank_(
          periodScores.extraFirstHome
        )
        :''
    );

  sheet.getRange('V9')
    .setValue(
      extraEnabled
        ?valueOrBlank_(
          periodScores.extraFirstAway
        )
        :''
    );

  sheet.getRange('S10')
    .setValue(
      extraEnabled
        ?valueOrBlank_(
          periodScores.extraSecondHome
        )
        :''
    );

  sheet.getRange('V10')
    .setValue(
      extraEnabled
        ?valueOrBlank_(
          periodScores.extraSecondAway
        )
        :''
    );

  sheet.getRange('S11')
    .setValue(
      pkFormatEnabled
        ?valueOrBlank_(
          rec['PK戦ホーム']
        )
        :''
    );

  sheet.getRange('V11')
    .setValue(
      pkFormatEnabled
        ?valueOrBlank_(
          rec['PK戦アウェイ']
        )
        :''
    );

  if(!pkFormatEnabled){
    // PKなしの場合はPK欄の文字だけ空欄にする。
    // 枠線を消すと隣の総得点・延長欄の線まで消えるため、枠線はテンプレートのまま残す
    sheet.getRange('S11').clearContent();
    sheet.getRange('T11:U11').clearContent();
    sheet.getRange('V11').clearContent();
  }

  // ---------------------------------------------
  // 選手 14〜36行
  // ---------------------------------------------
  const homePlayers =
    sortPlayersForPdf_(
      allPlayerRows.filter(r=>
        String(r['チームID'])===homeId
      )
    );

  const awayPlayers =
    sortPlayersForPdf_(
      allPlayerRows.filter(r=>
        String(r['チームID'])===awayId
      )
    );

  for(let i=0;i<23;i++){
    const row=14+i;

    writeSquareHomePlayerForPdf_(
      sheet,
      row,
      homePlayers[i],
      playersMaster,
      incomingFromNumber
    );

    writeSquareAwayPlayerForPdf_(
      sheet,
      row,
      awayPlayers[i],
      playersMaster,
      incomingFromNumber
    );
  }

  // ---------------------------------------------
  // 監督
  // ---------------------------------------------
  // 37行目は「監督」ラベルを残す
  sheet.getRange('N37')
    .setValue('監督');

  sheet.getRange('U37')
    .setValue('監督');

  // 監督名はその下の空欄
  sheet.getRange('N38')
    .setValue(
      String(home['監督名']||'')
    );

  sheet.getRange('U38')
    .setValue(
      String(away['監督名']||'')
    );

  // ---------------------------------------------
  // 警告・退場
  // 39〜46行
  // ---------------------------------------------
  const disc =
    objs_(シート.警告退場)
      .filter(r=>
        String(r['試合ID'])===mid &&
        String(
          r['情報源']||''
        )==='公式記録'
      );

  const homeDisc =
    disc.filter(r=>
      String(r['チームID'])===homeId
    );

  const awayDisc =
    disc.filter(r=>
      String(r['チームID'])===awayId
    );

  for(let i=0;i<8;i++){
    const row=39+i;

    writeSquareDiscHomeForPdf_(
      sheet,
      row,
      homeDisc[i],
      playersMaster,
      allPlayerRows
    );

    writeSquareDiscAwayForPdf_(
      sheet,
      row,
      awayDisc[i],
      playersMaster,
      allPlayerRows
    );
  }

  // ---------------------------------------------
  // チーム集計 40〜46行
  // ---------------------------------------------
  const teamStats =
    objs_(シート.チーム記録)
      .filter(r=>
        String(r['試合ID'])===mid
      );

  const hs =
    teamStats.find(r=>
      String(r['チームID'])===homeId
    )||{};

  const as =
    teamStats.find(r=>
      String(r['チームID'])===awayId
    )||{};

  const defs=[
    [
      'シュート',
      'シュート前半',
      'シュート後半',
      'シュート計'
    ],
    [
      'GK',
      'GK前半',
      'GK後半',
      'GK計'
    ],
    [
      'CK',
      'CK前半',
      'CK後半',
      'CK計'
    ],
    [
      '直接FK',
      '直接FK前半',
      '直接FK後半',
      '直接FK計'
    ],
    [
      '間接FK',
      '間接FK前半',
      '間接FK後半',
      '間接FK計'
    ],
    [
      '（オフサイド）',
      'オフサイド前半',
      'オフサイド後半',
      'オフサイド計'
    ],
    [
      'PK',
      'PK前半',
      'PK後半',
      'PK計'
    ]
  ];
  const extraOn=recordHasExtraTime_(rec);

  defs.forEach((d,i)=>{
    const row=40+i;
    const base=d[0].replace(/[（）]/g,'');
    const ex1=base+'延長前半';
    const ex2=base+'延長後半';

    const exCell=(r,k)=>
      extraOn
        ?valueOrBlank_(r[k])
        :'';

    // HOME
    sheet.getRange(row,14)
      .setValue(exCell(hs,ex2)); // N 延後

    sheet.getRange(row,15)
      .setValue(exCell(hs,ex1)); // O 延前

    sheet.getRange(row,16)
      .setValue(
        valueOrBlank_(
          hs[d[2]]
        )
      ); // P 後半

    sheet.getRange(row,17)
      .setValue(
        valueOrBlank_(
          hs[d[1]]
        )
      ); // Q 前半

    sheet.getRange(row,18)
      .setValue(
        teamStatTotalForPdf_(
          hs,
          d[1],
          d[2],
          d[3],
          extraOn?ex1:'',
          extraOn?ex2:''
        )
      ); // R HOME合計

    // AWAY
    sheet.getRange(row,24)
      .setValue(
        valueOrBlank_(
          as[d[1]]
        )
      ); // X 前半

    sheet.getRange(row,25)
      .setValue(
        valueOrBlank_(
          as[d[2]]
        )
      ); // Y 後半

    sheet.getRange(row,23)
      .setValue(
        teamStatTotalForPdf_(
          as,
          d[1],
          d[2],
          d[3],
          extraOn?ex1:'',
          extraOn?ex2:''
        )
      ); // W AWAY合計

    sheet.getRange(row,26)
      .setValue(exCell(as,ex1)); // Z 延前

    sheet.getRange(row,27)
      .setValue(exCell(as,ex2)); // AA 延後
  });

  // ---------------------------------------------
  // 得点経過 49〜60行
  // ---------------------------------------------
  const goals =
    objs_(シート.得点)
      .filter(r=>
        String(r['試合ID'])===mid
      );

  const goalSeq =
    objs_(シート.得点経過);

  for(let i=0;i<12;i++){
    const row=49+i;
    const g=goals[i];

    clearGoalRowForPdf_(
      sheet,
      row
    );

    if(!g) continue;

    const scorer =
      playersMaster[
        String(
          g['得点者選手ID']
        )
      ]||{};

    const assist =
      playersMaster[
        String(
          g['アシスト選手ID']
        )
      ]||{};

    const scorerMatch =
      allPlayerRows.find(r=>
        String(r['選手ID'])===
        String(
          g['得点者選手ID']
        )
      )||{};

    const assistMatch =
      allPlayerRows.find(r=>
        String(r['選手ID'])===
        String(
          g['アシスト選手ID']
        )
      )||{};

    // 得点チームは略称（チームマスターの「略称」。なければチーム名）
    const teamName =
      String(g['チームID'])===homeId
        ?String(home['略称']||homeName)
        :String(away['略称']||awayName);

    const seq =
      goalSeq
        .filter(s=>
          String(s['得点ID'])===
          String(g['得点ID'])
        )
        .sort((a,b)=>
          Number(a['順番']||0)-
          Number(b['順番']||0)
        )
        .map(s=>
          String(
            s['経過内容']||''
          )
        )
        .filter(Boolean)
        .join(' ');

    pdfCell_(sheet,row,1)
      .setValue(
        officialEventTime_(
          g['時間帯'],
          g['時間'],
          g['時間入力方式']
        )
      );

    pdfCell_(sheet,row,4)
      .setValue(teamName);

    pdfCell_(sheet,row,7)
      .setValue(
        scorerMatch['背番号']||''
      );

    pdfCell_(sheet,row,9)
      .setValue(
        String(g['得点種別']||'')==='オウンゴール'
          ?'OG'
          :(scorer['氏名']||'')
      );

    pdfCell_(sheet,row,16)
      .setValue(
        assistMatch['背番号']||''
      );

    pdfCell_(sheet,row,18)
      .setValue(
        assist['氏名']||''
      );

    // 得点経過が入力されていないときは、わかっている事実（開始の形・得点者の背番号・シュート／ヘディング）だけ書く
    const seqOut=seq||(()=>{
      const type=String(g['得点種別']||'');
      if(type==='オウンゴール') return 'OG';
      const start=String(g['開始状況']||'');
      const fin=type==='ヘディング'?'H':type==='PK'?'PK':'S';
      return [start&&start!=='流れの中'&&start!=='PK'?start:'',scorerMatch['背番号']||'',fin].filter(Boolean).join(' ');
    })();
    pdfCell_(sheet,row,24)
      .setValue(seqOut);
  }

  // ---------------------------------------------
  // PK戦 61〜65行
  // ---------------------------------------------
  fillSquarePkForPdf_(
    sheet,
    rec,
    match,
    homeName,
    awayName,
    allPlayerRows
  );

  // PDF全体を上下左右中央揃え
  sheet.getRange('A1:AN65')
    .setHorizontalAlignment('center')
    .setVerticalAlignment('middle');
}


// =====================================================
// スコア時間帯計算
// =====================================================

function getPeriodScoresForPdf_(
  mid,
  rec,
  homeId,
  awayId
){
  const s={
    firstHome:
      num_(rec['前半ホーム得点']),
    firstAway:
      num_(rec['前半アウェイ得点']),
    secondHome:
      num_(rec['後半ホーム得点']),
    secondAway:
      num_(rec['後半アウェイ得点']),
    extraFirstHome:'',
    extraFirstAway:'',
    extraSecondHome:'',
    extraSecondAway:''
  };

  const goals=
    objs_(シート.得点)
      .filter(r=>
        String(r['試合ID'])===
        String(mid)
      );

  const ef=goals.filter(g=>
    String(g['時間帯'])==='延長前半'
  );

  const es=goals.filter(g=>
    String(g['時間帯'])==='延長後半'
  );

  if(ef.length || es.length){
    s.extraFirstHome=
      ef.filter(g=>
        String(g['チームID'])===homeId
      ).length;

    s.extraFirstAway=
      ef.filter(g=>
        String(g['チームID'])===awayId
      ).length;

    s.extraSecondHome=
      es.filter(g=>
        String(g['チームID'])===homeId
      ).length;

    s.extraSecondAway=
      es.filter(g=>
        String(g['チームID'])===awayId
      ).length;

  }else if(
    rec['延長ホーム得点']!=='' ||
    rec['延長アウェイ得点']!==''
  ){
    // 旧データは延長前後半を分離していないため
    // 延長前半欄に合計値を表示
    s.extraFirstHome=
      num_(rec['延長ホーム得点']);

    s.extraFirstAway=
      num_(rec['延長アウェイ得点']);
  }

  s.totalHome=
    s.firstHome+
    s.secondHome+
    num_(s.extraFirstHome)+
    num_(s.extraSecondHome);

  s.totalAway=
    s.firstAway+
    s.secondAway+
    num_(s.extraFirstAway)+
    num_(s.extraSecondAway);

  return s;
}


// =====================================================
// チームスタッツ合計
// =====================================================

function teamStatTotalForPdf_(
  r,
  firstKey,
  secondKey,
  totalKey,
  extraFirstKey,
  extraSecondKey
){
  const has=k=>
    k &&
    r[k]!=='' &&
    r[k]!==null &&
    r[k]!==undefined;

  const keys=
    [firstKey,secondKey,extraFirstKey,extraSecondKey]
      .filter(has);

  if(keys.length){
    return keys.reduce((sum,k)=>sum+num_(r[k]),0);
  }

  return valueOrBlank_(
    r[totalKey]
  );
}


// =====================================================
// 正方形：選手 HOME
// =====================================================

function writeSquareHomePlayerForPdf_(
  sheet,
  row,
  r,
  playersMaster,
  incomingFromNumber
){
  [
    1,  // A 交代No.
    2,  // B OUT時間
    4,  // D 延後
    5,  // E 延前
    6,  // F 後半
    7,  // G 前半
    8,  // H 計
    9,  // I 得点
    10, // J 選手名
    17, // Q 番号
    19  // S 位置
  ].forEach(c=>
    sheet.getRange(row,c)
      .clearContent()
  );

  if(!r) return;

  const p=
    playersMaster[
      String(r['選手ID'])
    ]||{};

  // 入った選手：交代No.欄には
  // 退いた選手の背番号のみ
  sheet.getRange(row,1)
    .setValue(
      incomingFromNumber[
        String(r['選手ID'])
      ]||''
    );

  // 退いた選手：OUT時間のみ
  sheet.getRange(row,2)
    .setValue(
      r['交代OUT時間']||''
    );

  const played=
    String(r['出場']||'')==='○';

  const shotTotal=
    num_(r['シュート計']);

  // 試合に出た選手のみシュート数を記入
  if(played){
    if(shotTotal===0){
      // 0の場合は「計=0」だけ
      sheet.getRange(row,6)
        .clearContent();

      sheet.getRange(row,7)
        .clearContent();

      sheet.getRange(row,8)
        .setValue(0);

    }else{
      sheet.getRange(row,6)
        .setValue(
          valueOrBlank_(
            r['後半シュート']
          )
        );

      sheet.getRange(row,7)
        .setValue(
          valueOrBlank_(
            r['前半シュート']
          )
        );

      sheet.getRange(row,8)
        .setValue(shotTotal);
    }
  }

  sheet.getRange(row,9)
    .setValue(
      valueOrBlank_(
        r['得点']
      )
    );

  sheet.getRange(row,10)
    .setValue(
      p['氏名']||''
    );

  sheet.getRange(row,17)
    .setValue(
      r['背番号']||''
    );

  sheet.getRange(row,19)
    .setValue(
      r['位置']||''
    );
}

// =====================================================
// 正方形：選手 AWAY
// =====================================================

function writeSquareAwayPlayerForPdf_(
  sheet,
  row,
  r,
  playersMaster,
  incomingFromNumber
){
  [
    21, // U 位置
    23, // W 番号
    25, // Y 選手名
    32, // AF 得点
    33, // AG 計
    34, // AH 前半
    35, // AI 後半
    36, // AJ 延前
    37, // AK 延後
    38, // AL OUT時間
    40  // AN 交代No.
  ].forEach(c=>
    sheet.getRange(row,c)
      .clearContent()
  );

  if(!r) return;

  const p=
    playersMaster[
      String(r['選手ID'])
    ]||{};

  sheet.getRange(row,21)
    .setValue(
      r['位置']||''
    );

  sheet.getRange(row,23)
    .setValue(
      r['背番号']||''
    );

  sheet.getRange(row,25)
    .setValue(
      p['氏名']||''
    );

  sheet.getRange(row,32)
    .setValue(
      valueOrBlank_(
        r['得点']
      )
    );

  const played=
    String(r['出場']||'')==='○';

  const shotTotal=
    num_(r['シュート計']);

  if(played){
    if(shotTotal===0){
      sheet.getRange(row,33)
        .setValue(0);

      sheet.getRange(row,34)
        .clearContent();

      sheet.getRange(row,35)
        .clearContent();

    }else{
      sheet.getRange(row,33)
        .setValue(shotTotal);

      sheet.getRange(row,34)
        .setValue(
          valueOrBlank_(
            r['前半シュート']
          )
        );

      sheet.getRange(row,35)
        .setValue(
          valueOrBlank_(
            r['後半シュート']
          )
        );
    }
  }

  // 退いた選手：OUT時間のみ
  sheet.getRange(row,38)
    .setValue(
      r['交代OUT時間']||''
    );

  // 入った選手：交代No.欄には
  // 退いた選手の背番号のみ
  sheet.getRange(row,40)
    .setValue(
      incomingFromNumber[
        String(r['選手ID'])
      ]||''
    );
}

// =====================================================
// 警告・退場：入力時間 → 公式記録表示時間
// 前半18分 → 18分
// 後半18分 → 63分
// 古いデータ（時間帯なし）は時間をそのまま使用
// =====================================================

function officialEventTime_(period,time,mode){
  const raw=
    String(time??'').trim();

  if(!raw){
    return '';
  }

  // 旧データは既存表記をそのまま保持
  if(String(mode||'')!=='相対'){
    return raw;
  }

  const n=Number(raw);

  if(!Number.isFinite(n)){
    return raw;
  }

  const p=
    String(period||'').trim();

  if(p==='前半'){
    return n<=45
      ?String(n)
      :`45+${n-45}`;
  }

  if(p==='後半'){
    return n<=45
      ?String(45+n)
      :`90+${n-45}`;
  }

  if(p==='延長前半'){
    return n<=15
      ?String(90+n)
      :`105+${n-15}`;
  }

  if(p==='延長後半'){
    return n<=15
      ?String(105+n)
      :`120+${n-15}`;
  }

  return raw;
}


// 既存コード互換
function officialDisciplinaryTime_(period,time,mode){
  return officialEventTime_(
    period,
    time,
    mode
  );
}



// =====================================================
// 正方形：警告退場 HOME
// =====================================================

function writeSquareDiscHomeForPdf_(
  sheet,
  row,
  d,
  playersMaster,
  allPlayerRows
){
  [
    1, // A 時間
    3, // C 理由
    5, // E No.
    7  // G 選手名
  ].forEach(c=>
    sheet.getRange(row,c)
      .clearContent()
  );

  if(!d) return;

  const p=
    playersMaster[
      String(d['選手ID'])
    ]||{};

  const mp=
    allPlayerRows.find(r=>
      String(r['選手ID'])===
      String(d['選手ID'])
    )||{};

  sheet.getRange(row,1)
    .setValue(
      officialDisciplinaryTime_(
        d['時間帯'],
        d['時間'],
        d['時間入力方式']
      )
    );

  sheet.getRange(row,3)
    .setValue(
      d['理由']||''
    );

  sheet.getRange(row,5)
    .setValue(
      mp['背番号']||''
    );

  sheet.getRange(row,7)
    .setValue(
      p['氏名']||''
    );
}


// =====================================================
// 正方形：警告退場 AWAY
// =====================================================

function writeSquareDiscAwayForPdf_(
  sheet,
  row,
  d,
  playersMaster,
  allPlayerRows
){
  [
    28, // AB 時間
    30, // AD 理由
    32, // AF No.
    34  // AH 選手名
  ].forEach(c=>
    sheet.getRange(row,c)
      .clearContent()
  );

  if(!d) return;

  const p=
    playersMaster[
      String(d['選手ID'])
    ]||{};

  const mp=
    allPlayerRows.find(r=>
      String(r['選手ID'])===
      String(d['選手ID'])
    )||{};

  sheet.getRange(row,28)
    .setValue(
      officialDisciplinaryTime_(
        d['時間帯'],
        d['時間'],
        d['時間入力方式']
      )
    );

  sheet.getRange(row,30)
    .setValue(
      d['理由']||''
    );

  sheet.getRange(row,32)
    .setValue(
      mp['背番号']||''
    );

  sheet.getRange(row,34)
    .setValue(
      p['氏名']||''
    );
}


// =====================================================
// 選手並び順
// =====================================================

function sortPlayersForPdf_(rows){
  const positionOrder={
    'GK':0,
    'DF':1,
    'MF':2,
    'FW':3,
    '':9
  };

  return rows.slice().sort((a,b)=>{
    const aStarter=
      String(a['先発']||'')==='○'
        ?0
        :1;

    const bStarter=
      String(b['先発']||'')==='○'
        ?0
        :1;

    if(aStarter!==bStarter){
      return aStarter-bStarter;
    }

    const ap=
      String(a['位置']||'');

    const bp=
      String(b['位置']||'');

    const positionDiff=
      (positionOrder[ap] ?? 9)-
      (positionOrder[bp] ?? 9);

    if(positionDiff!==0){
      return positionDiff;
    }

    return (
      Number(a['背番号']||999)-
      Number(b['背番号']||999)
    );
  });
}


// =====================================================
// 得点行クリア
// =====================================================

function clearGoalRowForPdf_(
  sheet,
  row
){
  [
    1,  // A 得点時間
    4,  // D 得点チーム
    7,  // G No.
    9,  // I 得点者
    16, // P No.
    18, // R アシスト
    24  // X 得点経過
  ].forEach(c=>
    pdfCell_(sheet,row,c)
      .clearContent()
  );
}


/** 結合されたセルの途中の列を指定しても、結合範囲の左上に書く（書いた値が見えなくなるのを防ぐ） */
const PDF_CELL_CACHE_={};
function pdfCell_(sheet,row,col){
  // 得点欄は各行とも同じ結合なので、列ごとに1回だけ調べて使い回す
  const key=sheet.getSheetId()+':'+col;
  if(PDF_CELL_CACHE_[key]===undefined){
    let c=col;
    try{
      const m=sheet.getRange(row,col).getMergedRanges();
      if(m&&m.length) c=m[0].getColumn();
    }catch(e){}
    PDF_CELL_CACHE_[key]=c;
  }
  return sheet.getRange(row,PDF_CELL_CACHE_[key]);
}


// =====================================================
// PK戦
// row61 = タイトル
// row62 = 1〜18
// row63 = No. / ○×
// row64 = 先攻
// row65 = 後攻
// =====================================================

function fillSquarePkForPdf_(
  sheet,
  rec,
  match,
  homeName,
  awayName,
  allPlayerRows
){
  const pkFormatEnabled=
    recordHasPk_(rec);

  if(!pkFormatEnabled){
    sheet.getRange('A61:AN65')
      .clearContent();

    // PK戦記録欄を行ごと非表示
    sheet.hideRows(
      61,
      5
    );

    return;
  }

  sheet.showRows(
    61,
    5
  );

  const mid=
    String(rec['試合ID']||'');

  const homeId=
    String(
      match['ホームチームID']||''
    );

  const awayId=
    String(
      match['アウェイチームID']||''
    );

  const firstTeamId=
    String(
      rec['PK戦先攻チームID']||''
    );

  const firstIsHome=
    firstTeamId===homeId;

  const firstIsAway=
    firstTeamId===awayId;

  const hasFirstTeam=
    firstIsHome||firstIsAway;

  const secondTeamId=
    firstIsHome
      ?awayId
      :firstIsAway
        ?homeId
        :'';

  const firstTeamName=
    firstIsHome
      ?homeName
      :firstIsAway
        ?awayName
        :'';

  const secondTeamName=
    secondTeamId===homeId
      ?homeName
      :secondTeamId===awayId
        ?awayName
        :'';

  const pkRows=
    objs_(シート.PK戦)
      .filter(r=>
        String(r['試合ID'])===mid
      );

  const registrations=
    objs_(シート.選手登録);

  // 動的部分を消す
  for(let row=64;row<=65;row++){
    for(let order=1;order<=18;order++){
      const noCol=
        5+(order-1)*2;

      const resultCol=
        noCol+1;

      sheet.getRange(row,noCol)
        .clearContent();

      sheet.getRange(row,resultCol)
        .clearContent();
    }
  }

  if(hasFirstTeam){
    sheet.getRange('A64')
      .setValue(
        '先攻 '+firstTeamName
      );

    sheet.getRange('A65')
      .setValue(
        '後攻 '+secondTeamName
      );

  }else{
    sheet.getRange('A64')
      .setValue('先攻');

    sheet.getRange('A65')
      .setValue('後攻');
  }

  let homeMade=0;
  let awayMade=0;

  for(let order=1;order<=18;order++){
    const noCol=
      5+(order-1)*2;

    const resultCol=
      noCol+1;

    const homeKick=
      pkRows.find(r=>
        Number(r['順番']||0)===order &&
        String(r['チームID']||'')===homeId
      );

    const awayKick=
      pkRows.find(r=>
        Number(r['順番']||0)===order &&
        String(r['チームID']||'')===awayId
      );

    if(homeKick){
      const no=
        getPkNumberForPdf_(
          String(
            homeKick['選手ID']||''
          ),
          homeId,
          String(
            match['大会ID']||''
          ),
          allPlayerRows,
          registrations
        );

      const result=
        normalizePkResultForPdf_(
          homeKick['結果']
        );

      if(result==='○'){
        homeMade++;
      }

      const targetRow=
        firstIsAway
          ?65
          :64;

      sheet.getRange(
        targetRow,
        noCol
      ).setValue(no);

      sheet.getRange(
        targetRow,
        resultCol
      ).setValue(result);
    }

    if(awayKick){
      const no=
        getPkNumberForPdf_(
          String(
            awayKick['選手ID']||''
          ),
          awayId,
          String(
            match['大会ID']||''
          ),
          allPlayerRows,
          registrations
        );

      const result=
        normalizePkResultForPdf_(
          awayKick['結果']
        );

      if(result==='○'){
        awayMade++;
      }

      const targetRow=
        firstIsAway
          ?64
          :65;

      sheet.getRange(
        targetRow,
        noCol
      ).setValue(no);

      sheet.getRange(
        targetRow,
        resultCol
      ).setValue(result);
    }
  }

  const rawHome=
    rec['PK戦ホーム'];

  const rawAway=
    rec['PK戦アウェイ'];

  const hasFinalScore=
    rawHome!=='' &&
    rawHome!==null &&
    rawHome!==undefined &&
    rawAway!=='' &&
    rawAway!==null &&
    rawAway!==undefined;

  const finalHome=
    hasFinalScore
      ?Number(rawHome)
      :homeMade;

  const finalAway=
    hasFinalScore
      ?Number(rawAway)
      :awayMade;

  if(pkRows.length || hasFinalScore){
    const firstText=
      hasFirstTeam
        ?'先攻：'+
          firstTeamName+
          ' ／ 後攻：'+
          secondTeamName+
          '　'
        :'先攻未設定　';

    sheet.getRange('A61')
      .setValue(
        'PK戦　'+
        firstText+
        homeName+
        ' '+
        finalHome+
        ' - '+
        finalAway+
        ' '+
        awayName
      );

  }else{
    sheet.getRange('A61')
      .setValue('PK戦');
  }
}


function getPkNumberForPdf_(
  playerId,
  teamId,
  competitionId,
  allPlayerRows,
  registrations
){
  const mp=
    allPlayerRows.find(r=>
      String(r['選手ID'])===
      String(playerId)
    );

  if(
    mp &&
    mp['背番号']!=='' &&
    mp['背番号']!==null &&
    mp['背番号']!==undefined
  ){
    return mp['背番号'];
  }

  const reg=
    registrations.find(r=>
      String(r['選手ID'])===
        String(playerId) &&
      String(r['チームID'])===
        String(teamId) &&
      String(r['大会ID'])===
        String(competitionId)
    ) ||
    registrations.find(r=>
      String(r['選手ID'])===
        String(playerId) &&
      String(r['チームID'])===
        String(teamId)
    );

  return reg
    ?reg['背番号']||''
    :'';
}


function normalizePkResultForPdf_(value){
  const s=
    String(value||'').trim();

  if(
    s==='○' ||
    s==='〇' ||
    s==='◯' ||
    s==='⚪' ||
    s.indexOf('成功')!==-1
  ){
    return '○';
  }

  if(
    s==='×' ||
    s==='✕' ||
    s==='✖' ||
    s.toUpperCase()==='X' ||
    s.indexOf('失敗')!==-1
  ){
    return '×';
  }

  return s;
}


// =====================================================
// 承認表示 / 日付
// =====================================================

function formatApprovalForPdf_(a){
  if(!a) return '';

  const name=
    String(a['承認者名']||'');

  const status=
    String(a['承認状態']||'');

  const value=
    a['承認日時'];

  let time='';

  if(value){
    const d=
      Object.prototype.toString.call(value)==='[object Date]'
        ?value
        :new Date(value);

    if(!isNaN(d.getTime())){
      time=
        Utilities.formatDate(
          d,
          Session.getScriptTimeZone()||
            'Asia/Tokyo',
          'HH:mm'
        );
    }
  }

  if(status==='承認'){
    return (
      name+
      ' 承認'+
      (time?' '+time:'')
    );
  }

  return (
    name+
    ' '+
    status+
    (time?' '+time:'')
  );
}


function formatMatchDateForPdf_(value){
  if(!value) return '';

  if(
    Object.prototype.toString.call(value)==='[object Date]'
  ){
    return Utilities.formatDate(
      value,
      Session.getScriptTimeZone()||
        'Asia/Tokyo',
      'yyyy年M月d日 HH:mm'
    );
  }

  const s=String(value);
  const d=new Date(s);

  if(!isNaN(d.getTime())){
    return Utilities.formatDate(
      d,
      Session.getScriptTimeZone()||
        'Asia/Tokyo',
      'yyyy年M月d日 HH:mm'
    );
  }

  return s;
}


// =====================================================
// 複数行テキストを1つの欄に収める（折り返しなし・文字サイズ自動調整）
// =====================================================

function fitLinesToCellForPdf_(sheet,a1,lines,opts){
  opts=opts||{};
  const cell=sheet.getRange(a1);
  const merged=cell.getMergedRanges();
  const r=merged.length?merged[0]:cell;

  let width=0;
  for(let c=r.getColumn();c<r.getColumn()+r.getNumColumns();c++){
    width+=sheet.getColumnWidth(c);
  }

  let height=0;
  for(let i=r.getRow();i<r.getRow()+r.getNumRows();i++){
    height+=sheet.getRowHeight(i);
  }

  // 全角=1、半角=0.55 として1行の長さを見積もる
  const units=t=>
    [...String(t||'')].reduce(
      (n,ch)=>n+(/[ -~]/.test(ch)?0.55:1),
      0
    );

  const maxUnits=
    Math.max(1,...lines.map(units));

  const current=
    Number(cell.getFontSize())||10;

  // 1pt ≒ 1.34px、行間 1.2 倍で計算
  // 実際の描画は見積もりより広がるため 1.45 倍で余裕をみる
  const byWidth=(width-6)/(maxUnits*1.45);
  const byHeight=(height-4)/(lines.length*1.34*1.2);

  const size=
    Math.max(
      5,
      Math.min(
        current,
        Math.floor(Math.min(byWidth,byHeight))
      )
    );

  cell.setValue(lines.join('\n'));

  r.setFontSize(size)
    .setWrap(false)
    .setWrapStrategy(SpreadsheetApp.WrapStrategy.CLIP)
    .setVerticalAlignment('middle');

  // テンプレートの左右揃えを保つ指定がなければ左揃え
  if(!opts.keepAlign){
    r.setHorizontalAlignment('left');
  }
}


// =====================================================
// PDFエクスポート
// =====================================================

function exportOfficialRecordSheetAsPdf_(
  ss,
  sheet,
  mid,
  ver
){
  const url=
    'https://docs.google.com/spreadsheets/d/'+
    ss.getId()+
    '/export?'+
    [
      'format=pdf',
      'size=A4',
      'portrait=true',
      'scale=4',
      'sheetnames=false',
      'printtitle=false',
      'pagenumbers=false',
      'gridlines=false',
      'fzr=false',
      'top_margin=0.10',
      'bottom_margin=0.10',
      'left_margin=0.10',
      'right_margin=0.10',
      // 用紙の左右中央に配置（右側だけ余白が広くなるのを防ぐ）
      'horizontal_alignment=CENTER',
      'vertical_alignment=TOP',
      // テンプレートの記入範囲 A1:AN65 だけを出力（余分な列で右余白が出るのを防ぐ）
      'r1=0',
      'c1=0',
      'r2=65',
      'c2=40',
      'gid='+sheet.getSheetId()
    ].join('&');

  const response=
    UrlFetchApp.fetch(
      url,
      {
        headers:{
          Authorization:
            'Bearer '+
            ScriptApp.getOAuthToken()
        },
        muteHttpExceptions:true
      }
    );

  if(
    response.getResponseCode()!==200
  ){
    throw new Error(
      'PDF出力に失敗しました。HTTP '+
      response.getResponseCode()
    );
  }

  return response
    .getBlob()
    .setName(
      '公式記録_'+
      mid+
      '_v'+
      ver+
      '.pdf'
    );
}


