// =====================================================
// 審判報告書 Webアプリ
// 添付の審判報告書書式に合わせた
// 1ページ目 + 必要時「重要事項」2ページ目
// =====================================================

function ensureSheetWithHeaders_(name,headers){
  memoForget_(name);
  let s=ss_().getSheetByName(name);

  if(!s){
    s=ss_().insertSheet(name);
    s.setFrozenRows(1);
  }

  const last=
    Math.max(
      1,
      s.getLastColumn()
    );

  const current=
    s.getRange(
      1,
      1,
      1,
      last
    ).getValues()[0];

  headers.forEach((h,i)=>{
    if(String(current[i]||'')!==String(h)){
      s.getRange(1,i+1).setValue(h);
    }
  });

  return s;
}


