function normalizeReportName_(name){
  const s=
    String(name||'')
      .trim()
      .replace(/[ \t　]+/g,'　');

  return s;
}


function refOptionValues_(category){
  const v=
    sheetValues_(
      '入力候補マスター'
    );

  if(v.length<2){
    return [];
  }

  const h=v[0];
  const iCat=h.indexOf('カテゴリ');
  const iVal=h.indexOf('値');
  const iEn=h.indexOf('有効');
  const iOrd=h.indexOf('表示順');

  return v.slice(1)
    .filter(r=>
      String(r[iCat]||'')===String(category) &&
      String(r[iEn]||'有効')!=='無効'
    )
    .sort((a,b)=>
      num_(a[iOrd])-num_(b[iOrd])
    )
    .map(r=>String(r[iVal]||''))
    .filter(Boolean);
}


/** 高速化：読むだけの処理は同じシートを1回だけ読む */
