// =====================================================
// 審判報告書PDF（テンプレート版）
// -----------------------------------------------------
// スプレッドシート内の次の2シートを複製して値を転記し、PDF化する。
//   ・審判報告書PDFテンプレート
//   ・審判報告書重要事項テンプレート（重要事項がある場合のみ）
// テンプレートが見つからない場合は旧レイアウト（コード描画）で出力する。
// =====================================================

const REFEREE_PDF_TEMPLATE_='審判報告書PDFテンプレート';
const REFEREE_PDF_IMPORTANT_TEMPLATE_='審判報告書重要事項テンプレート';


function createRefereeReportPdf_(d){
  const ss=ss_();
  const t1=ss.getSheetByName(REFEREE_PDF_TEMPLATE_);
  const t2=ss.getSheetByName(REFEREE_PDF_IMPORTANT_TEMPLATE_);

  if(!t1 || (d.important && !t2)){
    return createRefereeReportPdfLegacy_(d);
  }

  const tmp=
    SpreadsheetApp.create(
      '審判報告書_作業用_'+d.matchId+'_'+d.reportId
    );

  try{
    const blank=tmp.getSheets()[0];

    const page1=t1.copyTo(tmp).setName('審判報告書');
    refereeTplFillMain_(page1,d);

    if(d.important){
      const page2=t2.copyTo(tmp).setName('重要事項');
      refereeTplFillImportant_(page2,d);
    }

    tmp.deleteSheet(blank);
    SpreadsheetApp.flush();

    const exportUrl=
      'https://docs.google.com/spreadsheets/d/'+
      tmp.getId()+
      '/export?'+
      [
        'format=pdf',
        'size=A4',
        'portrait=true',
        'scale=2',
        'sheetnames=false',
        'printtitle=false',
        'pagenumbers=false',
        'gridlines=false',
        'fzr=false',
        'top_margin=0.40',
        'bottom_margin=0.40',
        'left_margin=0.40',
        'right_margin=0.40',
        'horizontal_alignment=CENTER',
        'vertical_alignment=TOP'
      ].join('&');

    const response=
      UrlFetchApp.fetch(
        exportUrl,
        {
          headers:{
            Authorization:'Bearer '+ScriptApp.getOAuthToken()
          },
          muteHttpExceptions:true
        }
      );

    if(response.getResponseCode()!==200){
      throw new Error(
        '審判報告書PDFの出力に失敗しました。HTTP '+response.getResponseCode()
      );
    }

    const pdf=
      response
        .getBlob()
        .setName('審判報告書_'+d.matchId+'_'+d.reportId+'.pdf');

    const folderId=
      cfg_('審判報告書PDF保存フォルダID')||
      cfg_('公式記録PDF保存フォルダID');

    const folder=
      folderId
        ?DriveApp.getFolderById(folderId)
        :DriveApp.getRootFolder();

    const created=folder.createFile(pdf);
    // 大会ごとのフォルダへ（DocFiling.gs）
    if(typeof fileRefereeReportPdf_==='function'){
      return fileRefereeReportPdf_(created,d.matchId);
    }
    return created.getUrl();

  }finally{
    DriveApp.getFileById(tmp.getId()).setTrashed(true);
  }
}


// ---------- 共通ヘルパー ----------

function refereeTplSet_(sheet,a1,value){
  sheet.getRange(a1).setValue(
    value===null || value===undefined ? '' : value
  );
}

// 1行に収める（はみ出す場合は文字を小さくする）
function refereeTplFit_(sheet,a1,value){
  const text=String(value??'');

  if(!text){
    sheet.getRange(a1).setValue('');
    return;
  }

  fitLinesToCellForPdf_(sheet,a1,[text],{keepAlign:true});
}

// 指定幅（全角換算の文字数）で折り返す
function refereeTplWrap_(text,maxUnits){
  const out=[];

  String(text||'')
    .replace(/\r\n?/g,'\n')
    .split('\n')
    .forEach(para=>{
      if(!para){
        out.push('');
        return;
      }

      let line='',u=0;

      [...para].forEach(ch=>{
        const w=/[ -~]/.test(ch)?0.55:1;

        if(u+w>maxUnits){
          out.push(line);
          line='';
          u=0;
        }

        line+=ch;
        u+=w;
      });

      out.push(line);
    });

  return out;
}

// 行ごとに結合された記入欄（rows）へ文章を流し込む。
// 入りきらない場合は文字サイズを下げて1行あたりの文字数を増やす。
function refereeTplFlowText_(sheet,rows,colFrom,colTo,text){
  const first=sheet.getRange(colFrom+rows[0]);

  const merged=
    sheet.getRange(colFrom+rows[0]+':'+colTo+rows[0]);

  let width=0;
  for(let c=merged.getColumn();c<merged.getColumn()+merged.getNumColumns();c++){
    width+=sheet.getColumnWidth(c);
  }

  const baseSize=Number(first.getFontSize())||11;
  let size=baseSize;
  let lines=[];

  for(;size>=6;size--){
    const perLine=Math.floor((width-8)/(size*1.5));
    lines=refereeTplWrap_(text,perLine);
    if(lines.length<=rows.length)break;
  }

  if(lines.length>rows.length){
    lines=lines.slice(0,rows.length);
    lines[rows.length-1]=
      String(lines[rows.length-1]).slice(0,-2)+'…';
  }

  rows.forEach((r,i)=>{
    sheet.getRange(colFrom+r).setValue(lines[i]||'');
    sheet.getRange(colFrom+r+':'+colTo+r)
      .setFontSize(size)
      .setWrap(false)
      .setWrapStrategy(SpreadsheetApp.WrapStrategy.CLIP)
      .setHorizontalAlignment('left')
      .setVerticalAlignment('middle');
  });
}

// 行が結合されていない・分割されている場合は A:AN を1つに結合し直す
function refereeTplEnsureLineMerged_(sheet,row,colFrom,colTo){
  const r=sheet.getRange(colFrom+row+':'+colTo+row);
  const merged=r.getMergedRanges();

  if(
    merged.length===1 &&
    merged[0].getA1Notation()===r.getA1Notation()
  ){
    return;
  }

  r.breakApart();
  r.merge();
}

function refereeTplDateParts_(ymd){
  const m=String(ymd||'').match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  return m
    ?{y:m[1],m:String(Number(m[2])),d:String(Number(m[3]))}
    :{y:'',m:'',d:''};
}

function refereeTplTimeParts_(hm){
  const m=String(hm||'').match(/^(\d{1,2}):(\d{2})/);
  return m
    ?{h:String(Number(m[1])),mi:m[2]}
    :{h:'',mi:''};
}

function refereeTplToday_(){
  const tz=Session.getScriptTimeZone()||'Asia/Tokyo';
  const now=new Date();
  return{
    y:Utilities.formatDate(now,tz,'yyyy'),
    m:Utilities.formatDate(now,tz,'M'),
    d:Utilities.formatDate(now,tz,'d')
  };
}

// 宛名：「公益財団法人北海道サッカー協会会長殿」→ 前半部分を記入欄へ
function refereeTplRecipient_(sheet,prefixA1,suffixA1,recipient){
  const suffix='サッカー協会会長殿';
  const r=String(recipient||'').trim();

  if(r.endsWith(suffix)){
    refereeTplSet_(sheet,prefixA1,r.slice(0,-suffix.length));
  }else if(r){
    refereeTplSet_(sheet,prefixA1,'');
    refereeTplSet_(sheet,suffixA1,r);
  }
}

// 前半・後半・延長前半・延長後半の内訳（公式記録から取得）
function refereeTplScores_(d){
  const s=d.score||{};
  const out={
    totalHome:'',totalAway:'',
    firstHome:'',firstAway:'',
    secondHome:'',secondAway:'',
    ex1Home:'',ex1Away:'',
    ex2Home:'',ex2Away:'',
    pkHome:valueOrBlank_(s.pkHome),
    pkAway:valueOrBlank_(s.pkAway)
  };

  try{
    const rec=latestOfficialRecordForMatch_(d.matchId);

    if(rec){
      const m=findMatch_(d.matchId);
      const ps=getPeriodScoresForPdf_(
        String(d.matchId),
        rec,
        String(m['ホームチームID']),
        String(m['アウェイチームID'])
      );

      out.totalHome=ps.totalHome;
      out.totalAway=ps.totalAway;
      out.firstHome=ps.firstHome;
      out.firstAway=ps.firstAway;
      out.secondHome=ps.secondHome;
      out.secondAway=ps.secondAway;
      out.ex1Home=valueOrBlank_(ps.extraFirstHome);
      out.ex1Away=valueOrBlank_(ps.extraFirstAway);
      out.ex2Home=valueOrBlank_(ps.extraSecondHome);
      out.ex2Away=valueOrBlank_(ps.extraSecondAway);
      return out;
    }
  }catch(e){}

  // 公式記録がない場合は試合マスター等の値で総得点のみ
  const eh=s.extraHome, ea=s.extraAway;
  out.totalHome=
    s.regularHome===''?'':num_(s.regularHome)+num_(eh);
  out.totalAway=
    s.regularAway===''?'':num_(s.regularAway)+num_(ea);
  out.ex1Home=valueOrBlank_(eh);
  out.ex1Away=valueOrBlank_(ea);
  return out;
}


// ---------- 審判報告書（1枚目） ----------

function refereeTplFillMain_(sheet,d){
  const extraOn=
    d.extraTime && String(d.extraTime)!=='なし';

  // 競技会名・試合時間・延長・会場
  refereeTplFit_(sheet,'E2',d.competitionName);
  refereeTplSet_(sheet,'E3',d.matchTime||'');

  if(extraOn){
    refereeTplSet_(sheet,'N3',d.extraTime);
  }else{
    refereeTplSet_(sheet,'N3','なし');
    refereeTplSet_(sheet,'Q3','');
  }

  refereeTplFit_(sheet,'W3',d.venue);

  // 対戦（正式名称）
  refereeTplFit_(sheet,'F4',d.homeName);
  refereeTplFit_(sheet,'Y4',d.awayName);

  // 結果： 総得点（前半）（後半） 延長（前半）（後半） PK
  const sc=refereeTplScores_(d);
  refereeTplSet_(sheet,'E5',sc.totalHome);
  refereeTplSet_(sheet,'H5',sc.totalAway);
  refereeTplSet_(sheet,'K5',sc.firstHome);
  refereeTplSet_(sheet,'N5',sc.firstAway);
  refereeTplSet_(sheet,'Q5',sc.secondHome);
  refereeTplSet_(sheet,'T5',sc.secondAway);
  refereeTplSet_(sheet,'Y5',extraOn?sc.ex1Home:'');
  refereeTplSet_(sheet,'AA5',extraOn?sc.ex1Away:'');
  refereeTplSet_(sheet,'AC5',extraOn?sc.ex2Home:'');
  refereeTplSet_(sheet,'AE5',extraOn?sc.ex2Away:'');
  refereeTplSet_(sheet,'AI5',sc.pkHome);
  refereeTplSet_(sheet,'AL5',sc.pkAway);

  // 日時
  const dt=refereeTplDateParts_(d.date);
  const tm=refereeTplTimeParts_(d.kickoff);
  refereeTplSet_(sheet,'E6',dt.y);
  refereeTplSet_(sheet,'J6',dt.m);
  refereeTplSet_(sheet,'N6',dt.d);
  refereeTplSet_(sheet,'R6',tm.h);
  refereeTplSet_(sheet,'V6',tm.mi);

  // 審判員（氏名・所属）
  const o=d.officials||{};
  refereeTplFit_(sheet,'E7',(o.main||{}).name);
  refereeTplFit_(sheet,'O7',(o.main||{}).association);
  refereeTplFit_(sheet,'Y7',(o.ar1||{}).name);
  refereeTplFit_(sheet,'AI7',(o.ar1||{}).association);
  refereeTplFit_(sheet,'E8',(o.fourth||{}).name);
  refereeTplFit_(sheet,'O8',(o.fourth||{}).association);
  refereeTplFit_(sheet,'Y8',(o.ar2||{}).name);
  refereeTplFit_(sheet,'AI8',(o.ar2||{}).association);

  // 競技場、用具の状態
  refereeTplFit_(sheet,'A11',d.conditionText);

  const events=d.events||[];
  const overflow=[];

  // 警告（競技者・交代要員） 14〜21行
  const warnings=events.filter(e=>e.kind==='warning');
  warnings.forEach((e,i)=>{
    if(i>=8){
      overflow.push(
        '【警告】'+[e.displayTime?e.displayTime+'分':'',e.teamShort,e.number?'No.'+e.number:'',e.name,'('+(e.reason||'')+')',e.detail].filter(Boolean).join(' ')
      );
      return;
    }
    const r=14+i;
    refereeTplSet_(sheet,'B'+r,e.displayTime||'');
    refereeTplFit_(sheet,'E'+r,e.teamShort);
    refereeTplSet_(sheet,'H'+r,e.number||'');
    refereeTplFit_(sheet,'K'+r,e.name);
    refereeTplSet_(sheet,'S'+r,e.reason||'');
    refereeTplFit_(sheet,'V'+r,e.detail);
  });

  // 退場（競技者・交代要員） 24〜26行
  const sendoffs=events.filter(e=>e.kind==='sendoff');
  sendoffs.forEach((e,i)=>{
    const reasonText=[e.reason,e.detail].filter(Boolean).join('　');
    if(i>=3){
      overflow.push(
        '【退場】'+[e.displayTime?e.displayTime+'分':'',e.teamShort,e.number?'No.'+e.number:'',e.name,reasonText].filter(Boolean).join(' ')
      );
      return;
    }
    const r=24+i;
    refereeTplSet_(sheet,'B'+r,e.displayTime||'');
    refereeTplFit_(sheet,'E'+r,e.teamShort);
    refereeTplSet_(sheet,'H'+r,e.number||'');
    refereeTplFit_(sheet,'K'+r,e.name);
    refereeTplFit_(sheet,'R'+r,reasonText);
  });

  // 警告・退場（チーム役員） 29〜31行
  const officialsEv=events.filter(e=>e.kind==='official');
  officialsEv.forEach((e,i)=>{
    const reasonText=[e.reason,e.detail].filter(Boolean).join('　');
    if(i>=3){
      overflow.push(
        '【チーム役員・'+(e.subtype||'')+'】'+[e.displayTime?e.displayTime+'分':'',e.teamShort,e.role,e.name,reasonText].filter(Boolean).join(' ')
      );
      return;
    }
    const r=29+i;
    refereeTplSet_(sheet,'B'+r,e.subtype==='退場'?'退':'警');
    refereeTplSet_(sheet,'E'+r,e.displayTime||'');
    refereeTplFit_(sheet,'H'+r,e.teamShort);
    refereeTplFit_(sheet,'K'+r,e.role);
    refereeTplFit_(sheet,'P'+r,e.name);
    refereeTplFit_(sheet,'W'+r,reasonText);
  });

  // その他の報告事項 33〜37行（欄に入りきらない警告・退場もここへ続けて記載）
  const other=
    [String(d.otherReport||'').trim()]
      .concat(overflow)
      .filter(Boolean)
      .join('\n');

  refereeTplFlowText_(sheet,[33,34,35,36,37],'A','AN',other);

  // 提出日・主審署名
  const today=refereeTplToday_();
  refereeTplSet_(sheet,'K38',today.y);
  refereeTplSet_(sheet,'P38',today.m);
  refereeTplSet_(sheet,'T38',today.d);
  refereeTplFit_(sheet,'AB38',(o.main||{}).name);

  // 主審連絡先（署名の下の空き行）
  if((o.main||{}).phone){
    const r=sheet.getRange('X39:AN39');
    r.breakApart();
    r.merge();
    refereeTplFit_(sheet,'X39','主審連絡先：'+o.main.phone);
  }

  // 宛名
  refereeTplRecipient_(sheet,'A40','O40',d.recipient);
}


// ---------- 審判報告書（重要事項） ----------

function refereeTplFillImportant_(sheet,d){
  refereeTplFit_(sheet,'E3',d.competitionName);
  refereeTplFit_(sheet,'F4',d.homeName);
  refereeTplFit_(sheet,'Y4',d.awayName);

  const dt=refereeTplDateParts_(d.date);
  const tm=refereeTplTimeParts_(d.kickoff);
  refereeTplSet_(sheet,'E5',dt.y);
  refereeTplSet_(sheet,'J5',dt.m);
  refereeTplSet_(sheet,'N5',dt.d);
  refereeTplSet_(sheet,'R5',tm.h);
  refereeTplSet_(sheet,'V5',tm.mi);

  // 本文 7〜38行（9・10行目は1行の記入欄として結合し直す）
  const rows=[];
  for(let r=7;r<=38;r++){
    refereeTplEnsureLineMerged_(sheet,r,'A','AN');
    rows.push(r);
  }

  const text=
    String((d.important||{}).finalText||'').trim();

  refereeTplFlowText_(sheet,rows,'A','AN',text);

  const today=refereeTplToday_();
  refereeTplSet_(sheet,'K39',today.y);
  refereeTplSet_(sheet,'P39',today.m);
  refereeTplSet_(sheet,'T39',today.d);
  refereeTplFit_(sheet,'AB39',((d.officials||{}).main||{}).name);

  refereeTplRecipient_(sheet,'A41','O41',d.recipient);
}


function createRefereeReportPdfLegacy_(d){
  const tmp=
    SpreadsheetApp.create(
      '審判報告書_作業用_'+
      d.matchId+
      '_'+
      d.reportId,
      55,
      20
    );

  const page1=
    tmp.getSheets()[0];

  refereePdfBuildPage1_(
    page1,
    d
  );

  if(d.important){
    const page2=
      tmp.insertSheet(
        '重要事項',
        1
      );

    refereePdfBuildImportantPage_(
      page2,
      d
    );
  }

  SpreadsheetApp.flush();

  const exportUrl=
    'https://docs.google.com/spreadsheets/d/'+
    tmp.getId()+
    '/export?format=pdf'+
    '&size=A4'+
    '&portrait=true'+
    '&scale=4'+
    '&sheetnames=false'+
    '&printtitle=false'+
    '&pagenum=UNDEFINED'+
    '&gridlines=false'+
    '&fzr=false'+
    '&top_margin=0.25'+
    '&bottom_margin=0.25'+
    '&left_margin=0.25'+
    '&right_margin=0.25';

  const response=
    UrlFetchApp.fetch(
      exportUrl,
      {
        headers:{
          Authorization:
            'Bearer '+
            ScriptApp.getOAuthToken()
        },
        muteHttpExceptions:false
      }
    );

  const pdf=
    response
      .getBlob()
      .setName(
        '審判報告書_'+
        d.matchId+
        '_'+
        d.reportId+
        '.pdf'
      );

  const folderId=
    cfg_(
      '審判報告書PDF保存フォルダID'
    )||
    cfg_(
      '公式記録PDF保存フォルダID'
    );

  const folder=
    folderId
      ?DriveApp.getFolderById(
        folderId
      )
      :DriveApp.getRootFolder();

  const pdfFile=
    folder.createFile(
      pdf
    );

  DriveApp.getFileById(
    tmp.getId()
  ).setTrashed(true);

  if(typeof fileRefereeReportPdf_==='function'){
    return fileRefereeReportPdf_(pdfFile,d.matchId);
  }
  return pdfFile.getUrl();
}

function htmlEsc_(v){
  return String(v??'')
    .replace(/&/g,'&amp;')
    .replace(/</g,'&lt;')
    .replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;');
}


/**
 * メール・LINEに載せるWebアプリのURL（本番の /exec）
 * エディタやトリガーから実行すると ScriptApp.getService().getUrl() がテスト用の /dev を返すことがあり、
 * /dev は本人しか開けない（スマホや LINE から開けない）ため使わない。
 * システム設定「WebアプリURL」（/exec）を最優先にする。
 */
/**
 * Webアプリのページが開かれたとき、そのURL（/exec）を覚える。システム設定「WebアプリURL」が違っていたら直す
 *  ・古いURL・ほかのシステムのURLが入っていても、リンク集やメールのリンクが正しいURLになる
 *  ・同じURLのときは何もしない（ページを開くたびにシートへ書かない）
 */
function rememberWebAppUrl_(){
  try{
    const live=String(ScriptApp.getService().getUrl()||'');
    if(!/\/exec$/.test(live)) return;
    const props=PropertiesService.getScriptProperties();
    if(props.getProperty('WEBAPP_URL')===live) return;
    props.setProperty('WEBAPP_URL',live);
    if(String(cfg_('WebアプリURL')||'').trim()!==live) setCfg_('WebアプリURL',live,'本番のWebアプリURL（末尾が /exec）。ページを開くと自動で直る');
  }catch(e){}
}

function webAppBaseUrl_(){
  // Webアプリを開いたときに覚えた、本当に動いているURL（rememberWebAppUrl_）を最優先にする
  const seen=String(PropertiesService.getScriptProperties().getProperty('WEBAPP_URL')||'').trim();
  if(/\/exec$/.test(seen)) return seen;
  const cfgUrl=String(cfg_('WebアプリURL')||'').trim();
  if(/\/exec$/.test(cfgUrl)) return cfgUrl;
  let live='';
  try{ live=String(ScriptApp.getService().getUrl()||''); }catch(e){}
  if(/\/exec$/.test(live)) return live;
  return '';
}


function refereeReportUrlForMatch_(base,matchId){
  return (base||webAppBaseUrl_())+
    '?page=referee'+
    (matchId?'&match='+encodeURIComponent(matchId):'');
}


// =====================================================
// 主審メールアドレスのテスト送信（公式記録画面から呼び出し）
// =====================================================

function sendRefereeTestMail(email,matchId,refereeName){
  const to=String(email||'').trim();

  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to)){
    throw new Error('メールアドレスの形式を確認してください。');
  }

  if(MailApp.getRemainingDailyQuota()<1){
    throw new Error('本日のメール送信上限に達しています。明日以降に再度お試しください。');
  }

  let matchLine='';

  if(matchId){
    try{
      const m=findMatch_(matchId);
      const h=findTeam_(m['ホームチームID']);
      const a=findTeam_(m['アウェイチームID']);

      matchLine=
        [
          m['節／ラウンド']||'',
          (h['チーム名']||h['クラブ名']||'')+' vs '+(a['チーム名']||a['クラブ名']||''),
          matchDateYmd_(m)
        ].filter(Boolean).join('｜');
    }catch(e){}
  }

  const base=webAppBaseUrl_();
  const name=String(refereeName||'').trim();

  mail_(
    'テストメール',
    to,
    '【テスト】公式記録システムからのメール受信確認',
    '<p>'+(name?htmlEsc_(name)+' 様':'主審 様')+'</p>'+
    '<p>このメールは、公式記録の承認依頼が正しく届くかを確認するためのテストメールです。<br>'+
    'このメールが届いていれば、試合後の承認依頼メールも同じアドレスに届きます。</p>'+
    (matchLine?'<p>対象試合：'+htmlEsc_(matchLine)+'</p>':'')+
    (base
      ?'<p>審判報告書の入力ページ：<br><a href="'+refereeReportUrlForMatch_(base,matchId)+'">'+
        htmlEsc_(refereeReportUrlForMatch_(base,matchId))+'</a></p>'
      :'')+
    '<p style="color:#64748b;font-size:12px">迷惑メールフォルダに振り分けられていた場合は、差出人を受信許可に設定してください。<br>'+
    '返信は不要です。</p>',
    matchId||'',
    ''
  );

  return{
    ok:true,
    to,
    message:to+' にテストメールを送信しました。受信できたか主審に確認してください。'
  };
}


// =====================================================
// 入力候補
// =====================================================

/** 高速化：読むだけの処理は同じシートを1回だけ読む */
function getInputOptionsV2() {
  return withReadMemo_(function () { return getInputOptionsV2Read_(); });
}

function getInputOptionsV2Read_() {
  const grouped = {
    '会場名': [],
    'ピッチ': [],
    'ピッチ状態': [],
    '天候': [],
    '風': [],
    'クラブ名': []
  };

  const master =
    ss_().getSheetByName(
      '入力候補マスター'
    );

  if (master) {
    const vals =
      master.getDataRange().getValues();

    if (vals.length >= 2) {
      const h = vals[0];
      const idx = {};

      h.forEach(
        (x,i)=>idx[String(x)] = i
      );

      vals.slice(1).forEach(r => {
        const cat =
          String(
            r[idx['カテゴリ']] || ''
          );

        const val =
          String(
            r[idx['値']] || ''
          );

        const enabled =
          String(
            r[idx['有効']] || '有効'
          );

        const order =
          Number(
            r[idx['表示順']] || 999
          );

        if (
          grouped[cat] &&
          val &&
          enabled !== '無効'
        ) {
          grouped[cat].push({
            value: val,
            order
          });
        }
      });
    }
  }

  Object.keys(grouped).forEach(k => {
    grouped[k] = grouped[k]
      .sort((a,b)=>a.order-b.order)
      .map(x=>x.value)
      .filter(
        (v,i,a)=>a.indexOf(v)===i
      );
  });

  // 記録担当クラブ：入力候補マスターの「クラブ名」（統一記載一覧の正式表記）があればそれを使う
  const universities = grouped['クラブ名'].length ? grouped['クラブ名'] :
    objs_(シート.チーム)
      .map(r=>
        String(r['クラブ名'] || '')
      )
      .filter(Boolean)
      .filter(
        (v,i,a)=>a.indexOf(v)===i
      )
      .sort();

  return {
    venues: grouped['会場名'],
    pitches: grouped['ピッチ'],
    pitchConditions:
      grouped['ピッチ状態'],
    weather: grouped['天候'],
    wind: grouped['風'],
    universities
  };
}


// =====================================================
// 現行公式記録送信 V2
// =====================================================

function normalizeSecondCautionDisciplinary_(rows){
  const result=[];
  const counts={};
  const autoCreated={};

  (rows||[]).forEach(d=>{
    const x=
      Object.assign(
        {},
        d||{}
      );

    const key=
      String(x.teamId||'')+
      '__'+
      String(x.playerId||'');

    if(x.type==='警告'){
      // 2枚目の警告そのものは、その理由を保持して記録
      result.push(x);

      if(x.reason){
        counts[key]=
          (counts[key]||0)+1;

        if(
          counts[key]===2 &&
          !autoCreated[key]
        ){
          result.push(
            Object.assign(
              {},
              x,
              {
                type:'警告2枚による退場',
                reason:'CS'
              }
            )
          );

          autoCreated[key]=true;
        }
      }

      return;
    }

    if(
      x.type==='警告2枚による退場'
    ){
      // 直前の2枚警告から自動生成済みなら重複保存しない
      if(autoCreated[key]){
        return;
      }

      x.reason='CS';
    }

    result.push(x);
  });

  return result;
}

function evaluatePkSequenceServer_(
  kicks,
  firstTeamId,
  homeId,
  awayId
){
  const firstId=
    String(firstTeamId||'');

  if(
    firstId!==String(homeId) &&
    firstId!==String(awayId)
  ){
    throw new Error(
      'PK戦の先攻チームが不正です。'
    );
  }

  const secondId=
    firstId===String(homeId)
      ?String(awayId)
      :String(homeId);

  let firstKicks=0;
  let secondKicks=0;
  let firstScore=0;
  let secondScore=0;
  let finished=false;
  let winnerId='';

  const checkFinished=()=>{
    if(
      firstKicks<=5 &&
      secondKicks<=5
    ){
      const firstRemain=
        Math.max(
          0,
          5-firstKicks
        );

      const secondRemain=
        Math.max(
          0,
          5-secondKicks
        );

      if(
        firstScore>
        secondScore+secondRemain
      ){
        finished=true;
        winnerId=firstId;
        return;
      }

      if(
        secondScore>
        firstScore+firstRemain
      ){
        finished=true;
        winnerId=secondId;
        return;
      }
    }

    if(
      firstKicks===5 &&
      secondKicks===5 &&
      firstScore!==secondScore
    ){
      finished=true;
      winnerId=
        firstScore>secondScore
          ?firstId
          :secondId;
      return;
    }

    if(
      firstKicks>=5 &&
      secondKicks>=5 &&
      firstKicks===secondKicks &&
      firstScore!==secondScore
    ){
      finished=true;
      winnerId=
        firstScore>secondScore
          ?firstId
          :secondId;
    }
  };

  (kicks||[]).forEach((k,i)=>{
    if(finished){
      throw new Error(
        'PK戦の決着後に余分なキックが記録されています。'
      );
    }

    const expected=
      i%2===0
        ?firstId
        :secondId;

    const teamId=
      String(k.teamId||'');

    if(teamId!==expected){
      throw new Error(
        'PK戦のキック順が先攻・後攻の交互になっていません。'
      );
    }

    if(teamId===firstId){
      firstKicks++;

      if(k.result==='○'){
        firstScore++;
      }

    }else{
      secondKicks++;

      if(k.result==='○'){
        secondScore++;
      }
    }

    checkFinished();
  });

  return{
    finished,
    winnerId,
    firstKicks,
    secondKicks,
    firstScore,
    secondScore
  };
}


function submitOfficialRecordV2(p) {
  if (!p || !p.matchId) {
    throw new Error(
      '試合IDがありません。'
    );
  }

  // 同時・二重の提出で同じ版番号が重複しないよう、1件ずつ処理する（v17）
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(30000)) {
    throw new Error('他の提出を処理中です。少し待ってからもう一度提出してください。');
  }
  try {
    return submitOfficialRecordV2Locked_(p);
  } finally {
    lock.releaseLock();
  }
}


function submittedAtMs_(v) {
  if (Object.prototype.toString.call(v) === '[object Date]') return v.getTime();
  const t = new Date(String(v).replace(' ', 'T') + '+09:00').getTime();
  return isNaN(t) ? 0 : t;
}


function submitOfficialRecordV2Locked_(p) {
  // 直前（60秒以内）に同じ試合が提出されていれば、二重送信として扱う
  const recent = objs_(シート.公式記録).filter(r =>
    String(r['試合ID']) === String(p.matchId) &&
    r['提出日時'] &&
    (Date.now() - submittedAtMs_(r['提出日時'])) < 60000
  );
  if (recent.length) {
    const last = recent[recent.length - 1];
    return {
      ok: true,
      recordId: String(last['公式記録ID']),
      version: Number(last['版']),
      message: '直前に同じ試合の公式記録が提出済みです（二重送信を防止しました）。修正する場合は1分ほどおいてから再提出してください。'
    };
  }

  ensureHeader_(
    シート.得点,
    ['時間帯','時間入力方式']
  );

  ensureHeader_(
    シート.公式記録,
    [
      'PK戦先攻チームID',
      '延長戦有無',
      'PK戦有無'
    ]
  );

  ensureHeader_(
    シート.警告退場,
    ['情報源','時間帯','時間入力方式']
  );

  ensureHeader_(
    シート.試合イベント,
    ['時間帯','時間入力方式']
  );

  ensureHeader_(
    シート.選手試合記録,
    ['延長前半シュート','延長後半シュート']
  );

  const m =
    findMatch_(p.matchId);

  // 確定済みの試合は「訂正」扱い（運営パスコードと訂正理由が必要。Revision.gs）
  if(typeof revCheckCorrection_==='function'){
    revCheckCorrection_(p);
  }

  // 出場停止の選手が先発・ベンチにいないか（書き込み前に確認）
  assertNoSuspendedPlayers_(
    p.matchId,
    p.players
  );

  // 記録同士の食い違い（退いた後の得点・退場後の交代・背番号の重なりなど）。入力画面と同じ決まり（RecordCheck.gs）
  if(typeof orCheckConsistency_==='function'){
    orCheckConsistency_(p);
  }

  const homeId =
    String(m['ホームチームID']);

  const awayId =
    String(m['アウェイチームID']);

  const extraTimeEnabled=
    p.matchFormat &&
    String(p.matchFormat.extraTime||'');

  const pkEnabled=
    p.matchFormat &&
    String(p.matchFormat.pk||'');

  if(
    !['あり','なし'].includes(extraTimeEnabled) ||
    !['あり','なし'].includes(pkEnabled)
  ){
    throw new Error(
      '延長戦・PK戦のあり／なしを選択してください。'
    );
  }

  const previous =
    objs_(シート.公式記録)
      .filter(r=>
        String(r['試合ID'])===
        String(p.matchId)
      );

  const ver =
    previous.reduce(
      (mx,r)=>
        Math.max(
          mx,
          Number(r['版'])||0
        ),
      0
    )+1;

  const rid=id_('OR');

  // ---------------------------------
  // 現在版の子データを入れ替え
  // ---------------------------------
  delWhere_(
    シート.チーム記録,
    r=>
      String(r['試合ID'])===
      String(p.matchId)
  );

  delWhere_(
    シート.選手試合記録,
    r=>
      String(r['試合ID'])===
      String(p.matchId)
  );

  const oldGoalIds =
    objs_(シート.得点)
      .filter(r=>
        String(r['試合ID'])===
        String(p.matchId)
      )
      .map(r=>
        String(r['得点ID'])
      );

  if (oldGoalIds.length) {
    delWhere_(
      シート.得点経過,
      r=>
        oldGoalIds.includes(
          String(r['得点ID'])
        )
    );
  }

  delWhere_(
    シート.得点,
    r=>
      String(r['試合ID'])===
      String(p.matchId)
  );

  // PK戦記録は毎回いったん削除する。
  // 前版のPK記録が残る問題を防ぐ。
  const incomingPkKicks =
    p.pk &&
    Array.isArray(p.pk.kicks)
      ? p.pk.kicks
      : [];

  if(
    pkEnabled==='あり' &&
    incomingPkKicks.length
  ){
    const pkCheck=
      evaluatePkSequenceServer_(
        incomingPkKicks,
        p.pk && p.pk.firstTeamId,
        homeId,
        awayId
      );

    if(!pkCheck.finished){
      throw new Error(
        'PK戦がまだ決着していません。'
      );
    }
  }

  delWhere_(
    シート.PK戦,
    r=>
      String(r['試合ID'])===
      String(p.matchId)
  );

  delWhere_(
    シート.試合イベント,
    r=>
      String(r['試合ID'])===
        String(p.matchId) &&
      String(r['イベント種別'])===
        '交代'
  );

  delWhere_(
    シート.警告退場,
    r=>
      String(r['試合ID'])===
        String(p.matchId) &&
      String(
        r['情報源']||''
      )==='公式記録'
  );

  const goals =
    Array.isArray(p.goals)
      ?p.goals
      :[];

  const players =
    Array.isArray(p.players)
      ?p.players
      :[];

  const substitutions =
    Array.isArray(p.substitutions)
      ?p.substitutions
      :[];

  const disciplinary =
    normalizeSecondCautionDisciplinary_(
      Array.isArray(p.disciplinary)
        ?p.disciplinary
        :[]
    );

  if(extraTimeEnabled==='なし'){
    const hasExtra=
      goals.some(g=>
        String(g.period||'').startsWith('延長')
      ) ||
      substitutions.some(s=>
        String(s.period||'').startsWith('延長')
      ) ||
      disciplinary.some(d=>
        String(d.period||'').startsWith('延長')
      );

    if(hasExtra){
      throw new Error(
        '延長戦「なし」ですが、延長時間帯の記録があります。'
      );
    }
  }

  // ---------------------------------
  // 得点イベントから自動集計
  // ---------------------------------
  const score = {
    firstHome: 0,
    firstAway: 0,
    secondHome: 0,
    secondAway: 0,
    extraHome: 0,
    extraAway: 0
  };

  let extraUsed = false;

  goals.forEach(g => {
    const tid =
      String(g.teamId || '');

    const period =
      String(g.period || '前半');

    if (period === '前半') {
      if (tid === homeId) {
        score.firstHome++;
      }

      if (tid === awayId) {
        score.firstAway++;
      }

    } else if (
      period === '後半'
    ) {
      if (tid === homeId) {
        score.secondHome++;
      }

      if (tid === awayId) {
        score.secondAway++;
      }

    } else if (
      period === '延長前半' ||
      period === '延長後半'
    ) {
      extraUsed = true;

      if (tid === homeId) {
        score.extraHome++;
      }

      if (tid === awayId) {
        score.extraAway++;
      }
    }
  });

  // ---------------------------------
  // 個人シュートから自動集計（延長前半・延長後半を含む）
  // ---------------------------------
  const teamShots_=(tid,h)=>
    players
      .filter(x=>String(x.teamId)===tid)
      .reduce((sum,x)=>sum+num_(x['shots'+h]),0);

  p.teamStats =
    p.teamStats ||
    {home:{},away:{}};

  p.teamStats.home =
    p.teamStats.home || {};

  p.teamStats.away =
    p.teamStats.away || {};

  [1,2,3,4].forEach(h=>{
    p.teamStats.home['shots'+h]=teamShots_(homeId,h);
    p.teamStats.away['shots'+h]=teamShots_(awayId,h);
  });

  // ---------------------------------
  // オフサイドを取られた数だけ、相手チームの間接FKがある（延長も含む）
  // 足りない場合は補正する
  // ---------------------------------
  [
    [p.teamStats.home, p.teamStats.away],
    [p.teamStats.away, p.teamStats.home]
  ].forEach(([ts,opp])=>{
    [1,2,3,4].forEach(h=>{
      ts['ifk'+h]=
        Math.max(
          num_(ts['ifk'+h]),
          num_(opp['off'+h])
        );
    });
  });

  // ---------------------------------
  // 公式記録
  // ---------------------------------
  append_(シート.公式記録, {
    '公式記録ID': rid,
    '試合ID': p.matchId,
    '版': ver,
    '前半キックオフ':
      p.firstKickoff || '',
    '前半ホーム得点':
      score.firstHome,
    '前半アウェイ得点':
      score.firstAway,
    '後半ホーム得点':
      score.secondHome,
    '後半アウェイ得点':
      score.secondAway,
    '延長ホーム得点':
      extraUsed
        ?score.extraHome
        :'',
    '延長アウェイ得点':
      extraUsed
        ?score.extraAway
        :'',
    '延長戦有無':
      extraTimeEnabled,
    'PK戦有無':
      pkEnabled,
    'PK戦ホーム':
      pkEnabled==='あり'
        ?numBlank_(
          p.pk && p.pk.home
        )
        :'',
    'PK戦アウェイ':
      pkEnabled==='あり'
        ?numBlank_(
          p.pk && p.pk.away
        )
        :'',
    'PK戦先攻チームID':
      pkEnabled==='あり' &&
      p.pk &&
      p.pk.firstTeamId
        ?p.pk.firstTeamId
        :'',
    '記録状態':'承認待ち',
    '提出日時':now_(),
    '日時':
      (
        p.matchInfo &&
        p.matchInfo.dateTime
      ) ||
      m['実施日'] ||
      m['開催予定日'] ||
      '',
    '会場名':
      p.matchInfo &&
      p.matchInfo.venue || '',
    '試合時間':
      p.matchInfo &&
      p.matchInfo.duration ||
      '90分',
    'ピッチ':
      p.matchInfo &&
      p.matchInfo.pitch || '',
    'ピッチ状態':
      p.matchInfo &&
      p.matchInfo.pitchCondition || '',
    'WBGT':
      p.matchInfo &&
      p.matchInfo.wbgt || '',
    '天候':
      p.matchInfo &&
      p.matchInfo.weather || '',
    '風':
      p.matchInfo &&
      p.matchInfo.wind || '',
    '記録担当者':
      p.matchInfo &&
      p.matchInfo.recorder || '',
    '記録担当クラブ':
      p.matchInfo &&
      p.matchInfo.recorderUniversity || '',
    '主審':
      p.officials &&
      p.officials.referee || '',
    '副審1':
      p.officials &&
      p.officials.ar1 || '',
    '副審2':
      p.officials &&
      p.officials.ar2 || '',
    '第4の審判':
      p.officials &&
      p.officials.fourth || '',
    '後半キックオフ':
      p.secondKickoff || '',
    '主審メール':
      p.officials &&
      p.officials.refereeEmail || '',
    '確定PDF URL':''
  });

  saveTeam_(
    p.matchId,
    homeId,
    p.teamStats.home
  );

  saveTeam_(
    p.matchId,
    awayId,
    p.teamStats.away
  );

  // ---------------------------------
  // 交代時間を選手記録へ反映
  // 例：
  // 前半47分 → 45+2
  // 後半18分 → 63
  // 後半47分 → 90+2
  // ---------------------------------
  const playerById =
    Object.fromEntries(
      players.map(x=>[
        String(x.playerId||''),
        x
      ])
    );

  substitutions.forEach(s=>{
    const displayTime=
      officialEventTime_(
        s.period,
        s.time,
        '相対'
      );

    const outPlayer=
      playerById[
        String(s.outId||'')
      ];

    const inPlayer=
      playerById[
        String(s.inId||'')
      ];

    if(outPlayer){
      outPlayer.outTime=
        displayTime;
    }

    if(inPlayer){
      inPlayer.inTime=
        displayTime;
    }
  });

  // ---------------------------------
  // 個人記録
  // ---------------------------------
  players.forEach(x =>
    append_(
      シート.選手試合記録,
      {
        '試合ID':p.matchId,
        '選手ID':
          x.playerId||'',
        'チームID':
          x.teamId||'',
        '先発':
          x.starter?'○':'',
        '出場':
          x.played?'○':'',
        'シュート計':
          num_(x.shots1)+
          num_(x.shots2)+
          num_(x.shots3)+
          num_(x.shots4),
        '得点':
          num_(x.goals),
        'アシスト':
          num_(x.assists),
        '背番号':
          x.number||'',
        '位置':
          x.position||'',
        '前半シュート':
          num_(x.shots1),
        '後半シュート':
          num_(x.shots2),
        '延長前半シュート':
          num_(x.shots3),
        '延長後半シュート':
          num_(x.shots4),
        '交代IN時間':
          x.inTime||'',
        '交代OUT時間':
          x.outTime||''
      }
    )
  );

  // ---------------------------------
  // 得点記録
  // ---------------------------------
  let runningHome = 0;
  let runningAway = 0;

  goals.forEach(g => {
    const gid=id_('G');

    const beforeHome =
      runningHome;

    const beforeAway =
      runningAway;

    if (
      String(g.teamId)===homeId
    ){
      runningHome++;
    }

    if (
      String(g.teamId)===awayId
    ){
      runningAway++;
    }

    append_(シート.得点, {
      '得点ID': gid,
      '試合ID': p.matchId,
      '時間': g.time || '',
      '時間帯':
        g.period || '',
      '時間入力方式':
        '相対',
      'チームID':
        g.teamId || '',
      '得点者選手ID':
        g.scorerId || '',
      'アシスト選手ID':
        g.assistId || '',
      '得点種別':
        g.goalType || '',
      '開始状況':
        g.startType || '',
      '得点前ホーム':
        beforeHome,
      '得点前アウェイ':
        beforeAway,
      '得点後ホーム':
        runningHome,
      '得点後アウェイ':
        runningAway
    });

    const seq =
      Array.isArray(
        g.sequenceTokens
      )
        ?g.sequenceTokens
        :String(
          g.sequence || ''
        )
        .split(/\s+/)
        .filter(Boolean);

    seq.forEach((token,i)=>
      append_(
        シート.得点経過,
        {
          '得点ID':gid,
          '順番':i+1,
          '経過内容':token
        }
      )
    );
  });

  // ---------------------------------
  // PKキッカー記録
  // ---------------------------------
  (
    pkEnabled==='あり'
      ?incomingPkKicks
      :[]
  ).forEach(k=>{
    append_(シート.PK戦,{
      '試合ID':p.matchId,
      '順番':k.order||k.number||'',
      'チームID':k.teamId||'',
      '選手ID':k.playerId||'',
      '結果':k.result||''
    });
  });

  // ---------------------------------
  // 交代
  // ---------------------------------
  substitutions
    .forEach(s =>
      append_(
        シート.試合イベント,
        {
          'イベントID':
            id_('EV'),
          '試合ID':
            p.matchId,
          '時間':
            s.time || '',
          '時間帯':
            s.period || '',
          '時間入力方式':
            '相対',
          'チームID':
            s.teamId || '',
          'イベント種別':
            '交代',
          '選手ID':'',
          '交代OUT選手ID':
            s.outId || '',
          '交代IN選手ID':
            s.inId || '',
          '詳細':
            s.period || '',
          '登録日時':
            now_()
        }
      )
    );

  // ---------------------------------
  // 警告・退場
  // ---------------------------------
  disciplinary
    .forEach(d =>
      append_(
        シート.警告退場,
        {
          '事象ID':
            id_('DISC'),
          '試合ID':
            p.matchId,
          '大会ID':
            m['大会ID'],
          '選手ID':
            d.playerId || '',
          'チームID':
            d.teamId || '',
          '時間':
            d.time || '',
          '時間帯':
            d.period || '',
          '時間入力方式':
            '相対',
          '種別':
            d.type || '',
          '理由':
            d.reason || '',
          '確認状態':
            d.type ===
              '一発退場'
              ?'要審査'
              :'確認待ち',
          '情報源':
            '公式記録'
        }
      )
    );

  // 入力画面の内容を保存（別の端末・運営が修正するときに読み込む。Revision.gs）
  if(typeof revSaveState_==='function'){
    revSaveState_(rid,p);
  }

  createApprovals_(
    rid,
    p.matchId,
    ver,
    p
  );

  // 一発退場があれば、承認を待たずに規律委員会へ通知（ReviewNotify.gs）
  // v19：通知の確認は約1分後にまとめて行う（提出した人を待たせない）
  scheduleRecalc_();

  return {
    ok: true,
    recordId: rid,
    version: ver,
    message:
      (p._correction
        ?'訂正版を提出し、3者へ再承認の依頼を送りました。'
        :'公式記録を提出し、承認依頼を作成しました。')
  };
}


