/**
 * メニューから：運営ダッシュボード（?page=admin）に入るパスコードを決める
 *  ・シートには書かず、スクリプトプロパティ（CFG_運営パスコード）に置く。確定済みの公式記録を訂正するときにも使う
 *  ・変えると、発行済みのログインは無効になる
 */
function setupAdminPasscode(){
  let ui;
  try{ ui=SpreadsheetApp.getUi(); }catch(e){
    throw new Error('スプレッドシートを開いて、メニュー「大会運営」→「設定」→「運営ダッシュボードのパスコードを決める」から実行してください');
  }
  const r=ui.prompt('運営ダッシュボードのパスコード','事務局の担当者がダッシュボードに入るためのパスコードを決めてください（8文字以上）。\n確定済みの公式記録を訂正するときにも使います。',ui.ButtonSet.OK_CANCEL);
  if(r.getSelectedButton()!==ui.Button.OK) return;
  const p=String(r.getResponseText()||'').trim();
  if(p.length<8){ ui.alert('8文字以上にしてください'); return; }
  PropertiesService.getScriptProperties().setProperty('CFG_運営パスコード',p);
  // 前にシートへ書いていた値は消す（シートを共有しても見えないように）
  const row=objs_(シート.設定).find(x=>String(x['設定項目'])==='運営パスコード');
  if(row) update_(シート.設定,row._row,{'設定値':'（スクリプトプロパティに保存済み）'});
  let url='';
  try{ url=ScriptApp.getService().getUrl()+'?page=admin'; }catch(e){}
  ui.alert('パスコードを保存しました','運営ダッシュボード：'+(url||'WebアプリのURL＋?page=admin'),ui.ButtonSet.OK);
}


/** 連盟の正式名（書類・メールの差出人）。システム設定「連盟の正式名」で変えられる */
function orgName_(){
  try{ const v=String(cfg_('連盟の正式名')||'').trim(); if(v) return v; }catch(e){}
  return '北海道社会人サッカー連盟';
}

/** メニューから：連盟の正式名と規律委員長名を入れる（書類・メールの差出人。あとから何度でも変えられる） */
function setupOrgName(){
  const ui=SpreadsheetApp.getUi();
  const r1=ui.prompt('連盟の正式名','決定通知書・メール・公式記録などの差出人に使う名前です。\nいま：'+orgName_()+'\n（空のままOKで、いまのまま）',ui.ButtonSet.OK_CANCEL);
  if(r1.getSelectedButton()!==ui.Button.OK) return;
  const v1=String(r1.getResponseText()||'').trim();
  if(v1) setCfg_('連盟の正式名',v1,'書類・メールの差出人（例：北海道社会人サッカー連盟）');
  const now=String(cfg_('規律委員長名')||'').trim();
  const r2=ui.prompt('規律委員長名','決定通知書の「規律委員会委員長」の欄と、メールの「規律委員長の○○でございます」に使います。\nいま：'+(now||'（未設定：名前を載せない）')+'\n（空のままOKで、いまのまま）',ui.ButtonSet.OK_CANCEL);
  if(r2.getSelectedButton()!==ui.Button.OK) return;
  const v2=String(r2.getResponseText()||'').trim();
  if(v2) setCfg_('規律委員長名',v2,'決定通知書・メールに載せる規律委員長の名前');
  ui.alert('保存しました','連盟の正式名：'+orgName_()+'\n規律委員長名：'+(String(cfg_('規律委員長名')||'')||'（未設定）'),ui.ButtonSet.OK);
}

;
// ==== Contacts.gs
/**
 * Contacts.gs v1
 * メールの送り先（連絡先）を、各クラブと事務局が自分で追加・変更できるようにする
 *
 *  ■ クラブの連絡先（「クラブの連絡先」タブ。クラブごとに1行）
 *    ・連絡先メール（複数可）：試合の連絡（本日試合・スタメン・日程変更・弁明のお願い・登録リマインドなど）の宛先
 *    ・決定通知メール（複数可）：処分の決定通知の宛先（空なら「処分通知の連絡先」タブ → チームの責任者・監督）
 *    ・変えられる人：各クラブ（チームページの「連絡先」タブ）と事務局（運営ダッシュボードの「チーム」→「クラブの連絡先」）
 *    ・空のときは今まで通り、チームマスターの責任者メール・監督メールに送る
 *    ・公式記録の承認依頼は、スタメン提出で選んだ承認者に送る（ここの連絡先は使わない）
 *  ■ 運営の連絡先（事務局だけが変えられる。運営ダッシュボード）
 *    ・管理者メール（事務局）・規律委員会メール・決定通知のCC・テスト中も届けるアドレス（システム設定に保存）
 */

var CT = { SHEET: 'クラブの連絡先', COLS: ['クラブコード', 'クラブ名', '連絡先メール', '決定通知メール', '更新者', '更新日時'], MAX: 10 };

function ctSheet_() {
  var ss = ss_(), sh = ss.getSheetByName(CT.SHEET);
  if (!sh) {
    sh = ss.insertSheet(CT.SHEET);
    sh.getRange(1, 1, 1, CT.COLS.length).setValues([CT.COLS]).setFontWeight('bold').setBackground('#E8F4FB');
    sh.setFrozenRows(1); sh.setColumnWidth(2, 200); sh.setColumnWidth(3, 360); sh.setColumnWidth(4, 300);
  }
  return sh;
}

/** 「a@x, b@y」→ ['a@x','b@y']（形を確かめる。重複は除く） */
function ctParse_(v, strict) {
  var list = (Array.isArray(v) ? v : String(v || '').split(/[,、;；\s\n]+/))
    .map(function (x) { return String(x || '').trim().replace(/^mailto:/i, ''); }).filter(Boolean);
  var out = [];
  list.forEach(function (m) {
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(m)) { if (strict) throw new Error('メールアドレスの形が正しくありません：' + m); return; }
    if (out.map(function (x) { return x.toLowerCase(); }).indexOf(m.toLowerCase()) < 0) out.push(m);
  });
  if (strict && out.length > CT.MAX) throw new Error('メールアドレスは' + CT.MAX + '件までにしてください');
  return out;
}

var CT_CACHE_ = null; // 1回の実行の中では読み直さない（軽くするため）

function ctRows_() {
  if (CT_CACHE_) return CT_CACHE_;
  var sh = ss_().getSheetByName(CT.SHEET);
  if (!sh || sh.getLastRow() < 2) return (CT_CACHE_ = {});
  var out = {};
  CT_CACHE_ = out;
  sh.getRange(2, 1, sh.getLastRow() - 1, CT.COLS.length).getValues().forEach(function (r, i) {
    var c = String(r[0] || '').trim();
    if (c) out[c] = { row: i + 2, code: c, univ: String(r[1] || ''), mails: ctParse_(r[2]), notice: ctParse_(r[3]), by: String(r[4] || ''), at: r[5] instanceof Date ? Utilities.formatDate(r[5], 'Asia/Tokyo', 'yyyy-MM-dd HH:mm') : String(r[5] || '') };
  });
  return out;
}

/** 試合の連絡の宛先（登録がなければ空） */
function ctMails_(code) { var r = ctRows_()[String(code || '')]; return r ? r.mails.slice() : []; }
/** 決定通知の宛先（登録がなければ空） */
function ctNotice_(code) { var r = ctRows_()[String(code || '')]; return r ? r.notice.slice() : []; }

function ctSave_(code, univ, mails, notice, by) {
  var sh = ctSheet_();
  var rows = ctRows_(), now = Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm');
  var vals = [code, univ, mails.join(', '), notice.join(', '), by, now];
  if (rows[code]) sh.getRange(rows[code].row, 1, 1, vals.length).setValues([vals]);
  else sh.appendRow(vals);
  if (typeof memoForget_ === 'function') memoForget_(CT.SHEET);
  CT_CACHE_ = null;
  if (typeof TN_MAP_CACHE_ !== 'undefined') TN_MAP_CACHE_ = null;
}

/** チームマスターの責任者・監督のメール（クラブの連絡先が空のときの宛先） */
function ctTeamDefaults_(code) {
  var out = [];
  objs_(シート.チーム).forEach(function (t) {
    if (rgTeamCode_(t['チームID']) !== code) return;
    [t['責任者メール'], t['監督メール']].forEach(function (x) { x = String(x || '').trim(); if (x && out.indexOf(x) < 0) out.push(x); });
  });
  return out;
}

/** 決定通知の今の宛先（クラブの連絡先 → 処分通知の連絡先タブ） */
function ctNoticeNow_(code, univ) {
  var n = ctNotice_(code);
  if (n.length) return { mails: n, from: 'クラブの連絡先' };
  try {
    var c = typeof snContactFor_ === 'function' ? snContactFor_(snContactsSheet_(), univ) : null;
    if (c) return { mails: ctParse_(c.mail), from: '処分通知の連絡先' };
  } catch (e) {}
  return { mails: [], from: '' };
}

function ctView_(code, univ) {
  var r = ctRows_()[code] || null;
  var def = ctTeamDefaults_(code), nt = ctNoticeNow_(code, univ);
  return {
    code: code, univ: univ,
    mails: r ? r.mails : [], notice: r ? r.notice : [],
    defaults: def, noticeNow: nt.mails, noticeFrom: nt.from,
    by: r ? r.by : '', at: r ? r.at : ''
  };
}

// ─────────────────────── クラブ（チームページの「連絡先」タブ） ───────────────────────

function lineupContacts(u, t) {
  var univ = lnAuth_(u, t);
  if (u === 'JIMU') throw new Error('連盟事務局の連絡先は、システム設定の「管理者メール」です');
  return ctView_(u, univ);
}

function lineupContactsSave(u, t, p) {
  var univ = lnAuth_(u, t);
  if (u === 'JIMU') throw new Error('連盟事務局の連絡先は、システム設定の「管理者メール」です');
  p = p || {};
  var by = String(p.by || '').trim();
  if (!by) throw new Error('変更した人の名前を入力してください');
  var mails = ctParse_(p.mails, true), notice = ctParse_(p.notice, true);
  var before = ctView_(u, univ);
  ctSave_(u, univ, mails, notice, by + '（' + univ + '）');
  try { log_('連絡先の変更', 'クラブの連絡先', u, { mails: before.mails, notice: before.notice }, { mails: mails, notice: notice }, by); } catch (e) {}
  // 事務局へ知らせる（Discord。メールは使わない）
  try {
    if (typeof tnStaff_ === 'function') tnStaff_('事務局', '【連絡先の変更】' + univ,
      '変更した人：' + by + '\n試合の連絡：' + (mails.join(', ') || '（空＝チームの責任者・監督のメール）') + '\n決定通知：' + (notice.join(', ') || '（空＝今まで通り）'));
  } catch (e) {}
  return { ok: true, message: '連絡先を保存しました。次の連絡から、このアドレスに届きます。', view: ctView_(u, univ) };
}

// ─────────────────────── 事務局（運営ダッシュボード） ───────────────────────

function adminContacts(tok) {
  adCheck_(tok);
  return withReadMemo_(function () {
    var univs = lnUnivs_();
    var list = Object.keys(univs).sort(function (a, b) { return univs[a] < univs[b] ? -1 : 1; }).map(function (c) { return ctView_(c, univs[c]); });
    var cfg = function (k) { return String(cfg_(k) || '').trim(); };
    return {
      univs: list,
      staff: {
        admin: cfg('管理者メール'), committee: cfg('規律委員会メール'),
        cc: cfg('処分通知CC') || (typeof SN_CC_DEFAULT !== 'undefined' ? SN_CC_DEFAULT : ''),
        testAllow: cfg('テスト中も届けるアドレス'), testing: !!(typeof testModeTo_ === 'function' && testModeTo_())
      }
    };
  });
}

function adminSaveContacts(tok, code, p) {
  adCheck_(tok);
  p = p || {};
  var univs = lnUnivs_();
  if (!univs[code]) throw new Error('クラブが見つかりません');
  var mails = ctParse_(p.mails, true), notice = ctParse_(p.notice, true);
  var before = ctView_(code, univs[code]);
  ctSave_(code, univs[code], mails, notice, '事務局');
  try { log_('連絡先の変更', 'クラブの連絡先', code, { mails: before.mails, notice: before.notice }, { mails: mails, notice: notice }, '運営ダッシュボード'); } catch (e) {}
  return { ok: true, message: univs[code] + ' の連絡先を保存しました', view: ctView_(code, univs[code]) };
}

function adminSaveStaffMails(tok, p) {
  adCheck_(tok);
  p = p || {};
  var admin = ctParse_(p.admin, true), committee = ctParse_(p.committee, true), cc = ctParse_(p.cc, true);
  var allow = ctParse_(p.testAllow, false);
  if (!admin.length) throw new Error('管理者メール（事務局）は1件以上入れてください');
  setCfg_('管理者メール', admin.join(','), '事務局のメール（複数可）');
  setCfg_('規律委員会メール', committee.join(','), '規律委員会のメール（複数可。空なら管理者メール）');
  setCfg_('処分通知CC', cc.join(','), '決定通知のCC（複数可）');
  setCfg_('テスト中も届けるアドレス', allow.join(','), 'テストモード中でも本来の宛先として届けるアドレス（テストに参加する選手・審判）');
  try { log_('連絡先の変更', '運営の連絡先', '', null, { admin: admin, committee: committee, cc: cc }, '運営ダッシュボード'); } catch (e) {}
  return { ok: true, message: '運営の連絡先を保存しました' };
}

;
// ==== Dashboard.gs
/**
 * Dashboard.gs v1
 * クラブサッカー大会運営システム｜運営ダッシュボード（要対応一覧）
 *
 * 「運営ダッシュボード」シートに、運営が今日やるべきことを一覧で書き出す。
 *   1. 公式記録の承認待ち（誰の承認が残っているか）
 *   2. 修正依頼が出ている公式記録
 *   3. 公式記録が未提出の試合（開催予定日を過ぎたもの）
 *   4. 審判報告書が未提出の試合
 *   5. 規律委員会の審査待ち（一発退場）
 *   6. 今後14日間の試合と出場停止の選手
 *   7. 延期中の試合（日程の再調整が必要）
 *
 * 使い方
 *  - runHourlyUpdate() を1時間おきのトリガーに設定する（処分・順位表・ダッシュボードをまとめて更新）
 *  - シートのメニュー「大会運営」→「集計・処分・ダッシュボードを今すぐ更新」でも実行できる
 */

var DB_SHEET = '運営ダッシュボード';
var DB_UPCOMING_DAYS = 14;
var DB_APPROVAL_ALERT_DAYS = 3; // 提出からこの日数を過ぎた承認待ちを赤字にする

// ─────────────────────── 公開関数 ───────────────────────

/** 処分 → 順位表 → ダッシュボードの順にまとめて更新（トリガー用） */
function runHourlyUpdate() {
  var errors = [];
  var run = function (label, fn) {
    try { fn(); } catch (e) { errors.push(label + '：' + (e && e.message || e)); }
  };
  var central = typeof isCentral_ !== 'function' || isCentral_();
  // 処分・決定通知・順位表・規律委員会への通知は全体システムだけ（リーグは全体から取り込む）
  if (central && typeof rebuildDiscipline === 'function') run('処分', rebuildDiscipline);
  if (central && typeof buildNoticeDrafts === 'function') run('決定通知の作成', buildNoticeDrafts);
  if (central && typeof rebuildStandings === 'function') run('順位表', rebuildStandings);
  if (central && typeof notifyReviewCases === 'function') run('処分審査の通知', notifyReviewCases);
  run('ダッシュボード', rebuildDashboard);
  // メールの上限で届かなかった公式記録の承認依頼を送り直す（Admin.gs）
  if (typeof retryApprovalMails_ === 'function') run('承認依頼の再送', retryApprovalMails_);
  // 問題事項：弁明の締切を過ぎたものを規律委員会へ回す（Incident.gs）
  if (typeof icExpireExplanations_ === 'function') run('弁明の締切', icExpireExplanations_);
  // 弁明・公式記録の承認の催促（TeamNotify.gs）
  if (typeof tnReminders_ === 'function') run('催促', tnReminders_);
  // 規律委員会へのLINE：週末の試合がすべて終わったら、まとめて送る（LineDigest.gs）
  if (central && typeof flushLineDigest_ === 'function') run('LINEのまとめ通知', function () { var m = flushLineDigest_(false); if (/^一部送れません/.test(m)) throw new Error(m); });
  if (typeof bumpPublicVersion_ === 'function') bumpPublicVersion_(); // ホームページの表示を最新にする
  // ホームページ（GitHub）へ書き出す（StaticSite.gs）。失敗しても集計は止めない（結果はシステム設定に記録）
  if (central && typeof publishStaticSite_ === 'function') { try { publishStaticSite_(false); } catch (e) {} }
  if (errors.length) throw new Error('一部の更新に失敗しました\n' + errors.join('\n'));
}

function rebuildDashboard() {
  var ss = typeof ss_ === 'function' ? ss_() : SpreadsheetApp.getActiveSpreadsheet();
  var read = function (n) { return dbRead_(ss, n); };
  var data = {
    comps: read('大会マスター'), teams: read('チームマスター'), players: read('選手マスター'),
    matches: read('試合マスター'), records: read('公式記録データ'), approvals: read('公式記録承認'),
    changes: read('日程変更履歴'),
    refReports: read('審判報告書'), sanctions: read('処分管理')
  };
  // 出場停止は Discipline.gs の計算結果をそのまま使う
  data.suspTargets = [];
  if (typeof computeDiscipline_ === 'function' && typeof readDisciplineData_ === 'function') {
    var d = computeDiscipline_(readDisciplineData_(ss));
    var byId = {};
    d.sanctions.forEach(function (s) { byId[s['処分ID']] = s; });
    data.suspTargets = d.targets
      .filter(function (t) { return t['状態'] !== '消化済'; })
      .map(function (t) { return { matchId: String(t['対象試合ID']), sanction: byId[t['処分ID']] || {}, order: t['順番'] }; });
  }
  var today = Utilities.formatDate(new Date(), Session.getScriptTimeZone() || 'Asia/Tokyo', 'yyyy-MM-dd');
  var blocks = computeDashboard_(data, today);
  dbBackupOnce_(ss);
  dbWrite_(ss, blocks, today);
  return blocks.map(function (b) { return b.title + '：' + b.rows.length; });
}

// ─────────────────── 計算本体（シート非依存） ───────────────────

function computeDashboard_(data, today) {
  var teamName = {};
  data.teams.forEach(function (t) {
    teamName[String(t['チームID'])] = String(t['略称'] || t['チーム名'] || t['クラブ名'] || t['チームID']);
  });
  var compName = {};
  data.comps.forEach(function (c) { compName[String(c['大会ID'])] = String(c['大会名'] || c['大会ID']); });
  var playerName = {};
  data.players.forEach(function (p) { playerName[String(p['選手ID'])] = String(p['氏名'] || p['選手ID']); });

  var matches = data.matches.map(function (m) {
    return {
      id: String(m['試合ID']), comp: String(m['大会ID']), round: String(m['節／ラウンド'] || ''),
      planned: dbDate_(m['開催予定日']), note: String(m['備考'] || ''), date: dbDate_(m['実施日']) || dbDate_(m['開催予定日']),
      home: String(m['ホームチームID']), away: String(m['アウェイチームID']),
      status: String(m['試合状態'] || ''), confirmed: String(m['結果確定'] || '') === '確定'
    };
  });
  var matchById = {};
  matches.forEach(function (m) { matchById[m.id] = m; });
  var vs = function (m) { return m ? (teamName[m.home] || m.home) + ' vs ' + (teamName[m.away] || m.away) : ''; };
  var comp = function (m) { return m ? (compName[m.comp] || m.comp) + (m.round ? ' ' + m.round : '') : ''; };

  // 試合ごとの最新版の公式記録
  var latest = {};
  data.records.forEach(function (r) {
    var mid = String(r['試合ID']);
    if (!latest[mid] || Number(r['版']) > Number(latest[mid]['版'])) latest[mid] = r;
  });

  var blocks = [];

  // 1. 承認待ち
  var pending = [];
  Object.keys(latest).forEach(function (mid) {
    var r = latest[mid];
    if (String(r['記録状態']) !== '承認待ち') return;
    var aps = data.approvals.filter(function (a) { return String(a['対象公式記録ID']) === String(r['公式記録ID']); });
    var waiting = aps.filter(function (a) { return String(a['承認状態']) === '未承認'; })
      .map(function (a) { return a['承認者区分'] + (a['承認者名'] ? '（' + a['承認者名'] + '）' : ''); });
    var days = dbDays_(dbDate_(r['提出日時']), today);
    pending.push({
      cells: [mid, comp(matchById[mid]), vs(matchById[mid]), '版' + r['版'], dbDate_(r['提出日時']),
        days === '' ? '' : days + '日', waiting.join('、') || '（承認行なし）'],
      alert: days !== '' && days >= DB_APPROVAL_ALERT_DAYS
    });
  });
  blocks.push({
    title: '公式記録の承認待ち', note: DB_APPROVAL_ALERT_DAYS + '日以上経過したものは赤字。承認者へ催促してください。',
    headers: ['試合ID', '大会・節', '対戦', '版', '提出日', '経過', '未承認'], rows: pending
  });

  // 2. 修正依頼
  var revision = [];
  Object.keys(latest).forEach(function (mid) {
    var r = latest[mid];
    if (String(r['記録状態']) !== '要修正') return;
    var req = data.approvals.filter(function (a) {
      return String(a['対象公式記録ID']) === String(r['公式記録ID']) && String(a['承認状態']) === '修正依頼';
    });
    revision.push({
      cells: [mid, comp(matchById[mid]), vs(matchById[mid]), '版' + r['版'],
        req.map(function (a) { return a['承認者区分']; }).join('、'),
        req.map(function (a) { return String(a['コメント'] || '').replace(/\s+/g, ' '); }).join(' ／ ')],
      alert: true
    });
  });
  blocks.push({
    title: '修正依頼が出ている公式記録', note: '記録担当者が修正して再提出すると、新しい版で承認依頼が送られます。',
    headers: ['試合ID', '大会・節', '対戦', '版', '依頼者', '修正内容'], rows: revision
  });

  // 3. 公式記録 未提出
  var noRecord = matches.filter(function (m) {
    return m.planned && m.planned < today && !latest[m.id] &&
      ['開催済', '中断', '延期', '中止', '記録対象外'].indexOf(m.status) < 0 && !m.confirmed;
  }).sort(dbByDate_).map(function (m) {
    return { cells: [m.id, comp(m), vs(m), m.planned, dbDays_(m.planned, today) + '日'], alert: true };
  });
  blocks.push({
    title: '公式記録が未提出の試合', note: '開催予定日を過ぎても公式記録が出ていない試合。延期・中止なら試合マスターの試合状態を更新してください。',
    headers: ['試合ID', '大会・節', '対戦', '開催予定日', '経過'], rows: noRecord
  });

  // 4. 審判報告書 未提出
  var reported = {};
  data.refReports.forEach(function (r) { reported[String(r['試合ID'])] = true; });
  var noRef = matches.filter(function (m) {
    return (latest[m.id] || m.status === '開催済') && !reported[m.id] && m.status !== '中止';
  }).sort(dbByDate_).map(function (m) {
    var rec = latest[m.id] || {};
    return { cells: [m.id, comp(m), vs(m), m.date, String(rec['主審'] || ''), String(rec['主審メール'] || '')], alert: false };
  });
  blocks.push({
    title: '審判報告書が未提出の試合', note: '主審には承認依頼メールで審判報告書の入力ページが案内されています。',
    headers: ['試合ID', '大会・節', '対戦', '試合日', '主審', '主審メール'], rows: noRef
  });

  // 5. 規律委員会の確認・決定待ち
  var review = data.sanctions.filter(function (s) {
    if (/TEST|KIRIN/i.test(String(s['大会ID'] || ''))) return false;
    var kind = String(s['処分種別']);
    if (String(s['委員会確認']) === '確認済' || /決定/.test(String(s['処分状態'] || ''))) return false;
    if (Number(s['残り試合数']) === 0) return false;
    return kind === '一発退場' || kind === '警告2枚による退場' || kind === '警告累積';
  }).map(function (s) {
    var m = matchById[String(s['発生試合ID'])];
    var st = String(s['委員会確認']) === '要修正' ? '差し戻し' : String(s['処分種別']) === '一発退場' ? '決定待ち' : '確認待ち';
    return {
      cells: [st, String(s['処分種別']), playerName[String(s['選手ID'])] || s['選手ID'], teamName[String(s['チームID'])] || s['チームID'] || '',
        String(s['発生試合ID']) + (m ? '（' + vs(m) + '）' : ''), String(s['対象試合'] || '')],
      alert: st !== '確認待ち'
    };
  });
  blocks.push({
    title: '規律委員会の確認・決定待ち',
    note: '規律委員会に届いたメール／LINEの確認ページで「確認」「決定」されると消えます。確認・決定が済むまで、チームへの決定通知は送られません。',
    headers: ['状態', '種別', '選手', 'チーム', '発生試合', '対象試合'], rows: review
  });

  // 6. 今後の試合と出場停止者
  var until = dbAddDays_(today, DB_UPCOMING_DAYS);
  var upcoming = matches.filter(function (m) {
    return m.date && m.date >= today && m.date <= until && ['開催済', '中断', '延期', '中止', '記録対象外'].indexOf(m.status) < 0;
  }).sort(dbByDate_).map(function (m) {
    var sus = data.suspTargets.filter(function (t) { return t.matchId === m.id; }).map(function (t) {
      var s = t.sanction;
      var kind = s['処分種別'] === '警告累積' ? '累積' : s['処分種別'] === '一発退場' ? '退場' : '警告2枚';
      return (playerName[String(s['選手ID'])] || s['選手ID']) + '（' + (teamName[String(s['チームID'])] || '') + '・' + kind + '）';
    });
    return { cells: [m.date, m.id, comp(m), vs(m), sus.join('、') || 'なし'], alert: sus.length > 0 };
  });
  blocks.push({
    title: '今後' + DB_UPCOMING_DAYS + '日間の試合と出場停止の選手',
    note: '出場停止の選手がいる試合は赤字。両チームの代表者会議で確認してください。',
    headers: ['試合日', '試合ID', '大会・節', '対戦', '出場停止の選手'], rows: upcoming
  });

  // 6-2. 直近7日の日程変更（試合マスターの手動変更を記録したもの）
  var since = dbAddDays_(today, -7);
  var changes = (data.changes || []).filter(function (c) { return dbDate_(c['変更日時']) >= since; })
    .sort(function (a, b) { return String(b['変更日時']) < String(a['変更日時']) ? -1 : 1; })
    .map(function (c) {
      var m = matchById[String(c['試合ID'])];
      return {
        cells: [String(c['変更日時']).slice(0, 16), String(c['試合ID']), vs(m), String(c['項目']),
          String(c['変更前']), String(c['変更後']), String(c['変更者'] || '')],
        alert: false
      };
    });
  blocks.push({
    title: '直近7日の日程変更', note: '試合マスターで日付・キックオフ・会場・試合状態（延期）を変更すると自動で記録されます。関係クラブ・審判への連絡を確認してください。',
    headers: ['変更日時', '試合ID', '対戦', '項目', '変更前', '変更後', '変更者'], rows: changes
  });

  // 6.5 中断（協議中）
  var suspended = matches.filter(function (m) { return m.status === '中断'; }).sort(dbByDate_).map(function (m) {
    return { cells: [m.id, comp(m), vs(m), m.planned, m.note || ''], alert: true };
  });
  blocks.push({
    title: '中断（協議中）の試合', note: '扱いが決まったら：継続試合は「延期」＋再開日、再試合は「中止」＋試合マスターに再試合を追加、打ち切り成立は「開催済」にして公式記録を提出してください。',
    headers: ['試合ID', '大会・節', '対戦', '開催日', '備考（中断の状況）'], rows: suspended
  });

  // 7. 延期中
  var postponed = matches.filter(function (m) { return m.status === '延期'; }).sort(dbByDate_).map(function (m) {
    return { cells: [m.id, comp(m), vs(m), m.planned], alert: false };
  });
  blocks.push({
    title: '延期中の試合', note: '新しい日程が決まったら、試合マスターの開催予定日と試合状態を更新してください。',
    headers: ['試合ID', '大会・節', '対戦', '元の開催予定日'], rows: postponed
  });

  return blocks;
}

// ───────────────────────── 書き出し ─────────────────────────

function dbWrite_(ss, blocks, today) {
  var sh = ss.getSheetByName(DB_SHEET) || ss.insertSheet(DB_SHEET, 0);
  sh.clear();
  var width = blocks.reduce(function (w, b) { return Math.max(w, b.headers.length); }, 2);
  var rows = [], fmt = [];
  var pad = function (r) { var x = r.slice(); while (x.length < width) x.push(''); return x; };

  var stamp = Utilities.formatDate(new Date(), Session.getScriptTimeZone() || 'Asia/Tokyo', 'yyyy-MM-dd HH:mm');
  rows.push(pad(['運営ダッシュボード', '最終更新 ' + stamp])); fmt.push('title');
  rows.push(pad(blocks.map(function (b) { return b.title + '：' + b.rows.length + '件'; }).slice(0, width)));
  fmt.push('summary');
  rows.push(pad([''])); fmt.push('');

  blocks.forEach(function (b) {
    rows.push(pad([b.title + '（' + b.rows.length + '件）'])); fmt.push('section');
    rows.push(pad([b.note])); fmt.push('note');
    if (!b.rows.length) {
      rows.push(pad(['対応が必要なものはありません'])); fmt.push('empty');
    } else {
      rows.push(pad(b.headers)); fmt.push('header');
      b.rows.forEach(function (r) { rows.push(pad(r.cells)); fmt.push(r.alert ? 'alert' : ''); });
    }
    rows.push(pad([''])); fmt.push('');
  });

  sh.getRange(1, 1, rows.length, width).setValues(rows).setFontFamily('Noto Sans JP').setVerticalAlignment('middle');
  fmt.forEach(function (f, i) {
    var r = sh.getRange(i + 1, 1, 1, width);
    if (f === 'title') { sh.getRange(i + 1, 1).setFontSize(14).setFontWeight('bold'); sh.getRange(i + 1, 2).setFontColor('#888888'); }
    else if (f === 'summary') r.setFontColor('#222222').setFontSize(9).setWrap(true);
    else if (f === 'section') { sh.getRange(i + 1, 1).setFontWeight('bold').setFontColor('#1976D2').setFontSize(12); r.setBorder(null, null, true, null, null, null, '#1976D2', SpreadsheetApp.BorderStyle.SOLID); }
    else if (f === 'note') sh.getRange(i + 1, 1).setFontColor('#888888').setFontSize(9);
    else if (f === 'empty') sh.getRange(i + 1, 1).setFontColor('#888888');
    else if (f === 'header') r.setFontWeight('bold').setBackground('#E8F4FB');
    else if (f === 'alert') r.setFontColor('#D84315');
  });
  sh.setColumnWidths(1, width, 150);
  sh.setFrozenRows(2);
}

// ───────────────────────── 補助 ─────────────────────────

function dbRead_(ss, name) {
  var vals;
  if (typeof READ_MEMO_ !== 'undefined' && READ_MEMO_ && typeof sheetValues_ === 'function') {
    vals = sheetValues_(name); // 読むだけの処理の中では使い回す（高速化）
    if (vals.length < 2) return [];
  } else {
    var sh = ss.getSheetByName(name);
    if (!sh || sh.getLastRow() < 2) return [];
    vals = sh.getDataRange().getValues();
  }
  var head = vals[0].map(String);
  return vals.slice(1).filter(function (r) { return r.join('') !== ''; }).map(function (r) {
    var o = {};
    head.forEach(function (h, i) { if (h) o[h] = r[i]; });
    return o;
  });
}

function dbDate_(v) {
  if (!v) return '';
  if (Object.prototype.toString.call(v) === '[object Date]') {
    return Utilities.formatDate(v, Session.getScriptTimeZone() || 'Asia/Tokyo', 'yyyy-MM-dd');
  }
  var m = String(v).trim().replace(/\//g, '-').match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  return m ? m[1] + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[3]).slice(-2) : '';
}

function dbDays_(from, to) {
  if (!from || !to) return '';
  return Math.round((Date.parse(to + 'T00:00:00Z') - Date.parse(from + 'T00:00:00Z')) / 86400000);
}

function dbAddDays_(ymd, n) {
  var d = new Date(Date.parse(ymd + 'T00:00:00Z') + n * 86400000);
  return d.toISOString().slice(0, 10);
}

function dbByDate_(a, b) { return a.date < b.date ? -1 : a.date > b.date ? 1 : (a.id < b.id ? -1 : 1); }

function dbBackupOnce_(ss) {
  var props = PropertiesService.getDocumentProperties();
  if (props.getProperty('DASHBOARD_BACKUP_DONE')) return;
  var sh = ss.getSheetByName(DB_SHEET);
  if (sh) {
    var stamp = Utilities.formatDate(new Date(), Session.getScriptTimeZone() || 'Asia/Tokyo', 'yyyyMMdd_HHmm');
    sh.copyTo(ss).setName(DB_SHEET + '_旧_' + stamp);
  }
  props.setProperty('DASHBOARD_BACKUP_DONE', '1');
}

;
// ==== Discipline.gs
/**
 * Discipline.gs v4
 * 北海道社会人サッカーリーグ 大会運営システム｜処分（出場停止）自動生成
 *
 * 入力 : 大会マスター / チームマスター / 試合マスター / 警告・退場記録
 * 出力 : 処分管理（再生成・手入力欄は保持） / 処分対象試合（全面再生成）
 *
 * 根拠（2026年度の開催要項）
 *  - 北海道サッカーリーグ要項26 と運営要項細則（警告3回で1試合停止）
 *  - 札幌・道央ブロックリーグ要項22（警告2回で1試合停止）
 *  - 道南ブロックリーグ要項22・道東道北ブロックリーグ要項22（警告3回で1試合停止）
 *  - ブロックリーグ決勝大会要項11（リーグの累積は持ち込まない）
 *  - 全国社会人選手権・全国クラブ選手権 北海道予選要項11（警告2回で1試合停止）
 *  - 北海道サッカー選手権要項10（JFA懲罰規程による）
 *  - JFA懲罰規程 別紙2 第2条・第4条・第5条・第6条・第10条
 *
 * 使い方
 *  1. このファイルを Apps Script プロジェクトに「Discipline.gs」として追加
 *  2. 初回のみ applyDisciplineRulesToMaster() を実行（大会マスターの規程欄を埋める）
 *  3. rebuildDiscipline() を実行（3者承認で公式記録が確定した直後に Code.gs から呼ぶ）
 *  4. 公式記録入力画面からは getSuspendedPlayersForMatch(matchId) で出場停止者を取得
 */

// ───────────────────────── 設定 ─────────────────────────

var DISC_SHEETS = {
  COMP: '大会マスター',
  TEAM: 'チームマスター',
  MATCH: '試合マスター',
  REG: '選手登録',
  EVENT: '警告・退場記録',
  SANCTION: '処分管理',
  TARGET: '処分対象試合'
};

// 大会IDの末尾（2026-L1 → L1）ごとの既定ルール。大会マスターの値が数値ならそちらを優先。
//  TOP 北海道サッカーリーグ／SD 札幌・道央／DN 道南／DT 道東・道北／BF ブロックリーグ決勝大会
//  SC 全国社会人選手権 北海道予選／CC 全国クラブチーム選手権 北海道予選／HC 北海道サッカー選手権（天皇杯）
var DISC_DEFAULT_RULES = {
  TOP: { threshold: 3, phaseReset: false, source: '北海道サッカーリーグ運営要項細則' },
  SD:  { threshold: 2, phaseReset: false, source: '札幌・道央ブロックリーグ要項22(1)' },
  DN:  { threshold: 3, phaseReset: false, source: '道南ブロックリーグ要項22(1)' },
  DT:  { threshold: 3, phaseReset: false, source: '道東・道北ブロックリーグ要項22(1)' },
  BF:  { threshold: 2, phaseReset: false, source: 'JFA懲罰規程別紙2第2条(1)（決勝大会要項に定めなし。2026-10-12 連盟確認）' },
  SC:  { threshold: 2, phaseReset: false, source: '全国社会人選手権北海道予選要項11(7)' },
  CC:  { threshold: 2, phaseReset: false, source: '全国クラブチーム選手権北海道予選要項11(7)' },
  HC:  { threshold: 2, phaseReset: false, source: 'JFA懲罰規程別紙2第2条(1)（北海道選手権要項10-8。2026-10-12 連盟確認）' }
};

// 持越先。大会終了・敗退時の未消化の退場処分は、ここに挙げた大会のうち
// 当該選手が登録されているチームの直近の試合で消化する。
//  各要項「未消化の出場停止処分は、当該チームまたは処分対象者が出場する直近の公式試合において消化」
//  （決勝大会要項11(5)(7)・各ブロックリーグ要項22(1)③）→ このシステムで扱うすべての大会へ持ち越す
//  このシステムの外の試合（地区リーグなど）で消化したときは、処分管理で手で「消化済」にする
var DISC_ALL_COMPS = ['TOP', 'SD', 'DN', 'DT', 'BF', 'SC', 'CC', 'HC'];
var DISC_CARRY_TARGETS = {
  TOP: DISC_ALL_COMPS, SD: DISC_ALL_COMPS, DN: DISC_ALL_COMPS, DT: DISC_ALL_COMPS,
  BF: DISC_ALL_COMPS, SC: DISC_ALL_COMPS, CC: DISC_ALL_COMPS, HC: DISC_ALL_COMPS
};

// 試合状態のうち「その試合では処分を消化しない」もの（延期は実施されるまで対象外）
// 中断：試合中に中断し、扱い（継続試合・再試合・打ち切り）を協議中。決まるまでは試合をしていない扱い
var DISC_SKIP_STATUS = ['中断', '延期', '中止', '開催不能', '記録対象外'];

// 警告・退場記録の確認状態のうち、処分計算から除外するもの
var DISC_INVALID_EVENT_STATUS = ['取消', '無効', '削除'];

// 一発退場の理由コードごとの最低停止試合数（JFA懲罰規程 別紙1）。規律委員会の決定前でも、この試合数は停止とする
//  S1 著しく不正なプレー → 2-3 最低2試合 ／ S3 人をかむ・つばを吐く → 2-6 最低3試合
//  それ以外は「次の1試合」を自動停止し、以降は規律委員会で決定
var DISC_RED_MIN_GAMES = { S1: 2, S3: 3 };

var DISC_TYPE = {
  YELLOW: '警告',
  SECOND_YELLOW: '警告2枚による退場',
  RED: '一発退場',
  ACCUM: '警告累積'
};

// 処分管理の列（既存列＋追加列）。足りない列は右端に自動追加する。
var DISC_SANCTION_HEADERS = [
  '処分ID', '選手ID', '発生試合ID', '大会ID', '処分種別', '停止試合数', '消化済試合数',
  '残り試合数', '処分状態', '対象試合', '決定日', '備考', '事象ID', 'チームID', '根拠', '自動計算メモ',
  '根拠条文', '認定事実', '委員会確認', '確認日時', '確認者', '確認コメント'
];
var DISC_TARGET_HEADERS = ['処分対象ID', '処分ID', '順番', '対象試合ID', '対象大会ID', '状態', '消化日', '備考'];

// ─────────────────────── 公開関数 ───────────────────────

/** Code.gs の ss_()（openById）があればそれを使う。Webアプリ・トリガーからでも同じシートを開く */
function discSs_() {
  return typeof ss_ === 'function' ? ss_() : SpreadsheetApp.getActiveSpreadsheet();
}

function readDisciplineData_(ss) {
  return {
    comps: readSheetObjects_(ss, DISC_SHEETS.COMP),
    teams: readSheetObjects_(ss, DISC_SHEETS.TEAM),
    matches: readSheetObjects_(ss, DISC_SHEETS.MATCH),
    events: readSheetObjects_(ss, DISC_SHEETS.EVENT),
    regs: readSheetObjects_(ss, DISC_SHEETS.REG),
    existing: readSheetObjects_(ss, DISC_SHEETS.SANCTION)
  };
}

/**
 * 指定試合で出場停止となる選手を、その場で計算して返す（シートには書き込まない）。
 * 公式記録入力の画面表示と提出時チェックで使う。
 * 戻り値: [{playerId, teamId, sanctionId, type, order, total, originMatchId, carried}]
 */
function getSuspensionsForMatch_(matchId) {
  // リーグシステム：処分は全体システムで計算したもの（取り込んだ「処分管理」「処分対象試合」）を使う
  if (typeof isLeague_ === 'function' && isLeague_()) return discFromSheets_(matchId);
  // 同じ処理の中では計算は1回だけ（運営クラブの画面は両チーム分を続けて呼ぶ）
  var memo = typeof READ_MEMO_ !== 'undefined' ? READ_MEMO_ : null;
  var result = memo && memo['\u0000disc'];
  if (!result && typeof DS_DISC_ !== 'undefined' && DS_DISC_) result = DS_DISC_; // シーズン全体テスト：同じ日の試合は1回の計算を使い回す（SeasonTest.gs）
  if (!result) { result = computeDiscipline_(readDisciplineData_(discSs_())); if (memo) memo['\u0000disc'] = result; }
  var byId = {};
  result.sanctions.forEach(function (s) { byId[s['処分ID']] = s; });
  return result.targets
    .filter(function (t) { return String(t['対象試合ID']) === String(matchId); })
    .map(function (t) {
      var s = byId[t['処分ID']] || {};
      return {
        playerId: String(s['選手ID'] || ''), teamId: String(s['チームID'] || ''),
        sanctionId: String(t['処分ID']), type: String(s['処分種別'] || ''),
        order: Number(t['順番']), total: Number(s['停止試合数']),
        originMatchId: String(s['発生試合ID'] || ''), carried: t['状態'] === '持越予定'
      };
    });
}

/** 処分管理・処分対象試合を再生成する。公式記録確定時に呼ぶ。 */
function rebuildDiscipline() {
  if (typeof isLeague_ === 'function' && isLeague_()) return { skipped: 'リーグシステムでは処分を計算しない（全体システムから取り込む）' };
  var ss = discSs_();
  var lock = LockService.getScriptLock();
  lock.waitLock(30000);
  try {
    var data = readDisciplineData_(ss);
    backupSanctionOnce_(ss);
    var result = computeDiscipline_(data);
    writeObjects_(ss, DISC_SHEETS.SANCTION, DISC_SANCTION_HEADERS, result.sanctions);
    writeObjects_(ss, DISC_SHEETS.TARGET, DISC_TARGET_HEADERS, result.targets);
    return { sanctions: result.sanctions.length, targets: result.targets.length, warnings: result.warnings };
  } finally {
    lock.releaseLock();
  }
}

/**
 * 指定試合で出場停止となる選手の一覧（公式記録入力のメンバー選択で警告表示に使う）。
 * 戻り値: [{playerId, teamId, sanctionId, type, order, total}]
 */
function getSuspendedPlayersForMatch(matchId) {
  var ss = discSs_();
  var targets = readSheetObjects_(ss, DISC_SHEETS.TARGET);
  var sanctions = readSheetObjects_(ss, DISC_SHEETS.SANCTION);
  var byId = {};
  sanctions.forEach(function (s) { byId[s['処分ID']] = s; });
  return targets
    .filter(function (t) { return String(t['対象試合ID']) === String(matchId); })
    .map(function (t) {
      var s = byId[t['処分ID']] || {};
      return {
        playerId: s['選手ID'], teamId: s['チームID'], sanctionId: t['処分ID'],
        type: s['処分種別'], order: Number(t['順番']), total: Number(s['停止試合数'])
      };
    });
}

/** 大会マスターの規程欄を要項の内容で埋める（初回のみ実行）。 */
function applyDisciplineRulesToMaster() {
  var red = '次の1試合自動停止＋規律委員会審査';
  var carry = '退場処分は大会終了時の未消化分を、当該チーム・選手が出場する直近の公式試合へ持越。累積警告は停止発生時・大会終了時に消滅';
  var values = {
    TOP: { '延長戦': 'なし', 'PK戦': 'なし', '累積警告基準': '3', '一発退場処理': red, '持越ルール': carry },
    SD:  { '延長戦': 'なし', 'PK戦': 'なし', '累積警告基準': '2', '一発退場処理': red, '持越ルール': carry },
    DN:  { '延長戦': 'なし', 'PK戦': 'なし', '累積警告基準': '3', '一発退場処理': red, '持越ルール': carry },
    DT:  { '延長戦': 'なし', 'PK戦': 'なし', '累積警告基準': '3', '一発退場処理': red, '持越ルール': carry },
    BF:  { '延長戦': 'なし', 'PK戦': 'なし', '累積警告基準': '2', '一発退場処理': red,
           '持越ルール': '各リーグの累積警告は持ち込まない。' + carry },
    SC:  { '延長戦': '代表決定戦のみ（20分）', 'PK戦': '○（80分で決まらなければPK戦）', '累積警告基準': '2', '一発退場処理': red,
           '持越ルール': '地区予選の累積警告は持ち込まない。' + carry },
    CC:  { '延長戦': '代表決定戦のみ（20分）', 'PK戦': '○（70分で決まらなければPK戦）', '累積警告基準': '2', '一発退場処理': red,
           '持越ルール': '地区予選の累積警告は持ち込まない。' + carry },
    HC:  { '延長戦': '決勝のみ（30分）', 'PK戦': '○（1回戦は90分後すぐPK戦）', '累積警告基準': '2', '一発退場処理': red,
           '持越ルール': '北海道リーグ・学生リーグの累積警告による出場停止は持ち越さない。' + carry }
  };
  var ss = discSs_();
  var sh = ss.getSheetByName(DISC_SHEETS.COMP);
  var all = sh.getDataRange().getValues();
  var head = all[0];
  var idCol = head.indexOf('大会ID');
  for (var r = 1; r < all.length; r++) {
    var v = values[compSuffix_(all[r][idCol])];
    if (!v) continue;
    Object.keys(v).forEach(function (k) {
      var c = head.indexOf(k);
      if (c >= 0) sh.getRange(r + 1, c + 1).setValue(v[k]);
    });
  }
}

// ─────────────────── 計算本体（シート非依存） ───────────────────

/**
 * @param {{comps:Object[], teams:Object[], matches:Object[], events:Object[], existing:Object[]}} data
 * @return {{sanctions:Object[], targets:Object[], warnings:string[]}}
 */
function computeDiscipline_(data) {
  var warnings = [];

  // --- 大会ルール
  var rules = {};
  var formats = {};
  data.comps.forEach(function (c) {
    var id = String(c['大会ID']);
    formats[id] = String(c['大会形式'] || '');
    var def = DISC_DEFAULT_RULES[compSuffix_(id)] || { threshold: 2, phaseReset: false, source: 'JFA懲罰規程別紙2第2条(1)' };
    var n = parseInt(c['累積警告基準'], 10);
    rules[id] = {
      threshold: isNaN(n) ? def.threshold : n,
      phaseReset: def.phaseReset,
      source: isNaN(n) ? def.source + '（大会マスター未設定のため既定値）' : def.source
    };
  });

  // --- 選手登録（持越先で当該選手が登録されているチームを特定する）
  var regSet = {};
  (data.regs || []).forEach(function (r) {
    if (String(r['登録状態'] || '有効') !== '有効') return;
    regSet[r['選手ID'] + '|' + r['チームID']] = true;
  });
  var hasRegs = Object.keys(regSet).length > 0;

  // --- チーム → クラブ
  var teamUniv = {};
  data.teams.forEach(function (t) { teamUniv[String(t['チームID'])] = String(t['クラブ名'] || t['チームID']); });

  // --- 試合を正規化して並べる
  var matches = data.matches.map(function (m) {
    return {
      id: String(m['試合ID']),
      comp: String(m['大会ID']),
      round: String(m['節／ラウンド'] || ''),
      date: normDate_(m['実施日']) || normDate_(m['開催予定日']),
      home: String(m['ホームチームID']),
      away: String(m['アウェイチームID']),
      status: String(m['試合状態'] || ''),
      confirmed: String(m['結果確定'] || '') === '確定',
      winner: String(m['勝者チームID'] || '')
    };
  }).sort(compareMatch_);
  var matchById = {};
  matches.forEach(function (m, i) { m.idx = i; matchById[m.id] = m; });

  // --- 事象を正規化（重複・無効・未確定試合を除外）
  var seen = {};
  var events = [];
  // 公式記録由来を優先（審判報告で補完された同じ退場は後から来て重複扱いになる）
  var srcRank = function (e) { return String(e['情報源'] || '') === '公式記録' ? 0 : 1; };
  data.events.slice().sort(function (a, b) { return srcRank(a) - srcRank(b); }).forEach(function (e) {
    var m = matchById[String(e['試合ID'])];
    if (!m) { warnings.push('試合マスターに無い試合の事象: ' + e['事象ID']); return; }
    var type = String(e['種別']);
    // 公式記録が確定した試合のみ。ただし一発退場は、公式記録・審判報告書が提出された時点で数える
    // （承認がそろう前に次の試合が来ても、出場停止にするため）
    var early = type === DISC_TYPE.RED && ['公式記録', '審判報告'].indexOf(String(e['情報源'] || '')) >= 0;
    if (!m.confirmed && !early) return;
    if (DISC_INVALID_EVENT_STATUS.indexOf(String(e['確認状態'])) >= 0) return;
    if ([DISC_TYPE.YELLOW, DISC_TYPE.SECOND_YELLOW, DISC_TYPE.RED].indexOf(type) < 0) return;
    // 退場は1試合1選手につき1回のみ。警告は時間まで一致したものを重複とみなす
    var key = type === DISC_TYPE.YELLOW
      ? [e['試合ID'], e['選手ID'], type, e['時間帯'], e['時間']].join('|')
      : [e['試合ID'], e['選手ID'], '退場'].join('|');
    if (seen[key]) { warnings.push('重複事象を除外: ' + e['事象ID'] + '（' + seen[key] + 'と同一）'); return; }
    seen[key] = e['事象ID'];
    events.push({
      id: String(e['事象ID']), match: m, comp: m.comp, player: String(e['選手ID']),
      team: String(e['チームID']), type: type, minute: absMinute_(e['時間帯'], e['時間']),
      reason: String(e['理由'] || '')
    });
  });
  events.sort(function (a, b) { return (a.match.idx - b.match.idx) || (a.minute - b.minute); });

  // --- 処分の生成
  var sanctions = []; // 内部表現
  // 退場（警告2枚・一発）
  events.forEach(function (e) {
    if (e.type === DISC_TYPE.YELLOW) return;
    var code = String(e.reason || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
    var minGames = e.type === DISC_TYPE.RED ? (DISC_RED_MIN_GAMES[code] || 1) : 1;
    sanctions.push({
      id: (e.type === DISC_TYPE.RED ? 'RED-' : 'SY-') + e.match.id + '-' + e.player,
      kind: e.type, isDismissal: true, player: e.player, team: e.team, comp: e.comp,
      origin: e.match, eventId: e.id, games: minGames, minGames: minGames, reason: code,
      basis: e.type === DISC_TYPE.RED
        ? (minGames > 1
          ? '退場（' + code + '）は最低' + minGames + '試合停止（別紙1）。追加は規律委員会で決定'
          : '退場は次の1試合自動停止、以降は規律委員会（要項・別紙1 2項）')
        : '同一試合2警告による退場：1試合停止（別紙1 1-2）'
    });
  });
  // 警告累積：選手×大会ごとに数える
  var counters = {};
  var byMatchPlayer = {};
  events.forEach(function (e) {
    var k = e.match.id + '|' + e.player;
    (byMatchPlayer[k] = byMatchPlayer[k] || []).push(e);
  });
  Object.keys(byMatchPlayer)
    .sort(function (a, b) { return byMatchPlayer[a][0].match.idx - byMatchPlayer[b][0].match.idx; })
    .forEach(function (k) {
      var list = byMatchPlayer[k];
      var first = list[0];
      var rule = rules[first.comp] || { threshold: 2, phaseReset: false, source: '既定' };
      var hasSecondYellow = list.some(function (e) { return e.type === DISC_TYPE.SECOND_YELLOW; });
      // 同一試合2警告の退場では、その2枚は累積に加算しない（別紙2第2条1）
      var yellows = hasSecondYellow ? [] : list.filter(function (e) { return e.type === DISC_TYPE.YELLOW; });
      if (!yellows.length) return;
      var bucket = first.player + '|' + first.comp + (rule.phaseReset ? '|' + phaseOf_(first.match) : '');
      var c = counters[bucket] = counters[bucket] || { n: 0, ids: [] };
      yellows.forEach(function (y) {
        c.n += 1; c.ids.push(y.id);
        if (c.n >= rule.threshold) {
          sanctions.push({
            id: 'ACC-' + y.match.id + '-' + y.player, kind: DISC_TYPE.ACCUM, isDismissal: false, player: y.player, team: y.team,
            comp: y.comp, origin: y.match, eventId: c.ids.join(','), games: 1,
            basis: '警告' + rule.threshold + '回で次の1試合停止（' + rule.source + '）'
          });
          c.n = 0; c.ids = []; // 停止発生で累積消滅
        }
      });
    });

  // --- 手入力値の引き継ぎ（処分IDで照合）
  var prev = {};
  data.existing.forEach(function (s) { if (s['処分ID']) prev[String(s['処分ID'])] = s; });
  sanctions.forEach(function (s) {
    var p = prev[s.id];
    s.manual = p || null;
    if (p && s.kind === DISC_TYPE.RED) {
      var decided = parseInt(p['停止試合数'], 10);
      if (!isNaN(decided) && decided >= 1) s.games = Math.max(decided, s.minGames || 1); // 規律委員会の決定を優先（最低試合数は下回らない）
    }
  });
  var dropped = data.existing.filter(function (s) {
    return s['処分ID'] && !sanctions.some(function (x) { return x.id === String(s['処分ID']); });
  });
  if (dropped.length) {
    warnings.push('根拠となる事象が無い旧処分 ' + dropped.length + ' 件を除外（バックアップシートに保存）: ' +
      dropped.map(function (s) { return s['処分ID']; }).join(', '));
  }

  // --- 消化対象試合の割り当て
  var targets = [];
  var byPlayerComp = {};
  sanctions.forEach(function (s) {
    var k = s.player + '|' + s.comp + '|' + s.team;
    (byPlayerComp[k] = byPlayerComp[k] || []).push(s);
    s.slots = [];
  });

  Object.keys(byPlayerComp).forEach(function (k) {
    var list = byPlayerComp[k];
    var team = list[0].team, comp = list[0].comp;
    var teamMatches = matches.filter(function (m) {
      return m.comp === comp && (m.home === team || m.away === team) &&
        DISC_SKIP_STATUS.indexOf(m.status) < 0;
    });
    teamMatches.forEach(function (m) {
      // この試合より前に発生し、まだ残りがある処分。退場を先に消化（別紙2第5条）
      var pending = list.filter(function (s) { return s.origin.idx < m.idx && s.slots.length < s.games; })
        .sort(function (a, b) {
          return (b.isDismissal - a.isDismissal) || (a.origin.idx - b.origin.idx);
        });
      if (!pending.length) return;
      var s = pending[0];
      s.slots.push({ match: m, carried: false });
    });
    // 大会内で消化しきれない分：退場は同じクラブの直近の公式試合へ持越、累積は消滅
    list.forEach(function (s) {
      if (s.slots.length >= s.games) return;
      if (!s.isDismissal) {
        if (competitionFinished_(matches, comp, team, formats)) s.expired = s.games - s.slots.length;
        return;
      }
      var univ = teamUniv[team];
      var lastIdx = s.slots.length ? s.slots[s.slots.length - 1].match.idx : s.origin.idx;
      var targetsOk = DISC_CARRY_TARGETS[compSuffix_(comp)] || [];
      var player = s.player;
      // 持越先の大会で、この選手の登録が1件もない場合（過去データから作った選手など）は、
      // 同じクラブのチームの試合を持越先とする
      var targetTeams = Object.keys(teamUniv).filter(function (t) {
        return teamUniv[t] === univ && matches.some(function (m) {
          return (m.home === t || m.away === t) && m.comp !== comp && targetsOk.indexOf(compSuffix_(m.comp)) >= 0;
        });
      });
      var regInTargets = targetTeams.some(function (t) { return regSet[player + '|' + t]; });
      var sideOk = function (t) {
        return teamUniv[t] === univ && (!hasRegs || !regInTargets || regSet[player + '|' + t]);
      };
      // 大会がまだ続いている間は持ち越さない（各大会要項：大会終了・敗退後に持ち越す）
      if (!competitionFinished_(matches, comp, team, formats)) return;
      var others = matches.filter(function (m) {
        return m.comp !== comp && m.idx > lastIdx && DISC_SKIP_STATUS.indexOf(m.status) < 0 &&
          targetsOk.indexOf(compSuffix_(m.comp)) >= 0 && (sideOk(m.home) || sideOk(m.away));
      });
      for (var i = 0; i < others.length && s.slots.length < s.games; i++) {
        s.slots.push({ match: others[i], carried: true });
      }
    });
  });

  // --- 出力行の組み立て
  var outSanctions = sanctions.map(function (s) {
    var consumed = s.slots.filter(function (x) { return x.match.confirmed && x.match.status === '開催済'; }).length;
    var remaining = s.games - consumed;
    var status, memo = [];
    var p = s.manual;
    var committeeDecided = p && /決定/.test(String(p['処分状態']));
    if (s.expired) { status = '消滅（大会終了）'; remaining = 0; }
    else if (remaining <= 0) status = '消化済';
    else if (s.kind === DISC_TYPE.RED && !committeeDecided) status = '審査中（' + (s.minGames || 1) + '試合は自動停止）';
    else status = '出場停止中';
    if (s.expired) memo.push('大会内で未消化の累積停止 ' + s.expired + ' 試合は大会終了で消滅');
    if (s.slots.length < s.games && !s.expired) memo.push('対象試合が未確定（日程未登録または大会継続中の持越）');
    if (s.slots.some(function (x) { return x.carried; })) memo.push('大会終了・敗退により他大会へ持越（各大会要項の懲罰：直近の公式試合で消化）');

    s.slots.forEach(function (x, i) {
      var done = x.match.confirmed && x.match.status === '開催済';
      targets.push({
        '処分対象ID': s.id + '-' + (i + 1), '処分ID': s.id, '順番': i + 1,
        '対象試合ID': x.match.id, '対象大会ID': x.match.comp,
        '状態': done ? '消化済' : (x.carried ? '持越予定' : '予定'),
        '消化日': done ? x.match.date : '', '備考': x.carried ? '他大会へ持越' : ''
      });
    });

    var next = s.slots.filter(function (x) { return !(x.match.confirmed && x.match.status === '開催済'); })
      .map(function (x) { return x.match.id; });
    return {
      '処分ID': s.id, '選手ID': s.player, '発生試合ID': s.origin.id, '大会ID': s.comp,
      '処分種別': s.kind, '停止試合数': s.games, '消化済試合数': consumed,
      '残り試合数': Math.max(0, remaining),
      '処分状態': committeeDecided && remaining > 0 ? p['処分状態'] : status,
      '対象試合': next.length ? next.join(' / ') : (remaining > 0 ? '未確定' : '―'),
      '決定日': p ? p['決定日'] : '', '備考': p ? p['備考'] : '',
      '事象ID': s.eventId, 'チームID': s.team, '根拠': s.basis, '自動計算メモ': memo.join('／'),
      '根拠条文': p ? p['根拠条文'] || '' : '', '認定事実': p ? p['認定事実'] || '' : '',
      '委員会確認': p ? p['委員会確認'] || '' : '', '確認日時': p ? p['確認日時'] || '' : '',
      '確認者': p ? p['確認者'] || '' : '', '確認コメント': p ? p['確認コメント'] || '' : ''
    };
  });

  return { sanctions: outSanctions, targets: targets, warnings: warnings };
}

// ───────────────────────── 補助 ─────────────────────────

function compSuffix_(id) { var s = String(id || ''); return s.indexOf('-') >= 0 ? s.split('-').pop() : s; }

/** 予選／決勝の区分（phaseReset の大会だけ使う。社会人リーグ版では使っていない）。節／ラウンド名で判定する。 */
function phaseOf_(m) { return /予選|ブロック|グループ/.test(m.round) ? '予選' : '決勝'; }

/**
 * このチームがその大会を終えたか。
 * リーグ：未実施（延期含む）の試合が残っていない。
 * トーナメント：直近の実施済み試合で敗退している（勝ち上がって次戦未登録の場合は「未終了」）。
 */
function competitionFinished_(matches, comp, team, formats) {
  var own = matches.filter(function (m) { return m.comp === comp && (m.home === team || m.away === team); });
  if (own.some(function (m) { return ['開催済', '中止', '記録対象外'].indexOf(m.status) < 0; })) return false;
  if (formats && formats[comp] === 'トーナメント') {
    var played = own.filter(function (m) { return m.status === '開催済' && m.confirmed; });
    if (!played.length) return false;
    var last = played[played.length - 1];
    return last.winner !== '' && last.winner !== 'DRAW' && last.winner !== team;
  }
  return true;
}

function compareMatch_(a, b) {
  if (a.date !== b.date) return a.date < b.date ? -1 : 1;
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

/** 時間帯＋経過分 → 通算分（並べ替え用）。時間帯が空なら通算分として扱う。 */
function absMinute_(period, minute) {
  var m = parseFloat(String(minute || '').replace(/[^\d.]/g, '')) || 0;
  var off = { '前半': 0, '後半': 45, '延長前半': 90, '延長後半': 105 }[String(period || '')];
  return off === undefined ? m : off + m;
}

function normDate_(v) {
  if (!v) return '';
  if (Object.prototype.toString.call(v) === '[object Date]') {
    return Utilities.formatDate(v, Session.getScriptTimeZone(), 'yyyy-MM-dd');
  }
  var s = String(v).trim().replace(/\//g, '-');
  var m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  return m ? m[1] + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[3]).slice(-2) : s;
}

function readSheetObjects_(ss, name) {
  var vals;
  if (typeof READ_MEMO_ !== 'undefined' && READ_MEMO_ && typeof sheetValues_ === 'function') {
    vals = sheetValues_(name); // 読むだけの処理の中では使い回す（高速化）
    if (vals.length < 2) return [];
  } else {
    var sh = ss.getSheetByName(name);
    if (!sh || sh.getLastRow() < 2) return [];
    vals = sh.getDataRange().getValues();
  }
  var head = vals[0].map(String);
  return vals.slice(1).filter(function (r) { return r.join('') !== ''; }).map(function (r) {
    var o = {};
    head.forEach(function (h, i) { if (h) o[h] = r[i]; });
    return o;
  });
}

function writeObjects_(ss, name, headers, rows) {
  var sh = ss.getSheetByName(name) || ss.insertSheet(name);
  sh.clearContents();
  var out = [headers].concat(rows.map(function (o) {
    return headers.map(function (h) { return o[h] === undefined || o[h] === null ? '' : o[h]; });
  }));
  sh.getRange(1, 1, out.length, headers.length).setValues(out);
  sh.setFrozenRows(1);
}

/** 初回実行時のみ、処分管理をコピーして退避する */
function backupSanctionOnce_(ss) {
  var props = PropertiesService.getDocumentProperties();
  if (props.getProperty('DISC_BACKUP_DONE')) return;
  var sh = ss.getSheetByName(DISC_SHEETS.SANCTION);
  if (sh) {
    var stamp = Utilities.formatDate(new Date(), Session.getScriptTimeZone(), 'yyyyMMdd_HHmm');
    sh.copyTo(ss).setName(DISC_SHEETS.SANCTION + '_旧_' + stamp);
  }
  props.setProperty('DISC_BACKUP_DONE', '1');
}

/** リーグシステム用：取り込んだ処分管理・処分対象試合から、その試合の出場停止を読む */
function discFromSheets_(matchId) {
  var ss = discSs_();
  var read = function (n) {
    var sh = ss.getSheetByName(n);
    if (!sh || sh.getLastRow() < 2) return [];
    var v = sh.getDataRange().getValues(), h = v[0].map(String);
    return v.slice(1).map(function (r) { var o = {}; h.forEach(function (k, i) { o[k] = r[i]; }); return o; });
  };
  var byId = {};
  read(DISC_SHEETS.SANCTION).forEach(function (s) { byId[String(s['処分ID'])] = s; });
  return read(DISC_SHEETS.TARGET)
    .filter(function (t) { return String(t['対象試合ID']) === String(matchId); })
    .map(function (t) {
      var s = byId[String(t['処分ID'])] || {};
      return {
        playerId: String(s['選手ID'] || ''), teamId: String(s['チームID'] || ''),
        sanctionId: String(t['処分ID']), type: String(s['処分種別'] || ''),
        order: Number(t['順番']), total: Number(s['停止試合数']),
        originMatchId: String(s['発生試合ID'] || ''), carried: t['状態'] === '持越予定'
      };
    });
}

;
// ==== DocFilling.gs
/**
 * DocFiling.gs v1
 * 公式記録・審判報告書・決定通知のPDFを、Googleドライブに大会ごとに整理して保存する
 *
 *   北海道社会人サッカー連盟 公式書類/            ← システム設定「書類保存フォルダID」（なければ自動で作る）
 *     2026年度/
 *       01_2026年度 第45回北海道サッカーリーグ 1部/
 *         公式記録/     2026-05-16_第1節_No101_札幌クラブvs北翔クラブ_公式記録_版1.pdf
 *         審判報告書/   2026-05-16_第1節_No101_札幌クラブvs北翔クラブ_審判報告書.pdf
 *         決定通知/     2026-10-03_北翔クラブ_新息吹_決定通知.pdf
 *       02_…2部/  …
 *     テスト用/        （キリンチャレンジカップ・テスト大会）
 *
 *   新しく作られるPDFは自動でここへ入る。
 *   organizeExistingDocuments() … これまでに作ったPDFもまとめて移動・名前をそろえる（何度実行してもよい）
 */

var DOC_ROOT_NAME = '北海道社会人サッカー連盟 公式書類';
var DOC_ORDER = { TOP: '01', SD: '02', DN: '03', DT: '04', BF: '05', SC: '06', CC: '07', HC: '08' };

function docRoot_() {
  var id = String(cfg_('書類保存フォルダID') || '').trim();
  if (id) { try { return DriveApp.getFolderById(id); } catch (e) {} }
  var it = DriveApp.getFoldersByName(DOC_ROOT_NAME);
  var f = it.hasNext() ? it.next() : DriveApp.createFolder(DOC_ROOT_NAME);
  setCfg_('書類保存フォルダID', f.getId(), '公式記録・審判報告書・決定通知のPDFを大会ごとに保存するフォルダ');
  return f;
}

function docSub_(parent, name) {
  var it = parent.getFoldersByName(name);
  return it.hasNext() ? it.next() : parent.createFolder(name);
}

function docSafe_(s) { return String(s || '').replace(/[\\\/:*?"<>|]/g, '・').replace(/\s+/g, ' ').trim(); }

/** 大会・書類の種類ごとのフォルダ */
function docFolder_(compId, kind) {
  compId = String(compId || '');
  var root = docRoot_();
  if (!compId || /TEST|KIRIN/i.test(compId)) return docSub_(docSub_(root, 'テスト用'), kind);
  var c = objs_(シート.大会).filter(function (x) { return String(x['大会ID']) === compId; })[0] || {};
  var year = String(c['年度'] || (compId.match(/^(\d{4})/) || [])[1] || '');
  var suffix = compId.replace(/^\d{4}-/, '');
  var name = (DOC_ORDER[suffix] || '99') + '_' + docSafe_(c['正式名称'] || c['大会名'] || compId);
  return docSub_(docSub_(docSub_(root, year ? year + '年度' : 'その他'), name), kind);
}

/** 試合の書類のファイル名：日付_節_No_ホームvsアウェイ_種類 */
function docMatchName_(matchId, kind, extra) {
  var m = objs_(シート.試合).filter(function (x) { return String(x['試合ID']) === String(matchId); })[0] || {};
  var team = function (id) { var t = objs_(シート.チーム).filter(function (x) { return String(x['チームID']) === String(id); })[0] || {}; return String(t['チーム名'] || t['クラブ名'] || id || ''); };
  var d = (typeof dbDate_ === 'function' ? dbDate_(m['実施日']) || dbDate_(m['開催予定日']) : '') || '';
  return docSafe_([d, m['節／ラウンド'] || '', m['マッチNo'] ? 'No' + m['マッチNo'] : '', team(m['ホームチームID']) + 'vs' + team(m['アウェイチームID']), kind + (extra || '')]
    .filter(Boolean).join('_')) + '.pdf';
}

function docFileId_(fileOrUrl) {
  if (!fileOrUrl) return '';
  if (typeof fileOrUrl.getId === 'function') return fileOrUrl.getId();
  var m = String(fileOrUrl).match(/[-\w]{25,}/);
  return m ? m[0] : '';
}

/** PDFを所定のフォルダへ移し、名前をそろえる。失敗しても処理は止めない */
function fileDoc_(fileOrUrl, compId, kind, name) {
  try {
    var id = docFileId_(fileOrUrl);
    if (!id) return fileOrUrl;
    var f = DriveApp.getFileById(id);
    f.moveTo(docFolder_(compId, kind));
    if (name) f.setName(name);
    return f.getUrl();
  } catch (e) {
    try { log_('書類の保存先エラー', kind, String(compId), null, null, String(e && e.message || e)); } catch (x) {}
    return typeof fileOrUrl === 'string' ? fileOrUrl : (fileOrUrl && fileOrUrl.getUrl ? fileOrUrl.getUrl() : '');
  }
}

function docCompOfMatch_(matchId) {
  var m = objs_(シート.試合).filter(function (x) { return String(x['試合ID']) === String(matchId); })[0] || {};
  return String(m['大会ID'] || '');
}

/** 公式記録のPDF */
function fileOfficialRecordPdf_(file, matchId, ver) {
  return fileDoc_(file, docCompOfMatch_(matchId), '公式記録', docMatchName_(matchId, '公式記録', ver ? '_版' + ver : ''));
}

/** 審判報告書のPDF */
function fileRefereeReportPdf_(file, matchId) {
  return fileDoc_(file, docCompOfMatch_(matchId), '審判報告書', docMatchName_(matchId, '審判報告書'));
}

/** 決定通知のPDF（発生した試合の大会に入れる） */
function fileNoticePdf_(file, n) {
  var comp = docCompOfMatch_(n.originMatchId || n.matchId);
  var name = docSafe_([n.firstDate || '', n.teamName, String(n.playerName || '').replace(/\s+/g, ''), '決定通知'].filter(Boolean).join('_')) + '.pdf';
  return fileDoc_(file, comp, '決定通知', name);
}

function showDocumentFolder() {
  var url = docRoot_().getUrl();
  try { SpreadsheetApp.getUi().alert('書類フォルダ', url, SpreadsheetApp.getUi().ButtonSet.OK); } catch (e) { Logger.log(url); }
  return url;
}

/** 確定済みの公式記録PDFを作り直す（テンプレートや書き込みを直したとき用） */
function regenerateOfficialRecordPdf(matchId) {
  matchId = String(matchId || 'KIRIN-0928');
  var rec = objs_(シート.公式記録).filter(function (r) { return String(r['試合ID']) === matchId && String(r['記録状態']) === '確定'; })
    .sort(function (a, b) { return Number(b['版']) - Number(a['版']); })[0];
  if (!rec) throw new Error(matchId + ' の確定した公式記録がありません');
  var url = makePdf_(matchId, rec['版']);
  update_(シート.公式記録, rec._row, { '確定PDF URL': url });
  Logger.log(url);
  return url;
}

;
// ==== Entry.gs
/**
 * Entry.gs v1
 * 社会人リーグ版で足した届け出・確認（2026-10 決めたこと 4・6）
 *
 *  1. 上位大会のエントリー（全国社会人予選 SC・全国クラブ予選 CC・北海道選手権 HC）
 *     ・クラブがチームページの「大会の届け出」で、選手30名まで・役員6名までを選ぶ
 *     ・選べる選手は、その大会のチームに登録がある選手（リーグ戦の登録がそのまま写っている。リーグにいないクラブは上位大会として登録した選手）
 *     ・大会マスター「エントリー締切」の日（その日の23:59まで）を過ぎると変えられない。空なら、いつでも変えられる
 *     ・エントリーを出したチームは、エントリーした選手だけがスタメンに入れる（LineupFlow.gs の lnPlayers_）
 *  2. 帯同審判の届け出（ブロックリーグ決勝大会 BF・SC・CC）
 *     ・帯同する審判の氏名・級（2級以上）、または「帯同しない」（審判不帯同料）
 *  3. JFA登録の確認は、試合ごとに運営クラブと事務局がスタメンの確認画面で1人ずつする（LineupFlow.gs・Lineup.html。学連版と同じ）
 *  4. 追加登録の締切（出たい試合の5日前まで）
 *     ・追加登録が反映されると、登録開始日を「申請した日＋5日」にする（Registration.gs の rgApply_）。それより前の試合には出られない
 *     ・日数はシステム設定「追加登録の締切日数」（空なら5）
 */

var ENT = { SHEET: '上位大会エントリー', REF: '帯同審判届' };
var ENT_COLS = ['大会ID', 'チームID', 'クラブ名', '選手（JSON）', '役員（JSON）', '選手数', '役員数', '提出者名', '提出日時', '版'];
var ENT_REF_COLS = ['大会ID', 'チームID', 'クラブ名', '帯同', '審判1 氏名', '審判1 級', '審判2 氏名', '審判2 級', '連絡先メール', '提出者名', '提出日時'];
var ENT_RE = /-(SC|CC|HC)$/;      // エントリーのある大会
var ENT_REF_RE = /-(BF|SC|CC)$/;  // 帯同審判の大会
var ENT_MAX_PLAYERS = 30, ENT_MAX_STAFF = 6;
var ENT_GRADES = ['1級', '2級'];

function entRows_() { lnSheet_(ENT.SHEET, ENT_COLS); return objs_(ENT.SHEET); }
function entRefRows_() { lnSheet_(ENT.REF, ENT_REF_COLS); return objs_(ENT.REF); }
function entJson_(v) { try { var a = JSON.parse(String(v || '')); return Array.isArray(a) ? a : []; } catch (e) { return []; } }
function entComp_(compId) { return objs_(シート.大会).filter(function (c) { return String(c['大会ID']) === String(compId); })[0] || {}; }

/** エントリー締切（yyyy-MM-dd）と、過ぎたか */
function entDeadline_(compId) {
  var d = ymd_(entComp_(compId)['エントリー締切']);
  var today = Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd');
  return { date: d || '', locked: !!(d && today > d) };
}

/** エントリーした選手（選手IDの集まり）。エントリーがなければ null（登録のある選手はみな出られる） */
function entPlayerSet_(teamId) {
  if (!ENT_RE.test(String(teamId))) return null;
  var ss = ss_();
  if (!ss.getSheetByName(ENT.SHEET)) return null;
  var r = objs_(ENT.SHEET).filter(function (x) { return String(x['チームID']) === String(teamId); })[0];
  if (!r) return null;
  var set = {};
  entJson_(r['選手（JSON）']).forEach(function (p) { set[String(p.pid)] = true; });
  return set;
}

/** その大会のチームに登録がある選手（エントリーの候補） */
function entCandidates_(teamId) {
  var names = {};
  objs_(シート.選手).forEach(function (p) { names[String(p['選手ID'])] = String(p['氏名'] || ''); });
  return objs_(シート.選手登録).filter(function (r) {
    return String(r['チームID']) === String(teamId) && String(r['登録状態']) === '有効';
  }).map(function (r) {
    var pid = String(r['選手ID']);
    return { pid: pid, no: String(r['背番号'] || ''), name: names[pid] || pid, pos: String(r['位置'] || '') };
  }).sort(function (a, b) { return (Number(a.no) || 999) - (Number(b.no) || 999); });
}

function entStaffCandidates_(teamId) {
  var ss = ss_();
  if (!ss.getSheetByName(RG.STAFF)) return [];
  return objs_(RG.STAFF).filter(function (s) { return String(s['チームID']) === String(teamId) && String(s['有効'] || '有効') !== '無効'; })
    .map(function (s) { return { role: String(s['役職'] || ''), name: String(s['氏名'] || '') }; }).filter(function (s) { return s.name; });
}

/** クラブの、届け出が要る大会のチーム */
function entMyTeams_(u) {
  return rgTeamList_().filter(function (t) {
    var id = String(t['チームID']), c = String(t['大会ID']);
    return rgTeamCode_(id) === u && (ENT_RE.test(c) || ENT_REF_RE.test(c));
  });
}

// ─────────────────────── チームページ ───────────────────────

/** チームページ「大会の届け出」 */
function lineupEntries(u, t) {
  return withReadMemo_(function () {
    lnAuth_(u, t);
    var rows = entRows_(), refs = entRefRows_();
    return entMyTeams_(u).map(function (tm) {
      var teamId = String(tm['チームID']), compId = String(tm['大会ID']), comp = entComp_(compId);
      var out = { teamId: teamId, compId: compId, comp: String(comp['大会名'] || compId), teamName: String(tm['チーム名'] || tm['クラブ名']) };
      if (ENT_RE.test(compId)) {
        var r = rows.filter(function (x) { return String(x['チームID']) === teamId; })[0];
        out.entry = {
          deadline: entDeadline_(compId), maxPlayers: ENT_MAX_PLAYERS, maxStaff: ENT_MAX_STAFF,
          candidates: entCandidates_(teamId), staffCandidates: entStaffCandidates_(teamId),
          saved: r ? { players: entJson_(r['選手（JSON）']).map(function (p) { return String(p.pid); }), staff: entJson_(r['役員（JSON）']),
            by: String(r['提出者名'] || ''), at: String(r['提出日時'] || ''), version: num_(r['版']) } : null
        };
      }
      if (ENT_REF_RE.test(compId)) {
        var f = refs.filter(function (x) { return String(x['チームID']) === teamId; })[0];
        out.referee = {
          deadline: entDeadline_(compId), grades: ENT_GRADES,
          saved: f ? { mode: String(f['帯同']), refs: [[f['審判1 氏名'], f['審判1 級']], [f['審判2 氏名'], f['審判2 級']]].filter(function (x) { return String(x[0] || '').trim(); })
            .map(function (x) { return { name: String(x[0]), grade: String(x[1] || '') }; }), email: String(f['連絡先メール'] || ''), by: String(f['提出者名'] || ''), at: String(f['提出日時'] || '') } : null
        };
      }
      return out;
    });
  });
}

function entOwnTeam_(u, teamId, re) {
  var tm = entMyTeams_(u).filter(function (x) { return String(x['チームID']) === String(teamId); })[0];
  if (!tm || !re.test(String(tm['大会ID']))) throw new Error('このチームの届け出はできません。ページを開き直してください');
  return tm;
}

/** エントリーを出す（締切までは何度でも出し直せる） */
function lineupEntrySave(u, t, teamId, p) {
  var univ = lnAuth_(u, t);
  var tm = entOwnTeam_(u, teamId, ENT_RE), compId = String(tm['大会ID']);
  var dl = entDeadline_(compId);
  if (dl.locked) throw new Error('エントリーの締切（' + dl.date + '）を過ぎたため、変えられません。事務局へ連絡してください');
  p = p || {};
  var by = String(p.by || '').trim();
  if (!by) throw new Error('提出する人の名前を入力してください');
  var cand = {};
  entCandidates_(teamId).forEach(function (x) { cand[x.pid] = x; });
  var players = [];
  (p.players || []).forEach(function (pid) {
    var x = cand[String(pid)];
    if (!x) throw new Error('この大会に登録のない選手が含まれています。ページを開き直してください');
    if (!players.some(function (y) { return y.pid === x.pid; })) players.push({ pid: x.pid, no: x.no, name: x.name });
  });
  if (!players.length) throw new Error('選手を1人以上選んでください');
  if (players.length > ENT_MAX_PLAYERS) throw new Error('選手は' + ENT_MAX_PLAYERS + '名までです（いま' + players.length + '名）');
  var staff = (p.staff || []).map(function (s) { return { role: String(s.role || '').trim(), name: String(s.name || '').trim() }; }).filter(function (s) { return s.name; });
  if (staff.length > ENT_MAX_STAFF) throw new Error('役員は' + ENT_MAX_STAFF + '名までです（いま' + staff.length + '名）');
  if (staff.some(function (s) { return !s.role; })) throw new Error('役員の役職を入れてください');
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    var r = entRows_().filter(function (x) { return String(x['チームID']) === String(teamId); })[0];
    var o = { '大会ID': compId, 'チームID': teamId, 'クラブ名': univ, '選手（JSON）': JSON.stringify(players), '役員（JSON）': JSON.stringify(staff),
      '選手数': players.length, '役員数': staff.length, '提出者名': by, '提出日時': lnNow_(), '版': r ? num_(r['版']) + 1 : 1 };
    if (r) update_(ENT.SHEET, r._row, o); else append_(ENT.SHEET, o);
  } finally { lock.releaseLock(); }
  return { ok: true, message: 'エントリーを受け付けました（選手' + players.length + '名・役員' + staff.length + '名）' + (dl.date ? '。締切 ' + dl.date + ' までは出し直せます' : '') };
}

/** 帯同審判を届け出る */
function lineupRefereeSave(u, t, teamId, p) {
  var univ = lnAuth_(u, t);
  var tm = entOwnTeam_(u, teamId, ENT_REF_RE), compId = String(tm['大会ID']);
  var dl = entDeadline_(compId);
  if (dl.locked) throw new Error('締切（' + dl.date + '）を過ぎたため、変えられません。事務局へ連絡してください');
  p = p || {};
  var by = String(p.by || '').trim(), mode = p.mode === '帯同しない' ? '帯同しない' : '帯同する';
  if (!by) throw new Error('提出する人の名前を入力してください');
  var refs = (p.refs || []).map(function (x) { return { name: String(x.name || '').trim(), grade: String(x.grade || '').trim() }; }).filter(function (x) { return x.name; }).slice(0, 2);
  var email = String(p.email || '').trim();
  if (mode === '帯同する') {
    if (!refs.length) throw new Error('帯同する審判の氏名を入れてください（帯同しないときは「帯同しない」を選んでください）');
    if (refs.some(function (x) { return ENT_GRADES.indexOf(x.grade) < 0; })) throw new Error('審判の級を選んでください（2級以上）');
    if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('連絡先メールを確認してください');
  } else { refs = []; email = ''; }
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    var r = entRefRows_().filter(function (x) { return String(x['チームID']) === String(teamId); })[0];
    var o = { '大会ID': compId, 'チームID': teamId, 'クラブ名': univ, '帯同': mode,
      '審判1 氏名': refs[0] ? refs[0].name : '', '審判1 級': refs[0] ? refs[0].grade : '', '審判2 氏名': refs[1] ? refs[1].name : '', '審判2 級': refs[1] ? refs[1].grade : '',
      '連絡先メール': email, '提出者名': by, '提出日時': lnNow_() };
    if (r) update_(ENT.REF, r._row, o); else append_(ENT.REF, o);
  } finally { lock.releaseLock(); }
  return { ok: true, message: mode === '帯同しない' ? '「帯同しない」で受け付けました（審判不帯同料がかかります）' : '帯同審判を受け付けました（' + refs.map(function (x) { return x.name + '・' + x.grade; }).join('、') + '）' };
}

// ─────────────────────── 運営ダッシュボード ───────────────────────

/** 大会ごとの届け出の一覧（エントリー・帯同審判） */
function adminEntries(tok) {
  adCheck_(tok);
  return withReadMemo_(function () {
    var rows = entRows_(), refs = entRefRows_();
    var comps = objs_(シート.大会).filter(function (c) { var id = String(c['大会ID']); return (ENT_RE.test(id) || ENT_REF_RE.test(id)) && id.indexOf(rgYear_() + '-') === 0; });
    return comps.map(function (c) {
      var compId = String(c['大会ID']);
      var teams = rgTeamList_().filter(function (t) { return String(t['大会ID']) === compId; });
      return {
        compId: compId, comp: String(c['大会名'] || compId), deadline: entDeadline_(compId), entry: ENT_RE.test(compId), referee: ENT_REF_RE.test(compId),
        teams: teams.map(function (t) {
          var id = String(t['チームID']);
          var e = rows.filter(function (x) { return String(x['チームID']) === id; })[0];
          var f = refs.filter(function (x) { return String(x['チームID']) === id; })[0];
          return {
            teamId: id, name: String(t['略称'] || t['チーム名'] || t['クラブ名']),
            entry: e ? { players: entJson_(e['選手（JSON）']), staff: entJson_(e['役員（JSON）']), at: String(e['提出日時'] || ''), by: String(e['提出者名'] || '') } : null,
            referee: f ? { mode: String(f['帯同']), refs: [[f['審判1 氏名'], f['審判1 級']], [f['審判2 氏名'], f['審判2 級']]].filter(function (x) { return String(x[0] || '').trim(); }).map(function (x) { return x[0] + '（' + x[1] + '）'; }),
              email: String(f['連絡先メール'] || ''), at: String(f['提出日時'] || '') } : null
          };
        })
      };
    });
  });
}

/** エントリー締切を変える（空にすると締切なし） */
function adminSaveEntryDeadline(tok, compId, date) {
  adCheck_(tok);
  date = String(date || '').trim();
  if (date && !/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new Error('日付の形が違います');
  ensureHeader_(シート.大会, ['エントリー締切']);
  var c = objs_(シート.大会).filter(function (x) { return String(x['大会ID']) === String(compId); })[0];
  if (!c) throw new Error('大会がありません');
  update_(シート.大会, c._row, { 'エントリー締切': date ? "'" + date : '' });
  return { ok: true };
}

// ─────────────────────── 追加登録の締切 ───────────────────────

/** 追加登録の締切日数（出たい試合の何日前までに届け出るか） */
function entLeadDays_() { var n = Number(cfg_('追加登録の締切日数')); return n >= 0 && String(cfg_('追加登録の締切日数')).trim() !== '' ? n : 5; }

/** 申請日時 → 出場できる最初の日（申請した日＋締切日数）。今日より前にはしない */
function entStartFor_(applied, today) {
  var d = ymd_(applied) || today;
  var dt = Utilities.parseDate(d, 'Asia/Tokyo', 'yyyy-MM-dd');
  var s = Utilities.formatDate(new Date(dt.getTime() + entLeadDays_() * 86400000), 'Asia/Tokyo', 'yyyy-MM-dd');
  return s > today ? s : today;
}

;
// ==== Incident.gs
/**
 * Incident.gs v3
 * 問題事項報告書（運営クラブ）→ 事情聴取 → 規律委員会の処分検討 → 決定通知（クラブあて）→ 始末書の提出
 *
 *  1. 報告と事情聴取（運営クラブ・チームページの「運営クラブ」）
 *       問題事項についての詳細 … 運営クラブが記載
 *       事情聴取シート         … 運営クラブが当該クラブから聴取（聴取対象者・聴取事項／認否／発言内容・確認内容・今後の対応）
 *       問題事項が生じた理由   … 聴取内容から運営クラブがまとめる
 *  2. 処分検討（規律委員会）
 *       報告が出ると、一発退場と同じくLINEへ【処分検討】が届く（ReviewNotify.gs）。
 *       検討ページで処分を選ぶ（複数可）：処分なし／カウント／口頭での指導／全体周知／戒告／厳重注意／譴責／勝点没収／運営業務／HKFA事案として移送／その他
 *       そのクラブのこれまでの処分（今シーズン）も同じページに出る。
 *  3. 決定通知（戒告・厳重注意・譴責・勝点没収・運営業務・その他）
 *       クラブあての決定通知（PDF）を作り、処分通知と同じ承認（NoticeFlow.gs）に回す。承認したらすぐクラブへ送る。
 *       勝点没収は順位表に反映する（Standings.gs）。
 *  4. 始末書（譴責）
 *       決定通知に始末書の書式（Word・IncidentTemplate.gs）を添付。クラブはチームページの「始末書」から提出する。
 *       提出されたらLINEで知らせる。
 *
 *  ・事務局ページの「問題事項」タブ：報告・検討の状況・決定通知・始末書・印刷、今シーズンの処分一覧
 *
 *  新しいシステム：報告・事情聴取・始末書の提出はリーグシステム → 全体システムへ取り込み（Sync.gs）。
 *  処分の検討・決定・通知は全体システム。決定（問題事項の処分）はリーグへ写し、チームページの始末書の案内に使う。
 */

var IC = { SHEET: '問題事項報告', DEC: '問題事項の処分', SUB: '始末書の提出', PAST: '処分一覧（これまで）' };
var IC_COLS = ['報告ID', '試合ID', '大会名', '節', 'マッチNo', '対戦A', '対戦B', '試合日', 'キックオフ', '会場',
  '種類', '当該クラブ', '問題事項の詳細', '問題事項が生じた理由', '事情聴取の相手', '事情聴取（JSON）', '記入者', '所属クラブ', '報告日', '状態', '提出日時', '更新日時',
  '添付（写真）', '取込元', '弁明', '弁明者', '弁明日時', '弁明期限'];
var IC_DEC_COLS = ['報告ID', '試合ID', '当該クラブ', '処分', '勝点没収', '対象チームID', '運営業務の内容', '処分の内容（その他）', '始末書の提出期限',
  '決定通知', '認定事実', '根拠条文', '不服申立', '決定者', '決定日時', 'コメント', '通知ID'];
var IC_SUB_COLS = ['提出ID', '報告ID', '試合ID', 'クラブ名', '提出者', '提出日時', 'ファイルURL', 'ファイル名', '状態'];
var IC_PAST_COLS = ['No.', '日程', '大会', 'MN', '対象クラブ', '対象事案', '決定内容'];

/** 規律委員会が選べる処分（notice：クラブへ決定通知を送るのが基本のもの） */
var IC_PENALTIES = [
  { k: '処分なし', notice: false, note: '報告は受けたが処分しない' },
  { k: 'カウント', notice: false, note: '記録して回数を数える' },
  { k: '口頭での指導', notice: false },
  { k: '全体周知', notice: false },
  { k: '戒告', notice: true },
  { k: '厳重注意', notice: true },
  { k: '譴責', notice: true, note: '始末書の提出' },
  { k: '勝点没収', notice: true, note: '順位表に反映' },
  { k: '運営業務', notice: true, note: '運営クラブ運営・審判担当など' },
  { k: 'HKFA事案として移送', notice: false },
  { k: 'その他', notice: true }
];
var IC_APPEAL_DEFAULT = '上記懲罰は、懲罰規程第36条1項各号に該当しないため不服申立できない。';
var IC_NOTICE_KIND = '問題事項の決定通知';
var IC_SIMATSU_DAYS = 14; // 始末書の提出期限の初期値（決定日から）

/** 種類と、詳細の書き出し（〇〇クラブは当該クラブに置き換える）・事情聴取の聴取事項 */
var IC_KINDS = [
  ['帯同副審', '〇〇クラブの帯同副審が、マッチミーティングに〇分遅れて到着した。', ['何分遅れたか？', 'なぜ遅れたのか？', '遅れることを事前に連絡したか？', 'どうすれば間に合ったか？']],
  ['チームの遅刻', '〇〇クラブがマッチミーティングに〇分遅れて到着した。〇〇クラブが到着した時には、マッチミーティングは終了していた。', ['何分遅れたか？', 'なぜ遅れたのか？', '遅れることを事前に連絡したか？', 'どうすれば間に合ったか？']],
  ['忘れ物', '〇〇クラブは審判着を忘れ、［貸したクラブ］が貸し出した。', ['何を忘れたか？', 'なぜ忘れたのか？', '出発前に持ち物の確認はしたか？', 'どうすれば防げたか？']],
  ['ユニフォーム', '〇〇クラブのユニフォームが［どのような問題］であったため、［どう対応した］。', ['どのような問題があったか？', 'なぜ起きたのか？', 'どうすれば防げたか？']],
  ['登録・背番号', '〇〇クラブの［選手名］選手が、登録と異なる背番号［番号］で試合に出場した。', ['故意だったか？', 'なぜ登録と違ったのか？', '試合前に登録の確認はしたか？', 'どうすれば防げたか？']],
  ['キックオフの遅れ', 'キックオフが予定より〇分遅れた。', ['なぜ遅れたのか？', 'どうすれば防げたか？']],
  ['運営', '［運営面の問題の内容］があった。', ['なぜ起きたのか？', 'どうすれば防げたか？']],
  ['その他', '', ['報告の内容に間違いはないか？', '故意だったか？', 'どうすれば防げたか？']]
];

/** これまでの処分（規律委員会開催事項）の最初の一覧。学連版にあった2026年の一覧は消した（社会人リーグ版は空から） */
var IC_PAST_2026 = [];
var IC_PAST_YEAR = 0;

function icSheet_() { return lnSheet_(IC.SHEET, IC_COLS); }
function icRows_() { icSheet_(); return objs_(IC.SHEET); }
function icDecRows_() { lnSheet_(IC.DEC, IC_DEC_COLS); return objs_(IC.DEC); }
function icSubRows_() { lnSheet_(IC.SUB, IC_SUB_COLS); return objs_(IC.SUB); }
function icNow_() { return Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm:ss'); }
function icToday_() { return Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd'); }
function icStr_(v, fmt) { return v instanceof Date ? Utilities.formatDate(v, 'Asia/Tokyo', fmt) : String(v == null ? '' : v); }
function icToken_(id) { return rvToken_('INC:' + id); }
function icReviewUrl_(base, id) {
  base = base || (typeof webAppBaseUrl_ === 'function' ? webAppBaseUrl_() : '');
  return base ? base + '?page=incident&case=' + encodeURIComponent(id) + '&t=' + icToken_(id) : '';
}
function icJson_(s) { try { return s ? JSON.parse(String(s)) : null; } catch (e) { return null; } }
function icNorm_(s) { return String(s || '').normalize('NFKC').replace(/\s+/g, ''); }

function icView_(r) {
  var id = String(r['報告ID']);
  return {
    id: id, matchId: String(r['試合ID']), comp: String(r['大会名'] || ''), round: String(r['節'] || ''), no: String(r['マッチNo'] || ''),
    home: String(r['対戦A'] || ''), away: String(r['対戦B'] || ''), date: icStr_(r['試合日'], 'yyyy-MM-dd'), kickoff: icStr_(r['キックオフ'], 'HH:mm'),
    venue: String(r['会場'] || ''), kinds: String(r['種類'] || ''), party: String(r['当該クラブ'] || ''),
    detail: String(r['問題事項の詳細'] || ''), reason: String(r['問題事項が生じた理由'] || ''), heardFrom: String(r['事情聴取の相手'] || ''),
    hearing: icJson_(r['事情聴取（JSON）']),
    photos: String(r['添付（写真）'] || '').split(/\s+/).filter(function (x) { return /^https?:/.test(x); }), source: String(r['取込元'] || ''),
    writer: String(r['記入者'] || ''), writerUniv: String(r['所属クラブ'] || ''), reportDate: icStr_(r['報告日'], 'yyyy-MM-dd'),
    status: String(r['状態'] || ''), at: icStr_(r['提出日時'], 'yyyy-MM-dd HH:mm:ss'), updated: icStr_(r['更新日時'], 'yyyy-MM-dd HH:mm:ss'),
    explanation: String(r['弁明'] || ''), explainedBy: String(r['弁明者'] || ''), explainedAt: icStr_(r['弁明日時'], 'yyyy-MM-dd HH:mm:ss'),
    explainDeadline: icStr_(r['弁明期限'], 'yyyy-MM-dd HH:mm')
  };
}

function icDecView_(d) {
  if (!d) return null;
  return {
    penalties: String(d['処分'] || '').split('・').filter(Boolean), points: Number(d['勝点没収'] || 0) || 0, teamId: String(d['対象チームID'] || ''),
    duty: String(d['運営業務の内容'] || ''), other: String(d['処分の内容（その他）'] || ''), deadline: icStr_(d['始末書の提出期限'], 'yyyy-MM-dd'),
    sendNotice: String(d['決定通知'] || '') === '送る',
    fact: String(d['認定事実'] || ''), basis: String(d['根拠条文'] || ''), appeal: String(d['不服申立'] || ''),
    by: String(d['決定者'] || ''), at: icStr_(d['決定日時'], 'yyyy-MM-dd HH:mm'), comment: String(d['コメント'] || ''), nid: String(d['通知ID'] || ''), _row: d._row
  };
}

/** 決定内容の表示（例：戒告・勝点1没収） */
function icPenaltyLabel_(dec) {
  if (!dec) return '';
  return dec.penalties.map(function (p) {
    if (p === '勝点没収') return '勝点' + (dec.points || '') + '没収';
    if (p === '運営業務' && dec.duty) return '運営業務（' + dec.duty + '）';
    if (p === 'その他' && dec.other) return dec.other;
    return p;
  }).join('・');
}

function icSimatsuOf_(id, subs) {
  var l = (subs || icSubRows_()).filter(function (s) { return String(s['報告ID']) === String(id) && String(s['状態']) !== '差し替え'; });
  var s = l[l.length - 1];
  return s ? { at: icStr_(s['提出日時'], 'yyyy-MM-dd HH:mm'), url: String(s['ファイルURL'] || ''), name: String(s['ファイル名'] || ''), by: String(s['提出者'] || '') } : null;
}

/** 検討の状況 */
function icStage_(dec, nt, sim) {
  if (!dec) return '処分検討待ち';
  var label = icPenaltyLabel_(dec);
  var parts = [label];
  if (dec.sendNotice) {
    var st = nt ? String(nt['状態']) : '';
    parts.push({ '承認待ち': '決定通知の承認待ち', '修正依頼': '決定通知の修正依頼', '承認': '決定通知は承認済み', '送信済': '決定通知を送信済み' }[st] || '決定通知の作成待ち');
  }
  if (dec.penalties.indexOf('譴責') >= 0) parts.push(sim ? '始末書 提出済み' : '始末書 未提出' + (dec.deadline ? '（期限 ' + dec.deadline + '）' : ''));
  return parts.join('・');
}

function icCountByMatch_() {
  var n = {};
  icRows_().forEach(function (r) { if (String(r['状態']) !== '取り下げ') n[String(r['試合ID'])] = (n[String(r['試合ID'])] || 0) + 1; });
  return n;
}

function icUnivOf_(tid) {
  var t = objs_(シート.チーム).filter(function (x) { return String(x['チームID']) === String(tid); })[0] || {};
  return String(t['クラブ名'] || t['チーム名'] || '');
}

/** クラブの呼び方（正式名・チーム名・略称）。処分一覧の「室工大」なども同じクラブとして数える */
function icAliases_(univ) {
  var u = icNorm_(univ), out = [u];
  objs_(シート.チーム).forEach(function (t) {
    if (icNorm_(t['クラブ名']) !== u) return;
    [t['略称'], t['チーム名']].forEach(function (x) { x = icNorm_(x).replace(/[ABＡＢ]$|セカンド$|2nd$/, ''); if (x && out.indexOf(x) < 0) out.push(x); });
  });
  return out;
}
function icSameUniv_(aliases, text) {
  var t = icNorm_(String(text || '').split('\n')[0]);
  return !!t && aliases.some(function (a) { return a && (t === a || t.indexOf(a) === 0 || a.indexOf(t) === 0); });
}

function icFind_(id) {
  var r = icRows_().filter(function (x) { return String(x['報告ID']) === String(id); })[0];
  if (!r || String(r['状態']) === '取り下げ') throw new Error('報告が見つかりません（取り下げられた可能性があります）');
  return r;
}
function icDecFor_(id) { return icDecRows_().filter(function (x) { return String(x['報告ID']) === String(id); })[0] || null; }
function icNoticeRow_(nid) {
  if (!nid || typeof ntRows_ !== 'function') return null;
  return ntRows_().filter(function (x) { return String(x['通知ID']) === String(nid); })[0] || null;
}

// ─────────────────────── 1. 運営クラブ（チームページ） ───────────────────────

/** 当該クラブの選択肢：対戦する2クラブを先に、そのあとにほかのクラブ（帯同副審のクラブが当該になることもあるため） */
function icMatchUnivs_(info) {
  return [icUnivOf_(info.homeId), icUnivOf_(info.awayId)].filter(function (x, i, a) { return x && a.indexOf(x) === i; });
}
function icUnivChoices_(mu) {
  var all = lnUnivs_(), rest = Object.keys(all).map(function (c) { return all[c]; })
    .filter(function (n, i, a) { return n && a.indexOf(n) === i && mu.indexOf(n) < 0 && n !== '連盟事務局'; }).sort();
  return mu.concat(rest);
}

function lineupIncidents(u, t, mid) {
  return withReadMemo_(function () {
    var m = lnDutyAuth_(u, t, mid);
    var info = lnMatchInfo_(m);
    var mu = icMatchUnivs_(info), univs = icUnivChoices_(mu);
    var list = icRows_().filter(function (r) { return String(r['試合ID']) === String(mid) && String(r['状態']) !== '取り下げ'; }).map(icView_);
    return { match: info, univs: univs, matchUnivs: mu, myUniv: lnAuth_(u, t), kinds: IC_KINDS, list: list };
  });
}

function lineupIncidentSave(u, t, mid, p) {
  return icAfterSave_(icSave_(u, t, mid, p));
}

/** 保存のあと：新しい報告は当該クラブへ弁明のお願い、それ以外は規律委員会へ */
function icAfterSave_(res) {
  // 新しい報告：当該クラブへ弁明のお願い（規律委員会へは、弁明が出たとき・締切を過ぎたときに知らせる）
  if (res.explainRequest) {
    try { res.message += icRequestExplanation_(res.id); } catch (e) { res.message += '（当該クラブへのメールを送れませんでした：' + e.message + '）'; }
  } else if (!res.waiting) icNotifySoon_();
  return res;
}

// ─────────────────────── 公式記録の提出ページから（記録担当） ───────────────────────

/** 公式記録の提出ページ：この試合の問題事項報告書（運営クラブのページで試合前に出したものも含む） */
function officialIncidentContext(mid) {
  return withReadMemo_(function () {
    var m = findMatch_(mid);
    var info = lnMatchInfo_(m);
    var mu = icMatchUnivs_(info), univs = icUnivChoices_(mu);
    var list = icRows_().filter(function (r) { return String(r['試合ID']) === String(mid) && String(r['状態']) !== '取り下げ'; }).map(function (r) {
      var v = icView_(r);
      return { id: v.id, kinds: v.kinds, party: v.party, detail: v.detail, writer: v.writer, writerUniv: v.writerUniv, status: v.status, deadline: v.explainDeadline, at: v.at };
    });
    return { univs: univs, matchUnivs: mu, kinds: IC_KINDS.map(function (k) { return { name: k[0], template: k[1] }; }), list: list };
  });
}

/** 公式記録の提出ページから問題事項報告書を出す（記録担当クラブの名前で） */
function officialIncidentSave(mid, p) {
  p = p || {};
  var univ = String(p.writerUniv || '').trim();
  if (!univ) throw new Error('記録担当クラブを入力してください（試合のタブ）');
  var m = findMatch_(mid);
  return icAfterSave_(icSaveCore_(m, univ, mid, p));
}

/** 規律委員会への通知（新しいシステムのリーグでは、全体システムが取り込んでから送る） */
function icNotifySoon_() {
  // リーグシステム：全体システムに「すぐ取り込んで知らせて」と頼む（Sync.gs の pingCentralForReview）
  if (typeof isLeague_ === 'function' && isLeague_()) { if (typeof schedulePingCentral_ === 'function') schedulePingCentral_(); return; }
  if (typeof notifyReviewCasesSafe_ === 'function') notifyReviewCasesSafe_();
}

/** 事情聴取の発言内容から「理由」をまとめる */
function icReasonFromHearing_(h) {
  if (!h || !h.items) return '';
  return h.items.filter(function (x) { return String(x.a || '').trim(); }).map(function (x) { return String(x.a).trim().replace(/[。．]?$/, '。'); }).join('');
}

function icSave_(u, t, mid, p) {
  var m = lnDutyAuth_(u, t, mid);
  return icSaveCore_(m, lnAuth_(u, t), mid, p);
}

function icSaveCore_(m, myUniv, mid, p) {
  p = p || {};
  var detail = String(p.detail || '').trim(), writer = String(p.writer || '').trim();
  if (!detail) throw new Error('「問題事項についての詳細」を書いてください');
  if (/〇〇|［/.test(detail)) throw new Error('詳細に〇〇や［　］が残っています。書き換えてください');
  if (!String(p.party || '').trim()) throw new Error('当該クラブを選んでください');
  if (!writer) throw new Error('記入者（運営クラブ）の名前を入力してください');
  var h = p.hearing && typeof p.hearing === 'object' ? p.hearing : null;
  if (h) h.items = (h.items || []).filter(function (x) { return String(x.q || '').trim() || String(x.a || '').trim(); });
  var reason = String(p.reason || '').trim() || icReasonFromHearing_(h);
  var info = lnMatchInfo_(m);
  var lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    var sh = icSheet_();
    var vals = {
      '試合ID': String(mid), '大会名': info.comp, '節': info.round, 'マッチNo': info.no, '対戦A': info.home, '対戦B': info.away,
      '試合日': info.date, 'キックオフ': info.kickoff, '会場': info.venue,
      '種類': String(p.kinds || ''), '当該クラブ': String(p.party).trim(), '問題事項の詳細': detail,
      '問題事項が生じた理由': reason, '事情聴取の相手': h && h.target ? String(h.target.name || '').trim() : '',
      '事情聴取（JSON）': h ? JSON.stringify(h) : '',
      '記入者': writer, '所属クラブ': myUniv, '報告日': icToday_(), '更新日時': icNow_()
    };
    ['試合日', 'キックオフ', '報告日', '更新日時'].forEach(function (k) { if (vals[k]) vals[k] = "'" + vals[k]; });
    if (p.id) {
      var r = icRows_().filter(function (x) { return String(x['報告ID']) === String(p.id) && String(x['試合ID']) === String(mid); })[0];
      if (!r) throw new Error('報告が見つかりません');
      update_(IC.SHEET, r._row, vals);
      return { ok: true, id: String(p.id), waiting: String(r['状態']) === '弁明待ち', message: '問題事項報告書を修正しました' };
    }
    var id = id_('INC');
    vals['報告ID'] = id; vals['状態'] = '弁明待ち'; vals['提出日時'] = "'" + icNow_();
    vals['弁明期限'] = "'" + icToday_() + ' 23:59';
    sh.appendRow(IC_COLS.map(function (k) { return vals[k] == null ? '' : vals[k]; }));
    if (typeof memoForget_ === 'function') memoForget_(IC.SHEET);
    return { ok: true, id: id, explainRequest: true, message: '問題事項報告書を提出しました。' };
  } finally { lock.releaseLock(); }
}

// ─────────────────────── 1''. 当該クラブの弁明（締切：報告した日の23:59） ───────────────────────

/** 当該クラブのコード（クラブ名・略称から） */
function icPartyCode_(party) {
  var univs = lnUnivs_(), al = icAliases_(String(party || '').split('\n')[0]);
  var hit = Object.keys(univs).filter(function (c) { return icSameUniv_(al, univs[c]) || icSameUniv_(icAliases_(univs[c]), party); });
  return hit[0] || '';
}

/** 当該クラブへ「弁明を書いてください」のメール */
function icRequestExplanation_(id) {
  var r = icFind_(id);
  if (!r) return '';
  var code = icPartyCode_(r['当該クラブ']);
  var mails = code ? lnUnivMails_(code) : [];
  if (!code) return '（当該クラブ「' + r['当該クラブ'] + '」が見つからないため、弁明のお願いを送れませんでした。締切後に規律委員会へ送られます）';
  var url = lnUrl_(code);
  var dl = icStr_(r['弁明期限'], 'yyyy-MM-dd HH:mm');
  var html = '<p>' + lnEsc_(r['当該クラブ']) + ' ご担当者様</p>' +
    '<p>運営クラブから、貴クラブに関する<b>問題事項報告書</b>が提出されました。内容を確認し、<b>' + lnEsc_(dl) + ' まで</b>に弁明（経緯・理由・今後の対応）を書いてください。<br>' +
    '締切までに弁明がない場合は、報告書のみで規律委員会が検討します。</p>' +
    '<p>試合：' + lnEsc_(r['大会名']) + '　' + lnEsc_(r['節']) + '　No.' + lnEsc_(r['マッチNo']) + '　' + lnEsc_(r['対戦A']) + ' vs ' + lnEsc_(r['対戦B']) + '（' + lnEsc_(icStr_(r['試合日'], 'yyyy-MM-dd')) + '）<br>' +
    '種類：' + lnEsc_(r['種類'] || 'その他') + '</p>' +
    '<p style="white-space:pre-wrap;border-left:3px solid #D84315;padding-left:8px">' + lnEsc_(r['問題事項の詳細']) + '</p>' +
    (url ? '<p><a href="' + url + '" style="display:inline-block;padding:10px 18px;background:#1976D2;color:#fff;text-decoration:none;border-radius:6px">チームページで弁明を書く</a></p>' : '');
  var subj = '【要対応・締切' + dl.slice(5).replace('-', '/') + '】問題事項報告書の弁明のお願い（' + String(r['当該クラブ']) + '）';
  if (!mails.length && typeof tnMail_ !== 'function') return '（当該クラブ「' + r['当該クラブ'] + '」の連絡先が見つからないため、弁明のお願いを送れませんでした。締切後に規律委員会へ送られます）';
  if (typeof tnMail_ === 'function') tnMail_('問題事項の弁明依頼', mails.join(','), subj, html, String(r['試合ID']), [code]);
  else mail_('問題事項の弁明依頼', mails.join(','), subj, html, String(r['試合ID']), '');
  return '当該クラブ（' + r['当該クラブ'] + '）へ弁明のお願いを送りました（締切 ' + dl + '）。弁明が出るか締切を過ぎると、規律委員会へ送られます。';
}

/** チームページ：自分のクラブが当該クラブになっている報告（弁明待ち・弁明済み） */
function icExplainForUniv_(univ) {
  var al = icAliases_(univ), from = Utilities.formatDate(new Date(Date.now() - 30 * 86400000), 'Asia/Tokyo', 'yyyy-MM-dd');
  return icRows_().filter(function (r) {
    if (String(r['状態']) === '取り下げ' || !icSameUniv_(al, r['当該クラブ'])) return false;
    return String(r['状態']) === '弁明待ち' || icStr_(r['報告日'], 'yyyy-MM-dd') >= from;
  }).map(function (r) {
    var v = icView_(r);
    return { id: v.id, match: (v.comp + '　' + v.round + '　No.' + v.no + '　' + v.home + ' vs ' + v.away).trim(), date: v.date, kinds: v.kinds, detail: v.detail,
      status: v.status, deadline: v.explainDeadline, explanation: v.explanation, explainedBy: v.explainedBy, explainedAt: v.explainedAt };
  }).sort(function (a, b) { return (a.status === '弁明待ち' ? 0 : 1) - (b.status === '弁明待ち' ? 0 : 1) || (a.date < b.date ? 1 : -1); });
}

/** チームページ：弁明を提出する（締切前だけ） */
function lineupIncidentExplain(u, t, id, text, name) {
  var univ = lnAuth_(u, t);
  text = String(text || '').trim(); name = String(name || '').trim();
  if (!text) throw new Error('弁明を書いてください');
  if (!name) throw new Error('書いた人の名前を入力してください');
  var lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    var r = icFind_(id);
    if (!r || !icSameUniv_(icAliases_(univ), r['当該クラブ'])) throw new Error('この報告には弁明できません');
    if (String(r['状態']) !== '弁明待ち') throw new Error('締切を過ぎたか、すでに規律委員会へ送られています');
    var dl = icStr_(r['弁明期限'], 'yyyy-MM-dd HH:mm');
    if (dl && Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm') > dl) throw new Error('弁明の締切（' + dl + '）を過ぎました。規律委員会へは報告書のみで送られます');
    update_(IC.SHEET, r._row, { '弁明': text, '弁明者': name, '弁明日時': "'" + icNow_(), '状態': '提出', '更新日時': "'" + icNow_() });
  } finally { lock.releaseLock(); }
  icNotifySoon_();
  return { ok: true, message: '弁明を提出しました。報告書と一緒に規律委員会へ送りました。' };
}

/** 締切を過ぎた「弁明待ち」を、弁明なしで規律委員会へ回す（1時間ごとの更新・リーグの取り込みから） */
function icExpireExplanations_() {
  var now = Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm'), n = 0;
  if (!ss_().getSheetByName(IC.SHEET)) return 0;
  icRows_().forEach(function (r) {
    if (String(r['状態']) !== '弁明待ち') return;
    var dl = icStr_(r['弁明期限'], 'yyyy-MM-dd HH:mm');
    if (!dl || now <= dl) return;
    update_(IC.SHEET, r._row, { '状態': '提出', '弁明者': '（締切までに弁明なし）', '更新日時': "'" + icNow_() });
    n++;
  });
  if (n) icNotifySoon_();
  return n;
}

function lineupIncidentWithdraw(u, t, mid, id) {
  lnDutyAuth_(u, t, mid);
  var r = icRows_().filter(function (x) { return String(x['報告ID']) === String(id) && String(x['試合ID']) === String(mid); })[0];
  if (!r) throw new Error('報告が見つかりません');
  update_(IC.SHEET, r._row, { '状態': '取り下げ', '更新日時': "'" + icNow_() });
  return { ok: true, message: '取り下げました' };
}

// ─────────────────────── 1'. 問題事項報告書フォーム（写真）の取込（FormImport.gs から） ───────────────────────

/**
 * 運営クラブがGoogleフォームで写真をアップロードして出した問題事項報告書を、問題事項として取り込む。
 *   ・取込元を初めて見たときは、それまでの回答は取り込まない（これまでの処分は処分一覧のファイルにあるため）。その後の回答だけ
 *   ・列は見出しで判断（マッチナンバー・大会・当該クラブ・詳細・理由・記入者・所属・写真）。ほかの列は詳細の後ろに「見出し：内容」で付ける
 *   ・取り込んだら規律委員会のLINEへ【処分検討】（ReviewNotify.gs）。写真のリンクも付ける
 */
function icImportFormProblems_(sources) {
  var props = PropertiesService.getScriptProperties();
  var done = {};
  icRows_().forEach(function (r) { if (r['取込元']) done[String(r['取込元'])] = true; });
  var matches = objs_(シート.試合), teams = {};
  objs_(シート.チーム).forEach(function (t) { teams[String(t['チームID'])] = t; });
  var viewers = [];
  ['管理者メール', '規律委員会メール'].forEach(function (k) { String((typeof cfg_ === 'function' && cfg_(k)) || '').split(/[,\s]+/).filter(Boolean).forEach(function (m) { viewers.push(m); }); });
  var added = 0, firsts = [];
  sources.forEach(function (s) {
    var url = String(s['URL']).trim();
    var book = SpreadsheetApp.openByUrl(url);
    var gid = (url.match(/gid=(\d+)/) || [])[1];
    var sh = (gid ? book.getSheets().filter(function (x) { return String(x.getSheetId()) === gid; })[0] : null) || book.getSheets()[0];
    var v = sh.getDataRange().getValues();
    if (v.length < 1) return;
    var h = v[0].map(function (x) { return String(x).replace(/\s+/g, ''); });
    var find = function (re, not) { for (var i = 0; i < h.length; i++) if (re.test(h[i]) && !(not && not.test(h[i]))) return i; return -1; };
    var C = {
      ts: find(/^タイムスタンプ/), no: find(/マッチ|ＭＮ|^MN|試合番号/), comp: find(/大会|競技会|リーグ/), date: find(/日付|試合日|開催日/),
      home: find(/対戦A|ホーム|チームA/), away: find(/対戦B|アウェイ|チームB/),
      party: find(/当該|問題を起こした|対象クラブ|相手クラブ/), detail: find(/詳細|内容|状況/, /理由/), reason: find(/理由/),
      writer: find(/記入者|氏名|お名前/), univ: find(/所属|運営クラブ/, /当該/), mail: find(/メール/)
    };
    var photoCols = [];
    h.forEach(function (x, i) { if (/写真|画像|ファイル|アップロード|添付/.test(x)) photoCols.push(i); });
    var used = {};
    Object.keys(C).forEach(function (k) { if (C[k] >= 0) used[C[k]] = true; });
    photoCols.forEach(function (i) { used[i] = true; });
    // 初めて見た取込元：今までの回答は取り込まず、最後の時刻だけ覚える
    var mark = 'FRMP_TS:' + url;
    var since = Number(props.getProperty(mark) || 0);
    var maxTs = since;
    var tsOf = function (r) { var x = r[C.ts]; var d = x instanceof Date ? x : new Date(String(x || '').replace(/\//g, '-').replace(' ', 'T')); return isNaN(d.getTime()) ? 0 : d.getTime(); };
    if (!props.getProperty(mark)) {
      v.slice(1).forEach(function (r) { maxTs = Math.max(maxTs, tsOf(r)); });
      props.setProperty(mark, String(maxTs || 1));
      firsts.push(String(s['名前'] || ''));
      return;
    }
    for (var i = 1; i < v.length; i++) {
      var r = v[i], ts = tsOf(r);
      if (!ts || ts <= since) continue;
      var key = url + '#' + (i + 1) + '#' + ts;
      if (done[key]) continue;
      var get = function (k) { var x = C[k] >= 0 ? r[C[k]] : ''; return x instanceof Date ? Utilities.formatDate(x, 'Asia/Tokyo', 'yyyy-MM-dd') : String(x == null ? '' : x).trim(); };
      // 写真：フォームのアップロード（ドライブのリンク）。規律委員会が開けるように共有
      var photos = [];
      photoCols.concat(h.map(function (x, j) { return j; }).filter(function (j) { return /drive\.google\.com/.test(String(r[j])); }))
        .forEach(function (j) { String(r[j] || '').split(/[,\s]+/).filter(function (u) { return /^https?:/.test(u); }).forEach(function (u) { if (photos.indexOf(u) < 0) photos.push(u); }); });
      photos.forEach(function (u) {
        var fid = (u.match(/[?&]id=([^&]+)/) || u.match(/\/d\/([^/]+)/) || [])[1];
        if (fid) viewers.forEach(function (m) { try { DriveApp.getFileById(fid).addViewer(m); } catch (e) {} });
      });
      // 試合：マッチナンバー（＋大会）で探す
      var no = typeof frmNo_ === 'function' ? frmNo_(get('no')) : get('no');
      var comp = String(s['大会ID'] || '') || (typeof frmGuessComp_ === 'function' ? frmGuessComp_(ss_(), get('comp')) : '');
      var cands = matches.filter(function (m) { return no && (typeof frmNo_ === 'function' ? frmNo_(m['マッチNo']) : String(m['マッチNo'])) === no && (!comp || String(m['大会ID']) === comp); });
      var tsYmd = Utilities.formatDate(new Date(ts), 'Asia/Tokyo', 'yyyy-MM-dd');
      cands.sort(function (a, b) { var da = Math.abs(Date.parse(matchDateYmd_(a)) - Date.parse(tsYmd)), db = Math.abs(Date.parse(matchDateYmd_(b)) - Date.parse(tsYmd)); return da - db; });
      var m = cands[0] || null, info = m ? lnMatchInfo_(m) : null;
      var extra = h.map(function (x, j) { return used[j] || j === C.ts || !String(r[j] || '').trim() || /drive\.google\.com/.test(String(r[j])) ? '' : x + '：' + (r[j] instanceof Date ? Utilities.formatDate(r[j], 'Asia/Tokyo', 'yyyy-MM-dd HH:mm') : String(r[j]).trim()); })
        .filter(Boolean);
      var detail = [get('detail')].concat(extra).filter(Boolean).join('\n') || '（フォームで写真を提出。添付の写真を確認してください）';
      var vals = {
        '報告ID': id_('INC'), '試合ID': m ? String(m['試合ID']) : '', '大会名': info ? info.comp : get('comp'), '節': info ? info.round : '', 'マッチNo': info ? info.no : get('no'),
        '対戦A': info ? info.home : get('home'), '対戦B': info ? info.away : get('away'), '試合日': "'" + (info ? info.date : (get('date') || tsYmd)),
        'キックオフ': info && info.kickoff ? "'" + info.kickoff : '', '会場': info ? info.venue : '',
        '種類': 'フォーム（写真）', '当該クラブ': get('party') || '（写真で確認）', '問題事項の詳細': detail, '問題事項が生じた理由': get('reason'),
        '事情聴取の相手': '', '事情聴取（JSON）': '', '記入者': get('writer'), '所属クラブ': get('univ'),
        '報告日': "'" + tsYmd, '状態': '提出', '提出日時': "'" + Utilities.formatDate(new Date(ts), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm:ss'), '更新日時': "'" + icNow_(),
        '添付（写真）': photos.join(' '), '取込元': key
      };
      // 回答のし直し：同じ取込元・同じ試合・同じ当該クラブで、まだ処分を決めていない報告は、最新の回答で置き換える
      var decided = {};
      icDecRows_().forEach(function (d) { decided[String(d['報告ID'])] = true; });
      var same = m ? icRows_().filter(function (x) {
        return String(x['種類']) === 'フォーム（写真）' && String(x['状態']) !== '取り下げ' && String(x['試合ID']) === String(m['試合ID']) &&
          String(x['取込元'] || '').split('#')[0] === url && icNorm_(x['当該クラブ']) === icNorm_(vals['当該クラブ']) && !decided[String(x['報告ID'])];
      })[0] : null;
      if (same) {
        vals['報告ID'] = String(same['報告ID']);
        update_(IC.SHEET, same._row, vals);
      } else {
        icSheet_().appendRow(IC_COLS.map(function (k) { return vals[k] == null ? '' : vals[k]; }));
      }
      if (typeof memoForget_ === 'function') memoForget_(IC.SHEET);
      done[key] = true;
      added++;
      maxTs = Math.max(maxTs, ts);
    }
  });
  if (typeof memoForget_ === 'function') memoForget_(IC.SHEET);
  if (added) icNotifySoon_();
  return (added ? '問題事項報告書（フォーム）：' + added + '件を取り込みました' : '') +
    (firsts.length ? (added ? '／' : '') + '問題事項報告書のフォームを登録しました（これから届く回答を取り込みます）：' + firsts.join('、') : '');
}

// ─────────────────────── 4. 始末書（チームページ） ───────────────────────

/** そのクラブに出ている譴責（始末書）の一覧。lineupContext から呼ぶ */
function icSimatsuForUniv_(univ) {
  var subs = icSubRows_(), reps = {};
  icRows_().forEach(function (r) { reps[String(r['報告ID'])] = r; });
  return icDecRows_().filter(function (d) {
    return icNorm_(d['当該クラブ']) === icNorm_(univ) && String(d['処分'] || '').split('・').indexOf('譴責') >= 0;
  }).map(function (d) {
    var id = String(d['報告ID']), r = reps[id] ? icView_(reps[id]) : {};
    return { id: id, match: (r.comp || '') + '　' + (r.round || '') + (r.no ? '　No.' + r.no : '') + '　' + (r.home || '') + ' vs ' + (r.away || ''),
      date: r.date || '', deadline: icStr_(d['始末書の提出期限'], 'yyyy-MM-dd'), submitted: icSimatsuOf_(id, subs) };
  }).sort(function (a, b) { return a.date < b.date ? 1 : -1; });
}

function icSimatsuAuth_(u, t, id) {
  var univ = lnAuth_(u, t);
  var d = icDecRows_().filter(function (x) { return String(x['報告ID']) === String(id); })[0];
  if (!d || icNorm_(d['当該クラブ']) !== icNorm_(univ) || String(d['処分'] || '').split('・').indexOf('譴責') < 0) throw new Error('このクラブへの譴責（始末書）が見つかりません');
  return { univ: univ, dec: d };
}

/** 始末書の書式（Word）を、その事案の内容を入れて作る */
function icSimatsuDocx_(v) {
  var blob = Utilities.newBlob(Utilities.base64Decode(IC_SIMATSU_DOCX_B64), 'application/zip', 'a.zip');
  var files = Utilities.unzip(blob);
  var x = function (s) { return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
  var fill = {
    '{{UNIV}}': v.party || 'クラブ',
    '{{DATEPLACE}}': (typeof snDocDate_ === 'function' ? snDocDate_(v.date) : v.date) + (v.kickoff ? '　' + v.kickoff + ' キックオフ' : '') + (v.venue ? '　' + v.venue : ''),
    '{{MATCH}}': (v.comp || '') + (v.round ? '　' + v.round : '') + (v.no ? '　マッチNo.' + v.no : '') + '　' + (v.home || '') + ' 対 ' + (v.away || '') + (v.kinds ? '　事案：' + v.kinds : '')
  };
  var out = files.map(function (f) {
    if (f.getName() !== 'word/document.xml') return f;
    var s = f.getDataAsString('UTF-8');
    Object.keys(fill).forEach(function (k) { s = s.split(k).join(x(fill[k])); });
    return Utilities.newBlob(s, 'application/xml', f.getName());
  });
  var z = Utilities.zip(out, '始末書_' + (v.party || '') + '_No' + (v.no || '') + '.docx');
  return z.setContentType('application/vnd.openxmlformats-officedocument.wordprocessingml.document');
}

function lineupSimatsuTemplate(u, t, id) {
  icSimatsuAuth_(u, t, id);
  var r = icRows_().filter(function (x) { return String(x['報告ID']) === String(id); })[0];
  var b = icSimatsuDocx_(r ? icView_(r) : {});
  return { name: b.getName(), mime: b.getContentType(), b64: Utilities.base64Encode(b.getBytes()) };
}

/** 始末書の提出（f：{name, mime, b64}） */
function lineupSimatsuUpload(u, t, id, f, by) {
  var a = icSimatsuAuth_(u, t, id);
  by = String(by || '').trim();
  if (!by) throw new Error('提出する人の名前を入力してください');
  if (!f || !f.b64) throw new Error('ファイルを選んでください');
  var bytes = Utilities.base64Decode(f.b64);
  if (bytes.length > 15 * 1024 * 1024) throw new Error('ファイルが大きすぎます（15MBまで）');
  var name = '始末書_' + a.univ + '_' + icToday_() + (String(f.name || '').match(/\.[A-Za-z0-9]+$/) || [''])[0];
  var file = DriveApp.createFile(Utilities.newBlob(bytes, f.mime || 'application/octet-stream', name));
  var compId = String(a.dec['試合ID'] || '').replace(/-[^-]+$/, '');
  if (typeof fileDoc_ === 'function') fileDoc_(file, compId, '始末書', name);
  // 全体システム・規律委員会が開けるように
  ['管理者メール', '規律委員会メール'].forEach(function (k) {
    String((typeof cfg_ === 'function' && cfg_(k)) || '').split(/[,\s]+/).filter(Boolean).forEach(function (m) { try { file.addViewer(m); } catch (e) {} });
  });
  var lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    icSubRows_().forEach(function (s) { if (String(s['報告ID']) === String(id) && String(s['状態']) !== '差し替え') update_(IC.SUB, s._row, { '状態': '差し替え' }); });
    lnSheet_(IC.SUB, IC_SUB_COLS).appendRow(IC_SUB_COLS.map(function (k) {
      return { '提出ID': id_('SIM'), '報告ID': String(id), '試合ID': String(a.dec['試合ID']), 'クラブ名': a.univ, '提出者': by,
        '提出日時': "'" + icNow_(), 'ファイルURL': file.getUrl(), 'ファイル名': name, '状態': '提出' }[k] || '';
    }));
    if (typeof memoForget_ === 'function') memoForget_(IC.SUB);
  } finally { lock.releaseLock(); }
  icNotifySoon_();
  return { ok: true, message: '始末書を提出しました。規律委員会へ知らせます。' };
}

// ─────────────────────── 公式記録の入力ページ ───────────────────────

function incidentSummary(mid) {
  var l = icRows_().filter(function (r) { return String(r['試合ID']) === String(mid) && String(r['状態']) !== '取り下げ'; });
  return { count: l.length, kinds: l.map(function (r) { return String(r['種類'] || 'その他'); }).join('・') };
}

// ─────────────────────── 今シーズンの処分一覧 ───────────────────────

/** 処分一覧のファイル（規律委員会開催事項。出場停止以外の処分案件はここが元） */
var IC_PAST_FILE_DEFAULT = ''; // システム設定「処分一覧ファイルID」に入れる（学連版のファイルは使わない）

/**
 * これまでの処分（出場停止以外の処分案件の元）
 *   システム設定「処分一覧ファイルID」（既定 IC_PAST_FILE_DEFAULT）のファイルの、今年のシート（例「2026」）を読む。
 *   Excel（.xlsx）のままでもGoogleスプレッドシートでも読める。30分ごとに読み直す。
 *   読めないときは「処分一覧（これまで）」タブ（なければ組み込みの一覧）を使う。
 */
function icPastRows_() {
  var cache = CacheService.getScriptCache();
  var hit = cache.get('IC_PAST_ROWS');
  if (hit) { try { return JSON.parse(hit); } catch (e) {} }
  var rows = null;
  try { rows = icReadPastFile_(); } catch (e) { try { log_('処分一覧ファイルの読込エラー', '処分', '', null, null, String(e && e.message || e)); } catch (x) {} }
  if (!rows) rows = icPastSheetRows_();
  try { cache.put('IC_PAST_ROWS', JSON.stringify(rows), 1800); } catch (e) {}
  return rows;
}

function icPastSheetRows_() {
  var ss = ss_();
  var sh = ss.getSheetByName(IC.PAST);
  if (!sh) {
    sh = ss.insertSheet(IC.PAST);
    sh.getRange(1, 1, 1, IC_PAST_COLS.length).setValues([IC_PAST_COLS]).setFontWeight('bold').setBackground('#E8F4FB');
    if (IC_PAST_2026.length && Number(icToday_().slice(0, 4)) === IC_PAST_YEAR) sh.getRange(2, 1, IC_PAST_2026.length, IC_PAST_COLS.length).setNumberFormat('@').setValues(IC_PAST_2026.map(function (r) { return r.map(String); }));
    sh.setFrozenRows(1); sh.setColumnWidth(5, 180); sh.setColumnWidth(6, 320); sh.setColumnWidth(7, 220);
    if (typeof memoForget_ === 'function') memoForget_(IC.PAST);
  }
  return objs_(IC.PAST).filter(function (r) { return String(r['対象クラブ'] || '') || String(r['対象事案'] || ''); })
    .map(function (r) { var o = {}; IC_PAST_COLS.forEach(function (k) { o[k] = r[k] instanceof Date ? Utilities.formatDate(r[k], 'Asia/Tokyo', 'M/d') : String(r[k] == null ? '' : r[k]); }); return o; });
}

/** 処分一覧ファイルを読む（見出し「No.」「決定内容」の行から下）。見つからなければ null */
function icReadPastFile_() {
  var id = String((typeof cfg_ === 'function' && cfg_('処分一覧ファイルID')) || IC_PAST_FILE_DEFAULT).trim().replace(/^.*\/d\/([^/?#]+).*$/, '$1');
  if (!id) return null;
  var year = icToday_().slice(0, 4);
  var file = DriveApp.getFileById(id);
  var grid;
  if (file.getMimeType() === MimeType.GOOGLE_SHEETS) {
    var book = SpreadsheetApp.openById(id);
    var sh = book.getSheetByName(year) || book.getSheets()[0];
    grid = sh.getDataRange().getValues().map(function (r) { return r.map(function (x) { return x instanceof Date ? Utilities.formatDate(x, 'Asia/Tokyo', 'M/d') : String(x == null ? '' : x); }); });
  } else {
    grid = icXlsxSheet_(file.getBlob(), year);
  }
  if (!grid) return null;
  var hi = -1;
  for (var i = 0; i < Math.min(grid.length, 10); i++) {
    var j = grid[i].map(function (x) { return String(x).replace(/\s/g, ''); });
    if (j.indexOf('決定内容') >= 0 && j.some(function (x) { return /^No\.?$/i.test(x); })) { hi = i; break; }
  }
  if (hi < 0) return null;
  var H = grid[hi].map(function (x) { return String(x).replace(/\s/g, ''); });
  var col = function (k) { return H.indexOf(k); };
  return grid.slice(hi + 1).map(function (r) {
    var o = {};
    IC_PAST_COLS.forEach(function (k) { var c = col(k.replace('.', '.')); o[k] = c >= 0 ? String(r[c] == null ? '' : r[c]).trim() : ''; });
    if (!o['No.'] && col('No') >= 0) o['No.'] = String(r[col('No')] || '');
    return o;
  }).filter(function (o) { return o['対象クラブ'] || o['対象事案']; });
}

/** .xlsx のシートを2次元配列で読む（日付のシリアル値は「M/d」にする） */
function icXlsxSheet_(blob, name) {
  var files = Utilities.unzip(blob.setContentType('application/zip'));
  var byName = {};
  files.forEach(function (f) { byName[f.getName()] = f; });
  var X = function (p) { return byName[p] ? XmlService.parse(byName[p].getDataAsString('UTF-8')).getRootElement() : null; };
  var ns = XmlService.getNamespace('http://schemas.openxmlformats.org/spreadsheetml/2006/main');
  var rns = XmlService.getNamespace('r', 'http://schemas.openxmlformats.org/officeDocument/2006/relationships');
  var wb = X('xl/workbook.xml');
  if (!wb) return null;
  var sheets = wb.getChild('sheets', ns).getChildren('sheet', ns);
  var sheet = sheets.filter(function (s) { return String(s.getAttribute('name').getValue()).trim() === name; })[0] || sheets[0];
  var rid = sheet.getAttribute('id', rns).getValue();
  var rels = X('xl/_rels/workbook.xml.rels');
  var target = '';
  rels.getChildren().forEach(function (r) { if (r.getAttribute('Id').getValue() === rid) target = r.getAttribute('Target').getValue(); });
  target = target.replace(/^\/?xl\//, '').replace(/^\//, '');
  var sst = [];
  var ss = X('xl/sharedStrings.xml');
  if (ss) ss.getChildren('si', ns).forEach(function (si) {
    var t = '';
    var walk = function (el) { el.getChildren().forEach(function (c) { if (c.getName() === 't') t += c.getText(); else walk(c); }); };
    walk(si);
    sst.push(t);
  });
  var sh = X('xl/' + target);
  if (!sh) return null;
  var grid = [];
  var colNo = function (ref) { var m = String(ref).match(/^([A-Z]+)/); var n = 0; for (var i = 0; i < m[1].length; i++) n = n * 26 + (m[1].charCodeAt(i) - 64); return n - 1; };
  sh.getChild('sheetData', ns).getChildren('row', ns).forEach(function (row) {
    var ri = Number(row.getAttribute('r').getValue()) - 1;
    var out = grid[ri] = grid[ri] || [];
    row.getChildren('c', ns).forEach(function (c) {
      var t = c.getAttribute('t') ? c.getAttribute('t').getValue() : '';
      var v = c.getChild('v', ns), val = '';
      if (t === 's' && v) val = sst[Number(v.getText())] || '';
      else if (t === 'inlineStr') { var is = c.getChild('is', ns); val = is ? is.getValue() : ''; }
      else if (v) val = v.getText();
      if (/^-?\d+\.0+$/.test(val)) val = val.replace(/\.0+$/, ''); // 206.0 → 206
      out[colNo(c.getAttribute('r').getValue())] = val;
    });
  });
  for (var i = 0; i < grid.length; i++) grid[i] = grid[i] || [];
  // 日程の列の日付（シリアル値）を「M/d」に
  var hdr = -1;
  grid.some(function (r, i) { if (r.indexOf('日程') >= 0) { hdr = i; return true; } return false; });
  if (hdr >= 0) {
    var dc = grid[hdr].indexOf('日程');
    for (var k = hdr + 1; k < grid.length; k++) {
      var x = grid[k][dc];
      if (/^\d{5}(\.\d+)?$/.test(String(x || ''))) {
        var d = new Date(Date.UTC(1899, 11, 30) + Number(x) * 86400000);
        grid[k][dc] = (d.getUTCMonth() + 1) + '/' + d.getUTCDate();
      }
    }
  }
  return grid;
}

/** 「5/16」→ 2026-05-16 */
function icPastDate_(s) {
  if (s instanceof Date) return Utilities.formatDate(s, 'Asia/Tokyo', 'yyyy-MM-dd');
  var m = String(s || '').match(/(\d{1,2})\/(\d{1,2})/);
  return m ? icToday_().slice(0, 4) + '-' + ('0' + m[1]).slice(-2) + '-' + ('0' + m[2]).slice(-2) : '';
}

/**
 * 今シーズンの処分一覧（規律委員会開催事項と同じ並び）
 *   これまでの分（手入力のタブ）＋ このシステムで決めた問題事項の処分 ＋ 手入力より後の出場停止（処分管理）
 */
function icSeasonList_() {
  var out = [];
  var reps = {};
  icRows_().forEach(function (r) { reps[String(r['報告ID'])] = icView_(r); });
  icDecRows_().forEach(function (d) {
    var v = reps[String(d['報告ID'])]; if (!v) return;
    out.push({ date: v.date, comp: v.comp, mn: v.no, univ: v.party, matter: v.kinds + '：' + v.detail.replace(/\s*\n\s*/g, ''), result: icPenaltyLabel_(icDecView_(d)), source: 'システム', id: v.id });
  });
  // 出場停止：処分管理（システム）
  try {
    var by = function (list, k) { var o = {}; list.forEach(function (x) { o[String(x[k])] = x; }); return o; };
    var matches = by(objs_(シート.試合), '試合ID'), teams = by(objs_(シート.チーム), 'チームID'), comps = by(objs_(シート.大会), '大会ID');
    var players = by(objs_('選手マスター'), '選手ID');
    objs_('処分管理').forEach(function (s) {
      if (/TEST|KIRIN/i.test(String(s['大会ID'] || ''))) return;
      if (!/決定|確認済/.test(String(s['処分状態']) + String(s['委員会確認']))) return;
      var m = matches[String(s['発生試合ID'])] || {};
      var d = stDate_(m['実施日']) || stDate_(m['開催予定日']);
      if (!d) return;
      var t = teams[String(s['チームID'])] || {}, p = players[String(s['選手ID'])] || {};
      out.push({ date: d, comp: String((comps[String(m['大会ID'])] || {})['大会名'] || m['大会ID'] || ''), mn: String(m['マッチNo'] || ''),
        univ: String(t['略称'] || t['クラブ名'] || '') + '\n' + String(p['氏名'] || ''), matter: String(s['処分種別'] || ''),
        result: (Number(s['停止試合数']) || 1) + '試合出場停止', source: 'システム' });
    });
  } catch (e) {}
  // 出場停止以外：処分一覧のファイル（システムで決めたものと同じ日・MN・クラブなら重ねない）
  var sys = out.filter(function (x) { return x.id; });
  icPastRows_().forEach(function (r) {
    var result = String(r['決定内容'] || '');
    if (/出場停止/.test(result)) return;
    var x = { date: icPastDate_(r['日程']), comp: String(r['大会'] || ''), mn: String(r['MN'] || ''), univ: String(r['対象クラブ'] || ''),
      matter: String(r['対象事案'] || ''), result: result, source: '処分一覧' };
    var dup = sys.some(function (y) { return y.date === x.date && String(y.mn) === String(x.mn) && icSameUniv_(icAliases_(y.univ), x.univ); });
    if (!dup) out.push(x);
  });
  return out.sort(function (a, b) { return (a.date || '9') < (b.date || '9') ? -1 : (a.date || '9') > (b.date || '9') ? 1 : 0; });
}

/** そのクラブのこれまでの処分（検討ページ用） */
function icHistoryFor_(univ, exceptId) {
  var al = icAliases_(univ);
  return icSeasonList_().filter(function (x) { return x.id !== exceptId && icSameUniv_(al, x.univ); });
}

// ─────────────────────── 2. 処分検討（規律委員会：?page=incident&case=…&t=…） ───────────────────────

function icCheck_(id, t) {
  if (!id || !t || icToken_(id) !== String(t)) throw new Error('リンクが正しくありません。LINEのリンクから開き直してください。');
}

function icDefaultFact_(v) {
  var d = typeof snDocDate_ === 'function' ? snDocDate_(v.date) : v.date;
  return d + '、' + v.comp + (v.round ? '　' + v.round : '') + '　' + v.home + ' 対 ' + v.away + ' の試合において、' + v.detail.replace(/\s*\n\s*/g, '');
}

/** 勝点没収の対象になるチーム（当該クラブのチームのうち、その試合の大会のもの） */
function icTeamsFor_(v) {
  var m = objs_(シート.試合).filter(function (x) { return String(x['試合ID']) === v.matchId; })[0] || {};
  var comp = String(m['大会ID'] || '');
  var u = icNorm_(v.party);
  var list = objs_(シート.チーム).filter(function (t) { return icNorm_(t['クラブ名']) === u; }).map(function (t) {
    return { id: String(t['チームID']), name: String(t['チーム名'] || t['略称'] || t['チームID']), comp: String(t['大会ID'] || ''), same: String(t['大会ID'] || '') === comp };
  });
  var inMatch = [String(m['ホームチームID'] || ''), String(m['アウェイチームID'] || '')];
  list.sort(function (a, b) { return (inMatch.indexOf(b.id) >= 0) - (inMatch.indexOf(a.id) >= 0) || (b.same - a.same); });
  return list;
}

function getIncidentReview(id, t) {
  icCheck_(id, t);
  return withReadMemo_(function () {
    var v = icView_(icFind_(id));
    var dec = icDecView_(icDecFor_(id));
    var nt = dec ? icNoticeRow_(dec.nid) : null;
    var sim = icSimatsuOf_(id);
    return {
      report: v, decision: dec, stage: icStage_(dec, nt, sim), penalties: IC_PENALTIES, appealDefault: IC_APPEAL_DEFAULT,
      defaultFact: icDefaultFact_(v), defaultDeadline: snAddDays_(icToday_(), IC_SIMATSU_DAYS),
      teams: icTeamsFor_(v), history: icHistoryFor_(v.party, id),
      noticeStatus: nt ? String(nt['状態']) : '', noticePdf: nt ? String(nt['PDF URL'] || '') : '', simatsu: sim,
      locked: !!(nt && ['承認', '送信済'].indexOf(String(nt['状態'])) >= 0)
    };
  });
}

/** 決定（p：penalties[], points, teamId, duty, other, deadline, sendNotice, fact, basis, appeal, name, comment） */
function submitIncidentDecision(id, t, p) {
  icCheck_(id, t);
  p = p || {};
  var name = String(p.name || '').trim();
  var pens = (p.penalties || []).filter(function (k) { return IC_PENALTIES.some(function (x) { return x.k === k; }); });
  if (!name) throw new Error('お名前を入力してください');
  if (!pens.length) throw new Error('処分を選んでください');
  if (pens.indexOf('処分なし') >= 0) pens = ['処分なし'];
  var has = function (k) { return pens.indexOf(k) >= 0; };
  if (has('勝点没収') && !(Number(p.points) > 0)) throw new Error('没収する勝点を入れてください');
  if (has('勝点没収') && !p.teamId) throw new Error('勝点を没収するチームを選んでください');
  if (has('運営業務') && !String(p.duty || '').trim()) throw new Error('課す運営業務の内容を書いてください');
  if (has('その他') && !String(p.other || '').trim()) throw new Error('「その他」の処分の内容を書いてください');
  var send = !has('処分なし') && !!p.sendNotice;
  if (send && !String(p.fact || '').trim()) throw new Error('認定事実を書いてください');
  var inc = icFind_(id);
  var lock = LockService.getScriptLock(); lock.waitLock(30000);
  var nid = '';
  try {
    var cur = icDecFor_(id);
    var old = cur ? icNoticeRow_(cur['通知ID']) : null;
    if (old && ['承認', '送信済'].indexOf(String(old['状態'])) >= 0) throw new Error('決定通知はすでに' + old['状態'] + 'です。変更は事務局に相談してください');
    if (old && ['承認待ち', '修正依頼'].indexOf(String(old['状態'])) >= 0) ntUpdate_(old._row, { '状態': '作り直し', 'コメント': '処分の決定が変更されたため ' + icNow_() });
    var dec = {
      penalties: pens, points: has('勝点没収') ? Number(p.points) : 0, teamId: has('勝点没収') ? String(p.teamId) : '',
      duty: has('運営業務') ? String(p.duty).trim() : '', other: has('その他') ? String(p.other).trim() : '',
      deadline: has('譴責') ? String(p.deadline || '') : '', sendNotice: send,
      fact: String(p.fact || '').trim(), basis: String(p.basis || '').trim(), appeal: String(p.appeal || '').trim()
    };
    if (send) nid = icMakeNotice_(icView_(inc), dec).nid;
    var vals = {
      '報告ID': String(id), '試合ID': String(inc['試合ID']), '当該クラブ': String(inc['当該クラブ']), '処分': pens.join('・'),
      '勝点没収': dec.points || '', '対象チームID': dec.teamId, '運営業務の内容': dec.duty, '処分の内容（その他）': dec.other,
      '始末書の提出期限': dec.deadline ? "'" + dec.deadline : '', '決定通知': send ? '送る' : '送らない',
      '認定事実': dec.fact, '根拠条文': dec.basis, '不服申立': dec.appeal,
      '決定者': name, '決定日時': "'" + icNow_(), 'コメント': String(p.comment || '').trim(), '通知ID': nid
    };
    if (cur) update_(IC.DEC, cur._row, vals);
    else { lnSheet_(IC.DEC, IC_DEC_COLS).appendRow(IC_DEC_COLS.map(function (k) { return vals[k] == null ? '' : vals[k]; })); if (typeof memoForget_ === 'function') memoForget_(IC.DEC); }
  } finally { lock.releaseLock(); }
  if (has('勝点没収') && typeof scheduleRecalc_ === 'function') scheduleRecalc_(); // 順位表に反映
  var label = icPenaltyLabel_(dec);
  if (!nid) return { ok: true, message: '「' + label + '」で決定しました。' + (has('勝点没収') ? '順位表に反映します。' : '') };
  var res = typeof ntRequestApproval_ === 'function' ? (ntRequestApproval_([nid]) || {}) : {};
  return { ok: true, message: '「' + label + '」で決定しました。クラブあての決定通知を作り、承認依頼を送りました' + (res.ok === false ? '（送信エラー：' + res.error + '）' : '') +
    '。承認されると、すぐにクラブへ送られます。' + (has('勝点没収') ? '勝点は順位表に反映します。' : '') };
}

// ─────────────────────── 3. 決定通知（クラブあて） ───────────────────────

function icNotice_(v, dec) {
  var m = objs_(シート.試合).filter(function (x) { return String(x['試合ID']) === v.matchId; })[0] || {};
  var c = objs_(シート.大会).filter(function (x) { return String(x['大会ID']) === String(m['大会ID'] || ''); })[0] || null;
  var compName = (c && typeof snCompName_ === 'function' ? snCompName_(c) : '') || v.comp;
  var contact = typeof snContactFor_ === 'function' ? snContactFor_(snContacts_(), v.party) : null;
  var to = contact ? [contact.mail] : [];
  if (!to.length) {
    objs_(シート.チーム).forEach(function (t) {
      if (icNorm_(t['クラブ名']) !== icNorm_(v.party)) return;
      [t['責任者メール'], t['監督メール']].forEach(function (x) { x = String(x || '').trim(); if (x && to.indexOf(x) < 0) to.push(x); });
    });
  }
  var team = dec.teamId ? (objs_(シート.チーム).filter(function (t) { return String(t['チームID']) === dec.teamId; })[0] || {}) : {};
  var teamComp = team['大会ID'] ? objs_(シート.大会).filter(function (x) { return String(x['大会ID']) === String(team['大会ID']); })[0] : null;
  var S = {
    'カウント': '本事案を記録し、回数に数える。',
    '口頭での指導': '口頭で指導する。',
    '全体周知': '本事案を全クラブに周知する。',
    '戒告': '戒告とする。',
    '厳重注意': '厳重注意とする。今後、同様の事案が生じないよう、再発防止に努めること。',
    '譴責': '譴責の処分を科す。添付の書式により始末書を作成し、クラブの代表者の署名を得たうえで、' +
      (dec.deadline ? snJpDate_(dec.deadline, true) + 'までに、' : '') + 'チームページの「始末書」から提出すること。',
    '勝点没収': '『' + ((teamComp && snCompName_(teamComp)) || compName) + '』における' + String(team['チーム名'] || v.party) + 'の勝点' + dec.points + 'を没収する。',
    '運営業務': '次の運営業務を課す。' + dec.duty.replace(/[。．]?$/, '。'),
    'HKFA事案として移送': '本事案を、北海道サッカー協会へ移送する。',
    'その他': dec.other.replace(/[。．]?$/, '。')
  };
  var content = '当事者に対し、『' + compName + '』の下記試合における事案について、' + dec.penalties.map(function (k) { return S[k] || ''; }).join('');
  return {
    type: 'incident', incidentId: v.id, sanctionId: 'INC-' + v.id, kind: icPenaltyLabel_(dec).slice(0, 40),
    matchId: v.matchId, teamName: v.party, playerName: '', compName: compName, penaltyText: content,
    basis: dec.basis, fact: dec.fact, appeal: dec.appeal, simatsu: dec.penalties.indexOf('譴責') >= 0,
    origin: { comp: compName + (v.round ? '　' + v.round : ''), card: v.home + ' vs ' + v.away, date: snDocDate_(v.date) + (v.kickoff ? '　' + v.kickoff + ' キックオフ' : ''), venue: v.venue },
    chair: typeof cfg_ === 'function' && cfg_('規律委員長名') ? String(cfg_('規律委員長名')) : '',
    issued: snJpDate_(icToday_(), true), to: to, contactName: contact ? contact.name : ''
  };
}

function icSections_(n) {
  var s = [];
  var no = function () { return '１２３４５６'.charAt(s.length) + '．'; };
  s.push({ h: no() + '当事者', lines: [n.teamName] });
  s.push({ h: no() + '処分の内容', lines: [n.penaltyText] });
  if (n.basis) s.push({ h: no() + '根拠条文', lines: [n.basis] });
  s.push({ h: no() + '認定事実', lines: [n.fact, '【当該試合】'], sub: ['競技会：' + n.origin.comp, '対　戦：' + n.origin.card, '日　時：' + n.origin.date + (n.origin.venue ? '　会場：' + n.origin.venue : '')] });
  if (n.appeal) s.push({ h: no() + '不服申立について', lines: [n.appeal] });
  return s;
}
var IC_LEAD = '当委員会は貴クラブに関する事案につき、日本サッカー協会司法機関組織運営規則及び懲罰規程に基づき審議し、下記のとおり決定したので通知します。';

function icHtml_(n) {
  var e = function (x) { return String(x == null ? '' : x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
  var ind = function (x, px) { return '<div style="padding-left:' + (px || 16) + 'px">' + e(x) + '</div>'; };
  return '<div class="doc"><div style="text-align:right">' + e(n.issued) + '</div>' +
    '<div style="margin-top:6px;font-size:1.1em">' + e(n.teamName) + '　御中</div>' +
    '<div style="text-align:right;margin-top:4px">' + orgName_() + '<br>規律委員会委員長　' + e(n.chair) + '</div>' +
    '<div style="text-align:center;font-size:1.3em;font-weight:700;margin:10px 0 8px">決定通知</div><div>' + e(IC_LEAD) + '</div>' +
    '<div style="text-align:center;margin:6px 0 2px">記</div>' +
    icSections_(n).map(function (x) {
      return '<b>' + e(x.h) + '</b>' + x.lines.map(function (l) { return ind(l); }).join('') + (x.sub || []).map(function (l) { return ind(l, 28); }).join('');
    }).join('') + '<div style="text-align:right;margin-top:6px">以上</div>' +
    (n.simatsu ? '<div style="margin-top:6px;color:#888888;font-size:12px">添付：始末書の書式（Word）</div>' : '') + '</div>';
}

function icCreatePdf_(n) {
  var name = '決定通知_問題事項_' + n.teamName + '_' + n.matchId;
  var pdf;
  try {
    var doc = DocumentApp.create(name);
    var b = doc.getBody();
    b.setMarginTop(42).setMarginBottom(36).setMarginLeft(56).setMarginRight(56);
    b.clear();
    var P = function (text, o) {
      o = o || {};
      var p = b.appendParagraph(text || '');
      p.setFontFamily('Noto Sans JP').setFontSize(o.size || 10).setBold(!!o.bold).setLineSpacing(1.15).setSpacingBefore(o.before || 0).setSpacingAfter(o.after || 1);
      if (o.align === 'right') p.setAlignment(DocumentApp.HorizontalAlignment.RIGHT);
      if (o.align === 'center') p.setAlignment(DocumentApp.HorizontalAlignment.CENTER);
      if (o.indent) p.setIndentStart(o.indent).setIndentFirstLine(o.indent);
      return p;
    };
    P(n.issued, { align: 'right' });
    P(n.teamName + '　御中', { size: 12, before: 6 });
    P(orgName_(), { align: 'right', before: 4 });
    P('規律委員会委員長　' + n.chair, { align: 'right' });
    P('決定通知', { align: 'center', size: 15, bold: true, before: 10, after: 8 });
    P(IC_LEAD);
    P('記', { align: 'center', before: 6, after: 2 });
    icSections_(n).forEach(function (x) {
      P(x.h, { bold: true, before: 6 });
      x.lines.forEach(function (l) { P(l, { indent: 20 }); });
      (x.sub || []).forEach(function (l) { P(l, { indent: 28 }); });
    });
    P('以上', { align: 'right', before: 6 });
    if (n.simatsu) P('添付：始末書の書式（Word）', { size: 9, before: 6 });
    doc.saveAndClose();
    var file = DriveApp.getFileById(doc.getId());
    pdf = DriveApp.createFile(file.getAs(MimeType.PDF)).setName(name + '.pdf');
    try { file.setTrashed(true); } catch (e) {}
  } catch (e) {
    var html = '<html><head><meta charset="utf-8"><style>@page{size:A4;margin:14mm 18mm}body{font-family:"Noto Sans JP",sans-serif;font-size:10pt;line-height:1.5;color:#222222}.doc b{display:block;margin-top:6px}</style></head><body>' + icHtml_(n) + '</body></html>';
    pdf = DriveApp.createFile(Utilities.newBlob(html, MimeType.HTML, name + '.html').getAs(MimeType.PDF)).setName(name + '.pdf');
  }
  if (typeof fileDoc_ === 'function') {
    var m = objs_(シート.試合).filter(function (x) { return String(x['試合ID']) === n.matchId; })[0] || {};
    fileDoc_(pdf, String(m['大会ID'] || ''), '処分通知', name + '.pdf');
  }
  return pdf;
}

function icMakeNotice_(v, dec) {
  var n = icNotice_(v, dec);
  var pdf = icCreatePdf_(n);
  var nid = 'NT-' + Utilities.getUuid().replace(/-/g, '').slice(0, 10);
  ntAppend_({
    '通知ID': nid, '処分ID': n.sanctionId, '選手': '（問題事項）', 'チーム': n.teamName, '処分種別': n.kind,
    '発生試合ID': n.matchId, '最初の対象試合ID': '', '対象試合日': '', '状態': '承認待ち',
    '作成日時': ntNow_(), '文書ID': '', 'PDF ID': pdf.getId(), 'PDF URL': pdf.getUrl(), '内容キー': ntKey_(n), '内容': ntPack_(n),
    '承認依頼日時': '', '宛先': n.to.join(',')
  });
  return { nid: nid, n: n };
}

/** 承認されたら、すぐにクラブへ送る（NoticeFlow.gs の承認から呼ばれる） */
function icSendApproved_(r) {
  var n = ntUnpack_(r['内容']) || {};
  if (!n.to || !n.to.length) return '宛先が見つかりません（「処分通知の連絡先」に' + n.teamName + 'を登録してください）。送っていません。';
  var admin = typeof cfg_ === 'function' ? String(cfg_('管理者メール') || '') : '';
  var atts = [DriveApp.getFileById(String(r['PDF ID'])).getAs(MimeType.PDF)];
  var rep = null;
  try { rep = icView_(icFind_(n.incidentId)); } catch (e) {}
  if (n.simatsu && rep) { try { atts.push(icSimatsuDocx_(rep)); } catch (e) {} }
  var subject = '【決定通知】' + n.teamName + '　問題事項に関する処分（' + n.kind + '）のお知らせ';
  var addr = typeof snAddressHtml_ === 'function' ? snAddressHtml_(n) : snEsc_(n.teamName) + '<br>ご担当者様';
  var custom = typeof cfg_ === 'function' ? String(cfg_('処分通知の本文（問題事項）') || '').trim() : '';
  var html = '<p>' + addr + '</p>' +
    (custom ? '<p>' + snEsc_(custom) + '</p>' :
      '<p>いつも大変お世話になっております。<br>' + snEsc_(orgName_()) + ' 規律委員長' + (cfg_('規律委員長名') ? 'の' + snEsc_(String(cfg_('規律委員長名')).split(/[\s　]/)[0]) : '') + 'でございます。</p>' +
      '<p>このたび、下記の試合で報告された問題事項につきまして、規律委員会の決定通知をお送りいたします。</p>') +
    '<p>処分：' + snEsc_(n.kind) + '<br>試合：' + snEsc_(n.origin.comp) + '<br>' + snEsc_(n.origin.card) + '（' + snEsc_(n.origin.date) + '）</p>' +
    (custom ? '' : '<p>添付の決定通知書をチーム関係者の皆様にご共有いただき、内容をご確認のうえ、ご対応くださいますようお願い申し上げます。</p>') +
    (n.simatsu ? '<p style="border-left:3px solid #D84315;padding-left:8px">あわせて、始末書の書式（Word）を添付しております。ご記入のうえクラブの代表者のご署名をいただき、チームページの「始末書」からご提出ください（PDF・写真でも差し支えございません）。</p>' : '') +
    (custom ? '' : '<p>ご不明な点がございましたら、下記までお問い合わせください。<br>何卒よろしくお願い申し上げます。</p>') +
    (typeof snSignatureHtml_ === 'function' ? snSignatureHtml_() : '');
  sendMail_({ to: n.to.join(','), cc: typeof snCc_ === 'function' ? snCc_() : admin, subject: subject, htmlBody: html, attachments: atts,
    name: orgName_() + ' 規律委員会', noTest: true });
  ntMarkSent_({ row: r._row }, n.to);
  var sh = ntSs_().getSheetByName('通知履歴');
  if (sh) {
    var h = sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0].map(String);
    var o = { '通知ID': 'NTF-' + Utilities.getUuid().slice(0, 12), '通知種別': IC_NOTICE_KIND, '関連試合ID': n.matchId, '関連処分ID': n.sanctionId,
      '宛先': n.to.join(','), '件名': subject, '送信日時': icNow_(), '送信状態': '送信済', 'エラー内容': '' };
    sh.appendRow(h.map(function (k) { return o[k] !== undefined ? o[k] : ''; }));
  }
  return n.teamName + '（' + n.to.join(',') + '）へ送信しました。';
}

/** ダッシュボードで認定事実・根拠条文を直して作り直す */
function icEditNotice_(r, basis, fact) {
  var id = String(r['処分ID']).replace(/^INC-/, '');
  var d = icDecFor_(id);
  if (!d) throw new Error('問題事項の処分が見つかりません');
  var lock = LockService.getScriptLock(); lock.waitLock(30000);
  var nid;
  try {
    update_(IC.DEC, d._row, { '根拠条文': String(basis || ''), '認定事実': String(fact || '') });
    d = icDecFor_(id);
    ntUpdate_(r._row, { '状態': '作り直し', 'コメント': '認定事実・根拠条文を直したため作り直し ' + icNow_() });
    nid = icMakeNotice_(icView_(icFind_(id)), icDecView_(d)).nid;
    update_(IC.DEC, d._row, { '通知ID': nid });
  } finally { lock.releaseLock(); }
  ntRequestApproval_([nid]);
  return '作り直して、規律委員会へ承認を依頼しました';
}

// ─────────────────────── 勝点没収（Standings.gs から） ───────────────────────

/** {チームID: 没収する勝点}（シートを直接読む。順位表の計算用） */
function icDeductions_(ss) {
  var out = {};
  var rows = typeof stRead_ === 'function' ? stRead_(ss || ss_(), IC.DEC) : [];
  rows.forEach(function (d) {
    if (String(d['処分'] || '').split('・').indexOf('勝点没収') < 0) return;
    var tid = String(d['対象チームID'] || ''), n = Number(d['勝点没収'] || 0);
    if (tid && n > 0) out[tid] = (out[tid] || 0) + n;
  });
  return out;
}

// ─────────────────────── 検討ページ ───────────────────────

function incidentReviewPage(e) {
  var p = (e && e.parameter) || {};
  var id = String(p['case'] || ''), t = String(p.t || '');
  var html = HtmlService.createTemplateFromFile('IncidentReview');
  html.caseId = id; html.token = t;
  return html.evaluate().setTitle('問題事項の処分検討')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1, viewport-fit=cover')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

// ─────────────────────── 事務局（ダッシュボード） ───────────────────────

function adminIncidents(tok) {
  adCheck_(tok);
  return withReadMemo_(function () {
    var decs = {};
    icDecRows_().forEach(function (d) { decs[String(d['報告ID'])] = icDecView_(d); });
    var nts = {};
    if (typeof ntRows_ === 'function') ntRows_().forEach(function (r) { nts[String(r['通知ID'])] = r; });
    var subs = icSubRows_();
    var base = typeof webAppBaseUrl_ === 'function' ? webAppBaseUrl_() : '';
    var list = icRows_().filter(function (r) { return String(r['状態']) !== '取り下げ'; }).map(function (r) {
      var v = icView_(r), d = decs[v.id] || null, nt = d && d.nid ? nts[d.nid] : null, sim = icSimatsuOf_(v.id, subs);
      v.decision = d ? { label: icPenaltyLabel_(d), by: d.by, at: d.at, comment: d.comment } : null;
      v.stage = icStage_(d, nt, sim);
      v.pending = !d;
      v.open = !d || /承認待ち|修正依頼|作成待ち|始末書 未提出/.test(v.stage);
      v.noticePdf = nt ? String(nt['PDF URL'] || '') : '';
      v.simatsu = sim;
      v.reviewUrl = icReviewUrl_(base, v.id);
      return v;
    }).sort(function (a, b) { return (a.pending !== b.pending) ? (a.pending ? -1 : 1) : ((a.date + a.kickoff < b.date + b.kickoff) ? 1 : -1); });
    return { list: list, season: icSeasonList_() };
  });
}

/** 処分検討待ちの件数（タブの数字） */
function icUncheckedCount_() {
  var decided = {};
  icDecRows_().forEach(function (d) { decided[String(d['報告ID'])] = true; });
  return icRows_().filter(function (r) { return String(r['状態']) !== '取り下げ' && !decided[String(r['報告ID'])] && !/TEST|KIRIN/i.test(String(r['試合ID'])); }).length;
}

/** 今シーズンの処分一覧を、スプレッドシートの「処分一覧（今シーズン）」タブに書き出す */
function adminWriteSeasonList(tok) {
  adCheck_(tok);
  var list = icSeasonList_();
  var ss = ss_(), name = '処分一覧（今シーズン）';
  var sh = ss.getSheetByName(name) || ss.insertSheet(name);
  sh.clear();
  var rows = [[icToday_().slice(0, 4) + '年　規律委員会開催事項', '', '', '', '', '', icToday_()], IC_PAST_COLS].concat(list.map(function (x, i) {
    var m = String(x.date).match(/\d{4}-(\d{2})-(\d{2})/);
    return [i + 1, m ? Number(m[1]) + '/' + Number(m[2]) : '', x.comp, x.mn, x.univ, x.matter, x.result];
  }));
  sh.getRange(1, 1, rows.length, 7).setNumberFormat('@').setValues(rows.map(function (r) { return r.map(String); }));
  sh.getRange(2, 1, 1, 7).setFontWeight('bold').setBackground('#E8F4FB');
  sh.getRange(1, 1).setFontWeight('bold');
  sh.setColumnWidth(5, 180); sh.setColumnWidth(6, 320); sh.setColumnWidth(7, 220);
  sh.getRange(3, 1, Math.max(rows.length - 2, 1), 7).setWrap(true).setVerticalAlignment('top');
  return { ok: true, message: '「' + name + '」タブに' + list.length + '件を書き出しました', url: ss.getUrl() + '#gid=' + sh.getSheetId() };
}

