// ==== Init.gs
/**
 * Init.gs v2
 * 新しい大会運営システム（2027年〜）｜今のシステムのコピーを、新しいシステムの出発点にする（最初に1回）
 *
 *  使い方：今のシステムのスプレッドシートを新しいアカウントで「ファイル → コピーを作成」する
 *  （プログラムもいっしょにコピーされる）→ 変わったファイルを貼り替える → メニューの「最初の設定」を実行。
 *
 *  ・試合・公式記録・警告退場・処分・通知などの記録を空にする（見出し・書式は残す）
 *  ・全体システム：クラブ・チーム・選手・選手登録・審判員・処分通知の連絡先などのマスターは残す
 *    リーグシステム：マスターも空にする（全体システムから取り込む）
 *  ・今シーズンだけのタブ（シーズンテスト・試合報告の取込など）を消す
 *  ・システム設定のうち、URL・フォーム・フォルダなど今のシステム専用の値を空にする
 *  ・テストモードなど、今のシステムの状態（スクリプトプロパティ）を消す
 */

/** 中身を残す表 */
var INIT_KEEP_CENTRAL = ['システム設定', '入力候補マスター', '大会マスター', 'チームマスター', 'チームスタッフマスター', '選手マスター', '選手登録',
  '審判員マスター', '処分通知の連絡先', 'チーム通知先', 'Discord送信待ち', 'クラブの連絡先'];
var INIT_KEEP_LEAGUE = ['システム設定', '入力候補マスター'];

/** 消すタブ（今シーズンだけのもの） */
var INIT_DROP = ['シーズンテスト', '試合報告の取込元', '試合報告の取込記録', '結果取込の確認', '選手名寄せの確認', '選手名簿の照合',
  'リンク集', 'スタメン・運営クラブリンク', 'LINE連絡先', '一括登録リンク', '00_使い方', '全体テスト結果', 'テスト送信ログ', '導入チェック'];

/** システム設定のうち、空にする項目 */
var INIT_SCRUB = /URL|フォームID|フォルダID|全体システムのID|担当大会ID|システムの役割|最終取込/;

/** 今のシステムの状態（スクリプトプロパティ）のうち、消すもの */
var INIT_PROPS = /^(TEST_MODE_TO|SELFTEST_|SYNC:|RECALC_AT|PUB_VER|REVIEW_NOTIFY_READY|REVIEW_CONFIRM_READY|MD7|MD2|LNREF:|NT_)/;

/** 今（2026年）のシステムのスプレッドシート。これには絶対に実行しない */
var INIT_OLD_ID = '1Dr4P8Pe3gQZ9G3ThiPAgI27g85jlnOdHL_0rqxjOZT8';

function initCleanCopy_(asRole) {
  var ss = ss_();
  if (ss.getId() === INIT_OLD_ID) throw new Error('これは今（2026年）のシステムです。コピーしたスプレッドシートで実行してください');
  // 全体システムのアカウントで「リーグにする」を押しても、本物の全体システムを消さないように止める
  var me = '';
  try { me = String(Session.getEffectiveUser().getEmail() || '').toLowerCase(); } catch (e) {}
  if (asRole === ROLE.LEAGUE && /^jufa\.hokkaido\.d\.c@/.test(me)) {
    throw new Error('全体システムのアカウント（' + me + '）では、リーグシステムにできません。リーグのアカウントでコピーしてから実行してください');
  }
  var keep = asRole === ROLE.LEAGUE ? INIT_KEEP_LEAGUE : INIT_KEEP_CENTRAL;
  var cleared = [], dropped = [];
  ss.getSheets().forEach(function (sh) {
    var name = sh.getName();
    if (INIT_DROP.indexOf(name) >= 0 || /_旧_\d{8}_\d{4}$|^PDF_.+_v\d+_\d+$|^審判報告書_作業用_/.test(name)) {
      if (ss.getSheets().length > 1) { ss.deleteSheet(sh); dropped.push(name); }
      return;
    }
    if (/テンプレート/.test(name) || keep.indexOf(name) >= 0) return;
    if (sh.getLastRow() > 1) {
      sh.getRange(2, 1, sh.getLastRow() - 1, sh.getMaxColumns()).clearContent();
      cleared.push(name);
    }
  });
  // システム設定の、今のシステム専用の値を空にする
  var cfg = ss.getSheetByName('システム設定');
  if (cfg && cfg.getLastRow() > 1) {
    var v = cfg.getDataRange().getValues(), h = v[0].map(String), ki = h.indexOf('設定項目'), vi = h.indexOf('設定値');
    for (var i = 1; i < v.length; i++) if (INIT_SCRUB.test(String(v[i][ki]))) cfg.getRange(i + 1, vi + 1).setValue('');
  }
  // スクリプトプロパティ（テストモードなど）
  var props = PropertiesService.getScriptProperties();
  props.getKeys().forEach(function (k) { if (INIT_PROPS.test(k)) props.deleteProperty(k); });
  // 以前のトリガー（コピーでは付いてこないが念のため）
  ScriptApp.getProjectTriggers().forEach(function (t) { ScriptApp.deleteTrigger(t); });
  SHEET_CACHE_ = {};
  if (typeof READ_MEMO_ !== 'undefined') READ_MEMO_ = null;
  return '空にした表：' + cleared.length + '・消したタブ：' + dropped.length;
}

/** 最初の設定：全体システムとして始める */
function startAsCentral() {
  var ui = SpreadsheetApp.getUi();
  if (ui.alert('全体システムとして始める',
    'このスプレッドシートを「全体システム」にします。\n・試合・公式記録・処分などの記録を空にします（クラブ・チーム・選手・選手登録などのマスターは残します）\n・今シーズンだけのタブを消します\n\n今のシステムのコピーで実行していることを確かめてから、OKを押してください。',
    ui.ButtonSet.OK_CANCEL) !== ui.Button.OK) return;
  var a = initCleanCopy_(ROLE.CENTRAL);
  var b = setupCentralSystem();
  return a + '\n' + b;
}

/** 最初の設定：一体のシステムとして始める（おすすめ。Google Workspace 1アカウントで運用） */
function startAsSingle() {
  var ui = SpreadsheetApp.getUi();
  if (ui.alert('一体のシステムとして始める',
    'このスプレッドシートを「一体のシステム」にします（全体とリーグの両方を1つで受け持つ）。\n・試合・公式記録・処分などの記録を空にします（クラブ・チーム・選手・選手登録などのマスターは残します）\n・今シーズンだけのタブを消します\n\n今のシステムのコピーで実行していることを確かめてから、OKを押してください。',
    ui.ButtonSet.OK_CANCEL) !== ui.Button.OK) return;
  var a = initCleanCopy_(ROLE.CENTRAL);
  var b = setupSingleSystem_(true);
  return a + '\n' + b;
}

/** 最初の設定：リーグシステムとして始める */
function startAsLeague() {
  var ui = SpreadsheetApp.getUi();
  if (ui.alert('リーグシステムとして始める',
    'このスプレッドシートを「リーグシステム」にします。\n・マスターを含めて記録を空にします（全体システムから取り込みます）\n・今シーズンだけのタブを消します\n\n今のシステムのコピーで実行していることを確かめてから、OKを押してください。',
    ui.ButtonSet.OK_CANCEL) !== ui.Button.OK) return;
  var a = initCleanCopy_(ROLE.LEAGUE);
  var b = setupLeagueSystem();
  return a + '\n' + b;
}

;
// ==== LeagueMail.gs
/**
 * LeagueMail.gs v1
 * 新しい大会運営システム（2027年〜）｜リーグシステムの試合日のメールと、リンク台帳
 *
 *  ・sendMatchDayLineupMails（毎朝7時）：今日試合がある両チームの連絡先（1人）へ
 *    「本日は試合日です。スタメンを入力してください」（提出済みのチームには送らない）
 *  ・リンク台帳：全体とリーグで、相手のページのリンクを知るための表
 *    全体 →「全体リンク台帳」（クラブごとの一括登録ページ・登録申請フォーム）…リーグが取り込む
 *    リーグ →「チームページ台帳」（クラブごとのチームページ）…全体が取り込んでリンク集に載せる
 */

var LINK_CENTRAL_SHEET = '全体リンク台帳';
var LINK_CENTRAL_COLS = ['クラブコード', 'クラブ名', '一括登録URL', '登録申請フォームURL'];
var LINK_LEAGUE_SHEET = 'チームページ台帳';
var LINK_LEAGUE_COLS = ['クラブコード', 'クラブ名', 'チームページURL', '担当大会ID', 'リーグ名'];

// ─────────────────────── 試合日の朝のメール（リーグ） ───────────────────────

function sendMatchDayLineupMails() {
  if (!runsMatches_()) return '全体システムでは送らない（試合の仕事はリーグ／一体のシステム）';
  var today = Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd');
  var props = PropertiesService.getScriptProperties();
  var rows = lnRows_(), sent = [];
  objs_(シート.試合).forEach(function (m) {
    if (!inMyComps_(m['試合ID']) || matchDateYmd_(m) !== today) return;
    if (/中止|延期|中断/.test(String(m['試合状態'] || ''))) return;
    var info = lnMatchInfo_(m);
    [info.homeId, info.awayId].forEach(function (tid) {
      if (!tid) return;
      var key = 'MDLN:' + info.id + ':' + tid;
      if (props.getProperty(key)) return;
      var cur = lnLatest_(rows, info.id, tid);
      if (cur && ['確定', '運営クラブOK'].indexOf(String(cur['状態'])) >= 0) return; // 提出済み
      var to = lnTeamMail_(tid);
      var team = lnTeamName_(tid), opp = tid === info.homeId ? info.away : info.home;
      var url = lnUrl_(rgTeamCode_(tid));
      tnMail_('試合日スタメン', to, '【本日試合】スタメンを入力してください：' + info.round + '　vs ' + opp + '（' + info.kickoff + '）',
        '<p>' + lnEsc_(team) + ' ご担当者様</p><p>本日は試合日です。<b>キックオフ90分前（' + lnEsc_(info.deadline || '') + '）まで</b>に、スタメンを提出してください。</p>' +
        '<p>' + lnEsc_(info.comp) + '　' + lnEsc_(info.round) + '<br>' + lnEsc_(info.home) + ' vs ' + lnEsc_(info.away) + '<br>' +
        lnEsc_(info.date) + ' ' + lnEsc_(info.kickoff) + '　' + lnEsc_(info.venue) + '</p>' +
        (url ? '<p><a href="' + url + '" style="display:inline-block;padding:10px 18px;background:#1976D2;color:#fff;text-decoration:none;border-radius:6px">スタメンを提出する</a></p>' : ''),
        info.id, [rgTeamCode_(tid)]);
      props.setProperty(key, '1');
      sent.push(team);
    });
  });
  return sent.length ? sent.length + 'チームに送りました' : '送る相手はありません';
}

function setupMatchDayLineupTrigger_() {
  ScriptApp.getProjectTriggers().forEach(function (t) { if (t.getHandlerFunction() === 'sendMatchDayLineupMails') ScriptApp.deleteTrigger(t); });
  ScriptApp.newTrigger('sendMatchDayLineupMails').timeBased().everyDays(1).atHour(7).nearMinute(0).inTimezone('Asia/Tokyo').create();
}

// ─────────────────────── リンク台帳 ───────────────────────

/** 全体：クラブごとの一括登録ページ（合言葉つき）と、登録申請フォーム */
function writeCentralLinks_() {
  if (!isCentral_()) return;
  var base = typeof linkBase_ === 'function' ? linkBase_() : webAppBaseUrl_();
  var form = String(cfg_('選手登録申請フォームURL') || '');
  var univs = lnUnivs_();
  var rows = Object.keys(univs).sort().map(function (code) {
    return [code, univs[code], base && typeof bkToken_ === 'function' ? base + '?page=bulk&u=' + encodeURIComponent(code) + '&t=' + bkToken_(code) : '', form];
  });
  linkWriteSheet_(LINK_CENTRAL_SHEET, LINK_CENTRAL_COLS, rows);
}

/** リーグ：担当大会にチームがあるクラブのチームページ */
function writeLeagueLinks_() {
  if (!isLeague_()) return;
  var comps = leagueComps_();
  var seen = {}, rows = [];
  objs_(シート.チーム).forEach(function (t) {
    if (comps.indexOf(String(t['大会ID'])) < 0) return;
    var code = rgTeamCode_(t['チームID']);
    if (seen[code]) return;
    seen[code] = true;
    rows.push([code, String(t['クラブ名'] || ''), lnUrl_(code), comps.join(','), '']);
  });
  linkWriteSheet_(LINK_LEAGUE_SHEET, LINK_LEAGUE_COLS, rows.sort(function (a, b) { return a[1] < b[1] ? -1 : 1; }));
}

/** リーグ：全体の一括登録ページ（クラブコード → URL） */
function centralBulkLink_(code) {
  var sh = ss_().getSheetByName(LINK_CENTRAL_SHEET);
  var v = sh && sh.getLastRow() >= 2 ? sh.getDataRange().getValues() : [];
  var r = v.filter(function (x) { return String(x[0]) === String(code); })[0];
  var bulk = r ? String(r[2] || '') : '', form = v.length ? String((r || v[1])[3] || '') : '';
  // 一体・全体のシステムでは、その場でリンクを作る（あとから入れたクラブ・URLが変わったときも、台帳を作り直さずに出る）
  if (isCentral_() && typeof bkToken_ === 'function') {
    var base = typeof linkBase_ === 'function' ? linkBase_() : webAppBaseUrl_();
    if (base) bulk = base + '?page=bulk&u=' + encodeURIComponent(code) + '&t=' + bkToken_(code);
  }
  if (!form) form = String(cfg_('選手登録申請フォームURL') || '');
  return { bulk: bulk, form: form };
}

function linkWriteSheet_(name, cols, rows) {
  var ss = ss_();
  var sh = ss.getSheetByName(name) || ss.insertSheet(name);
  sh.clearContents();
  sh.getRange(1, 1, 1, cols.length).setValues([cols]).setFontWeight('bold');
  if (rows.length) sh.getRange(2, 1, rows.length, cols.length).setValues(rows);
  sh.setFrozenRows(1);
  if (typeof memoForget_ === 'function') memoForget_(name);
}

;
// ==== LineDigest.gs
/**
 * LineDigest.gs v1
 * 新しい大会運営システム（2027年〜）｜規律委員会へのLINEを「週末のまとめ」で送る
 *
 *  LINE公式アカウントの無料の範囲（月200通。グループへの送信は人数分で数える）に収めるため、
 *  規律委員会へのLINEは、その週（月〜日）の試合がすべて終わったあとに、リーグごとの吹き出しにまとめて1回で送る。
 *    ・1回の送信に吹き出しは5つまで（1部・2部・3部・Iリーグ・カップ戦）。吹き出しの数にかかわらず1通の扱い
 *    ・「すべて終わった」＝その週の試合が、開催済・中止・延期・記録対象外のどれか、または結果（得点）が入っている
 *    ・中断して協議中の試合などで終わらないときも、翌週の月曜12時になったら、その時点の内容で送る
 *    ・🚨 MC緊急報告だけは、待たずにすぐ送る
 *    ・メールは今まで通りすぐに届く（「LINEだけ」の通知も、LINEを待たせる間はメールで送る）
 *
 *  システム設定「LINE通知の送り方」：まとめて（空のときも）／すぐ
 *  送信待ちは「LINE送信待ち」タブ。1時間ごとの更新（runHourlyUpdate）で送るか確かめる。
 *  メニュー「規律委員会へのLINE（まとめ）を今すぐ送る」で、待たずに送れる。
 */

var LD = {
  sheet: 'LINE送信待ち',
  cols: ['受付日時', '大会ID', 'リーグ', '件名', '本文', '状態', '送信日時'],
  done: /^(開催済|中止|延期|記録対象外)$/,
  perItem: 900,   // 1件あたりの文字数（長いものは切る）
  perBubble: 4800 // 吹き出し1つの文字数（LINEの上限は5000）
};

/** まとめて送るか（MC緊急報告・設定「すぐ」のときは送らない） */
function ldShouldQueue_(subject, opt) {
  if (opt && opt.now) return false;
  if (String(cfg_('LINE通知の送り方') || '').trim() === 'すぐ') return false;
  var s = String(subject || '').replace(/^(【テスト】)+/, '');
  return !/^【MC緊急報告】/.test(s);
}

/** 試合ID（2027-TOP-101）→ 大会ID（2027-TOP） */
function ldCompOf_(matchId) {
  var m = String(matchId || '').match(/^(.+)-[^-]+$/);
  return m ? m[1] : '';
}

function ldLeagueName_(comp) {
  if (!comp) return '全体';
  var c = objs_(シート.大会).filter(function (x) { return String(x['大会ID']) === comp; })[0];
  var name = c ? String(c['大会名'] || c['正式名称'] || comp) : comp;
  return name.replace(/^第\d+回\s*/, '');
}

function ldSheet_() {
  var ss = ss_();
  var sh = ss.getSheetByName(LD.sheet);
  if (!sh) {
    sh = ss.insertSheet(LD.sheet);
    sh.getRange(1, 1, 1, LD.cols.length).setValues([LD.cols]).setFontWeight('bold');
    sh.setFrozenRows(1);
    sh.setColumnWidth(4, 320); sh.setColumnWidth(5, 420);
  }
  return sh;
}

function ldNow_() { return Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm:ss'); }

/** 送信待ちに入れる */
function ldEnqueue_(subject, text, opt) {
  var comp = (opt && opt.comp) || ldCompOf_(opt && opt.matchId);
  var sh = ldSheet_();
  sh.appendRow([ldNow_(), comp, ldLeagueName_(comp), String(subject || ''), String(text || '').slice(0, 20000), '待ち', '']);
  if (typeof memoForget_ === 'function') memoForget_(LD.sheet);
}

function ldPending_() {
  var sh = ldSheet_();
  if (sh.getLastRow() < 2) return [];
  var v = sh.getRange(2, 1, sh.getLastRow() - 1, LD.cols.length).getValues();
  var out = [];
  v.forEach(function (r, i) {
    if (String(r[5]) !== '待ち') return;
    out.push({ row: i + 2, at: r[0] instanceof Date ? Utilities.formatDate(r[0], 'Asia/Tokyo', 'yyyy-MM-dd HH:mm:ss') : String(r[0]),
      comp: String(r[1] || ''), league: String(r[2] || '全体'), subject: String(r[3] || ''), text: String(r[4] || '') });
  });
  return out;
}

/** yyyy-MM-dd の週（月曜はじまり）の月曜 */
function ldMonday_(ymd) {
  var d = new Date(ymd.slice(0, 10) + 'T00:00:00+09:00');
  var dow = (Number(Utilities.formatDate(d, 'Asia/Tokyo', 'u')) + 6) % 7; // 月=0 … 日=6
  return Utilities.formatDate(new Date(d.getTime() - dow * 86400000), 'Asia/Tokyo', 'yyyy-MM-dd');
}
function ldAddDays_(ymd, n) {
  return Utilities.formatDate(new Date(new Date(ymd + 'T00:00:00+09:00').getTime() + n * 86400000), 'Asia/Tokyo', 'yyyy-MM-dd');
}

/** 送ってよいか：その週の試合がすべて終わった、または翌週月曜12時を過ぎた */
function ldReady_(items) {
  var oldest = items.map(function (x) { return x.at.slice(0, 10); }).sort()[0];
  var mon = ldMonday_(oldest), sun = ldAddDays_(mon, 6), cut = ldAddDays_(mon, 7) + ' 12:00';
  var now = Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm');
  if (now >= cut) return { ok: true, why: '締め（' + cut + '）を過ぎたため' };
  var left = objs_(シート.試合).filter(function (m) {
    var d = typeof matchDateYmd_ === 'function' ? matchDateYmd_(m) : '';
    if (!d || d < mon || d > sun) return false;
    var st = String(m['試合状態'] || '').trim();
    if (LD.done.test(st)) return false;
    if (st !== '中断' && String(m['ホーム得点']) !== '' && String(m['アウェイ得点']) !== '') return false;
    return true;
  });
  if (!left.length) return { ok: true, why: mon + '〜' + sun + ' の試合がすべて終わったため' };
  return { ok: false, why: 'まだ終わっていない試合が ' + left.length + ' 試合（' + left.slice(0, 3).map(function (m) { return m['試合ID']; }).join('、') + (left.length > 3 ? ' ほか' : '') + '）。締めは ' + cut };
}

/** リーグごとの吹き出しを作る */
function ldBubbles_(items) {
  var order = [], groups = {};
  items.slice().sort(function (a, b) { var x = a.comp || '~', y = b.comp || '~'; return x < y ? -1 : x > y ? 1 : (a.at < b.at ? -1 : 1); }).forEach(function (x) {
    if (!groups[x.league]) { groups[x.league] = []; order.push(x.league); }
    groups[x.league].push(x);
  });
  var test = items.some(function (x) { return /^【テスト】/.test(x.subject); });
  return order.map(function (name) {
    var list = groups[name];
    var head = '📋 規律委員会へのまとめ（' + name + '）' + (test ? '（テスト）' : '') + '\n' + list.length + '件\n';
    var body = '', shown = 0;
    list.forEach(function (x) {
      var one = rvLineMessage_(x.subject, x.text);
      if (one.length > LD.perItem) one = one.slice(0, LD.perItem) + '…（続きはメール・リンク先で）';
      var add = (shown ? '\n\n━━━━━━━━━━━\n' : '\n') + one;
      if ((head + body + add).length > LD.perBubble) return;
      body += add; shown++;
    });
    if (shown < list.length) body += '\n\nほか ' + (list.length - shown) + '件はメールでご確認ください';
    return { name: name, text: head + body, rows: list.map(function (x) { return x.row; }) };
  });
}

/** 送信待ちを送る（force：週の終わりを待たない） */
function flushLineDigest_(force) {
  if (typeof isCentral_ === 'function' && !isCentral_()) return 'リーグシステムでは送らない';
  var lock = LockService.getScriptLock();
  if (!lock.tryLock(20000)) return 'ほかの処理が実行中のため見送り';
  try {
    var items = ldPending_();
    if (!items.length) return '送信待ちはありません';
    var ready = force ? { ok: true, why: '手動で送信' } : ldReady_(items);
    if (!ready.ok) return '待ちます：' + ready.why;
    var token = String(cfg_('LINEチャネルアクセストークン') || '').trim();
    var ids = String(cfg_('LINE送信先ID') || '').split(/[,\s]+/).filter(Boolean);
    if (!token || !ids.length) return 'LINEが設定されていません（送信待ち ' + items.length + '件）';
    var bubbles = ldBubbles_(items);
    var errors = [];
    for (var i = 0; i < bubbles.length; i += 5) {
      var chunk = bubbles.slice(i, i + 5);
      var okAll = true;
      ids.forEach(function (id) {
        try {
          var res = UrlFetchApp.fetch('https://api.line.me/v2/bot/message/push', {
            method: 'post', contentType: 'application/json', muteHttpExceptions: true,
            headers: { Authorization: 'Bearer ' + token },
            payload: JSON.stringify({ to: id, messages: chunk.map(function (b) { return { type: 'text', text: b.text }; }) })
          });
          if (res.getResponseCode() >= 300) { okAll = false; errors.push('LINE ' + res.getResponseCode() + ' ' + res.getContentText().slice(0, 120)); }
        } catch (e) { okAll = false; errors.push('LINE：' + e.message); }
      });
      if (okAll) {
        var sh = ldSheet_(), at = ldNow_();
        chunk.forEach(function (b) { b.rows.forEach(function (r) { sh.getRange(r, 6, 1, 2).setValues([['送信済', at]]); }); });
      }
    }
    if (typeof memoForget_ === 'function') memoForget_(LD.sheet);
    return errors.length ? '一部送れませんでした：' + errors.join(' / ')
      : items.length + '件を ' + bubbles.length + 'リーグ分の吹き出しにまとめて送りました（' + ready.why + '）';
  } finally {
    lock.releaseLock();
  }
}

/** メニュー：規律委員会へのLINE（まとめ）を今すぐ送る */
function flushLineDigestNow() {
  var n = ldPending_().length;
  var msg = n ? flushLineDigest_(true) : '送信待ちはありません';
  try { SpreadsheetApp.getUi().alert('規律委員会へのLINE（まとめ）', msg, SpreadsheetApp.getUi().ButtonSet.OK); } catch (e) {}
  return msg;
}

;
// ==== LineupFlow.gs
/**
 * LineupFlow.gs v1（HTMLは Lineup）
 * クラブサッカー大会運営システム｜スタメン（メンバー表）の提出 → 運営クラブの確認 → 審判団へ送付
 *
 * 流れ
 *  1. チーム（主務など）が、キックオフ90分前までにスタメン・控え・スタッフを提出
 *     → 提出した本人に確認メール。リンクから内容を見て「確定」
 *  2. 確定すると運営クラブへメール。運営クラブはクラブごとのページで、登録・出場停止のチェック結果を見て「出場可能（OK）」または「差し戻し」
 *  3. 運営クラブが審判団のメールアドレスを入力。両チームOK＋審判のメールがそろうと、審判団へスタメン表をメールで送る
 *  4. 運営クラブがOKにしたスタメンは、公式記録の入力画面に最初から入る（先発・控え・背番号・位置）
 *
 *  締切（キックオフ90分前）を過ぎても提出・変更はできる（「締切後」と表示）。締切後の変更は理由が必須。
 *  ページ：?page=lineup&u=クラブコード&t=トークン（クラブごとの固定リンク。メニュー「スタメン・運営クラブリンクを作成」）
 */

var LN = { SHEET: 'スタメン提出', REF: '審判連絡先', LINKS: 'スタメン・運営クラブリンク' };
var LN_COLS = ['提出ID', '試合ID', 'チームID', '版', '状態', '提出者名', '提出者メール', '提出日時', '確定日時', '締切後', '変更理由', '内容',
  '運営クラブ確認者', '運営クラブ確認日時', '運営クラブコメント', 'JFA登録未確認'];
var LN_REF_COLS = ['試合ID', '主審', '主審メール', '副審1', '副審1メール', '副審2', '副審2メール', '第4の審判', '第4の審判メール', '入力者', '更新日時', '審判団へ送信日時'];
var LN_ROLES = [['main', '主審'], ['ar1', '副審1'], ['ar2', '副審2'], ['fourth', '第4の審判']];
var LN_DEADLINE_MIN = 90;

// ─────────────────────── 共通 ───────────────────────

function lnSheet_(name, cols) {
  var ss = ss_();
  var sh = ss.getSheetByName(name);
  if (!sh) {
    sh = ss.insertSheet(name);
    sh.getRange(1, 1, 1, cols.length).setValues([cols]).setFontWeight('bold').setBackground('#E8F4FB');
    sh.setFrozenRows(1);
    if (typeof memoForget_ === 'function') memoForget_(name);
  } else {
    // 読むだけの処理の中では、先にシート全体を読んでおく（見出しの確認で別に読みに行かない）
    if (typeof READ_MEMO_ !== 'undefined' && READ_MEMO_ && typeof sheetValues_ === 'function') sheetValues_(name);
    ensureHeader_(name, cols);
  }
  return sh;
}

function lnRows_() { lnSheet_(LN.SHEET, LN_COLS); return objs_(LN.SHEET); }
function lnRefRows_() { lnSheet_(LN.REF, LN_REF_COLS); return objs_(LN.REF); }
function lnNow_() { return Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm:ss'); }
function lnEsc_(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }

function lnToken_(code) { return rvToken_('LN:' + code); }
function lnConfirmToken_(sid) { return rvToken_('LNC:' + sid); }

function lnUnivs_() {
  var out = {};
  rgTeamList_().forEach(function (t) { var c = rgTeamCode_(t['チームID']); if (!out[c]) out[c] = String(t['クラブ名']); });
  return out;
}

function lnAuth_(code, token) {
  code = String(code || '');
  var univ = code === LN_JIMU ? LN_JIMU_NAME : lnUnivs_()[code];
  if (!univ || String(token || '') !== lnToken_(code)) throw new Error('リンクが正しくありません。運営から届いたリンクを開き直してください。');
  return univ;
}

function lnUrl_(code) {
  var base = (typeof entryBase_ === 'function' && webAppBaseUrl_() && entryBase_()) || webAppBaseUrl_();
  return base ? base + '?page=lineup&u=' + encodeURIComponent(code) + '&t=' + lnToken_(code) : '';
}

/** 試合マスターの「運営クラブ」（略称など）→ クラブコード */
var LN_JIMU = 'JIMU'; // 運営クラブが「連盟事務局」の試合（事務局が運営クラブの仕事をする）
var LN_JIMU_NAME = '連盟事務局';

function lnDutyCode_(m) {
  var v = String(m['運営クラブ'] || '').replace(/\s/g, '');
  if (!v) return '';
  if (/連盟|事務局/.test(v)) return LN_JIMU;
  var hit = objs_(シート.チーム).filter(function (t) {
    return [t['略称'], t['クラブ名'], t['チーム名']].some(function (x) { return String(x || '').replace(/\s/g, '') === v; });
  })[0];
  return hit ? rgTeamCode_(hit['チームID']) : '';
}

/** クラブコードのチームのメール（責任者・監督） */
/** クラブの連絡先（1人）：チームマスターの責任者メール、なければ監督メール */
function lnUnivMails_(code) {
  if (code === LN_JIMU) return String(cfg_('管理者メール') || '').split(/[,;\s]+/).filter(Boolean).slice(0, 1);
  // クラブが登録した連絡先（Contacts.gs）があれば、それを使う（複数可）
  var ct = typeof ctMails_ === 'function' ? ctMails_(code) : [];
  if (ct.length) return ct;
  var resp = '', coach = '';
  objs_(シート.チーム).forEach(function (t) {
    if (rgTeamCode_(t['チームID']) !== code) return;
    if (!resp) resp = String(t['責任者メール'] || '').trim();
    if (!coach) coach = String(t['監督メール'] || '').trim();
  });
  var one = resp || coach;
  return one ? [one] : [];
}

/** チームの連絡先（1人） */
function lnTeamMail_(tid) {
  var ct = typeof ctMails_ === 'function' ? ctMails_(rgTeamCode_(tid)) : [];
  if (ct.length) return ct.join(',');
  var t = objs_(シート.チーム).filter(function (x) { return String(x['チームID']) === String(tid); })[0] || {};
  var one = String(t['責任者メール'] || '').trim() || String(t['監督メール'] || '').trim();
  return one || (lnUnivMails_(rgTeamCode_(tid))[0] || '');
}

function lnTeamName_(tid) {
  var t = objs_(シート.チーム).filter(function (x) { return String(x['チームID']) === String(tid); })[0] || {};
  return String(t['チーム名'] || t['クラブ名'] || tid);
}

/** 試合の基本情報と締切 */
function lnMatchInfo_(m) {
  var date = matchDateYmd_(m);
  var ko = kickoffText_(m['キックオフ']);
  var dl = null;
  if (date && ko) {
    try { dl = new Date(Utilities.parseDate(date + ' ' + ko, 'Asia/Tokyo', 'yyyy-MM-dd HH:mm').getTime() - LN_DEADLINE_MIN * 60000); } catch (e) { dl = null; }
  }
  var comp = objs_(シート.大会).filter(function (c) { return String(c['大会ID']) === String(m['大会ID']); })[0] || {};
  return {
    id: String(m['試合ID']), comp: String(comp['大会名'] || m['大会ID'] || ''), round: String(m['節／ラウンド'] || ''), no: String(m['マッチNo'] || ''),
    date: date, kickoff: ko, venue: String(m['会場'] || ''), duty: String(m['運営クラブ'] || ''),
    homeId: String(m['ホームチームID']), awayId: String(m['アウェイチームID']),
    home: lnTeamName_(m['ホームチームID']), away: lnTeamName_(m['アウェイチームID']),
    deadline: dl ? Utilities.formatDate(dl, 'Asia/Tokyo', 'M/d HH:mm') : '',
    deadlineMs: dl ? dl.getTime() : 0,
    late: !!(dl && Date.now() > dl.getTime())
  };
}

/** そのチームの最新のスタメン（取消・差し替えを除く） */
function lnLatest_(rows, mid, tid) {
  return rows.filter(function (r) {
    return String(r['試合ID']) === String(mid) && String(r['チームID']) === String(tid) && ['差し替え', '取消'].indexOf(String(r['状態'])) < 0;
  }).sort(function (a, b) { return num_(b['版']) - num_(a['版']); })[0] || null;
}

function lnContent_(r) {
  if (!r) return null;
  try { return JSON.parse(String(r['内容'] || '')); } catch (e) { return null; }
}

function lnRowView_(r) {
  if (!r) return null;
  return {
    sid: String(r['提出ID']), version: num_(r['版']), status: String(r['状態']), by: String(r['提出者名'] || ''), email: String(r['提出者メール'] || ''),
    at: String(r['提出日時'] || ''), confirmedAt: String(r['確定日時'] || ''), late: String(r['締切後']) === '締切後', reason: String(r['変更理由'] || ''),
    checker: String(r['運営クラブ確認者'] || ''), checkedAt: String(r['運営クラブ確認日時'] || ''), comment: String(r['運営クラブコメント'] || ''),
    content: lnContent_(r), jfaUnchecked: lnJfaUnchecked_(r)
  };
}

/** 運営クラブがJFA登録を確認できなかった選手（選手IDの配列）。まだ確認していなければ null */
function lnJfaUnchecked_(r) {
  var v = r ? String(r['JFA登録未確認'] || '').trim() : '';
  if (!v) return null;
  try { var a = JSON.parse(v); return Array.isArray(a) ? a.map(String) : null; } catch (e) { return null; }
}

/** 未確認の選手の表示（No.・氏名） */
function lnJfaNames_(c, pids) {
  if (!c || !pids || !pids.length) return [];
  var all = (c.starters || []).concat(c.bench || []);
  return pids.map(function (pid) {
    var x = all.filter(function (y) { return String(y.pid) === String(pid); })[0];
    return x ? 'No.' + (x.no || '?') + ' ' + (x.name || '') : '';
  }).filter(Boolean);
}

/** 出場できる選手（登録あり）と出場停止 */
/** 画面に出す出場停止（2分だけ覚えておく。提出のときは lnPlayers_ の fresh で毎回計算） */
function lnSuspView_(mid) {
  var c = CacheService.getScriptCache(), k = 'ln:susp:' + mid;
  try { var hit = c.get(k); if (hit) return JSON.parse(hit); } catch (e) {}
  var list = suspendedPlayersView_(mid).map(function (x) { return { playerId: String(x.playerId), label: x.label }; });
  try { c.put(k, JSON.stringify(list), 120); } catch (e) {}
  return list;
}

function lnPlayers_(mid, tid, date, fresh) {
  // 登録開始日がこの試合より後の選手（追加登録の締切に間に合っていない）も、出られない選手として画面に出す
  var regs = objs_(シート.選手登録).filter(function (r) {
    return String(r['チームID']) === String(tid) && String(r['登録状態']) === '有効' &&
      (!r['登録終了日'] || ymd_(r['登録終了日']) >= date);
  });
  // 上位大会でエントリーを出したチームは、エントリーした選手だけ（Entry.gs）
  var ent = typeof entPlayerSet_ === 'function' ? entPlayerSet_(tid) : null;
  if (ent) regs = regs.filter(function (r) { return ent[String(r['選手ID'])]; });
  var mdj = function (d) { var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(d); return m ? Number(m[2]) + '/' + Number(m[3]) : d; };
  var names = {};
  objs_(シート.選手).forEach(function (p) { names[String(p['選手ID'])] = String(p['氏名'] || ''); });
  var susp = {};
  try { (fresh ? suspendedPlayersView_(mid) : lnSuspView_(mid)).forEach(function (x) { susp[String(x.playerId)] = x.label; }); } catch (e) {}
  return regs.map(function (r) {
    var pid = String(r['選手ID']);
    var st = ymd_(r['登録開始日']);
    return { pid: pid, no: String(r['背番号'] || ''), name: names[pid] || pid, pos: String(r['位置'] || ''), susp: susp[pid] || '',
      wait: st && st > date ? mdj(st) + 'の試合から出場できます（追加登録は試合の' + (typeof entLeadDays_ === 'function' ? entLeadDays_() : 5) + '日前まで）' : '' };
  }).sort(function (a, b) { return (Number(a.no) || 999) - (Number(b.no) || 999); });
}

function lnStaffDefaults_(tid) {
  var t = objs_(シート.チーム).filter(function (x) { return String(x['チームID']) === String(tid); })[0] || {};
  var out = [];
  if (t['監督名']) out.push({ role: '監督', name: String(t['監督名']) });
  try {
    objs_(シート.チームスタッフ).filter(function (s) { return String(s['チームID']) === String(tid) && String(s['有効'] || '有効') !== '無効'; })
      .forEach(function (s) { if (!out.some(function (x) { return x.name === String(s['氏名']); })) out.push({ role: String(s['役職'] || ''), name: String(s['氏名'] || '') }); });
  } catch (e) {}
  return out.slice(0, 30); // 登録スタッフ全員（ベンチ入りは画面で選ぶ）
}

/**
 * 公式記録の承認者の候補（試合ごとにスタメン提出で選ぶ）
 *  監督（監督メール）・チーム責任者（責任者メール）・メールのある登録スタッフ。候補にない人は画面で「その他」に名前とメールを入れる
 */
function lnApproverOptions_(tid) {
  var t = objs_(シート.チーム).filter(function (x) { return String(x['チームID']) === String(tid); })[0] || {};
  var out = [], seen = {};
  var add = function (role, name, email) {
    name = String(name || '').trim(); email = String(email || '').trim();
    if (!name || !email) return;
    var k = name.replace(/[\s　]/g, '') + '|' + email.toLowerCase();
    if (seen[k]) return;
    seen[k] = true;
    out.push({ role: role, name: name, email: email });
  };
  add('監督', t['監督名'], t['監督メール']);
  add('チーム責任者', t['チーム責任者'], t['責任者メール']);
  try {
    objs_(シート.チームスタッフ).filter(function (x) { return String(x['チームID']) === String(tid) && String(x['有効'] || '有効') !== '無効'; })
      .forEach(function (x) { add(String(x['役職'] || 'スタッフ'), x['氏名'], x['メール']); });
  } catch (e) {}
  return out;
}

/** その試合・チームの承認者（スタメン提出で選んだ人）。なければ null */
function lnApproverFor_(mid, tid) {
  try {
    if (!ss_().getSheetByName(LN.SHEET)) return null;
    var r = objs_(LN.SHEET).filter(function (x) { return String(x['試合ID']) === String(mid) && String(x['チームID']) === String(tid) && ['運営クラブOK', '確定'].indexOf(String(x['状態'])) >= 0; })
      .sort(function (a, b) { return num_(b['版']) - num_(a['版']); })[0];
    var c = lnContent_(r);
    var a = c && c.approver;
    return a && a.email ? { role: String(a.role || ''), name: String(a.name || ''), email: String(a.email) } : null;
  } catch (e) { return null; }
}

function lnBenchMax_() { var n = Number(cfg_('スタメン控え上限') || 0); return n > 0 ? n : 9; }

/** 自動チェック（登録・出場停止・人数・背番号の重複・GK） */
function lnCheck_(content, players) {
  var byPid = {};
  players.forEach(function (p) { byPid[p.pid] = p; });
  var issues = [], ok = [];
  if (!content) return { ok: false, issues: ['スタメンが提出されていません'], notes: [] };
  var all = (content.starters || []).concat(content.bench || []);
  all.forEach(function (x) {
    var p = byPid[x.pid];
    if (!p) issues.push('No.' + (x.no || '?') + ' ' + (x.name || x.pid) + '：この試合の日に有効な登録がありません');
    else if (p.susp) issues.push('No.' + p.no + ' ' + p.name + '：出場停止（' + p.susp + '）');
    else if (p.wait) issues.push('No.' + p.no + ' ' + p.name + '：' + p.wait);
  });
  var nos = {};
  all.forEach(function (x) { var n = String(x.no || ''); if (!n) return; nos[n] = (nos[n] || 0) + 1; });
  Object.keys(nos).forEach(function (n) { if (nos[n] > 1) issues.push('背番号 ' + n + ' が重複しています'); });
  var s = (content.starters || []).length;
  if (s !== 11) issues.push('先発が' + s + '人です');
  if (!(content.starters || []).some(function (x) { return String(x.pos) === 'GK'; })) ok.push('先発にGKがいません（位置を確認）');
  if ((content.bench || []).length > lnBenchMax_()) issues.push('控えが' + content.bench.length + '人です（上限' + lnBenchMax_() + '人）');
  return { ok: !issues.length, issues: issues, notes: ok };
}

// ─────────────────────── ページ ───────────────────────

function lineupPage(e) {
  var p = (e && e.parameter) || {};
  var t = HtmlService.createTemplateFromFile('Lineup');
  t.u = String(p.u || ''); t.t = String(p.t || ''); t.c = String(p.lc || p.c || ''); // 「c」はGoogleの予約語のため「lc」を使う
  // 一覧のデータもページと一緒に送る（画面を開いてからもう一度サーバーに聞きに行かない）。失敗したら画面から読み直す
  t.ctx = 'null';
  if (!t.c) { try { t.ctx = JSON.stringify(lineupContext(t.u, t.t)).replace(/</g, '\\u003c'); } catch (err) { t.ctx = 'null'; } }
  return t.evaluate().setTitle('チームページ')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1, viewport-fit=cover')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

/** クラブのページ：自クラブの試合（スタメン提出）と、当番の試合 */
function lineupContext(u, t) {
  return withReadMemo_(function () {
    var univ = lnAuth_(u, t);
    var today = Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd');
    var from = Utilities.formatDate(new Date(Date.now() - 2 * 86400000), 'Asia/Tokyo', 'yyyy-MM-dd');
    var to = Utilities.formatDate(new Date(Date.now() + 21 * 86400000), 'Asia/Tokyo', 'yyyy-MM-dd');
    var myTeams = {};
    rgTeamList_().forEach(function (x) { if (rgTeamCode_(x['チームID']) === u) myTeams[String(x['チームID'])] = true; });
    var rows = lnRows_(), refs = lnRefRows_();
    var inRange = function (m) { var d = matchDateYmd_(m); return d && d >= from && d <= to && String(m['試合状態'] || '') !== '中止'; };
    var status = function (mid, tid) { var r = lnLatest_(rows, mid, tid); return r ? { status: String(r['状態']), version: num_(r['版']), late: String(r['締切後']) === '締切後' } : null; };
    var matches = objs_(シート.試合).filter(inRange);
    var team = [], duty = [];
    matches.forEach(function (m) {
      var info = lnMatchInfo_(m);
      [info.homeId, info.awayId].forEach(function (tid) {
        if (!myTeams[tid]) return;
        team.push(Object.assign({}, info, { teamId: tid, teamName: lnTeamName_(tid), opp: tid === info.homeId ? info.away : info.home, lineup: status(info.id, tid) }));
      });
      // 事務局は、すべての試合のスタメンを確認できる（JFA登録の確認は、運営クラブと事務局の両方でする）
      if (lnDutyCode_(m) === u || u === LN_JIMU) {
        var ref = refs.filter(function (r) { return String(r['試合ID']) === info.id; })[0] || {};
        duty.push(Object.assign({}, info, { homeLineup: status(info.id, info.homeId), awayLineup: status(info.id, info.awayId), refsSent: String(ref['審判団へ送信日時'] || ''), asJimu: u === LN_JIMU && lnDutyCode_(m) !== u }));
      }
    });
    var sortFn = function (a, b) { return (a.date + a.kickoff < b.date + b.kickoff) ? -1 : 1; };
    // チームページのほかの機能（選手登録・公式記録入力）へのリンク
    var base = typeof linkBase_ === 'function' ? linkBase_() : webAppBaseUrl_();
    // 公式記録の入力画面へ（ru：記録担当クラブ＝このチームページのクラブ）
    var recUrl = function (id) { return base ? base + '?page=official&match=' + encodeURIComponent(id) + '&ru=' + encodeURIComponent(univ) : ''; };
    var recFrom = Utilities.formatDate(new Date(Date.now() - 7 * 86400000), 'Asia/Tokyo', 'yyyy-MM-dd');
    var records = objs_(シート.試合).filter(function (m) {
      var d = matchDateYmd_(m);
      return d && d >= recFrom && d <= today && lnDutyCode_(m) === u && String(m['試合状態'] || '') !== '中止';
    }).map(function (m) {
      var info = lnMatchInfo_(m);
      var rec = objs_(シート.公式記録).filter(function (r) { return String(r['試合ID']) === info.id; }).pop();
      return Object.assign({}, info, { recordUrl: recUrl(info.id), recordStatus: rec ? String(rec['記録状態'] || rec['状態'] || '入力あり') : '' });
    }).sort(sortFn).reverse();
    duty.forEach(function (x) { x.recordUrl = recUrl(x.id); });
    // 選手登録は全体システム（全体リンク台帳から）
    var cl = typeof centralBulkLink_ === 'function' ? centralBulkLink_(u) : { bulk: '', form: '' };
    var links = {
      bulk: u === LN_JIMU ? '' : cl.bulk,
      regForm: cl.form,
      official: base ? base + '?page=official' : '',
      pub: typeof publicSiteUrl_ === 'function' ? publicSiteUrl_() : (base ? base + '?page=public' : '')
    };
    var simatsu = [];
    try { if (typeof icSimatsuForUniv_ === 'function') simatsu = icSimatsuForUniv_(univ); } catch (e) {} // 譴責の始末書（Incident.gs）
    var explain = [];
    try { if (typeof icExplainForUniv_ === 'function') explain = icExplainForUniv_(univ); } catch (e) {} // 問題事項の弁明（Incident.gs）
    var entN = 0;
    try { if (typeof entMyTeams_ === 'function') entN = entMyTeams_(u).length; } catch (e) {}
    return { univ: univ, today: today, team: team.sort(sortFn), duty: duty.sort(sortFn), records: records, links: links, benchMax: lnBenchMax_(), simatsu: simatsu, explain: explain, entries: entN };
  });
}

/** スタメン入力フォーム用のデータ */
function lineupForm(u, t, mid, tid) {
  return withReadMemo_(function () {
    lnAuth_(u, t);
    if (rgTeamCode_(tid) !== u) throw new Error('このチームのスタメンは提出できません');
    var m = findMatch_(mid);
    if ([String(m['ホームチームID']), String(m['アウェイチームID'])].indexOf(String(tid)) < 0) throw new Error('この試合のチームではありません');
    var info = lnMatchInfo_(m);
    var rows = lnRows_();
    var cur = lnLatest_(rows, mid, tid);
    var hasFixed = rows.some(function (r) { return String(r['試合ID']) === String(mid) && String(r['チームID']) === String(tid) && ['確定', '運営クラブOK'].indexOf(String(r['状態'])) >= 0; });
    return {
      match: info, teamId: String(tid), teamName: lnTeamName_(tid),
      players: lnPlayers_(mid, tid, info.date), staff: lnStaffDefaults_(tid), benchMax: lnBenchMax_(), approvers: lnApproverOptions_(tid),
      current: lnRowView_(cur), needReason: info.late && hasFixed
    };
  });
}

/** 提出（確認待ち）→ 提出した人に確認メール */
function lineupSubmit(u, t, mid, tid, p) {
  lnAuth_(u, t);
  if (rgTeamCode_(tid) !== u) throw new Error('このチームのスタメンは提出できません');
  p = p || {};
  var name = String(p.name || '').trim(), email = String(p.email || '').trim();
  if (!name) throw new Error('提出者の名前を入力してください');
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('提出者のメールアドレスを確認してください');
  var m = findMatch_(mid);
  var info = lnMatchInfo_(m);
  var players = lnPlayers_(mid, tid, info.date, true);
  var byPid = {};
  players.forEach(function (x) { byPid[x.pid] = x; });
  var pick = function (list) {
    return (list || []).map(function (x) {
      var pl = byPid[String(x.pid)];
      if (!pl) throw new Error('登録のない選手が含まれています。ページを開き直してください');
      if (pl.susp) throw new Error(pl.name + ' は出場停止です（' + pl.susp + '）。メンバーから外してください');
      if (pl.wait) throw new Error(pl.name + ' はこの試合に出られません（' + pl.wait + '）。メンバーから外してください');
      return { pid: pl.pid, no: pl.no, name: pl.name, pos: String(x.pos || pl.pos || '') };
    });
  };
  var starters = pick(p.starters), bench = pick(p.bench);
  if (starters.length < 7 || starters.length > 11) throw new Error('先発は7〜11人で入力してください（現在' + starters.length + '人）');
  if (bench.length > lnBenchMax_()) throw new Error('控えは' + lnBenchMax_() + '人までです');
  var staff = (p.staff || []).map(function (s) { return { role: String(s.role || '').trim(), name: String(s.name || '').trim() }; }).filter(function (s) { return s.name; });
  // 公式記録の承認者（この試合で、チームを代表して公式記録を承認する人）
  var ap = p.approver || {};
  var approver = { role: String(ap.role || 'その他').trim(), name: String(ap.name || '').trim(), email: String(ap.email || '').trim() };
  if (!approver.name || !approver.email) throw new Error('公式記録の承認者を選んでください（「その他」のときは名前とメールアドレスを入力）');
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(approver.email)) throw new Error('公式記録の承認者のメールアドレスを確認してください');

  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  var sid;
  try {
    var rows = lnRows_();
    var mine = rows.filter(function (r) { return String(r['試合ID']) === String(mid) && String(r['チームID']) === String(tid); });
    var hasFixed = mine.some(function (r) { return ['確定', '運営クラブOK'].indexOf(String(r['状態'])) >= 0; });
    var reason = String(p.reason || '').trim();
    if (info.late && hasFixed && !reason) throw new Error('締切（キックオフ90分前）を過ぎた変更です。変更の理由を入力してください');
    // 前の提出は差し替え（提出した時点で確定。確認メールは送らない）
    mine.forEach(function (r) { if (['確認待ち', '確定', '運営クラブOK', '差し戻し'].indexOf(String(r['状態'])) >= 0) update_(LN.SHEET, r._row, { '状態': '差し替え' }); });
    var ver = mine.reduce(function (a, r) { return Math.max(a, num_(r['版'])); }, 0) + 1;
    sid = 'LN-' + Utilities.getUuid().replace(/-/g, '').slice(0, 10);
    append_(LN.SHEET, {
      '提出ID': sid, '試合ID': "'" + mid, 'チームID': "'" + tid, '版': ver, '状態': '確定', '提出者名': name, '提出者メール': email,
      '提出日時': lnNow_(), '確定日時': lnNow_(), '締切後': info.late ? '締切後' : '', '変更理由': reason,
      '内容': JSON.stringify({ starters: starters, bench: bench, staff: staff, captain: String(p.captain || ''), approver: approver })
    });
  } finally {
    lock.releaseLock();
  }
  try { if (typeof tnLineupReceipt_ === 'function') tnLineupReceipt_(mid, tid, name, info.late); } catch (e) {}
  var sent = lnMaybeNotifyDuty_(mid);
  return { ok: true, sid: sid, message: '提出しました。' + (sent ? '両チームのスタメンがそろったので、運営クラブへ確認をお願いしました。' : '相手チームの提出がそろうと、運営クラブへ確認のお願いが届きます。') };
}

/** 確認ページ（メールのリンク） */
function lineupConfirmView(sid, t) {
  return withReadMemo_(function () {
    if (String(t || '') !== lnConfirmToken_(sid)) throw new Error('リンクが正しくありません');
    var r = lnRows_().filter(function (x) { return String(x['提出ID']) === String(sid); })[0];
    if (!r) throw new Error('提出が見つかりません');
    var info = lnMatchInfo_(findMatch_(r['試合ID']));
    return { match: info, teamName: lnTeamName_(r['チームID']), row: lnRowView_(r) };
  });
}

function lineupConfirm(sid, t) {
  if (String(t || '') !== lnConfirmToken_(sid)) throw new Error('リンクが正しくありません');
  var lock = LockService.getScriptLock();
  lock.waitLock(20000);
  var r, info;
  try {
    var rows = lnRows_();
    r = rows.filter(function (x) { return String(x['提出ID']) === String(sid); })[0];
    if (!r) throw new Error('提出が見つかりません');
    var st = String(r['状態']);
    if (st === '確定' || st === '運営クラブOK') return { ok: true, message: 'すでに確定しています' };
    if (st !== '確認待ち') throw new Error('この提出は「' + st + '」のため確定できません。新しい提出のメールから開いてください');
    rows.forEach(function (x) {
      if (String(x['試合ID']) === String(r['試合ID']) && String(x['チームID']) === String(r['チームID']) && x._row !== r._row &&
        ['確定', '運営クラブOK', '差し戻し'].indexOf(String(x['状態'])) >= 0) update_(LN.SHEET, x._row, { '状態': '差し替え' });
    });
    update_(LN.SHEET, r._row, { '状態': '確定', '確定日時': lnNow_() });
    info = lnMatchInfo_(findMatch_(r['試合ID']));
  } finally {
    lock.releaseLock();
  }
  lnMaybeNotifyDuty_(info.id);
  return { ok: true, message: '確定しました。' };
}

/**
 * 運営クラブへ：両チームのスタメンがそろったら1通だけ「スタメンが届きました。承認してください」
 * 差し戻しのあと出し直されたときは、もう一度送る（両チームの最新の提出の組み合わせが変わったとき）
 */
function lnMaybeNotifyDuty_(mid) {
  try {
    var m = findMatch_(mid), info = lnMatchInfo_(m);
    var rows = lnRows_();
    var h = lnLatest_(rows, mid, info.homeId), a = lnLatest_(rows, mid, info.awayId);
    var ready = function (r) { return r && ['確定', '運営クラブOK'].indexOf(String(r['状態'])) >= 0; };
    if (!ready(h) || !ready(a)) return false;
    if (String(h['状態']) === '運営クラブOK' && String(a['状態']) === '運営クラブOK') return false;
    var sig = String(h['提出ID']) + '|' + String(a['提出ID']);
    var props = PropertiesService.getScriptProperties();
    if (props.getProperty('LNDUTY:' + mid) === sig) return false;
    var code = lnDutyCode_(m);
    var to = code ? lnUnivMails_(code) : [];
    if (!to.length) to = [String(cfg_('管理者メール') || '')].filter(Boolean);
    if (!to.length) return false;
    var url = code ? lnUrl_(code) : '';
    var late = [h, a].filter(function (r) { return String(r['締切後']) === '締切後'; });
    mail_('スタメン運営クラブ確認', to.join(','),
      '【運営クラブ】スタメンが届きました：' + info.round + '　' + info.home + ' vs ' + info.away,
      '<p>運営クラブご担当者様</p><p>' + lnEsc_(info.home) + '・' + lnEsc_(info.away) + ' の両チームのスタメンが届きました。' +
      '運営クラブのページで、登録・出場停止のチェック結果を確認し、それぞれ「出場可能（OK）」を押してください。</p>' +
      (late.length ? '<p style="color:#D84315">締切後の提出があります：' + late.map(function (r) { return lnEsc_(lnTeamName_(r['チームID'])) + (r['変更理由'] ? '（' + lnEsc_(r['変更理由']) + '）' : ''); }).join('、') + '</p>' : '') +
      (url ? '<p><a href="' + url + '">運営クラブのページを開く</a></p>' : '') +
      '<p>審判団のメールアドレスも、キックオフ90分前までに入力してください（両チームOKでスタメンが審判団へ送られます）。</p>', mid, '', [code || 'JIMU']);
    props.setProperty('LNDUTY:' + mid, sig);
    return true;
  } catch (e) {
    try { log_('スタメン運営クラブ通知エラー', 'スタメン', mid, null, null, String(e && e.message || e)); } catch (x) {}
    return false;
  }
}

/** チームへ：スタメンが承認された／差し戻された */
function lnNotifyTeam_(r, ok, comment) {
  var info = lnMatchInfo_(findMatch_(r['試合ID']));
  var to = lnTeamMail_(r['チームID']);
  var team = lnTeamName_(r['チームID']);
  var url = lnUrl_(rgTeamCode_(r['チームID']));
  // メールがなくても、チームのDiscordには届ける（TeamNotify.gs）
  (typeof tnMail_ === 'function' ? tnMail_ : function (ty, t, s, h, id) { if (t) mail_(ty, t, s, h, id, ''); })(ok ? 'スタメン承認' : 'スタメン差し戻し', to,
    (ok ? '【スタメン承認】' : '【スタメン差し戻し】') + info.round + '　' + info.home + ' vs ' + info.away,
    '<p>' + lnEsc_(team) + ' ご担当者様</p>' +
    (ok ? '<p>運営クラブがスタメンを確認し、出場可能（OK）としました。</p>' + lnJfaHtml_(lnContent_(r), lnJfaUnchecked_(r))
      : '<p>運営クラブから、スタメンの差し戻しがありました。直して提出し直してください。</p>' +
        '<p style="border-left:3px solid #D84315;padding-left:8px">' + lnEsc_(comment).replace(/\n/g, '<br>') + '</p>' +
        '<p><a href="' + url + '">スタメン提出のページを開く</a></p>'), String(r['試合ID']), [rgTeamCode_(r['チームID'])]);
  return to;
}

// ─────────────────────── 運営クラブ ───────────────────────

function lnDutyAuth_(u, t, mid) {
  lnAuth_(u, t);
  var m = findMatch_(mid);
  if (lnDutyCode_(m) !== u && u !== LN_JIMU) throw new Error('この試合の運営クラブではありません');
  return m;
}

function lineupDutyView(u, t, mid) {
  return withReadMemo_(function () {
    var m = lnDutyAuth_(u, t, mid);
    var info = lnMatchInfo_(m);
    var rows = lnRows_();
    var side = function (tid) {
      var r = lnLatest_(rows, mid, tid);
      var v = lnRowView_(r);
      if (v && v.content) delete v.content.approver; // 承認者の連絡先は運営クラブには見せない
      var players = lnPlayers_(mid, tid, info.date);
      return { teamId: tid, teamName: lnTeamName_(tid), row: v, check: v && ['確定', '運営クラブOK', '差し戻し'].indexOf(v.status) >= 0 ? lnCheck_(v.content, players) : null };
    };
    var ref = lnRefRows_().filter(function (r) { return String(r['試合ID']) === String(mid); })[0] || {};
    var refs = {};
    LN_ROLES.forEach(function (x) {
      refs[x[0]] = { name: String(ref[x[1]] || ''), email: String(ref[x[1] + 'メール'] || '') };
    });
    // 日程表の審判名を初期値に
    if (!refs.main.name && m['主審']) refs.main.name = String(m['主審']);
    if (!refs.ar1.name && m['副審']) { var ars = String(m['副審']).split(/[・、,／\/]/); refs.ar1.name = ars[0] || ''; refs.ar2.name = ars[1] || ''; }
    if (!refs.fourth.name && m['第4審']) refs.fourth.name = String(m['第4審']);
    // 審判員マスターにメールがあれば入れておく（MatchDay.gs）
    if (typeof mdRefByName_ === 'function') {
      LN_ROLES.forEach(function (x) {
        var o = refs[x[0]];
        if (o.name && !o.email) { var r = mdRefByName_(o.name); if (r && r['メール']) o.email = String(r['メール']); }
      });
    }
    return { match: info, home: side(info.homeId), away: side(info.awayId), refs: refs, refsSent: String(ref['審判団へ送信日時'] || ''), refBy: String(ref['入力者'] || ''),
      liveUrl: typeof liveUrl_ === 'function' ? liveUrl_(mid) : '' };
  });
}

/** 運営クラブ：OK／差し戻し */
function lineupDutyDecide(u, t, mid, sid, action, comment, name, unchecked) {
  lnDutyAuth_(u, t, mid);
  name = String(name || '').trim();
  if (!name) throw new Error('確認した人の名前を入力してください');
  var r = lnRows_().filter(function (x) { return String(x['提出ID']) === String(sid) && String(x['試合ID']) === String(mid); })[0];
  if (!r) throw new Error('提出が見つかりません');
  var st = String(r['状態']);
  if (['確定', '運営クラブOK', '差し戻し'].indexOf(st) < 0) throw new Error('このスタメンは「' + st + '」のため確認できません。ページを開き直してください');
  if (action === 'ok') {
    // JFA登録：画面でチェックが入っていない選手＝JFA登録が確認できなかった選手
    var c = lnContent_(r) || {};
    var inList = {};
    (c.starters || []).concat(c.bench || []).forEach(function (x) { inList[String(x.pid)] = true; });
    var unc = (Array.isArray(unchecked) ? unchecked : []).map(String).filter(function (pid, i, a) { return inList[pid] && a.indexOf(pid) === i; });
    update_(LN.SHEET, r._row, { '状態': '運営クラブOK', '運営クラブ確認者': name, '運営クラブ確認日時': lnNow_(), '運営クラブコメント': String(comment || ''), 'JFA登録未確認': JSON.stringify(unc) });
    r['JFA登録未確認'] = JSON.stringify(unc);
    lnNotifyTeam_(r, true, '');
    var sent = lnMaybeSendRefs_(mid, false);
    var nm = lnJfaNames_(c, unc);
    return { ok: true, message: '出場可能（OK）にしました。チームへ知らせました。' + (nm.length ? 'JFA登録未確認：' + nm.length + '人。' : '') + (sent || '') };
  }
  if (action === 'return') {
    if (!String(comment || '').trim()) throw new Error('差し戻しの理由を書いてください');
    update_(LN.SHEET, r._row, { '状態': '差し戻し', '運営クラブ確認者': name, '運営クラブ確認日時': lnNow_(), '運営クラブコメント': String(comment) });
    lnNotifyTeam_(r, false, comment);
    return { ok: true, message: '差し戻しました。チームへメールで知らせました。' };
  }
  throw new Error('操作が正しくありません');
}

/** 運営クラブ：審判団のメールアドレス */
function lineupSaveRefs(u, t, mid, refs, name) {
  lnDutyAuth_(u, t, mid);
  refs = refs || {};
  var patch = { '試合ID': "'" + mid, '入力者': String(name || ''), '更新日時': lnNow_() };
  LN_ROLES.forEach(function (x) {
    var o = refs[x[0]] || {};
    var em = String(o.email || '').trim();
    if (em && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em)) throw new Error(x[1] + 'のメールアドレスを確認してください');
    patch[x[1]] = String(o.name || '').trim();
    patch[x[1] + 'メール'] = em;
  });
  var cur = lnRefRows_().filter(function (r) { return String(r['試合ID']) === String(mid); })[0];
  if (cur) update_(LN.REF, cur._row, patch); else append_(LN.REF, patch);
  var sent = lnMaybeSendRefs_(mid, false);
  return { ok: true, message: '審判団の連絡先を保存しました。' + (sent || '') };
}

function lineupSendRefsNow(u, t, mid) {
  lnDutyAuth_(u, t, mid);
  var s = lnMaybeSendRefs_(mid, true);
  return { ok: true, message: s || '送れませんでした' };
}

/** 両チームが運営クラブOKで、審判のメールがあれば、審判団へスタメン表を送る（force：送信済みでも送り直す） */
function lnMaybeSendRefs_(mid, force) {
  var m = findMatch_(mid);
  var info = lnMatchInfo_(m);
  var rows = lnRows_();
  var h = lnLatest_(rows, mid, info.homeId), a = lnLatest_(rows, mid, info.awayId);
  var ok = function (r) { return r && String(r['状態']) === '運営クラブOK'; };
  if (!ok(h) || !ok(a)) return force ? '両チームのスタメンが運営クラブOKになっていません' : '';
  var ref = lnRefRows_().filter(function (r) { return String(r['試合ID']) === String(mid); })[0];
  var mails = ref ? LN_ROLES.map(function (x) { return String(ref[x[1] + 'メール'] || '').trim(); }).filter(Boolean) : [];
  if (!mails.length) return force ? '審判団のメールアドレスが入力されていません' : '（審判団のメールアドレスを入力すると、スタメンが審判団へ送られます）';
  var sig = String(h['提出ID']) + '|' + String(a['提出ID']) + '|' + mails.join(',') + '|' + String(h['JFA登録未確認'] || '') + '|' + String(a['JFA登録未確認'] || '');
  var props = PropertiesService.getScriptProperties();
  if (!force && props.getProperty('LNREF:' + mid) === sig) return '';
  var html = '<p>審判団の皆様</p><p>' + lnEsc_(info.comp) + '　' + lnEsc_(info.round) + '（' + lnEsc_(info.date) + ' ' + lnEsc_(info.kickoff) + '　' + lnEsc_(info.venue) + '）のスタメンです。<br>運営クラブが登録・出場停止を確認済みです。</p>' +
    '<h3 style="font-size:15px;margin:14px 0 4px">' + lnEsc_(info.home) + '</h3>' + lnListHtml_(lnContent_(h), lnJfaUnchecked_(h)) +
    '<h3 style="font-size:15px;margin:14px 0 4px">' + lnEsc_(info.away) + '</h3>' + lnListHtml_(lnContent_(a), lnJfaUnchecked_(a));
  // 第4の審判へ：試合中に交代・得点・警告退場を記録するページ（Live.gs）
  var live = typeof liveUrl_ === 'function' ? liveUrl_(mid) : '';
  if (live) html += '<hr><p><b>第4の審判の方へ</b><br>試合中は、次のページで交代・得点・警告・退場を記録してください（記録は公式記録の入力に取り込まれます）。</p>' +
    '<p><a href="' + live + '" style="display:inline-block;padding:10px 18px;background:#1976D2;color:#fff;text-decoration:none;border-radius:6px">試合中の記録ページを開く</a></p>';
  mail_('スタメン審判団送付', mails.join(','), '【スタメン】' + info.round + '　' + info.home + ' vs ' + info.away + '（' + info.date + ' ' + info.kickoff + '）', html, mid, '');
  props.setProperty('LNREF:' + mid, sig);
  update_(LN.REF, ref._row, { '審判団へ送信日時': lnNow_() });
  return '審判団（' + mails.length + '人）へスタメンを送りました。';
}

/** メール用のスタメン表 */
function lnJfaHtml_(c, pids) {
  var nm = lnJfaNames_(c, pids);
  return nm.length ? '<p style="border-left:3px solid #D84315;padding-left:8px">運営クラブで<b>JFA登録が確認できなかった選手</b>：' + nm.map(lnEsc_).join('、') +
    '<br>試合前に、運営クラブへJFA登録の分かるもの（登録証の画面など）を見せてください。</p>' : '';
}

/** 位置順（GK→DF→MF→FW）×背番号順 */
function lnSortPlayers_(list) {
  var po = { GK: 0, DF: 1, MF: 2, FW: 3 };
  var num = function (n) { var v = parseInt(String(n || ''), 10); return isNaN(v) ? 999 : v; };
  return (list || []).slice().sort(function (a, b) {
    var pa = po[String(a.pos || '')] === undefined ? 9 : po[String(a.pos)], pb = po[String(b.pos || '')] === undefined ? 9 : po[String(b.pos)];
    return pa !== pb ? pa - pb : num(a.no) - num(b.no);
  });
}

function lnListHtml_(c, unchecked) {
  var unc = unchecked || [];
  if (!c) return '<p>（未提出）</p>';
  var td = 'style="border:1px solid #E0E0E0;padding:4px 8px"';
  var row = function (x) {
    return '<tr><td ' + td + ' align="right">' + lnEsc_(x.no) + '</td><td ' + td + '>' + lnEsc_(x.pos || '') + '</td><td ' + td + '>' +
      lnEsc_(x.name) + (String(c.captain) === String(x.pid) ? '（C）' : '') +
      (unc.indexOf(String(x.pid)) >= 0 ? ' <span style="color:#D84315">※JFA登録未確認</span>' : '') + '</td></tr>';
  };
  var band = function (label, n) {
    return '<tr><td colspan="3" style="border:1px solid #E0E0E0;border-top:2px solid #222222;background:#E8F4FB;padding:4px 8px;font-weight:bold">' + label + '（' + n + '人）</td></tr>';
  };
  var st = lnSortPlayers_(c.starters), bn = lnSortPlayers_(c.bench);
  return '<table style="border-collapse:collapse;font-size:13px;min-width:280px"><tr><th ' + td + '>No.</th><th ' + td + '>位置</th><th ' + td + '>氏名</th></tr>' +
    band('先発', st.length) + st.map(row).join('') +
    band('控え', bn.length) + (bn.length ? bn.map(row).join('') : '<tr><td colspan="3" ' + td + '>（なし）</td></tr>') + '</table>' +
    ((c.staff || []).length ? '<p style="font-size:13px;margin:6px 0 0"><b>ベンチ入りスタッフ</b>：' + c.staff.map(function (s) { return lnEsc_((s.role ? s.role + ' ' : '') + s.name); }).join('、') + '</p>' : '');
}

// ─────────────────────── 公式記録の入力画面へ ───────────────────────

/**
 * ベンチ入りスタッフ（審判報告書の「チーム役員」の候補）
 *  スタメン提出（運営クラブOK・確定）→ なければ公式記録の入力内容 の順に探す
 */
function lnBenchStaff_(mid, tid) {
  try {
    var ss = ss_();
    if (ss.getSheetByName(LN.SHEET)) {
      var r = objs_(LN.SHEET).filter(function (x) { return String(x['試合ID']) === String(mid) && String(x['チームID']) === String(tid) && ['運営クラブOK', '確定'].indexOf(String(x['状態'])) >= 0; })
        .sort(function (a, b) { return num_(b['版']) - num_(a['版']); })[0];
      var c = lnContent_(r);
      if (c && (c.staff || []).length) return c.staff;
    }
    var rec = typeof revRecordsForMatch_ === 'function' ? revRecordsForMatch_(mid)[0] : null;
    var st = rec ? revUnpack_(rec['入力データ']) : null;
    if (st && st.staff) {
      var m = findMatch_(mid);
      var side = String(m['ホームチームID']) === String(tid) ? 'home' : 'away';
      return (st.staff[side] || []).filter(function (s) { return s.name; });
    }
  } catch (e) {}
  return [];
}

/** 運営クラブOK（なければ確定）のスタメンと審判団 → 公式記録の入力画面の初期値 */
function lnForRecord_(mid) {
  try {
    var ss = ss_();
    var m = findMatch_(mid);
    var rows = ss.getSheetByName(LN.SHEET) ? objs_(LN.SHEET) : [];
    var pick = function (tid) {
      var list = rows.filter(function (r) { return String(r['試合ID']) === String(mid) && String(r['チームID']) === String(tid) && ['運営クラブOK', '確定'].indexOf(String(r['状態'])) >= 0; })
        .sort(function (a, b) { return (String(b['状態']) === '運営クラブOK') - (String(a['状態']) === '運営クラブOK') || num_(b['版']) - num_(a['版']); });
      var r = list[0];
      if (!r) return null;
      var c = lnContent_(r) || {};
      return { status: String(r['状態']), version: num_(r['版']), starters: c.starters || [], bench: c.bench || [], captain: c.captain || '', staff: c.staff || [], approver: c.approver || null };
    };
    var out = { home: pick(m['ホームチームID']), away: pick(m['アウェイチームID']), refs: null };
    if (ss.getSheetByName(LN.REF)) {
      var ref = objs_(LN.REF).filter(function (r) { return String(r['試合ID']) === String(mid); })[0];
      if (ref) out.refs = { referee: String(ref['主審'] || ''), refereeEmail: String(ref['主審メール'] || ''), ar1: String(ref['副審1'] || ''), ar2: String(ref['副審2'] || ''), fourth: String(ref['第4の審判'] || '') };
    }
    // 運営クラブの入力がなければ、試合マスターの割り当て＋審判員マスターのメール
    if (!out.refs && typeof mdAssigned_ === 'function') {
      var as = mdAssigned_(m), by = {};
      as.forEach(function (a) { by[a.role] = a; });
      if (as.length) out.refs = { referee: (by['主審'] || {}).name || '', refereeEmail: (by['主審'] || {}).email || '', ar1: (by['副審1'] || {}).name || '', ar2: (by['副審2'] || {}).name || '', fourth: (by['第4の審判'] || {}).name || '' };
    }
    return (out.home || out.away || out.refs) ? out : null;
  } catch (e) { return null; }
}

// ─────────────────────── リンク ───────────────────────


;
// ==== Links.gs
/**
 * Links.gs v1
 * ページのリンクを「各クラブ」「規律委員会＆事務局」「審判員」に分けてまとめる
 *  ・createLinkDirectory()：スプレッドシートに「リンク集」タブを作る（各クラブの専用リンクもここ）
 *  ・linkHomePage()：だれでも開ける案内ページ（?page=home）。専用リンク（合言葉つき）は載せない
 *  ・運営ダッシュボードの「リンク集」タブも linkDirectory_() を使う
 */

var LINK_SHEET = 'リンク集';

/** ページのURLの土台（入口ページがあればそちら。スマホでドライブのアプリに横取りされないため） */
function linkBase_() {
  var base = webAppBaseUrl_();
  return (typeof entryBase_ === 'function' && base && entryBase_()) || base;
}

function linkDirectory_() {
  var base = linkBase_(), exec = webAppBaseUrl_();
  var u = function (q) { return base ? base + q : ''; };
  var docs = '';
  try { if (typeof docRoot_ === 'function') docs = docRoot_().getUrl(); } catch (e) {}
  var regForm = String(cfg_('選手登録申請フォームURL') || '');
  var refForm = String(cfg_('審判員登録フォームURL') || '');
  var univs = typeof lnUnivs_ === 'function' ? lnUnivs_() : {};
  var schools = [];
  // 全体システム：チームページはリーグごと（リーグから取り込んだ「チームページ台帳」）
  // 一体のシステムは、チームページ・公式記録などのページも自分のURL（リーグ別の台帳は使わない）
  var central = typeof isCentral_ === 'function' && isCentral_() && !(typeof isSingle_ === 'function' && isSingle_());
  var tp = central ? ss_().getSheetByName('チームページ台帳') : null;
  if (tp && tp.getLastRow() > 1) {
    var tv = tp.getDataRange().getValues(), th = tv[0].map(String);
    schools = tv.slice(1).map(function (r) {
      var code = String(r[th.indexOf('クラブコード')]);
      return { univ: String(r[th.indexOf('クラブ名')]) + '（' + String(r[th.indexOf('リーグ名')]) + '）', code: code, url: String(r[th.indexOf('チームページURL')]),
        mails: typeof lnUnivMails_ === 'function' ? lnUnivMails_(code).join(', ') : '' };
    }).sort(function (a, b) { return a.univ < b.univ ? -1 : 1; });
  } else {
    schools = Object.keys(univs).sort(function (a, b) { return univs[a] < univs[b] ? -1 : 1; }).map(function (code) {
      return { univ: univs[code], code: code, url: typeof lnUrl_ === 'function' ? lnUrl_(code) : '',
        mails: typeof lnUnivMails_ === 'function' ? lnUnivMails_(code).join(', ') : '' };
    });
  }
  // 全体システム：公式記録入力・審判報告書は各リーグのページ（「連携リーグ」タブの「ページURL」）
  var leaguePages = [];
  if (central) {
    var lg = ss_().getSheetByName('連携リーグ');
    if (lg && lg.getLastRow() > 1) {
      var lv = lg.getDataRange().getValues(), lh = lv[0].map(String), pi = lh.indexOf('ページURL');
      if (pi >= 0) lv.slice(1).forEach(function (r) {
        var pu = String(r[pi] || '').trim().replace(/[?#].*$/, '');
        if (pu) leaguePages.push({ name: String(r[lh.indexOf('名前')]), url: pu });
      });
    }
  }
  var rec = central
    ? leaguePages.map(function (p) { return { label: '公式記録入力（' + p.name + '）', url: p.url + '?page=official', note: '運営クラブが入力' }; })
    : [{ label: '公式記録入力', url: u('?page=official'), note: '運営クラブが入力' },
       { label: '連盟事務局のスタメン確認ページ', url: typeof lnUrl_ === 'function' ? lnUrl_('JIMU') : '', note: 'すべての試合のスタメン確認（JFA登録の1人ずつの確認）。運営クラブが「連盟事務局」の試合は、審判員のメール・公式記録も' }];
  var refp = central
    ? leaguePages.map(function (p) { return { label: '審判報告書（' + p.name + '）', url: p.url + '?page=referee', note: '試合後に主審が入力' }; })
    : [{ label: '審判報告書', url: u('?page=referee'), note: '試合後に主審が入力' }];
  // マッチコミッショナー報告書（McReport.gs）も各リーグのページ
  refp = refp.concat(central
    ? leaguePages.map(function (p) { return { label: 'マッチコミッショナー報告書（' + p.name + '）', url: p.url + '?page=mc', note: '試合後にMCが入力（緊急報告書も）' }; })
    : [{ label: 'マッチコミッショナー報告書', url: u('?page=mc'), note: '試合後にMCが入力（緊急報告書も）' }]);
  return {
    schools: schools,
    office: [
      { label: '運営ダッシュボード', url: base ? base + '?page=admin' : '', note: '運営パスコードでログイン。試合・日程、登録、処分、決定通知、取込の確認、チーム' }
    ].concat(rec).concat([
      { label: 'ホームページ（日程・結果・順位表）', url: typeof publicSiteUrl_ === 'function' ? publicSiteUrl_() : u('?page=public'), note: '公開' },
      { label: '書類フォルダ（PDF）', url: docs, note: '公式記録・審判報告書・決定通知のPDF' },
      { label: 'スプレッドシート', url: ss_().getUrl(), note: '事務局のみ' },
      { label: '処分の確認・決定通知の承認', url: '', note: 'ページは処分ごと。規律委員会へのメール・LINEのリンクから開きます' }
    ]),
    referees: refp.concat([
      { label: '審判員の登録フォーム', url: refForm, note: 'シーズン前に連絡先を登録' },
      { label: 'ホームページ（日程・結果）', url: typeof publicSiteUrl_ === 'function' ? publicSiteUrl_() : u('?page=public'), note: '担当する試合の確認' }
    ]),
    regForm: regForm,
    home: u('?page=home')
  };
}

/** メニュー：スプレッドシートに「リンク集」タブを作る */
function createLinkDirectory() {
  if (!webAppBaseUrl_()) throw new Error('システム設定の「WebアプリURL」に /exec のURLを入れてください');
  if (typeof lnSheet_ === 'function') { lnSheet_(LN.SHEET, LN_COLS); lnSheet_(LN.REF, LN_REF_COLS); }
  var d = linkDirectory_();
  var rows = [];
  var head = function (t) { rows.push([t, '', '', '']); };
  var blank = function () { rows.push(['', '', '', '']); };
  rows.push(['リンク集（' + Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm') + ' 作成）', '', '', '']);
  rows.push(['案内ページ（だれでも開ける）', d.home, '各クラブ・規律委員会＆事務局・審判員の入口', '']);
  blank();
  head('■ 各クラブ（チームページ：スタメン提出・運営クラブ・選手登録・公式記録入力）');
  rows.push(['クラブ', 'チームページ（このクラブ専用。ほかのクラブに渡さない）', '送り先（責任者・監督）', '']);
  d.schools.forEach(function (s) { rows.push([s.univ, s.url, s.mails, '']); });
  blank();
  head('■ 規律委員会＆事務局');
  d.office.forEach(function (x) { rows.push([x.label, x.url, x.note, '']); });
  blank();
  head('■ 審判員');
  d.referees.forEach(function (x) { rows.push([x.label, x.url, x.note, '']); });

  var ss = ss_();
  var sh = ss.getSheetByName(LINK_SHEET) || ss.insertSheet(LINK_SHEET, 0);
  sh.clear();
  sh.getRange(1, 1, rows.length, 4).setValues(rows);
  sh.setColumnWidth(1, 230); sh.setColumnWidth(2, 560); sh.setColumnWidth(3, 360);
  sh.getRange(1, 1).setFontWeight('bold').setFontSize(12);
  rows.forEach(function (r, i) {
    if (/^■/.test(r[0])) sh.getRange(i + 1, 1, 1, 4).merge().setFontWeight('bold').setBackground('#E8F4FB').setFontColor('#1976D2');
    if (r[0] === 'クラブ') sh.getRange(i + 1, 1, 1, 3).setFontWeight('bold').setFontColor('#888888');
  });
  // 旧「スタメン・運営クラブリンク」タブは不要になったので消す
  var old = ss.getSheetByName('スタメン・運営クラブリンク');
  if (old) { try { ss.deleteSheet(old); } catch (e) {} }
  var msg = '「' + LINK_SHEET + '」タブを作りました。\n・各クラブには、そのクラブの行の「チームページ」のURLを送ってください（スタメン提出・運営クラブ・選手登録・公式記録入力がまとまっています）\n・規律委員会＆事務局、審判員のリンクもこのタブにあります\n・運営ダッシュボードの「リンク集」タブでも同じものが見られます';
  try { SpreadsheetApp.getUi().alert('リンク集', msg, SpreadsheetApp.getUi().ButtonSet.OK); } catch (e) { Logger.log(msg); }
  return msg;
}

/** 案内ページ（?page=home）：専用リンクは載せない */
function linkHomePage() {
  var d = linkDirectory_();
  var a = function (label, url, note) {
    if (!url) return '<div class="item"><div class="l">' + htmlEsc_(label) + '</div><div class="n">' + htmlEsc_(note || '') + '</div></div>';
    return '<a class="item" target="_top" href="' + htmlEsc_(url) + '"><div class="l">' + htmlEsc_(label) + ' ›</div><div class="n">' + htmlEsc_(note || '') + '</div></a>';
  };
  var office = d.office.filter(function (x) { return !/スプレッドシート|書類フォルダ/.test(x.label); });
  var html =
    '<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">' +
    '<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;700&display=swap" rel="stylesheet">' +
    '<style>body{margin:0;background:#FFFFFF;color:#222222;font-family:"Noto Sans JP",sans-serif}' +
    '.w{max-width:640px;margin:0 auto;padding:20px 16px 40px}h1{font-size:19px;margin:0 0 4px}.sub{color:#888888;font-size:13px}' +
    'h2{font-size:15px;color:#1976D2;border-bottom:1px solid #E0E0E0;padding-bottom:6px;margin:26px 0 8px}' +
    '.item{display:block;padding:12px 4px;border-bottom:1px solid #E0E0E0;color:#222222;text-decoration:none}' +
    'a.item .l{color:#1976D2;font-weight:700}.n{color:#888888;font-size:12px;margin-top:2px}' +
    '.box{background:#E8F4FB;padding:12px;font-size:13px;line-height:1.7}</style></head><body><div class="w">' +
    '<h1>' + orgName_() + '</h1><div class="sub">大会運営のページ</div>' +
    '<h2>各クラブ</h2><div class="box">スタメン提出・運営クラブ・選手登録・公式記録入力は、<b>各クラブ専用の「チームページ」</b>から行います。事務局から届いたリンクを開き、ブックマーク（ホーム画面に追加）してください。リンクが分からないときは事務局へ連絡してください。</div>' +
    a('ホームページ（日程・結果・順位表）', (d.office.filter(function (x) { return /ホームページ/.test(x.label); })[0] || {}).url, '') +
    '<h2>規律委員会＆事務局</h2>' + office.map(function (x) { return a(x.label, x.url, x.note); }).join('') +
    '<h2>審判員</h2>' + d.referees.map(function (x) { return a(x.label, x.url, x.note); }).join('') +
    '</div></body></html>';
  return HtmlService.createHtmlOutput(html).setTitle(orgName_() + ' 大会運営')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

/** 運営ダッシュボードの「リンク集」タブ */
