// ==== Logo.gs
/**
 * Logo.gs v2（社会人リーグ版）
 * 公式記録PDFに連盟のロゴを入れる
 *  メニュー「設定」→「公式記録PDFにロゴを入れる」：
 *   システム設定「ロゴ画像のファイルID」（Googleドライブの PNG・JPEG。URL でもよい）の画像を、
 *   「公式記録PDFテンプレート_正方形」タブの左上に置く（前に置いたロゴは置き換える）。
 *   PDFはこのタブを写して作るので、次に作る公式記録PDFからロゴが入る。
 *   位置・大きさは、テンプレートのタブの上でロゴをドラッグして直せる。
 *  学連版に入っていた JUFA のロゴの画像は消した（Bootstrap.gs が、写した様式からも JUFA のロゴを外す）
 */
var JUFA_LOGO_ALT = '連盟ロゴ';
var JUFA_LOGO_ALT_OLD = 'JUFAロゴ';

function logoBlob_() {
  var id = String(cfg_('ロゴ画像のファイルID') || '').trim().replace(/^.*\/d\/([^/?#]+).*$/, '$1').replace(/^.*[?&]id=([^&#]+).*$/, '$1');
  if (!id) {
    setCfg_('ロゴ画像のファイルID', '', '公式記録PDFに入れる連盟のロゴ（GoogleドライブのPNG・JPEGのファイルIDかURL）');
    throw new Error('システム設定「ロゴ画像のファイルID」に、ロゴの画像（Googleドライブ）のIDかURLを入れてから、もう一度実行してください');
  }
  return DriveApp.getFileById(id).getBlob();
}

function insertRecordLogo() {
  var ui = null;
  try { ui = SpreadsheetApp.getUi(); } catch (e) {}
  var sh = ss_().getSheetByName('公式記録PDFテンプレート_正方形');
  if (!sh) throw new Error('「公式記録PDFテンプレート_正方形」タブがありません');
  var removed = 0;
  var blob = logoBlob_();
  sh.getImages().forEach(function (i) { var a = i.getAltTextTitle(); if (a === JUFA_LOGO_ALT || a === JUFA_LOGO_ALT_OLD) { i.remove(); removed++; } });
  // 1〜2行目の高さに合わせる（30〜64px）
  var h = Math.max(30, Math.min(64, sh.getRowHeight(1) + sh.getRowHeight(2) - 6));
  var img = sh.insertImage(blob, 1, 1, 3, 3);
  var ratio = img.getWidth() / img.getHeight();
  img.setHeight(h).setWidth(Math.round(h * ratio)).setAltTextTitle(JUFA_LOGO_ALT);
  var near = sh.getRange('A1:H2').getDisplayValues().map(function (r) { return r.filter(String).join(' '); }).filter(String).join(' ／ ');
  var msg = '「公式記録PDFテンプレート_正方形」タブの左上にロゴを入れました' + (removed ? '（前のロゴと置き換え）' : '') + '。\n' +
    '次に作る公式記録PDFからロゴが入ります。\n' +
    (near ? '※左上の欄に「' + near + '」が書かれています。ロゴと重なる場合は、タブの上でロゴをドラッグして位置・大きさを直してください。' : '位置・大きさは、タブの上でロゴをドラッグして直せます。');
  if (ui) ui.alert('公式記録PDFのロゴ', msg, ui.ButtonSet.OK);
  return msg;
}

;
// ==== MatchDay.gs
/**
 * MatchDay.gs v2
 * 審判員マスター（シーズン前に審判員の連絡先を集める）と、試合の審判の割り当ての読み取り
 *  ・メニュー「設定」→「審判員の登録フォームを作成」→ 審判員がフォームで登録 →「審判員マスター」タブに入る
 *  ・試合マスターの「主審」「副審」（2人は「・」で区切る）「第4審」の氏名から、審判員マスターのメールを探す
 *    （運営クラブページの審判団の連絡先・公式記録の審判欄に使う）
 *  ・試合日の通知・割り当てのお知らせは使わない運用のため削除
 */

var MD = { REF_SHEET: '審判員マスター' };
var MD_REF_COLS = ['審判員ID', '氏名', 'フリガナ', '所属', '審判級', '所属協会', 'メール', '電話番号', '有効', '登録日時', '備考'];

// ─────────────────────── 共通 ───────────────────────

function mdNorm_(s) { return String(s || '').normalize('NFKC').replace(/[\s　]/g, ''); }
function mdNow_() { return Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm:ss'); }

function mdSheet_(name, cols) {
  if (typeof lnSheet_ === 'function') return lnSheet_(name, cols);
  var ss = ss_(), sh = ss.getSheetByName(name);
  if (!sh) { sh = ss.insertSheet(name); sh.getRange(1, 1, 1, cols.length).setValues([cols]).setFontWeight('bold').setBackground('#E8F4FB'); sh.setFrozenRows(1); }
  else ensureHeader_(name, cols);
  return sh;
}

function mdReferees_() { mdSheet_(MD.REF_SHEET, MD_REF_COLS); return objs_(MD.REF_SHEET).filter(function (r) { return String(r['有効'] || '有効') !== '無効'; }); }

/** 氏名 → 審判員（マスター） */
function mdRefByName_(name) {
  var k = mdNorm_(name);
  if (!k) return null;
  return mdReferees_().filter(function (r) { return mdNorm_(r['氏名']) === k; })[0] || null;
}

/** 試合に割り当てられた審判（試合マスターの 主審・副審・第4審） */
function mdAssigned_(m) {
  var out = [];
  var add = function (role, name) {
    name = String(name || '').trim();
    if (!name) return;
    var r = mdRefByName_(name);
    out.push({ role: role, name: name, email: r ? String(r['メール'] || '').trim() : '', ref: r });
  };
  add('主審', m['主審']);
  String(m['副審'] || '').split(/[・、,，／\/]/).forEach(function (n, i) { add('副審' + (i + 1), n); });
  add('第4の審判', m['第4審']);
  return out;
}

// ─────────────────────── 1. 審判員の登録フォーム ───────────────────────

function setupRefereeForm() {
  mdSheet_(MD.REF_SHEET, MD_REF_COLS);
  var f = null;
  var id = String(cfg_('審判員登録フォームID') || '');
  if (id) { try { f = FormApp.openById(id); } catch (e) { f = null; } }
  if (!f) {
    f = FormApp.create('審判員 連絡先登録フォーム（' + (typeof rgYear_ === 'function' ? rgYear_() : '') + '年度）');
    f.setDescription(orgName_() + 'の試合を担当する審判員の連絡先を登録するフォームです。\n' +
      '登録したメールアドレスに、担当試合の割り当て・試合当日の案内・スタメン表が届きます。\n変更があるときは、同じメールアドレスでもう一度送信してください（上書きされます）。');
    f.setConfirmationMessage('登録しました。担当試合が決まると、メールでお知らせします。');
    f.addTextItem().setTitle('氏名').setRequired(true).setHelpText('例：北海 太郎（姓と名の間にスペース）');
    f.addTextItem().setTitle('フリガナ');
    f.addTextItem().setTitle('所属（クラブ・チームなど）');
    f.addListItem().setTitle('審判級').setChoiceValues(['1級', '2級', '3級', '4級']).setRequired(true);
    f.addTextItem().setTitle('所属協会').setHelpText('例：札幌、北海道');
    f.addTextItem().setTitle('メールアドレス').setRequired(true)
      .setValidation(FormApp.createTextValidation().requireTextIsEmail().setHelpText('メールアドレスを入力してください').build());
    f.addTextItem().setTitle('電話番号').setHelpText('審判報告書に記入する番号（主審を担当する場合）');
    setCfg_('審判員登録フォームID', f.getId(), '審判員の連絡先登録フォーム');
    setCfg_('審判員登録フォームURL', f.getPublishedUrl(), '審判員に送るURL');
  }
  ScriptApp.getProjectTriggers().forEach(function (t) { if (t.getHandlerFunction() === 'handleRefereeRegistrationSubmit') ScriptApp.deleteTrigger(t); });
  ScriptApp.newTrigger('handleRefereeRegistrationSubmit').forForm(f).onFormSubmit().create();
  var msg = '審判員の登録フォーム：\n' + f.getPublishedUrl() + '\n\nこのURLを審判員に送ってください。回答は「' + MD.REF_SHEET + '」タブに入ります。';
  try { SpreadsheetApp.getUi().alert('審判員の登録フォーム', msg, SpreadsheetApp.getUi().ButtonSet.OK); } catch (e) { Logger.log(msg); }
  return msg;
}

function handleRefereeRegistrationSubmit(e) {
  var v = {};
  (e && e.response ? e.response.getItemResponses() : []).forEach(function (ir) { v[ir.getItem().getTitle()] = String(ir.getResponse() || '').trim(); });
  var email = String(v['メールアドレス'] || '').trim();
  if (!email) return;
  mdSheet_(MD.REF_SHEET, MD_REF_COLS);
  var cur = objs_(MD.REF_SHEET).filter(function (r) { return String(r['メール']).trim().toLowerCase() === email.toLowerCase(); })[0];
  var o = { '氏名': String(v['氏名'] || '').replace(/\s+/g, ' '), 'フリガナ': v['フリガナ'] || '', '所属': v['所属（クラブ・チームなど）'] || '', '審判級': v['審判級'] || '',
    '所属協会': v['所属協会'] || '', 'メール': email, '電話番号': v['電話番号'] ? "'" + v['電話番号'] : '', '有効': '有効', '登録日時': mdNow_() };
  if (cur) update_(MD.REF_SHEET, cur._row, o);
  else { o['審判員ID'] = 'REF-' + Utilities.getUuid().replace(/-/g, '').slice(0, 8); append_(MD.REF_SHEET, o); }
}

/** 試合日の通知は停止。以前の定期実行が残っていたら、動いたときに自分で消える */
function runMatchDayNotices(forceNow, onlyIds) {
  // 試合日の通知（朝7時・2時間前）は使わない運用になったため停止。残っている定期実行も片付ける
  stopMatchDayNotices_();
  return '試合日の通知は停止しています';
}

function stopMatchDayNotices_() {
  try {
    ScriptApp.getProjectTriggers().forEach(function (t) { if (t.getHandlerFunction() === 'runMatchDayNotices') ScriptApp.deleteTrigger(t); });
  } catch (e) {}
}

