  'label{display:block;font-size:13px;color:var(--sub);margin:14px 0 4px}input,textarea{width:100%;font:inherit;border:1px solid var(--line);border-radius:6px;padding:10px}',
  'textarea{min-height:70px}.row{display:flex;gap:8px;margin-top:18px}button{flex:1;font:inherit;font-weight:700;border-radius:8px;padding:14px;border:1px solid var(--blue);cursor:pointer}',
  '.ok{background:var(--blue);color:#fff}.ng{background:#fff;color:var(--red);border-color:var(--red)}button:disabled{opacity:.5}',
  '.msg{margin-top:16px;padding:12px;border-radius:6px;background:var(--pale)}.err{background:#fff;border:1px solid var(--red);color:var(--red)}',
  '.done{color:var(--sub);font-size:13px;margin-top:8px}',
