  'function esc(s){return String(s==null?"":s).replace(/[&<>"]/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;","\\"":"&quot;"}[c]})}',
  'function show(d){var red=d.kind==="一発退場";var h="<h1>"+(red?"一発退場の処分決定":"出場停止の確認")+"</h1><dl>";',
  ' h+="<dt>選手</dt><dd><b>"+esc(d.player)+"</b>（"+esc(d.team)+"）<span class=k>"+esc(d.kind)+"</span></dd>";',
  ' h+="<dt>大会</dt><dd>"+esc(d.comp)+"</dd><dt>発生試合</dt><dd>"+esc(d.origin)+"</dd>";',
  ' if(d.reason)h+="<dt>理由</dt><dd>"+esc(d.reason)+"</dd>";',
  ' if(d.yellows.length)h+="<dt>警告を受けた試合</dt><dd>"+d.yellows.map(esc).join("<br>")+"</dd>";',
  ' h+="<dt>停止する試合</dt><dd>"+(d.targets.length?d.targets.map(esc).join("<br>"):"未確定")+"</dd>";',
  ' if(d.basis)h+="<dt>根拠</dt><dd>"+esc(d.basis)+"</dd>";',
  ' h+="</dl>";',
  ' if(d.confirm)h+="<div class=done>現在の状態："+esc(d.confirm)+(d.confirmedBy?"（"+esc(d.confirmedBy)+" "+esc(d.confirmedAt)+"）":"")+"</div>";',
  ' if(red)h+="<label>停止試合数（最低"+d.minGames+"試合）</label><input id=g type=number inputmode=numeric min="+d.minGames+" value="+Math.max(d.games,d.minGames)+">";',
  ' h+="<label>確認者（氏名）</label><input id=n autocomplete=name><label>コメント（差し戻しの場合は理由）</label><textarea id=c></textarea>";',
