      stAssert_(n, '一発退場の決定通知が作られていません（作成 ' + made.length + '件' + (NT_LAST_ERRORS.length ? '・' + NT_LAST_ERRORS.join(' ') : '') + '）');
      stAssert_(String(n['PDF URL'] || ''), '決定通知のPDFがありません');
