  add('ファイル', 'PublicSite.html', htmlOk('PublicSite'), htmlOk('PublicSite') ? '' : '「＋」→「HTML」で PublicSite を追加してください');
  add('ファイル', 'BulkRegistration.html', htmlOk('BulkRegistration'), htmlOk('BulkRegistration') ? '' : '「＋」→「HTML」で BulkRegistration を追加してください');
  add('ファイル', 'Admin.html', htmlOk('Admin'), htmlOk('Admin') ? '' : '「＋」→「HTML」で Admin を追加してください');
