  var adminFrame = false; try { adminFrame = /ALLOWALL/.test(String(eval('adminPage'))); } catch (e) {}
  add('ファイル', '運営ダッシュボードを入口ページで開ける', adminFrame, adminFrame ? '' : 'Admin.gs を最新版に貼り替えてください（入口ページで「接続が拒否されました」になります）');

  // 2. セキュリティ
  try {
    var access = DriveApp.getFileById(ss.getId()).getSharingAccess();
    var open = access === DriveApp.Access.ANYONE || access === DriveApp.Access.ANYONE_WITH_LINK;
    add('セキュリティ', 'スプレッドシートの共有', !open, open ? 'リンクを知っている全員が閲覧できます。「制限付き」にしてください' : '制限付き');
  } catch (e) { add('セキュリティ', 'スプレッドシートの共有', null, '確認できませんでした：' + e.message); }
