/** メニュー：システムチェックを実行して「導入チェック」タブを開く */
function runSystemCheckFromMenu() {
  var text = runSystemCheck();
  var ss = typeof ss_ === 'function' ? ss_() : SpreadsheetApp.getActiveSpreadsheet();
  var sh = ss.getSheetByName('導入チェック');
  if (sh) sh.activate();
  var lines = String(text).split('\n');
  var bad = lines.filter(function (l) { return /^❌/.test(l); }).length, warn = lines.filter(function (l) { return /^⚠️/.test(l); }).length;
  try { SpreadsheetApp.getUi().alert('システムチェック', '❌ ' + bad + '件　⚠️ ' + warn + '件　（全' + lines.length + '項目）\n\n結果は「導入チェック」タブにあります。' +
    (bad ? '\n\n' + lines.filter(function (l) { return /^❌/.test(l); }).join('\n') : ''), SpreadsheetApp.getUi().ButtonSet.OK); } catch (e) {}
  return text;
}

