// ==== TeamColors.gs
/**
 * TeamColors.gs v2（v2：applyTeamColorList で「チーム紹介」の色を一覧にそろえる）
 * クラブごとのチームカラー（運営の画面・ホームページの色に使う）
 *
 *  ・下の表が基本の色（2026-10 事務局から）。
 *  ・ホームページ管理画面の「チーム紹介」の「チームカラー」が入っていれば、そちらを優先する（クラブが自分で直せる）
 *  ・運営の画面（ダッシュボード・チームページ・公式記録入力など）には uiInclude_('UiTheme') で
 *    「チームID・クラブ名・略称 → 色」の表を渡す（window.JUFA_TC）
 */

// 基本の色の一覧（クラブ名: '#RRGGBB'）。社会人リーグ版では空から始め、ホームページ管理画面の「チーム紹介」→「チームカラー」で入れる
var JUFA_TEAM_COLORS = {};

function tcValid_(c) { return /^#[0-9a-f]{6}$/i.test(String(c || '').trim()) ? String(c).trim().toUpperCase() : ''; }

/** クラブ名 → 色（チーム紹介のチームカラーがあれば優先） */
function teamColorsByUniv_() {
  var out = {};
  Object.keys(JUFA_TEAM_COLORS).forEach(function (u) { out[u] = JUFA_TEAM_COLORS[u]; });
  try {
    var ss = typeof ss_ === 'function' ? ss_() : SpreadsheetApp.getActiveSpreadsheet();
    var name = typeof ROSTER_PROFILE_SHEET !== 'undefined' ? ROSTER_PROFILE_SHEET : 'チーム紹介';
    stRead_(ss, name).forEach(function (r) {
      var u = String(r['クラブ名'] || '').trim(), c = tcValid_(r['チームカラー']);
      if (u && c) out[u] = c;
    });
  } catch (e) {}
  return out;
}

/** 画面に渡す表：{ univ:{クラブ名:色}, team:{チームID:色}, name:{チーム名・略称:色} }。30分キャッシュ */
function teamColors_() {
  var cache = CacheService.getScriptCache(), key = 'jufa:tc:v1';
  try { var hit = cache.get(key); if (hit) return JSON.parse(hit); } catch (e) {}
  var byUniv = teamColorsByUniv_(), team = {}, name = {};
  try {
    var ss = typeof ss_ === 'function' ? ss_() : SpreadsheetApp.getActiveSpreadsheet();
    stRead_(ss, 'チームマスター').forEach(function (t) {
      var u = String(t['クラブ名'] || '').trim(), c = byUniv[u];
      if (!c) return;
      var id = String(t['チームID'] || '').trim();
      if (id) team[id] = c;
      [t['チーム名'], t['略称']].forEach(function (n) { n = String(n || '').trim(); if (n && !name[n]) name[n] = c; });
    });
  } catch (e) {}
  var out = { univ: byUniv, team: team, name: name };
  try { cache.put(key, JSON.stringify(out), 1800); } catch (e) {}
  return out;
}

/** HTML のテンプレートの中で、別のテンプレート（UiTheme.html など）を読み込む */
function uiInclude_(file) {
  try { return HtmlService.createTemplateFromFile(file).evaluate().getContent(); } catch (e) { return ''; }
}

/**
 * 1回だけ実行（2026-10 事務局確認済み）：「チーム紹介」のチームカラーを、上の一覧の色にそろえる
 *  ・書きかえるのはチームカラーの列だけ。一覧にないクラブ・行のないクラブはそのまま
 *  ・エディタで関数を選んで「実行」。終わったら、ホームページのデータを書き出し直す
 */
function applyTeamColorList() {
  var ss = typeof ss_ === 'function' ? ss_() : SpreadsheetApp.getActiveSpreadsheet();
  var name = typeof ROSTER_PROFILE_SHEET !== 'undefined' ? ROSTER_PROFILE_SHEET : 'チーム紹介';
  var sh = ss.getSheetByName(name);
  if (!sh || sh.getLastRow() < 2) { Logger.log('「' + name + '」に行がありません'); return; }
  var lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    var v = sh.getRange(1, 1, sh.getLastRow(), sh.getLastColumn()).getValues();
    var cu = v[0].indexOf('クラブ名'), cc = v[0].indexOf('チームカラー');
    if (cu < 0 || cc < 0) throw new Error('「クラブ名」「チームカラー」の列が見つかりません');
    var col = [], changed = [];
    for (var i = 1; i < v.length; i++) {
      var u = String(v[i][cu] || '').trim(), cur = String(v[i][cc] || '').trim(), want = JUFA_TEAM_COLORS[u];
      if (want && cur.toUpperCase() !== want) { changed.push(u + '：' + (cur || '（空）') + ' → ' + want); cur = want; }
      col.push([cur]);
    }
    if (changed.length) sh.getRange(2, cc + 1, col.length, 1).setValues(col);
    try { CacheService.getScriptCache().remove('jufa:tc:v1'); } catch (e) {}
    Logger.log(changed.length ? changed.length + '件をそろえました\n' + changed.join('\n') : 'すべて一覧の色と同じでした');
  } finally { lock.releaseLock(); }
}

;
// ==== TeamNotify.gs
/**
 * TeamNotify.gs v2
 * 連絡を「埋もれにくく」する（メール＋Discord）
 *
 *  1. Discord：「チーム通知先」タブの行ごとのチャンネルへ自動で投稿する（無料・件数の上限なし・スマホに通知）
 *     チャンネルの「連携サービス → ウェブフック」でURLを作り、タブのC列に貼る。
 *
 *     ■ クラブのチャンネル（そのクラブの主務・監督だけが見られる）
 *       ・チームあてのメール（日程変更・弁明のお願い・承認依頼・スタメン・決定通知など）の要点
 *       ・【明日の試合】前日の12時以降に、両チームへ（対戦・会場・キックオフ・スタメンの締切）
 *       ・【運営クラブのお知らせ】運営クラブへ、試合の1週間前と前日（当日の流れとページのリンク）
 *         ※1週間前のお知らせは、Discordがないクラブにはメールで送る
 *     ■ 事務局のチャンネル
 *       ・管理者メールあての連絡（登録申請・運営クラブが決まっていない試合など）
 *       ・日程変更のお知らせの写し、メールが送れなかったときの知らせ
 *       ・【本日の試合】試合日の朝7時以降に、その日の試合と運営クラブ・スタメンの提出状況
 *     ■ 理事会のチャンネル
 *       ・【週のまとめ】毎週月曜12時以降に、先週の結果・公式記録の確定状況と、今週の試合数
 *     ■ 規律委員会のチャンネル
 *       ・規律委員会への連絡（処分の確認依頼・問題事項・MC緊急報告など）を、その場ですぐ
 *         （LINEは今まで通り週末のまとめ。Discordは件数の上限がないので待たずに送る）
 *
 *     ・規律委員会あてのメールは、クラブのチャンネルには投稿しない（委員がクラブの監督を兼ねていても漏れない）
 *     ・クラブのチャンネルは「宛先（To）」のメールアドレスで決める（CCの人のクラブには投稿しない）
 *     ・テストモード中：システム設定「Discordテスト用Webhook」があれば、そこにだけ投稿する。
 *       空のときは、本来のチャンネルに【テスト】を付けて投稿する（各クラブをまだ招待していない間のテスト用）
 *     ・止めたいとき：システム設定「チームへのDiscord通知」を「しない」に（すべてのDiscord投稿が止まる）
 *  2. 催促（1時間ごとの更新から）
 *     ・弁明：締切の4時間前（19時台）になっても弁明がなければ、もう一度お願いする
 *     ・公式記録の承認：依頼から24時間たっても未承認なら、1回だけもう一度お願いする
 */

var TN = {
  SHEET: 'チーム通知先',
  COLS: ['宛先（クラブコード）', '名前', 'DiscordのWebhook URL', 'メモ'],
  STAFF: [
    ['事務局', '事務局', '管理者あての連絡・日程変更の写し・本日の試合・送信エラー'],
    ['理事会', '理事会', '週のまとめ（月曜）'],
    ['規律委員会', '規律委員会', '処分の確認依頼・問題事項・MC緊急報告（すぐ）']
  ],
  EVE_HOUR: 12,   // 【明日の試合】【運営クラブ（前日）】を送る時刻（前日の何時以降）
  DAY_HOUR: 7,    // 【本日の試合】（事務局）を送る時刻
  WEEK_HOUR: 12,  // 【週のまとめ】（理事会）を送る時刻（月曜の何時以降）
  DUTY_DAYS: 7    // 運営クラブのお知らせ（1回目）：試合の何日前から
};

function tnOff_() { return String(cfg_('チームへのDiscord通知') || '').trim() === 'しない'; }
function tnIsStaff_(code) { return TN.STAFF.some(function (s) { return s[0] === code; }); }

/** メニュー：「チーム通知先」タブを作る（事務局・理事会・規律委員会＋クラブの一覧。貼ってあるURLは残す） */
function setupTeamNotifySheet() {
  var ss = ss_();
  var sh = ss.getSheetByName(TN.SHEET);
  var have = {};
  if (sh && sh.getLastRow() > 1) {
    sh.getRange(2, 1, sh.getLastRow() - 1, TN.COLS.length).getValues().forEach(function (r) { if (String(r[0])) have[String(r[0])] = r; });
  }
  if (!sh) sh = ss.insertSheet(TN.SHEET);
  var rows = TN.STAFF.map(function (s) { var o = have[s[0]] || []; return [s[0], s[1], o[2] || '', o[3] || s[2]]; });
  var univs = lnUnivs_();
  Object.keys(univs).sort(function (a, b) { return univs[a] < univs[b] ? -1 : 1; }).forEach(function (c) {
    var o = have[c] || [];
    rows.push([c, univs[c], o[2] || '', o[3] || '']);
  });
  Object.keys(have).forEach(function (c) { if (!univs[c] && !tnIsStaff_(c)) rows.push(have[c]); });
  sh.clearContents();
  sh.getRange(1, 1, 1, TN.COLS.length).setValues([TN.COLS]).setFontWeight('bold').setBackground('#E8F4FB');
  if (rows.length) sh.getRange(2, 1, rows.length, TN.COLS.length).setValues(rows);
  sh.setFrozenRows(1); sh.setColumnWidth(1, 140); sh.setColumnWidth(2, 200); sh.setColumnWidth(3, 520); sh.setColumnWidth(4, 360);
  if (typeof memoForget_ === 'function') memoForget_(TN.SHEET);
  TN_HOOKS_CACHE_ = null;
  var msg = '「' + TN.SHEET + '」タブを作りました（事務局・理事会・規律委員会＋' + Object.keys(univs).length + 'クラブ）。\n' +
    '各チャンネルの「チャンネルの編集 → 連携サービス → ウェブフック → 新しいウェブフック → URLをコピー」で取ったURLを、C列に貼ってください。\n' +
    '貼ったら、メニュー「Discordへのテスト投稿」で届くか確かめられます。';
  try { SpreadsheetApp.getUi().alert('Discord通知', msg, SpreadsheetApp.getUi().ButtonSet.OK); } catch (e) {}
  return msg;
}

var TN_HOOKS_CACHE_ = null, TN_MAP_CACHE_ = null; // 1回の実行の中では読み直さない（軽くするため）

function tnHooks_() {
  if (TN_HOOKS_CACHE_) return TN_HOOKS_CACHE_;
  TN_HOOKS_CACHE_ = tnHooksRead_();
  return TN_HOOKS_CACHE_;
}

function tnHooksRead_() {
  var sh = ss_().getSheetByName(TN.SHEET);
  if (!sh || sh.getLastRow() < 2) return {};
  var out = {};
  sh.getRange(2, 1, sh.getLastRow() - 1, 3).getValues().forEach(function (r) {
    var url = String(r[2] || '').trim();
    if (/^https:\/\/([a-z]+\.)?(discord|discordapp)\.com\/api\/(v\d+\/)?webhooks\//.test(url)) out[String(r[0]).trim()] = { name: String(r[1] || ''), url: url };
  });
  return out;
}

/** メールアドレス → クラブコード（チームの責任者・監督・スタッフのメール） */
function tnMailMap_() {
  if (TN_MAP_CACHE_) return TN_MAP_CACHE_;
  var map = {};
  TN_MAP_CACHE_ = map;
  var add = function (mail, code) {
    String(mail || '').split(/[,;\s]+/).forEach(function (m) {
      m = m.trim().toLowerCase();
      if (!m || !code) return;
      (map[m] = map[m] || []).indexOf(code) < 0 && map[m].push(code);
    });
  };
  objs_(シート.チーム).forEach(function (t) { var c = rgTeamCode_(t['チームID']); add(t['責任者メール'], c); add(t['監督メール'], c); });
  try { objs_(シート.チームスタッフ).forEach(function (s) { add(s['メール'], rgTeamCode_(s['チームID'])); }); } catch (e) {}
  try { if (typeof ctRows_ === 'function') { var cr = ctRows_(); Object.keys(cr).forEach(function (c) { cr[c].mails.forEach(function (m) { add(m, c); }); }); } } catch (e) {}
  return map;
}

function tnSplitMails_(s) { return String(s || '').split(/[,;\s]+/).map(function (m) { return m.trim().toLowerCase(); }).filter(Boolean); }

/** メールの本文（HTML）→ Discord用の短い文 */
function tnText_(subject, html) {
  var links = [];
  String(html || '').replace(/<a[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi, function (m, href, label) {
    label = label.replace(/<[^>]+>/g, '').trim();
    if (/^https?:/.test(href) && links.length < 3 && !links.some(function (l) { return l.href === href; })) links.push({ href: href, label: label });
    return m;
  });
  var text = String(html || '').replace(/<(br|\/p|\/div|\/tr|\/h\d|hr|\/li)[^>]*>/gi, '\n').replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .split('\n').map(function (l) { return l.trim(); }).filter(Boolean).join('\n');
  if (text.length > 900) text = text.slice(0, 900) + '…（続きはメールで）';
  var s = '**' + String(subject || '').replace(/\*/g, '') + '**\n' + text +
    (links.length ? '\n' + links.map(function (l) { return (l.label ? l.label + '：' : '') + '<' + l.href + '>'; }).join('\n') : '');
  return s.slice(0, 1900);
}

/**
 * Discordへ投稿する（codes：クラブコード・「事務局」「理事会」「規律委員会」）
 * ・同じ内容は6時間に1回まで（メールからの投稿と、直接の投稿が重ならないように）
 * ・テストモード中は「Discordテスト用Webhook」にだけ（空なら本来のチャンネルに【テスト】を付けて）。全体テスト中は投稿せず記録だけ
 * 戻り値：投稿できた宛先コードの一覧
 */
/** テストモード中に、テスト用チャンネルへまとめて送るか（「Discordテスト用Webhook」があるとき） */
function tnTestHook_() {
  var testing = typeof testModeTo_ === 'function' && testModeTo_();
  return testing ? String(cfg_('Discordテスト用Webhook') || '').trim() : '';
}
function tnTesting_() { return !!(typeof testModeTo_ === 'function' && testModeTo_()); }

function tnPost_(codes, content) {
  codes = (codes || []).filter(function (c, i, a) { return c && a.indexOf(c) === i; });
  if (!codes.length || !content || tnOff_()) return [];
  if (typeof seasonTestOn_ === 'function' && seasonTestOn_()) return []; // シーズン全体テスト中は送らない
  if (typeof dummyData_ === 'function' && dummyData_(content)) return []; // 架空のデータの連絡は、テストの後でも送らない
  if (typeof selfTestMuted_ === 'function' && selfTestMuted_()) {
    try { selfTestRecord_('Discord', codes.join('・'), String(content).split('\n')[0].replace(/\*/g, '')); } catch (e) {}
    return codes;
  }
  var hooks = tnHooks_();
  var testHook = tnTestHook_(), testing = !!testHook, marked = tnTesting_() && !testHook;
  if (marked && !/^【テスト】/.test(content)) content = '【テスト】' + content;
  var targets = testing ? [{ code: 'TEST', url: testHook, label: codes.map(function (c) { return (hooks[c] && hooks[c].name) || c; }).join('・') }]
    : codes.filter(function (c) { return hooks[c]; }).map(function (c) { return { code: c, url: hooks[c].url }; });
  var cache = CacheService.getScriptCache(), done = [], todo = [];
  targets.forEach(function (t) {
    var body = testing ? '【テスト・本来は ' + t.label + ' のチャンネル】\n' + content : content;
    var key = 'TN:' + t.code + ':' + Utilities.base64EncodeWebSafe(Utilities.computeDigest(Utilities.DigestAlgorithm.MD5, body, Utilities.Charset.UTF_8));
    if (cache.get(key)) { done.push(t.code); return; }
    todo.push({ t: t, body: body, key: key });
  });
  // 複数のチャンネルへは同時に送る（待ち時間を短くする）
  var res = tnSendAll_(todo.map(function (x) { return { url: x.t.url, body: x.body }; }));
  todo.forEach(function (x, i) {
    var r = res[i];
    if (r.ok) { cache.put(x.key, '1', 21600); done.push(x.t.code); return; }
    try { log_('Discord投稿エラー', 'Discord通知', x.t.code, null, null, r.code + ' ' + r.text); } catch (e) {}
    // Discordが一時的に受け付けないとき（429など）は、ためておいて10分ごと・1時間ごとに送り直す
    if (r.retry) { tnQueue_(x.t.code, x.body, r.code + ' ' + r.text); cache.put(x.key, '1', 21600); done.push(x.t.code); }
  });
  return testing ? (done.length ? codes : []) : done;
}

// ─────────────────────── 見た目（v3）：種類ごとに色と目印を変えて、ひと目で見分けられるようにする ───────────────────────
//  投稿は「埋め込み（カード）」で送る。左の色の帯と、1行目の目印で種類が分かる。
//  ・赤  ⚠️ 対応してください：要対応・差し戻し・修正依頼・承認の催促・登録リマインド・MC緊急報告
//  ・橙  ✍️ お願い：承認のお願い・確認依頼・登録申請・本日のスタメン入力・運営クラブのスタメン確認
//  ・黄  🟨 処分・報告：処分検討・決定通知・始末書・問題事項報告書・審判報告
//  ・青  📅 日程の変更：日程変更
//  ・緑  ✅ 完了：公式記録 確定・スタメン提出の受付・運営クラブOK・登録完了・代理承認
//  ・青  ⚽ 試合の連絡：本日・明日の試合、運営クラブのお知らせ、週のまとめ
//  ・灰  📣 お知らせ／🔧 テスト：それ以外
var TN_KINDS = [
  { re: /診断|テスト|復元用/, icon: '🔧', label: 'テスト', color: 0x888888 },
  { re: /要対応|差し戻し|修正依頼|送れませんでした|緊急|承認リンク無効|再送|リマインド|受け付けできませんでした/, icon: '⚠️', label: '対応してください', color: 0xD84315 },
  { re: /承認のお願い|承認依頼|確認依頼|要確認|申請|本日試合|スタメンが届きました/, icon: '✍️', label: 'お願い', color: 0xEF6C00 },
  { re: /処分|決定通知|始末書|問題事項|審判報告|出場停止/, icon: '🟨', label: '処分・報告', color: 0xF2C200 },
  { re: /日程変更|延期|中止/, icon: '📅', label: '日程の変更', color: 0x1976D2 },
  { re: /確定|完了|スタメン提出|スタメン承認|代理承認/, icon: '✅', label: '完了', color: 0x2E7D32 },
  { re: /試合|運営クラブ|スタメン|週のまとめ/, icon: '⚽', label: '試合の連絡', color: 0x1976D2 },
  { re: /[\s\S]/, icon: '📣', label: 'お知らせ', color: 0x888888 }
];

/** 投稿の本文（**題名** + 本文 + リンク）→ Discordに送る形（カード） */
function tnPayload_(body) {
  var s = String(body || ''), notes = [];
  // 先頭の【テスト】【テスト・本来は ○○ のチャンネル】を取り出す
  for (var i = 0; i < 3; i++) {
    var m = s.match(/^【(テスト[^】]*)】\n?/);
    if (!m) break;
    notes.push(m[1]); s = s.slice(m[0].length);
  }
  var lines = s.split('\n'), first = String(lines.shift() || '');
  var title = first.replace(/^\*\*/, '').replace(/\*\*$/, '').trim() || 'お知らせ';
  var url = '', desc = [];
  lines.forEach(function (l) {
    var a = l.match(/^(.*?)[：:]?\s*<(https?:\/\/[^>\s]+)>\s*$/);
    if (a) {
      if (!url) url = a[2];
      desc.push('🔗 [' + (a[1].trim() || 'ひらく').replace(/[\[\]]/g, '') + '](' + a[2] + ')');
    } else desc.push(l);
  });
  // 種類は、題名の最初の【 】で決める（なければ題名全体）。「受け付けできませんでした」など題名の中身で決まるものもある
  var tag = (title.match(/【([^】]+)】/) || [])[1] || title;
  var kind = TN_KINDS.filter(function (k) { return k.re.test(tag + ' ' + (/受け付けできませんでした|スタメンが届きました/.test(title) ? title : '')); })[0];
  var test = notes.length ? '【' + notes.join('／') + '】' : '';
  var embed = {
    title: (kind.icon + ' ' + title).slice(0, 250),
    description: desc.join('\n').slice(0, 3900),
    color: kind.color,
    footer: { text: (test ? test + '　' : '') + orgName_() + ' 大会運営システム' },
    timestamp: new Date().toISOString()
  };
  if (url) embed.url = url;
  return { content: (test ? '【テスト】' : '') + kind.icon + ' **' + kind.label + '**', embeds: [embed], allowed_mentions: { parse: [] } };
}

/** 1件送る。retry：あとで送り直せばよい失敗（Discordの一時的な受付停止・通信エラー） */
function tnSend_(url, body) {
  try {
    var res = UrlFetchApp.fetch(url, { method: 'post', contentType: 'application/json', muteHttpExceptions: true,
      payload: JSON.stringify(tnPayload_(body)) });
    var code = res.getResponseCode();
    if (code < 300) return { ok: true, code: code };
    return { ok: false, code: code, text: res.getContentText().slice(0, 120), retry: code === 429 || code >= 500 };
  } catch (e) { return { ok: false, code: 0, text: String(e && e.message || e).slice(0, 120), retry: true }; }
}

/** まとめて送る（1件なら tnSend_ と同じ） */
function tnSendAll_(list) {
  if (!list.length) return [];
  if (list.length === 1) return [tnSend_(list[0].url, list[0].body)];
  try {
    var rs = UrlFetchApp.fetchAll(list.map(function (x) {
      return { url: x.url, method: 'post', contentType: 'application/json', muteHttpExceptions: true,
        payload: JSON.stringify(tnPayload_(x.body)) };
    }));
    return rs.map(function (res) {
      var code = res.getResponseCode();
      return code < 300 ? { ok: true, code: code } : { ok: false, code: code, text: res.getContentText().slice(0, 120), retry: code === 429 || code >= 500 };
    });
  } catch (e) { return list.map(function (x) { return tnSend_(x.url, x.body); }); }
}

// ─────────────────────── 送り直し（Discordが一時的に受け付けないとき） ───────────────────────

var TNQ = { SHEET: 'Discord送信待ち', COLS: ['受付日時', '宛先', '内容', '回数', '最後のエラー'], GIVEUP_H: 24 };

function tnQueue_(code, body, err) {
  try {
    var ss = ss_(), sh = ss.getSheetByName(TNQ.SHEET);
    if (!sh) {
      sh = ss.insertSheet(TNQ.SHEET);
      sh.getRange(1, 1, 1, TNQ.COLS.length).setValues([TNQ.COLS]).setFontWeight('bold');
      sh.setFrozenRows(1); sh.setColumnWidth(3, 480);
    }
    sh.appendRow([Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm:ss'), code, String(body), 0, String(err || '')]);
  } catch (e) {}
}

/** ためた投稿を送り直す（10分ごと・1時間ごとの更新から。メニューからも） */
function flushDiscordQueue_() {
  var sh = ss_().getSheetByName(TNQ.SHEET);
  if (!sh || sh.getLastRow() < 2) return '';
  var lock = LockService.getScriptLock();
  if (!lock.tryLock(5000)) return '';
  try {
    var v = sh.getRange(2, 1, sh.getLastRow() - 1, TNQ.COLS.length).getValues();
    var hooks = tnHooks_(), testHook = tnTestHook_();
    var sent = 0, dropped = 0, keep = [], stop = false;
    v.forEach(function (r) {
      if (stop) { keep.push(r); return; }
      var code = String(r[1]), url = code === 'TEST' ? testHook : (hooks[code] && hooks[code].url);
      var at = r[0] instanceof Date ? r[0].getTime() : new Date(String(r[0]).replace(' ', 'T') + '+09:00').getTime();
      var age = at ? (Date.now() - at) / 3600000 : 0;
      if (!url || age > TNQ.GIVEUP_H) { dropped++; try { log_('Discord送信あきらめ', 'Discord通知', code, null, null, String(r[2]).split('\n')[0].slice(0, 80)); } catch (e) {} return; }
      var res = tnSend_(url, r[2]);
      if (res.ok) { sent++; Utilities.sleep(400); return; }
      if (!res.retry) { dropped++; try { log_('Discord投稿エラー', 'Discord通知', code, null, null, res.code + ' ' + res.text); } catch (e) {} return; }
      r[3] = Number(r[3] || 0) + 1; r[4] = res.code + ' ' + res.text;
      keep.push(r);
      if (res.code === 429) stop = true; // まだ止められているので、続きは次回
    });
    sh.getRange(2, 1, sh.getLastRow() - 1, TNQ.COLS.length).clearContent();
    if (keep.length) sh.getRange(2, 1, keep.length, TNQ.COLS.length).setValues(keep);
    return (sent ? 'Discordの送り直し ' + sent + '件' : '') + (keep.length ? '（送信待ち ' + keep.length + '件）' : '') + (dropped ? '（あきらめ ' + dropped + '件）' : '');
  } finally { lock.releaseLock(); }
}

/** メニュー：Discordの送信待ちを今すぐ送る */
function flushDiscordQueue() {
  var msg = flushDiscordQueue_() || '送信待ちはありません';
  try { SpreadsheetApp.getUi().alert('Discordの送信待ち', msg, SpreadsheetApp.getUi().ButtonSet.OK); } catch (e) {}
  return msg;
}

/** 運営のチャンネル（事務局・理事会・規律委員会）へ（本文はふつうの文。改行はそのまま） */
function tnStaff_(code, subject, text) {
  return tnPost_([code], tnText_(subject, String(text || '').replace(/\n/g, '<br>')));
}

/** sendMail_ から呼ばれる：メールの宛先に合わせて、クラブ・運営のチャンネルにも投稿する */
function tnFromMail_(o) {
  if (!o || tnOff_()) return;
  var to = tnSplitMails_(o.to), all = to.concat(tnSplitMails_(o.cc));
  var admin = tnSplitMails_(cfg_('管理者メール')), committee = tnSplitMails_(cfg_('規律委員会メール'));
  var codes = [];
  if (all.some(function (m) { return admin.indexOf(m) >= 0; })) codes.push('事務局');
  // 規律委員会のチャンネルは、規律委員会への連絡（ReviewNotify.gs の rvSend_）からだけ投稿する。
  // メールの宛先では判定しない（規律委員会メールが管理者メールと同じとき、事務局あての連絡まで流れてしまうため）
  // クラブのチャンネル：宛先（To）に規律委員会が入っていないときだけ（委員会への連絡が、委員が監督を兼ねるクラブに漏れないように）
  // 'NONE'：本人だけに送る連絡（公式記録の承認依頼など）は、クラブのチャンネルに投稿しない
  var personal = o.discord === 'NONE';
  var staffMail = personal || to.some(function (m) { return committee.indexOf(m) >= 0; });
  if (!staffMail) {
    var map = tnMailMap_();
    to.forEach(function (m) { (map[m] || []).forEach(function (c) { codes.push(c); }); });
  }
  // 試合の連絡は、呼び出し元がクラブを指定している（メールの宛先が個人のアドレスでも、そのクラブのチャンネルへ）
  if (o.discord && !personal) tnCh_(o.discord).forEach(function (c) { codes.push(c); });
  var subj = String(o.subject || '').replace(/^(【テスト】)+/, '');
  // 決定通知は当該クラブのチャンネルだけ（事務局・理事会には投稿しない）
  if (/^【決定通知】/.test(subj)) codes = codes.filter(function (c) { return !tnIsStaff_(c); });
  if (/^【日程変更】/.test(subj)) codes.push('事務局');
  if (!codes.length) return;
  tnPost_(codes, tnText_(o.subject, o.htmlBody || String(o.body || '').replace(/\n/g, '<br>')));
}

/** クラブコードの一覧 → Discordの宛先（連盟事務局が運営クラブの試合は「事務局」） */
function tnCh_(codes) {
  return (codes || []).map(function (c) { return String(c || '') === 'JIMU' ? '事務局' : String(c || ''); })
    .filter(function (c, i, a) { return c && a.indexOf(c) === i; });
}

/** 試合の連絡：宛先のメールがあればメール（＋Discord）、なければDiscordだけ */
function tnMail_(type, to, subject, html, mid, codes) {
  if (String(to || '').trim()) return mail_(type, to, subject, html, mid, '', codes);
  tnPost_(tnCh_(codes), tnText_(subject, html));
}

/** スタメンを提出したとき：そのチームのチャンネルへ受付の知らせ */
function tnLineupReceipt_(mid, tid, name, late) {
  try {
    var info = lnMatchInfo_(findMatch_(mid));
    var opp = String(tid) === info.homeId ? info.away : info.home;
    tnPost_([rgTeamCode_(tid)], '**【スタメン提出】' + tnCompShort_(info.comp) + ' ' + info.round + '　' + lnTeamName_(tid) + ' vs ' + opp + '**\n' +
      '提出者：' + name + (late ? '（締切後の提出）' : '') + '\n運営クラブの確認（出場可能OK）を待っています。結果はこのチャンネルとメールでお知らせします。');
  } catch (e) {}
}

/** 公式記録が確定したとき：両チーム・運営クラブのチャンネルへ */
function tnRecordConfirmed_(m, h, a, rec, pdf) {
  var info = lnMatchInfo_(m);
  var pk = String(rec['PK戦ホーム'] || '') !== '' && String(rec['PK戦アウェイ'] || '') !== '' ? '（PK ' + rec['PK戦ホーム'] + '-' + rec['PK戦アウェイ'] + '）' : '';
  var text = '**【公式記録 確定】' + tnCompShort_(info.comp) + ' ' + info.round + '　' + info.home + ' ' + h + '-' + a + ' ' + info.away + pk + '**\n' +
    '3者の承認がそろい、公式記録（版' + rec['版'] + '）が確定しました。' + (pdf ? '\n公式記録（PDF）：<' + pdf + '>' : '');
  tnPost_(tnCh_([rgTeamCode_(info.homeId), rgTeamCode_(info.awayId), lnDutyCode_(m)]), text);
}

/** メニュー：Discordへのテスト投稿（URLを貼った全部のチャンネルへ） */
function testTeamDiscord() {
  var hooks = tnHooks_(), ok = [], ng = [];
  var what = {};
  TN.STAFF.forEach(function (s) { what[s[0]] = s[2]; });
  Object.keys(hooks).forEach(function (c) {
    var text = tnIsStaff_(c)
      ? '**【テスト】大会運営システムからの通知**\nこのチャンネルに、' + hooks[c].name + 'あての連絡（' + what[c] + '）が届きます。'
      : '**【テスト】大会運営システムからの通知**\nこのチャンネルに、' + hooks[c].name + 'あての連絡（明日の試合・運営クラブのお知らせ・日程変更・承認依頼・弁明のお願いなど）が届きます。';
    try {
      var r = UrlFetchApp.fetch(hooks[c].url, { method: 'post', contentType: 'application/json', muteHttpExceptions: true,
        payload: JSON.stringify({ content: text, allowed_mentions: { parse: [] } }) });
      (r.getResponseCode() < 300 ? ok : ng).push(hooks[c].name);
    } catch (e) { ng.push(hooks[c].name); }
  });
  var miss = TN.STAFF.filter(function (s) { return !hooks[s[0]]; }).map(function (s) { return s[1]; });
  var msg = Object.keys(hooks).length
    ? '届いた：' + (ok.join('、') || 'なし') + (ng.length ? '\n届かなかった（URLを確認）：' + ng.join('、') : '') +
      (miss.length ? '\nURLがまだない運営のチャンネル：' + miss.join('、') : '')
    : '「' + TN.SHEET + '」タブにURLがありません';
  try { SpreadsheetApp.getUi().alert('Discordへのテスト投稿', msg, SpreadsheetApp.getUi().ButtonSet.OK); } catch (e) {}
  return msg;
}

/** メニュー：Discordの診断（届かないときに、どこで止まっているかを調べる） */
function diagnoseDiscord() {
  var out = [];
  var hooks = tnHooks_();
  var tm = tnTesting_(), th = String(cfg_('Discordテスト用Webhook') || '').trim();
  out.push('■ 設定');
  out.push('・Discord通知：' + (tnOff_() ? '⚠ 止めています（システム設定「チームへのDiscord通知」が「しない」）' : 'オン'));
  out.push('・テストモード：' + (tm ? 'オン' : 'オフ'));
  out.push('・Discordテスト用Webhook：' + (th ? (tm ? '⚠ 入っています → テスト中の投稿は、すべてこのURLのチャンネルだけに届きます（各クラブには届きません）' : '入っています（テストモードがオフなので使いません）') : '空（テスト中も各チャンネルに【テスト】付きで届きます）'));
  if (typeof selfTestMuted_ === 'function' && selfTestMuted_()) out.push('・⚠ 全体テスト中：Discordには送らず、記録だけになっています');
  var sh = ss_().getSheetByName(TN.SHEET);
  out.push('・「' + TN.SHEET + '」タブ：' + (sh ? 'あり' : '⚠ ありません（メニュー「チーム通知先（Discord）のタブを作る」）'));
  out.push('・URLが入っている行：' + Object.keys(hooks).length + '件');
  var univs = typeof lnUnivs_ === 'function' ? lnUnivs_() : {};
  var miss = Object.keys(univs).filter(function (c) { return !hooks[c]; });
  if (miss.length) out.push('・URLがないクラブ：' + miss.map(function (c) { return univs[c] + '（' + c + '）'; }).join('、'));
  var odd = Object.keys(hooks).filter(function (c) { return !univs[c] && !tnIsStaff_(c); });
  if (odd.length) out.push('・⚠ 今のクラブの一覧にない行：' + odd.join('、') + '（年度が変わった可能性。メニュー「チーム通知先（Discord）のタブを作る」で作り直し、URLを貼り直してください）');

  out.push('', '■ 実際に送ってみる');
  var pick = TN.STAFF.map(function (s) { return s[0]; }).filter(function (c) { return hooks[c]; }).slice(0, 1)
    .concat(Object.keys(univs).filter(function (c) { return hooks[c]; }).slice(0, 1));
  if (!pick.length) out.push('・URLが1つもないため、送れません');
  pick.forEach(function (c) {
    try {
      var r = UrlFetchApp.fetch(hooks[c].url, { method: 'post', contentType: 'application/json', muteHttpExceptions: true,
        payload: JSON.stringify({ content: '**【診断】大会運営システムからの送信テスト**（' + hooks[c].name + '）', allowed_mentions: { parse: [] } }) });
      var code = r.getResponseCode();
      out.push('・' + hooks[c].name + '：' + (code < 300 ? '届きました（' + code + '）' :
        '⚠ 届きません（' + code + '）' + (code === 404 ? '：WebhookのURLが消されたか、間違っています' : code === 429 ? '：Discordが一時的に受け付けていません。届かなかった通知はためておき、10分〜1時間ごとに自動で送り直します' : '') + '\n　' + r.getContentText().slice(0, 160)));
    } catch (e) { out.push('・' + hooks[c].name + '：⚠ エラー ' + e.message); }
  });

  var qs = ss_().getSheetByName(TNQ.SHEET);
  out.push('・送信待ち（あとで送り直す分）：' + (qs ? Math.max(0, qs.getLastRow() - 1) : 0) + '件');
  out.push('', '■ 最近の投稿エラー（操作履歴）');
  try {
    var errs = objs_(シート.操作).filter(function (x) { return String(x['処理']) === 'Discord投稿エラー'; }).slice(-5);
    out.push(errs.length ? errs.map(function (x) { return '・' + String(x['日時']).slice(0, 16) + '　' + x['対象ID'] + '　' + x['備考']; }).join('\n') : '・なし');
  } catch (e) { out.push('・読めません'); }
  out.push('', '※ 画面（チームページ・運営クラブ・承認など）からの通知は、「デプロイを管理」→ 鉛筆 →「新バージョン」でデプロイした版で動きます。ファイルを貼り替えたあと、デプロイし直したか確かめてください。');
  var msg = out.join('\n');
  try { SpreadsheetApp.getUi().alert('Discordの診断', msg, SpreadsheetApp.getUi().ButtonSet.OK); } catch (e) {}
  return msg;
}

// ─────────────────────── 試合日・運営クラブ・運営のお知らせ（1時間ごと） ───────────────────────

function tnYmd_(t) { return Utilities.formatDate(t || new Date(), 'Asia/Tokyo', 'yyyy-MM-dd'); }
function tnAddDays_(ymd, n) { return tnYmd_(new Date(new Date(ymd + 'T00:00:00+09:00').getTime() + n * 86400000)); }
function tnMd_(ymd) {
  if (!ymd) return '';
  var d = new Date(ymd + 'T00:00:00+09:00');
  return Utilities.formatDate(d, 'Asia/Tokyo', 'M/d') + '（' + '日月火水木金土'.charAt(Number(Utilities.formatDate(d, 'Asia/Tokyo', 'u')) % 7) + '）';
}
function tnCompShort_(name) { return String(name || '').replace(/^\d{4}年度\s*/, '').replace(/^第\d+回\s*/, ''); }

/** この仕組みで扱う試合（自分の担当大会・中止／延期／開催済を除く） */
function tnMatches_() {
  return objs_(シート.試合).filter(function (m) {
    if (!String(m['試合ID'] || '')) return false;
    if (typeof inMyComps_ === 'function' && !inMyComps_(m['試合ID'])) return false;
    if (/TEST|-ZT-|-DM-/i.test(String(m['試合ID']))) return false; // -ZT-：全体テスト、-DM-：シーズン全体テストの試合は Discord の試合の連絡に出さない
    return !/中止|延期|中断|開催済|記録対象外/.test(String(m['試合状態'] || ''));
  });
}

function tnMatchNotices_() {
  if (tnOff_()) return '';
  if (typeof runsMatches_ === 'function' && !runsMatches_()) return '';
  var hooks = tnHooks_();
  if (!Object.keys(hooks).length && !String(cfg_('Discordテスト用Webhook') || '').trim()) return '';
  var props = PropertiesService.getScriptProperties();
  var now = new Date(), today = tnYmd_(now), tomorrow = tnAddDays_(today, 1), dutyFrom = tnAddDays_(today, TN.DUTY_DAYS);
  var hour = Number(Utilities.formatDate(now, 'Asia/Tokyo', 'H'));
  var sent = { eve: 0, duty: 0 };
  tnMatches_().forEach(function (m) {
    var d = matchDateYmd_(m);
    if (!d || d < today || d > dutyFrom) return;
    var info = lnMatchInfo_(m), mid = info.id;
    var title = tnCompShort_(info.comp) + ' ' + info.round + '　' + info.home + ' vs ' + info.away;
    var when = tnMd_(d) + ' ' + (info.kickoff ? info.kickoff + ' キックオフ' : 'キックオフ未定');
    var duty = lnDutyCode_(m);
    // 運営クラブ（1回目）：試合の1週間前から前々日まで（日程を入れたのが遅いときは、入れた後すぐ）
    if (duty && d > tomorrow && d <= dutyFrom && !props.getProperty('TNDW:' + mid + ':' + d)) {
      if (tnDutyNotice_(m, info, duty, title, when, false)) { props.setProperty('TNDW:' + mid + ':' + d, '1'); sent.duty++; }
    }
    if (d !== tomorrow || hour < TN.EVE_HOUR) return;
    // 運営クラブ（前日）
    if (duty && !props.getProperty('TNDE:' + mid + ':' + d)) {
      if (tnDutyNotice_(m, info, duty, title, when, true)) { props.setProperty('TNDE:' + mid + ':' + d, '1'); sent.duty++; }
    }
    // 両チームへ【明日の試合】
    [info.homeId, info.awayId].forEach(function (tid) {
      if (!tid) return;
      var key = 'TNEV:' + mid + ':' + tid + ':' + d;
      if (props.getProperty(key)) return;
      var code = rgTeamCode_(tid);
      if (!hooks[code] && !tnTestHook_()) { props.setProperty(key, '-'); return; }
      var url = lnUrl_(code);
      var opp = tid === info.homeId ? info.away : info.home;
      var text = '**【明日の試合】' + title + '**\n' +
        '日時：' + when + '\n会場：' + (info.venue || '未定') + '\n対戦：' + lnTeamName_(tid) + ' vs ' + opp + '（' + (tid === info.homeId ? 'HOME' : 'AWAY') + '）\n' +
        (info.duty ? '運営クラブ：' + info.duty + '\n' : '') +
        'スタメンの提出：キックオフ90分前（' + (info.deadline || '—') + '）まで' +
        (url ? '\nチームページ（スタメンの提出）：<' + url + '>' : '');
      if (tnPost_([code], text).length) { props.setProperty(key, '1'); sent.eve++; }
    });
  });
  var out = [];
  if (sent.eve) out.push('明日の試合 ' + sent.eve + '件');
  if (sent.duty) out.push('運営クラブのお知らせ ' + sent.duty + '件');
  try { var a = tnTodayForOffice_(today, hour); if (a) out.push(a); } catch (e) { out.push('本日の試合：' + e.message); }
  try { var b = tnWeeklyForBoard_(now, today, hour); if (b) out.push(b); } catch (e) { out.push('週のまとめ：' + e.message); }
  return out.join('／');
}

/** 運営クラブのお知らせ（eve：前日の分）。1週間前の分は、Discordがないクラブにはメールで送る */
function tnDutyNotice_(m, info, duty, title, when, eve) {
  var url = lnUrl_(duty);
  var head = eve ? '【運営クラブ・明日です】' : '【運営クラブのお知らせ】';
  var lines = [
    '日時：' + when, '会場：' + (info.venue || '未定'),
    '貴クラブがこの試合の運営クラブです。当日の流れ：',
    '1. 両チームのスタメンが届いたら、運営クラブのページで確認して「出場可能（OK）」を押す',
    '2. マッチコーディネーションミーティングで審判員のメールアドレスを聞き、運営クラブのページに入力（キックオフ90分前まで）',
    '3. 第4の審判に「試合中の記録」のページを開いてもらう（審判員にメールで届きます）',
    '4. 試合後、公式記録を入力して提出'
  ];
  var hooks = tnHooks_();
  var testing = !!tnTestHook_();
  var ch = duty === 'JIMU' ? '事務局' : duty; // 運営クラブが連盟事務局の試合は、事務局のチャンネルへ
  if (duty === 'JIMU') lines[2] = '連盟事務局がこの試合の運営クラブです。当日の流れ：';
  if (hooks[ch] || testing) {
    var text = '**' + head + title + '**\n' + lines.join('\n') + (url ? '\n運営クラブのページ：<' + url + '>' : '');
    return tnPost_([ch], text).length > 0;
  }
  if (eve) return true; // 前日の分はDiscordだけ（メールの上限を節約）
  var to = lnUnivMails_(duty);
  if (!to.length) return true;
  mail_('運営クラブのお知らせ', to.join(','), head + title + '（' + when + '）',
    '<p>運営クラブご担当者様</p>' + lines.map(function (l) { return '<p style="margin:4px 0">' + lnEsc_(l) + '</p>'; }).join('') +
    (url ? '<p><a href="' + url + '">運営クラブのページを開く</a></p>' : ''), info.id, '');
  return true;
}

/** 事務局へ【本日の試合】（試合日の朝） */
function tnTodayForOffice_(today, hour) {
  if (hour < TN.DAY_HOUR) return '';
  var props = PropertiesService.getScriptProperties(), key = 'TNDAY:' + today;
  if (props.getProperty(key)) return '';
  var list = tnMatches_().filter(function (m) { return matchDateYmd_(m) === today; });
  if (!list.length) { props.setProperty(key, '-'); return ''; }
  var rows = typeof lnRows_ === 'function' ? lnRows_() : [];
  var st = function (mid, tid) {
    var r = rows.length ? lnLatest_(rows, mid, tid) : null;
    if (!r) return '未提出';
    return String(r['状態']) === '運営クラブOK' ? 'OK' : '提出済';
  };
  list.sort(function (a, b) { return String(kickoffText_(a['キックオフ'])) < String(kickoffText_(b['キックオフ'])) ? -1 : 1; });
  var lines = list.map(function (m) {
    var i = lnMatchInfo_(m);
    return '・' + (i.kickoff || '--:--') + '　' + tnCompShort_(i.comp) + ' ' + i.round + '　' + i.home + ' vs ' + i.away +
      '\n　会場：' + (i.venue || '未定') + '／運営クラブ：' + (i.duty || '未定') + '／スタメン：HOME ' + st(i.id, i.homeId) + '・AWAY ' + st(i.id, i.awayId);
  });
  var text = '**【本日の試合】' + tnMd_(today) + '　' + list.length + '試合**\n' + lines.join('\n');
  var chunks = tnChunks_(text);
  var ok = chunks.every(function (c) { return tnPost_(['事務局'], c).length > 0; });
  if (ok) props.setProperty(key, '1');
  return ok ? '本日の試合（事務局）' : '';
}

/** 理事会へ【週のまとめ】（月曜の昼） */
function tnWeeklyForBoard_(now, today, hour) {
  var dow = Number(Utilities.formatDate(now, 'Asia/Tokyo', 'u')); // 月=1
  if (dow !== 1 || hour < TN.WEEK_HOUR) return '';
  var props = PropertiesService.getScriptProperties(), key = 'TNWK:' + today;
  if (props.getProperty(key)) return '';
  var from = tnAddDays_(today, -7), to = tnAddDays_(today, -1), next = tnAddDays_(today, 6);
  var recs = {};
  objs_(シート.公式記録).forEach(function (r) { recs[String(r['試合ID'])] = String(r['記録状態'] || ''); });
  var mine = objs_(シート.試合).filter(function (m) {
    return String(m['試合ID'] || '') && !/TEST/i.test(String(m['試合ID'])) && (typeof inMyComps_ !== 'function' || inMyComps_(m['試合ID']));
  });
  var last = mine.filter(function (m) { var d = matchDateYmd_(m); return d && d >= from && d <= to; });
  var coming = mine.filter(function (m) { var d = matchDateYmd_(m); return d && d >= today && d <= next && !/中止|延期/.test(String(m['試合状態'] || '')); });
  if (!last.length && !coming.length) { props.setProperty(key, '-'); return ''; }
  var byComp = {}, unconfirmed = 0;
  last.forEach(function (m) {
    var i = lnMatchInfo_(m), c = tnCompShort_(i.comp);
    var s = String(m['試合状態'] || ''), rec = recs[i.id] || '';
    var has = function (v) { return v !== undefined && v !== null && String(v) !== ''; };
    var score = has(m['ホーム得点']) && has(m['アウェイ得点']) ? m['ホーム得点'] + '-' + m['アウェイ得点'] : '';
    var state = /中止|延期/.test(s) ? s : rec === '確定' ? '確定' : rec ? '記録：' + rec : '記録なし';
    if (!/中止|延期|確定/.test(state)) unconfirmed++;
    (byComp[c] = byComp[c] || []).push('・' + i.round + '　' + i.home + ' ' + (score || 'vs') + ' ' + i.away + '（' + state + '）');
  });
  var comingBy = {};
  coming.forEach(function (m) { var c = tnCompShort_(lnMatchInfo_(m).comp); comingBy[c] = (comingBy[c] || 0) + 1; });
  var text = '**【週のまとめ】' + tnMd_(from) + '〜' + tnMd_(to) + '**\n' +
    (last.length ? '先週の試合：' + last.length + '試合（公式記録が未確定：' + unconfirmed + '試合）\n' : '先週の試合：なし\n') +
    Object.keys(byComp).map(function (c) { return '▼' + c + '\n' + byComp[c].join('\n'); }).join('\n') +
    '\n今週の試合（' + tnMd_(today) + '〜' + tnMd_(next) + '）：' +
    (coming.length ? Object.keys(comingBy).map(function (c) { return c + ' ' + comingBy[c] + '試合'; }).join('、') : 'なし');
  var ok = tnChunks_(text).every(function (c) { return tnPost_(['理事会'], c).length > 0; });
  if (ok) props.setProperty(key, '1');
  return ok ? '週のまとめ（理事会）' : '';
}

/** Discordの1投稿（2000字）に収まるように分ける */
function tnChunks_(text) {
  var out = [], cur = '';
  String(text).split('\n').forEach(function (l) {
    if ((cur + '\n' + l).length > 1900) { out.push(cur); cur = l; } else cur = cur ? cur + '\n' + l : l;
  });
  if (cur) out.push(cur);
  return out;
}

// ─────────────────────── 催促（1時間ごと） ───────────────────────

function tnReminders_() {
  if (typeof withReadMemo_ === 'function') return withReadMemo_(tnRemindersRun_);
  return tnRemindersRun_();
}
function tnRemindersRun_() {
  var out = [];
  try { var q = flushDiscordQueue_(); if (q) out.push(q); } catch (e) { out.push('Discordの送り直し：' + e.message); }
  try { var a = tnExplainReminders_(); if (a) out.push(a); } catch (e) { out.push('弁明の催促：' + e.message); }
  try { var b = tnApprovalReminders_(); if (b) out.push(b); } catch (e) { out.push('承認の催促：' + e.message); }
  try { var c = tnMatchNotices_(); if (c) out.push(c); } catch (e) { out.push('試合日・運営クラブのお知らせ：' + e.message); }
  return out.join('／');
}

/** 弁明：締切の4時間前を過ぎても弁明がなければ、もう一度お願いする（1回だけ） */
function tnExplainReminders_() {
  if (typeof icRows_ !== 'function' || !ss_().getSheetByName('問題事項報告')) return '';
  var props = PropertiesService.getScriptProperties(), now = Date.now(), n = 0;
  icRows_().forEach(function (r) {
    if (String(r['状態']) !== '弁明待ち') return;
    var dl = icStr_(r['弁明期限'], 'yyyy-MM-dd HH:mm');
    var t = Date.parse(dl.replace(' ', 'T') + ':00+09:00');
    if (!t || now < t - 4 * 3600000 || now > t) return;
    var key = 'ICREM:' + r['報告ID'];
    if (props.getProperty(key)) return;
    var code = icPartyCode_(r['当該クラブ']), mails = code ? lnUnivMails_(code) : [];
    if (!code) return;
    var url = lnUrl_(code);
    tnMail_('問題事項の弁明（催促）', mails.join(','), '【要対応・本日' + dl.slice(11) + '締切】問題事項報告書の弁明がまだ出ていません（' + r['当該クラブ'] + '）',
      '<p>' + lnEsc_(r['当該クラブ']) + ' ご担当者様</p><p>問題事項報告書への弁明が、まだ提出されていません。<b>' + lnEsc_(dl) + '</b> を過ぎると、報告書のみで規律委員会が検討します。</p>' +
      '<p style="white-space:pre-wrap;border-left:3px solid #D84315;padding-left:8px">' + lnEsc_(r['問題事項の詳細']) + '</p>' +
      (url ? '<p><a href="' + url + '">チームページで弁明を書く</a></p>' : ''), String(r['試合ID']), [code]);
    props.setProperty(key, '1');
    n++;
  });
  return n ? '弁明の催促 ' + n + '件' : '';
}

/** 公式記録の承認：依頼から24時間たっても未承認なら、1回だけもう一度お願いする */
function tnApprovalReminders_() {
  var props = PropertiesService.getScriptProperties(), now = Date.now(), n = 0;
  var recs = {};
  objs_(シート.公式記録).forEach(function (r) { recs[String(r['公式記録ID'])] = r; });
  var base = typeof adApproveBase_ === 'function' ? adApproveBase_() : webAppBaseUrl_();
  objs_(シート.承認).forEach(function (a) {
    if (String(a['承認状態']) !== '未承認' || /TEST/i.test(String(a['試合ID']))) return;
    var rec = recs[String(a['対象公式記録ID'])];
    if (!rec || String(rec['記録状態']) !== '承認待ち') return;
    var exp = a['トークン期限'] instanceof Date ? a['トークン期限'].getTime() : Date.parse(String(a['トークン期限'] || '').replace(' ', 'T') + '+09:00');
    if (!exp) return;
    var created = exp - 7 * 86400000;
    if (now - created < 24 * 3600000) return;
    var key = 'APREM:' + a['承認ID'];
    if (props.getProperty(key)) return;
    var to = String(a['承認者メール'] || '').trim(), mid = String(a['試合ID'] || '');
    if (!to) return;
    var m = {};
    try { m = findMatch_(mid); } catch (e) {}
    var url = base + '?page=approve&token=' + encodeURIComponent(a['承認トークン']);
    mail_('公式記録承認依頼（催促）', to, '【要対応・再送】公式記録の承認がまだです　' + (m['節／ラウンド'] || '') + ' ' + mid,
      '<p>' + htmlEsc_(a['承認者名'] || '') + ' 様</p><p>公式記録の承認が、まだ済んでいません。3者の承認がそろうと公式記録が確定します。内容を確認し、承認または修正依頼をお願いします。</p>' +
      '<p><a href="' + url + '">承認画面を開く</a></p>', mid, '', 'NONE');
    props.setProperty(key, '1');
    n++;
  });
  return n ? '承認の催促 ' + n + '件' : '';
}

;
// ==== TestRound.gs
/**
 * TestRound.gs v1
 * 新しい大会運営システム（2027年〜）｜使用感を確かめるための「テスト大会（1節分）」
 *
 *  ① 全体システム：メニュー「テスト」→「テスト大会（1節）を作る」
 *     ・大会「【テスト】1部リーグ」（大会ID 2027-T-L1）を作る。ホームページにも出す（日程・結果・順位表・得点者を確かめるため）
 *     ・チームマスターの1部のクラブ（実際のクラブ・登録選手）を2つずつ組み合わせて、第1節の試合を作る
 *     ・テスト用の審判員（メールはテスト担当）を審判員マスターに入れる
 *     ・「連携リーグ」タブの1部の行に、テスト大会の大会IDを足す
 *     ・テストモードを開始する（すべてのメールはテスト担当だけに届く。規律委員会のLINEは【テスト】付き）
 *  ② 1部のリーグシステム：メニュー「テスト」→「テスト大会を受け持つ（全体で作ったあとに）」
 *     ・担当大会IDにテスト大会を足し、テストモードを開始し、全体システムから日程を取り込む
 *     ・「テスト大会のリンク」タブに、試合ごとのチームページ・運営クラブ・公式記録・審判報告書・MC報告書のリンクを出す
 *  ③ 終わったら：リーグ → 全体 の順に、メニュー「テスト大会のデータを削除」
 *     ・テスト大会の試合・スタメン・公式記録・警告退場・処分・決定通知・問題事項・MC報告書・PDFを消す
 *     ・担当大会ID／連携リーグからテスト大会を外す（テストモードはそのまま。終えるときはメニューから）
 */

var TR = {
  comp: '2027-T-L1',
  name: '【テスト】1部リーグ',
  round: '第1節',
  refNote: 'テスト大会',
  refs: [{ id: 'REF-TR1', name: 'テスト 主審', grade: '1級', assoc: '北海道' }, { id: 'REF-TR2', name: 'テスト 副審', grade: '2級', assoc: '北海道' }],
  kickoffs: ['11:00', '13:30'],
  linkSheet: 'テスト大会のリンク'
};

function trTo_() { return (typeof testModeAddresses_ === 'function' && testModeAddresses_()[0]) || ''; }
function trHit_(v) { var s = String(v || ''); return s === TR.comp || s.indexOf(TR.comp + '-') === 0; }
function trAlert_(title, msg) {
  try { SpreadsheetApp.getUi().alert(title, msg, SpreadsheetApp.getUi().ButtonSet.OK); } catch (e) {}
  Logger.log(msg);
  return msg;
}
function trTestModeOn_() {
  PropertiesService.getScriptProperties().setProperty('TEST_MODE_TO', (typeof testModeAddresses_ === 'function' ? testModeAddresses_() : [trTo_()]).join(','));
}
function trFresh_() { if (typeof READ_MEMO_ !== 'undefined') READ_MEMO_ = null; }

// ─────────────────────── ① 全体：テスト大会を作る ───────────────────────

function createTestRound() {
  if (!isCentral_()) return trAlert_('テスト大会', 'これは全体システムで実行してください。リーグシステムでは「テスト大会を受け持つ」を使います。');
  var tomorrow = Utilities.formatDate(new Date(Date.now() + 86400000), 'Asia/Tokyo', 'yyyy-MM-dd');
  var date = tomorrow, round = trNextRound_();
  try {
    var ui = SpreadsheetApp.getUi();
    var r0 = ui.prompt('テスト大会の節を作る', '何節を作りますか（数字）。空のままOKで 第' + round + '節', ui.ButtonSet.OK_CANCEL);
    if (r0.getSelectedButton() !== ui.Button.OK) return 'キャンセルしました';
    var rn = String(r0.getResponseText() || '').replace(/[^0-9０-９]/g, '').replace(/[０-９]/g, function (c) { return String.fromCharCode(c.charCodeAt(0) - 0xFEE0); });
    if (rn) round = Number(rn);
    var r = ui.prompt('テスト大会 第' + round + '節', '試合日（yyyy-MM-dd）。空のままOKで ' + tomorrow + '\n\nテストモードも開始します（すべてのメールは ' + trTo_() + ' だけに届きます）。', ui.ButtonSet.OK_CANCEL);
    if (r.getSelectedButton() !== ui.Button.OK) return 'キャンセルしました';
    date = String(r.getResponseText() || '').trim() || tomorrow;
  } catch (e) {}
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return trAlert_('テスト大会', '日付は 2026-10-03 の形で入力してください');
  return trAlert_('テスト大会を作りました', createTestRound_(date, round));
}

/** 次に作る節（テスト大会にある節の最大＋1） */
function trNextRound_() {
  var mx = 0;
  objs_(シート.試合).forEach(function (m) {
    if (!trHit_(m['試合ID'])) return;
    var x = String(m['節／ラウンド'] || '').match(/(\d+)/);
    if (x) mx = Math.max(mx, Number(x[1]));
  });
  return mx + 1;
}

/** 総当たりの組み合わせ（円の方法）：round 節目の対戦。奇数のときは1チームお休み */
function trPairs_(teams, round) {
  var list = teams.slice();
  if (list.length % 2) list.push(null);
  var n = list.length, fixed = list[0], rest = list.slice(1);
  var k = ((round - 1) % (n - 1) + (n - 1)) % (n - 1);
  rest = rest.slice(rest.length - k).concat(rest.slice(0, rest.length - k));
  var a = [fixed].concat(rest), out = [];
  for (var i = 0; i < n / 2; i++) {
    var x = a[i], y = a[n - 1 - i];
    if (!x || !y) continue;
    out.push((round + i) % 2 ? [x, y] : [y, x]); // ホームとアウェイを節ごとに入れ替える
  }
  return out;
}

function createTestRound_(date, round) {
  round = Number(round) || 1;
  var ss = ss_();
  // 1部のチーム（いちばん新しい年度の「YYYY-L1」）
  var teams = objs_(シート.チーム).filter(function (t) { return /^\d{4}-L1$/.test(String(t['大会ID'])) && String(t['チームID']); });
  var year = teams.map(function (t) { return String(t['大会ID']).slice(0, 4); }).sort().pop();
  teams = teams.filter(function (t) { return String(t['大会ID']).slice(0, 4) === year; });
  if (teams.length < 2) throw new Error('チームマスターに1部（大会IDが「年-L1」）のチームが2つ以上ありません');
  // チームページを開けるクラブか（システム設定「年度」とチームの年度が合っているか）
  var univs = lnUnivs_();
  var missing = teams.filter(function (t) { return !univs[rgTeamCode_(t['チームID'])]; }).map(function (t) { return t['クラブ名']; });

  var venues = (typeof refOptionValues_ === 'function' ? refOptionValues_('会場名') : []).map(function (v) { return String(v.value || v.label || v); }).filter(Boolean);
  if (!venues.length) venues = ['テスト会場'];

  ensureHeader_('大会マスター', ['正式名称', '公開', '登録締切日']);
  stUpsert_(ss, '大会マスター', '大会ID', [{ '大会ID': TR.comp, '年度': '2027', '大会名': TR.name, '正式名称': TR.name,
    '大会形式': 'リーグ', '延長戦': 'なし', 'PK戦': 'なし', '累積警告基準': '', '一発退場処理': '次の1試合自動停止＋規律委員会審査', '公開': '○', '主催地域協会': '北海道' }]);

  var short = function (t) { return String(t['略称'] || t['クラブ名'] || t['チーム名']); };
  var rows = [], lines = [];
  var pairs = trPairs_(teams, round), playing = {};
  pairs.forEach(function (pr) { playing[String(pr[0]['チームID'])] = playing[String(pr[1]['チームID'])] = true; });
  var resting = teams.filter(function (t) { return !playing[String(t['チームID'])]; });
  pairs.forEach(function (pr, k) {
    var no = String(round * 100 + 1 + k);
    var h = pr[0], a = pr[1];
    rows.push({ '試合ID': TR.comp + '-' + no, '大会ID': TR.comp, '節／ラウンド': '第' + round + '節', '開催予定日': date, 'ホームチームID': String(h['チームID']), 'アウェイチームID': String(a['チームID']),
      '種別': 'リーグ', 'マッチNo': no, '会場': venues[Math.floor(k / 2) % venues.length], 'キックオフ': TR.kickoffs[k % 2], '試合状態': '予定', '運営クラブ': short(h),
      '主審': TR.refs[0].name, '副審': TR.refs[1].name, '第4審': '' });
    lines.push('No.' + no + '　' + TR.kickoffs[k % 2] + '　' + short(h) + ' vs ' + short(a) + '（' + venues[Math.floor(k / 2) % venues.length] + '・運営クラブ ' + short(h) + '）');
  });
  stUpsert_(ss, '試合マスター', '試合ID', rows);

  // テスト用の審判員（メールはテスト担当）
  mdSheet_(MD.REF_SHEET, MD_REF_COLS);
  trFresh_();
  var have = {};
  objs_(MD.REF_SHEET).forEach(function (x) { have[String(x['審判員ID'])] = true; });
  TR.refs.forEach(function (r) {
    if (!have[r.id]) append_(MD.REF_SHEET, { '審判員ID': r.id, '氏名': r.name, '審判級': r.grade, '所属協会': r.assoc, 'メール': trTo_(), '電話番号': "'000-0000-0000", '有効': '有効', '登録日時': mdNow_(), '備考': TR.refNote });
  });

  // 連携リーグ：1部の行にテスト大会を足す
  var single = typeof isSingle_ === 'function' && isSingle_();
  var linked = single ? '（一体のシステムなので不要）' : trLinkCentral_(true);
  trTestModeOn_();
  memoForget_('大会マスター'); memoForget_('試合マスター');
  try { if (typeof bumpPublicVersion_ === 'function') bumpPublicVersion_(); } catch (e) {} // ホームページをすぐ作り直す
  try { if (typeof scheduleRecalc_ === 'function') scheduleRecalc_(); } catch (e) {} // ホームページ・順位表を更新
  var home = typeof publicSiteUrl_ === 'function' ? publicSiteUrl_() : (linkBase_() ? linkBase_() + '?page=public' : '');

  return '大会「' + TR.name + '」（' + TR.comp + '）の第' + round + '節を ' + date + ' に作りました（' + rows.length + '試合）。\n' + lines.join('\n') +
    (resting.length ? '\n※ ' + resting.map(short).join('・') + ' は今節お休みです' : '') +
    '\n\n・審判員：' + TR.refs.map(function (r) { return r.name; }).join('・') + '（メールは ' + trTo_() + '）' +
    '\n・連携リーグ：' + linked +
    '\n・ホームページ：' + (home || '（システム設定の「WebアプリURL」が空です）') + '（大会「' + TR.name + '」を選ぶ）' +
    '\n・テストモード：開始しました（すべてのメールは ' + trTo_() + ' だけ。規律委員会のLINEは【テスト】付き）' +
    (missing.length ? '\n\n⚠ チームページを開けないクラブがあります：' + missing.join('、') + '\n　システム設定の「年度」を ' + year + ' にしてください（全体と1部の両方）' : '') +
    (single ? trSingleLinks_() : '\n\n次に、1部のリーグシステムで メニュー「テスト」→「テスト大会を受け持つ（全体で作ったあとに）」を実行してください。');
}

/** 全体の「連携リーグ」で、1部（2027-L1）の行の大会IDにテスト大会を足す／外す */
function trLinkCentral_(add) {
  var sh = ss_().getSheetByName(SYNC_LEAGUE_SHEET);
  if (!sh || sh.getLastRow() < 2) return '「連携リーグ」タブがありません';
  var v = sh.getDataRange().getValues(), h = v[0].map(String), ci = h.indexOf('大会ID'), ni = h.indexOf('名前');
  var done = '1部の行が見つかりません';
  for (var r = 1; r < v.length; r++) {
    var ids = String(v[r][ci] || '').split(/[,、\s]+/).filter(Boolean);
    var is1 = ids.indexOf('2027-L1') >= 0 || String(v[r][ni]) === '1部';
    var cleaned = ids.filter(function (x) { return x !== TR.comp; });
    if (add && is1) cleaned.push(TR.comp);
    if (cleaned.join(', ') !== ids.join(', ')) sh.getRange(r + 1, ci + 1).setValue(cleaned.join(', '));
    if (is1) done = String(v[r][ni]) + '：' + cleaned.join(', ');
  }
  return done;
}

// ─────────────────────── ② リーグ：テスト大会を受け持つ ───────────────────────

function joinTestRound() {
  if (!isLeague_()) return trAlert_('テスト大会', 'これは1部のリーグシステムで実行してください。');
  var comps = leagueComps_();
  if (comps.indexOf(TR.comp) < 0) setCfg_('担当大会ID', comps.concat([TR.comp]).join(', '), '');
  trTestModeOn_();
  var pulled = pullFromCentralQuiet_();
  trFresh_();
  var n = objs_(シート.試合).filter(function (m) { return trHit_(m['試合ID']); }).length;
  var links = trWriteLinks_();
  return trAlert_('テスト大会を受け持ちました',
    '担当大会ID：' + leagueComps_().join(', ') + '\nテストモード：開始しました（すべてのメールは ' + trTo_() + ' だけ）\n全体からの取り込み：' + pulled +
    '\nテスト大会の試合：' + n + '試合' + (n ? '' : '（全体システムで「テスト大会（1節）を作る」を先に実行してください）') +
    '\n\n「' + TR.linkSheet + '」タブに、試合ごとのリンクを出しました。' + (links.missing ? '\n⚠ ' + links.missing : ''));
}

/** 一体のシステム：テスト大会のリンクのタブをすぐ作る（リーグで「受け持つ」をする代わり） */
function trSingleLinks_() {
  trFresh_();
  var links = trWriteLinks_();
  return '\n\n「' + TR.linkSheet + '」タブに、試合ごとのリンクを出しました。' + (links.missing ? '\n⚠ ' + links.missing : '');
}

function pullFromCentralQuiet_() {
  try { return String(pullFromCentral() || '').split('\n').slice(0, 3).join('／'); } catch (e) { return 'エラー：' + e.message; }
}

/** 「テスト大会のリンク」タブ：試合ごとに、両チーム・運営クラブのチームページと、公式記録・審判報告書・MC報告書 */
function trWriteLinks_() {
  var base = linkBase_();
  var u = function (q) { return base ? base + q : ''; };
  var univs = lnUnivs_();
  var notOpen = {};
  var page = function (tid) { var c = rgTeamCode_(tid); if (!univs[c]) notOpen[lnTeamName_(tid)] = true; return lnUrl_(c); };
  var rows = [['リンク', 'URL', 'メモ']];
  rows.push(['運営ダッシュボード', u('?page=admin'), '運営パスコードでログイン']);
  rows.push(['公式記録入力', u('?page=official'), '運営クラブが入力 → 3者（主審・両チーム）に承認依頼']);
  rows.push(['審判報告書', u('?page=referee'), '試合後に主審が入力']);
  rows.push(['マッチコミッショナー報告書', u('?page=mc'), '1部は全試合が対象']);
  rows.push(['', '', '']);
  objs_(シート.試合).filter(function (m) { return trHit_(m['試合ID']); })
    .sort(function (a, b) { return String(a['マッチNo']) < String(b['マッチNo']) ? -1 : 1; })
    .forEach(function (m) {
      var hid = String(m['ホームチームID']), aid = String(m['アウェイチームID']);
      var title = 'No.' + m['マッチNo'] + '　' + kickoffText_(m['キックオフ']) + '　' + lnTeamName_(hid) + ' vs ' + lnTeamName_(aid) + '（' + m['会場'] + '）';
      rows.push(['■ ' + title, '', '']);
      rows.push(['　' + lnTeamName_(hid) + '（ホーム・運営クラブ）', page(hid), 'スタメン提出／運営クラブ（スタメン確認・審判団へ送付・問題事項報告書）']);
      rows.push(['　' + lnTeamName_(aid) + '（アウェイ）', page(aid), 'スタメン提出']);
    });
  linkWriteSheet_(TR.linkSheet, rows[0], rows.slice(1));
  var sh = ss_().getSheetByName(TR.linkSheet);
  sh.setColumnWidth(1, 330); sh.setColumnWidth(2, 520); sh.setColumnWidth(3, 380);
  var miss = Object.keys(notOpen);
  return { missing: miss.length ? 'チームページを開けないクラブ：' + miss.join('、') + '（システム設定の「年度」を、チームマスターの年度に合わせてください）' : '' };
}

// ─────────────────────── ③ 片付け（リーグ → 全体の順） ───────────────────────

function removeTestRound() {
  try {
    var ui = SpreadsheetApp.getUi();
    if (ui.alert('テスト大会のデータを削除', 'テスト大会（' + TR.comp + '）の試合・スタメン・公式記録・警告退場・処分・決定通知・問題事項・MC報告書・PDFを消します。\n' +
      (isLeague_() ? 'リーグで先に実行し、そのあと全体システムでも実行してください。' : isSingle_() ? '' : 'リーグシステムで先に実行してあることを確かめてください。'), ui.ButtonSet.OK_CANCEL) !== ui.Button.OK) return 'キャンセルしました';
  } catch (e) {}
  return trAlert_('テスト大会のデータを削除しました', removeTestRound_());
}

var TR_KEEP_SHEETS = ['システム設定', '操作履歴', '連携リーグ', 'チームマスター', 'チームスタッフマスター', '選手マスター', '選手登録', '入力候補マスター',
  '処分通知の連絡先', 'クラブの連絡先', 'チーム通知先', 'Discord送信待ち', '処分一覧（これまで）', '全体テスト結果', 'テスト送信ログ'];

function removeTestRound_() {
  var ss = ss_();
  var lock = LockService.getScriptLock();
  lock.waitLock(30000);
  var removed = {};
  try {
    var keyCols = ['大会ID', '試合ID', '発生試合ID', '対象試合ID', '最初の対象試合ID', '対象大会ID', '関連試合ID'];
    var linkCols = ['得点ID', '公式記録ID', '対象公式記録ID', '報告書ID', '処分ID', '関連処分ID', '報告ID', '提出ID'];
    var linked = {};
    var sheets = ss.getSheets().filter(function (sh) { return TR_KEEP_SHEETS.indexOf(sh.getName()) < 0 && !/テンプレート/.test(sh.getName()); });
    var plan = function (sh, useLinked) {
      if (sh.getLastRow() < 2) return [];
      var v = sh.getDataRange().getValues(), h = v[0].map(String);
      var ix = function (l) { return l.map(function (c) { return h.indexOf(c); }).filter(function (i) { return i >= 0; }); };
      var kc = ix(keyCols), lc = ix(linkCols), nc = ix(['備考']);
      var rows = [];
      for (var r = 1; r < v.length; r++) {
        var row = v[r];
        var d = kc.some(function (i) { return trHit_(row[i]); }) ||
          (sh.getName() === MD.REF_SHEET && nc.some(function (i) { return String(row[i]) === TR.refNote; }));
        var l = useLinked && lc.some(function (i) { var x = String(row[i] || ''); return x && linked[x]; });
        if (d || l) {
          rows.push(r + 1);
          lc.forEach(function (i) { var x = String(row[i] || ''); if (x) { linked[x] = true; linked['INC-' + x] = true; } });
        }
      }
      return rows;
    };
    sheets.forEach(function (sh) { plan(sh, false); }); // 1回目：つながっているIDを集める
    sheets.forEach(function (sh) {
      var rows = plan(sh, true).sort(function (a, b) { return b - a; });
      var i = 0;
      while (i < rows.length) {
        var end = rows[i], start = end;
        while (i + 1 < rows.length && rows[i + 1] === start - 1) { i++; start = rows[i]; }
        safeDeleteRows_(sh, start, end - start + 1);
        i++;
      }
      if (rows.length) { removed[sh.getName()] = rows.length; memoForget_(sh.getName()); }
    });
  } finally {
    lock.releaseLock();
  }
  // PDFのフォルダ（「【テスト】」の大会フォルダ）
  var trashed = 0;
  try {
    var years = docRoot_().getFolders();
    while (years.hasNext()) {
      var cs = years.next().getFolders();
      while (cs.hasNext()) { var f = cs.next(); if (f.getName().indexOf(TR.name) >= 0) { f.setTrashed(true); trashed++; } }
    }
  } catch (e) {}
  var props = PropertiesService.getScriptProperties();
  props.getKeys().forEach(function (k) { if (k.indexOf(TR.comp) >= 0) props.deleteProperty(k); });
  try { if (typeof bumpPublicVersion_ === 'function') bumpPublicVersion_(); } catch (e) {}

  var extra = '';
  if (isLeague_()) {
    setCfg_('担当大会ID', leagueComps_().filter(function (c) { return c !== TR.comp; }).join(', '), '');
    var tab = ss.getSheetByName(TR.linkSheet);
    if (tab) ss.deleteSheet(tab);
    try { writeLeagueLinks_(); } catch (e) {}
    extra = '\n・担当大会ID：' + leagueComps_().join(', ') + '\n\n続けて、全体システムでも「テスト大会のデータを削除」を実行してください。';
  } else if (isSingle_()) {
    var tab1 = ss.getSheetByName(TR.linkSheet);
    if (tab1) ss.deleteSheet(tab1);
    try { runHourlyUpdate(); } catch (e) { extra += '\n・集計の更新：' + e.message; }
  } else {
    extra = '\n・連携リーグ：' + trLinkCentral_(false);
    try { runHourlyUpdate(); } catch (e) { extra += '\n・集計の更新：' + e.message; }
  }
  return Object.keys(removed).map(function (k) { return '・' + k + '：' + removed[k] + '行'; }).join('\n') +
    '\n・書類フォルダ：' + trashed + '件をゴミ箱へ' + extra +
    '\n\nテストモードはそのままです。終えるときはメニュー「テスト」→「テストモードを終了」を実行してください。';
}

;
// ==== admin.gs
/**
 * Admin.gs v1
 * クラブサッカー大会運営システム｜運営ダッシュボード（Webページ）
 *
 *   WebアプリURL + ?page=admin
 *   「運営パスコード」（システム設定）でログイン。ログインは12時間有効
 *
 *   ホーム      ：要対応（承認待ち・修正依頼・未提出・審判報告・規律委員会・登録申請・取込の確認）と今後の試合
 *   試合        ：日程・会場・キックオフ・試合状態の変更（日程変更履歴に記録）、公式記録がない試合の結果の修正、
 *                 公式記録の入力画面・承認状況・未承認者への催促
 *   登録        ：登録申請の承認・却下、大会ごとの登録状況と登録締切日
 *   処分        ：規律委員会の確認・決定・差し戻し
 *   取込の確認  ：試合報告から取り込んだ結果・選手名寄せ・名簿照合の確認
 *   チーム      ：監督・責任者の氏名とメール、一括登録ページのリンク
 */

var AD_SESSION_HOURS = 12;

// ─────────────────────── ログイン ───────────────────────

function adSecret_() {
  var props = PropertiesService.getScriptProperties();
  var s = props.getProperty('ADMIN_SECRET');
  if (!s) { s = Utilities.getUuid() + Utilities.getUuid(); props.setProperty('ADMIN_SECRET', s); }
  return s;
}

function adSign_(exp) {
  var code = String(cfg_('運営パスコード') || '');
  return Utilities.base64EncodeWebSafe(Utilities.computeHmacSha256Signature(String(exp) + '|' + code, adSecret_())).slice(0, 32);
}

function adminLogin(code) {
  var real = String(cfg_('運営パスコード') || '').trim();
  if (!real) throw new Error('システム設定に「運営パスコード」を設定してください');
  Utilities.sleep(300);
  if (String(code || '').trim() !== real) throw new Error('パスコードが違います');
  var exp = Date.now() + AD_SESSION_HOURS * 3600 * 1000;
  return exp + '.' + adSign_(exp);
}

/** パスコードを変えると、発行済みのログインは無効になる */
function adCheck_(tok) {
  var p = String(tok || '').split('.');
  if (p.length !== 2 || Number(p[0]) < Date.now() || adSign_(p[0]) !== p[1]) throw new Error('LOGIN');
}

function adminPage() {
  return HtmlService.createTemplateFromFile('Admin').evaluate()
    .setTitle('運営ダッシュボード')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1, viewport-fit=cover')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

// ─────────────────────── 共通 ───────────────────────

function adSs_() { return typeof ss_ === 'function' ? ss_() : SpreadsheetApp.getActiveSpreadsheet(); }
function adRead_(n) { return stRead_(adSs_(), n); }
function adDate_(v) { return typeof dbDate_ === 'function' ? dbDate_(v) : stDate_(v); }
function adToday_() { return Utilities.formatDate(new Date(), Session.getScriptTimeZone() || 'Asia/Tokyo', 'yyyy-MM-dd'); }
function adNow_() { return Utilities.formatDate(new Date(), Session.getScriptTimeZone() || 'Asia/Tokyo', 'yyyy-MM-dd HH:mm:ss'); }
var AD_SKIP = /TEST|KIRIN/i;

function adTeamNames_() {
  var n = {};
  adRead_('チームマスター').forEach(function (t) { n[String(t['チームID'])] = String(t['略称'] || t['チーム名'] || t['クラブ名'] || t['チームID']); });
  return n;
}

/** ページを開いたとき：大会一覧など */
/** 高速化：読むだけの処理は同じシートを1回だけ読む */
function adminBoot(tok) {
  return withReadMemo_(function () { return adminBootRead_(tok); });
}

function adminBootRead_(tok) {
  adCheck_(tok);
  var comps = adRead_('大会マスター').filter(function (c) { return !AD_SKIP.test(String(c['大会ID'] || '')); })
    .map(function (c) { return { id: String(c['大会ID']), name: String(c['大会名'] || c['大会ID']), format: String(c['大会形式'] || ''), deadline: typeof bkYmd_ === 'function' ? bkYmd_(c['登録締切日']) : '' }; });
  var docsUrl = '';
  try { if (typeof docRoot_ === 'function') docsUrl = docRoot_().getUrl(); } catch (e) {}
  var refNames = [];
  try { if (typeof mdReferees_ === 'function') refNames = mdReferees_().map(function (r) { return String(r['氏名'] || '') + (r['メール'] ? '' : '（メール未登録）'); }).filter(Boolean); } catch (e) {}
  // 会場の候補：入力候補マスターの「会場名」＋日程に入っている会場
  var venues = [];
  try { venues = (typeof refOptionValues_ === 'function' ? refOptionValues_('会場名') : []).map(String); } catch (e) {}
  try { objs_(シート.試合).forEach(function (m) { var v = String(m['会場'] || '').trim(); if (v && venues.indexOf(v) < 0) venues.push(v); }); } catch (e) {}
  return { refNames: refNames, venues: venues, comps: comps, docsUrl: docsUrl, sheetUrl: adSs_().getUrl(), officialUrl: (typeof webAppBaseUrl_ === 'function' ? webAppBaseUrl_() : '') + '?page=official', today: adToday_() };
}

// ─────────────────────── ホーム ───────────────────────

/** 高速化：読むだけの処理は同じシートを1回だけ読む */
function adminHome(tok) {
  return withReadMemo_(function () { return adminHomeRead_(tok); });
}

function adminHomeRead_(tok) {
  adCheck_(tok);
  var ss = adSs_();
  var read = function (n) { return dbRead_(ss, n); };
  var data = {
    comps: read('大会マスター'), teams: read('チームマスター'), players: read('選手マスター'),
    matches: read('試合マスター').filter(function (m) { return !AD_SKIP.test(String(m['大会ID'] || '')); }),
    records: read('公式記録データ'), approvals: read('公式記録承認'), changes: read('日程変更履歴'),
    refReports: read('審判報告書'), sanctions: read('処分管理')
  };
  data.suspTargets = [];
  if (typeof computeDiscipline_ === 'function' && typeof readDisciplineData_ === 'function') {
    var d = computeDiscipline_(readDisciplineData_(ss));
    var byId = {};
    d.sanctions.forEach(function (s) { byId[s['処分ID']] = s; });
    data.suspTargets = d.targets.filter(function (t) { return t['状態'] !== '消化済'; })
      .map(function (t) { return { matchId: String(t['対象試合ID']), sanction: byId[t['処分ID']] || {}, order: t['順番'] }; });
  }
  var blocks = computeDashboard_(data, adToday_());

  var reqs = adRead_('選手登録申請').filter(function (r) { return String(r['申請状態']) === '確認待ち'; }).length;
  var imp = adImportRows_().filter(function (r) { return r.needs; }).length;
  var names = adNameReviews_().filter(function (r) { return !r.done; }).length;
  var regs = [];
  adRead_('大会マスター').forEach(function (c) {
    var dl = typeof bkYmd_ === 'function' ? bkYmd_(c['登録締切日']) : '';
    if (!dl || AD_SKIP.test(String(c['大会ID']))) return;
    var st = typeof bkRegistrationStatus_ === 'function' ? bkRegistrationStatus_(String(c['大会ID'])) : [];
    var left = st.filter(function (x) { return !x.submitted && !x.pending; });
    if (dl >= adToday_() || left.length) regs.push({ comp: String(c['大会名']), deadline: dl, total: st.length, missing: left.map(function (x) { return x.team; }) });
  });
  return {
    blocks: blocks.map(function (b) { return { title: b.title, note: b.note, headers: b.headers, rows: b.rows }; }),
    counts: { requests: reqs, imports: imp, names: names, notices: typeof ntRows_ === 'function' ? ntRows_().filter(function (r) { return ['承認待ち', '修正依頼'].indexOf(String(r['状態'])) >= 0; }).length : 0,
      incidents: typeof icUncheckedCount_ === 'function' ? icUncheckedCount_() : 0 }, registrations: regs,
    mailLeft: (function () { try { return MailApp.getRemainingDailyQuota(); } catch (e) { return null; } })()
  };
}

// ─────────────────────── 試合 ───────────────────────

/** 高速化：読むだけの処理は同じシートを1回だけ読む */
function adminMatches(tok, compId) {
  return withReadMemo_(function () { return adminMatchesRead_(tok, compId); });
}

function adminMatchesRead_(tok, compId, pred) {
  adCheck_(tok);
  var tn = adTeamNames_();
  var latest = {}, appr = {};
  adRead_('公式記録データ').forEach(function (r) {
    var mid = String(r['試合ID']);
    if (!latest[mid] || Number(r['版']) > Number(latest[mid]['版'])) latest[mid] = r;
  });
  var inc = typeof icCountByMatch_ === 'function' ? icCountByMatch_() : {};
  var mcr = typeof mcPdfByMatch_ === 'function' ? mcPdfByMatch_() : {};
  // 審判報告書（試合ごと。ドライブを探さなくても、ダッシュボードからPDFを開けるように）
  var rrep = {};
  try {
    adRead_('審判報告書').forEach(function (r) {
      var k = String(r['試合ID'] || ''); if (!k) return;
      var at = r['提出日時'];
      at = Object.prototype.toString.call(at) === '[object Date]' ? Utilities.formatDate(at, 'Asia/Tokyo', 'yyyy-MM-dd HH:mm') : String(at || '').slice(0, 16);
      (rrep[k] = rrep[k] || []).push({ id: String(r['報告書ID'] || ''), at: at, main: String(r['主審'] || ''), pdf: String(r['PDF URL'] || ''),
        red: String(r['一発退場'] || '') === 'あり', imp: !!String(r['重要事項本文'] || '').trim() });
    });
    Object.keys(rrep).forEach(function (k) { rrep[k].sort(function (a, b) { return a.at < b.at ? 1 : -1; }); });
  } catch (e) {}
  adRead_('公式記録承認').forEach(function (a) { (appr[String(a['対象公式記録ID'])] = appr[String(a['対象公式記録ID'])] || []).push(a); });
  var mailSt = adApprovalMailState_();
  var apBase = adApproveBase_();
  // スタメンの状態・大会の略称（ダッシュボード v3：試合ごとの進み具合）
  var lnRowsAll = typeof lnRows_ === 'function' ? lnRows_() : [];
  var lnSt = function (mid, tid) {
    if (!tid || typeof lnLatest_ !== 'function') return '';
    var r = lnLatest_(lnRowsAll, mid, tid);
    return r ? String(r['状態'] || '') : '';
  };
  var compNm = {};
  adRead_('大会マスター').forEach(function (c) { compNm[String(c['大会ID'])] = String(c['略称'] || c['大会名'] || c['大会ID']); });
  return adRead_('試合マスター').filter(function (m) { return pred ? pred(m) : String(m['大会ID']) === String(compId); }).map(function (m) {
    var mid = String(m['試合ID']);
    var rec = latest[mid];
    var aps = rec ? (appr[String(rec['公式記録ID'])] || []).map(function (a) {
      var em = String(a['承認者メール'] || '').trim(), pending = String(a['承認状態']) === '未承認';
      return { id: String(a['承認ID'] || ''), role: String(a['承認者区分']), name: String(a['承認者名'] || ''), status: String(a['承認状態']), comment: String(a['コメント'] || ''), email: !!em,
        // 未承認の人だけ：承認画面のリンク（メールが届かないときに手で送る）と、依頼メールが届いたか
        url: pending && apBase ? apBase + '?page=approve&token=' + encodeURIComponent(String(a['承認トークン'] || '')) : '',
        mail: pending ? (em ? (mailSt[mid + '|' + em.toLowerCase()] || '未送信') : 'メール未登録') : '' };
    }) : [];
    return {
      id: mid, no: String(m['マッチNo'] || ''), round: String(m['節／ラウンド'] || ''),
      comp: String(m['大会ID'] || ''), compName: compNm[String(m['大会ID'])] || String(m['大会ID'] || ''), duty: String(m['運営クラブ'] || ''),
      lnHome: lnSt(mid, String(m['ホームチームID'] || '')), lnAway: lnSt(mid, String(m['アウェイチームID'] || '')),
      date: adDate_(m['開催予定日']), actual: adDate_(m['実施日']),
      kickoff: typeof kickoffText_ === 'function' ? kickoffText_(m['キックオフ']) : String(m['キックオフ'] || ''),
      venue: String(m['会場'] || ''), note: String(m['備考'] || ''), status: String(m['試合状態'] || ''),
      ref: String(m['主審'] || ''), ar: String(m['副審'] || ''), fourth: String(m['第4審'] || ''),
      home: String(m['ホームチームID'] || ''), away: String(m['アウェイチームID'] || ''),
      homeName: tn[String(m['ホームチームID'])] || '', awayName: tn[String(m['アウェイチームID'])] || '',
      confirmed: String(m['結果確定'] || '') === '確定',
      hs: m['ホーム得点'] === '' ? '' : String(m['ホーム得点']), as: m['アウェイ得点'] === '' ? '' : String(m['アウェイ得点']),
      hpk: String(m['ホームPK'] == null ? '' : m['ホームPK']), apk: String(m['アウェイPK'] == null ? '' : m['アウェイPK']),
      record: rec ? { version: Number(rec['版']), status: String(rec['記録状態'] || ''), pdf: String(rec['確定PDF URL'] || '') } : null,
      approvals: aps,
      incidents: inc[mid] || 0,
      mc: mcr[mid] || null,
      refReports: rrep[mid] || [],
      editUrl: typeof revEditUrl_ === 'function' ? revEditUrl_(mid) : '',
      liveUrl: typeof liveUrl_ === 'function' && !(typeof isCentral_ === 'function' && isCentral_() && !(typeof isSingle_ === 'function' && isSingle_())) ? liveUrl_(mid) : ''
    };
  }).sort(function (a, b) { return (a.date < b.date ? -1 : a.date > b.date ? 1 : 0) || (a.kickoff < b.kickoff ? -1 : 1); });
}

/** ダッシュボード v3「試合」の日ごとの表示：from〜to（yyyy-MM-dd）の試合（すべての大会。テスト用の大会は除く） */
function adminDays(tok, from, to) {
  return withReadMemo_(function () {
    adCheck_(tok);
    from = String(from || adToday_()); to = String(to || from);
    var list = adminMatchesRead_(tok, null, function (m) {
      if (AD_SKIP.test(String(m['大会ID'] || ''))) return false;
      var d = adDate_(m['開催予定日']);
      return d && d >= from && d <= to;
    });
    return { today: adToday_(), from: from, to: to, list: list };
  });
}

/** ホームの「今日・明日の試合」：試合ごとの進み具合（スタメン・運営クラブ・公式記録・承認） */
function adminToday(tok) {
  return withReadMemo_(function () {
    adCheck_(tok);
    var t0 = adToday_();
    var d1 = new Date(); d1.setDate(d1.getDate() + 1);
    var t1 = Utilities.formatDate(d1, Session.getScriptTimeZone() || 'Asia/Tokyo', 'yyyy-MM-dd');
    var comps = {};
    adRead_('大会マスター').forEach(function (c) { comps[String(c['大会ID'])] = String(c['略称'] || c['大会名'] || c['大会ID']); });
    var rows = typeof lnRows_ === 'function' ? lnRows_() : [];
    var ln = function (mid, tid) {
      if (!tid || typeof lnLatest_ !== 'function') return '';
      var r = lnLatest_(rows, mid, tid);
      return r ? String(r['状態'] || '') : '';
    };
    var list = adminMatchesRead_(tok, null, function (m) { var d = adDate_(m['開催予定日']); return d === t0 || d === t1; });
    var master = {};
    adRead_('試合マスター').forEach(function (m) { master[String(m['試合ID'])] = m; });
    list.forEach(function (m) {
      var x = master[m.id] || {};
      m.compName = comps[String(x['大会ID'])] || String(x['大会ID'] || '');
      m.duty = String(x['運営クラブ'] || '');
      m.lnHome = ln(m.id, m.home); m.lnAway = ln(m.id, m.away);
    });
    return { today: t0, tomorrow: t1, list: list };
  });
}

var AD_MATCH_FIELDS = { date: '開催予定日', kickoff: 'キックオフ', venue: '会場', status: '試合状態', note: '備考', duty: '運営クラブ', ref: '主審', ar: '副審', fourth: '第4審' };

/** 日程・結果の変更 */
function adminSaveMatch(tok, matchId, patch, reason) {
  adCheck_(tok);
  patch = patch || {};
  var lock = LockService.getScriptLock();
  if (!lock.tryLock(30000)) throw new Error('他の処理が実行中です。少し待ってからもう一度押してください');
  var changed = [], m0 = {};
  try {
    var m = objs_(シート.試合).filter(function (x) { return String(x['試合ID']) === String(matchId); })[0];
    if (!m) throw new Error('試合が見つかりません');
    m0 = m;
    var up = {};
    Object.keys(AD_MATCH_FIELDS).forEach(function (k) {
      if (patch[k] === undefined) return;
      var col = AD_MATCH_FIELDS[k];
      var before = k === 'date' ? adDate_(m[col]) : k === 'kickoff' ? (typeof kickoffText_ === 'function' ? kickoffText_(m[col]) : String(m[col] || '')) : String(m[col] || '');
      var after = String(patch[k] || '').trim();
      if (k === 'date' && after && !/^\d{4}-\d{2}-\d{2}$/.test(after)) throw new Error('日付は 2026-10-03 の形で入力してください');
      if (k === 'kickoff' && after && !/^\d{1,2}:\d{2}$/.test(after)) throw new Error('キックオフは 13:30 の形で入力してください');
      if (before === after) return;
      up[col] = (k === 'date' || k === 'kickoff') && after ? "'" + after : after;
      changed.push({ col: col, before: before, after: after });
    });

    // 結果（公式記録がない試合だけ）
    var hasRecord = objs_(シート.公式記録).some(function (r) { return String(r['試合ID']) === String(matchId); });
    if (patch.result) {
      if (hasRecord) throw new Error('公式記録がある試合の結果は、公式記録の「訂正」から直してください');
      var R = patch.result;
      var hs = String(R.hs).trim(), as = String(R.as).trim();
      if (R.clear) {
        Object.assign(up, { 'ホーム得点': '', 'アウェイ得点': '', 'ホームPK': '', 'アウェイPK': '', '結果確定': '', '勝者チームID': '', 'ホーム結果': '', 'アウェイ結果': '', 'ホーム表示': '', 'アウェイ表示': '', 'ホーム勝点': '', 'アウェイ勝点': '' });
        if (String(m['試合状態']) === '開催済') up['試合状態'] = '';
        changed.push({ col: '結果', before: String(m['ホーム得点']) + '-' + String(m['アウェイ得点']), after: '（取り消し）' });
      } else {
        if (!/^\d+$/.test(hs) || !/^\d+$/.test(as)) throw new Error('スコアを数字で入力してください');
        var h = Number(hs), a = Number(as);
        var hpk = String(R.hpk || '').trim(), apk = String(R.apk || '').trim();
        var hr = h > a ? 'W' : h < a ? 'L' : 'D', ar = h > a ? 'L' : h < a ? 'W' : 'D';
        var win = h > a ? m['ホームチームID'] : h < a ? m['アウェイチームID'] : 'DRAW';
        if (h === a && hpk !== '' && apk !== '') win = Number(hpk) > Number(apk) ? m['ホームチームID'] : m['アウェイチームID'];
        var mark = function (x) { return x === 'W' ? '○' : x === 'L' ? '×' : '△'; };
        Object.assign(up, {
          'ホーム得点': h, 'アウェイ得点': a, 'ホームPK': hpk, 'アウェイPK': apk, '結果確定': '確定', '試合状態': '開催済',
          'ホーム結果': hr, 'アウェイ結果': ar, 'ホーム表示': mark(hr) + ' ' + h + '-' + a, 'アウェイ表示': mark(ar) + ' ' + a + '-' + h,
          'ホーム勝点': hr === 'W' ? 3 : hr === 'D' ? 1 : 0, 'アウェイ勝点': ar === 'W' ? 3 : ar === 'D' ? 1 : 0, '勝者チームID': win,
          '結果出典': '運営（ダッシュボード）' // 試合報告フォームの取込で上書きしない
        });
        var before = m['結果確定'] === '確定' ? String(m['ホーム得点']) + '-' + String(m['アウェイ得点']) + (m['ホームPK'] !== '' && m['ホームPK'] != null ? '（PK' + m['ホームPK'] + '-' + m['アウェイPK'] + '）' : '') : '（結果なし）';
        var after = h + '-' + a + (hpk !== '' ? '（PK' + hpk + '-' + apk + '）' : '');
        if (before !== after) changed.push({ col: '結果', before: before, after: after });
      }
    }
    if (!changed.length) return { ok: true, message: '変更はありません' };
    if (up['試合状態'] !== undefined && ['', '予定', '開催済', '中断', '延期', '中止', '記録対象外'].indexOf(up['試合状態']) < 0) throw new Error('試合状態が正しくありません');

    var watch = { '開催予定日': '日程変更', 'キックオフ': 'KO変更', '会場': '会場変更' };
    var kinds = String(m['変更区分'] || '').split(/[、,]\s*/).filter(Boolean);
    changed.forEach(function (c) {
      var k = watch[c.col] || (c.col === '試合状態' && c.after === '延期' ? '延期' : '');
      if (k && kinds.indexOf(k) < 0) kinds.push(k);
    });
    if (typeof schEnsureColumns_ === 'function') { try { schEnsureColumns_(adSs_()); } catch (e) {} }
    up['変更区分'] = kinds.join('、');
    up['最終変更日時'] = adNow_();
    // 結果の列（試合状態・実施日・結果）を直したら、全体とリーグの受け渡しで「こちらが新しい」と分かるように記録（Sync.gs）
    if (['試合状態', '実施日', '結果確定', 'ホーム得点'].some(function (k) { return up[k] !== undefined; })) up['結果更新日時'] = adNow_();
    update_(シート.試合, m._row, up);

    // 日程変更履歴
    var ss = adSs_();
    var hist = ss.getSheetByName('日程変更履歴') || ss.insertSheet('日程変更履歴');
    if (hist.getLastRow() === 0) hist.appendRow(typeof SCH_HISTORY_HEADERS !== 'undefined' ? SCH_HISTORY_HEADERS : ['変更ID', '試合ID', '項目', '変更前', '変更後', '変更日時', '変更者', '理由']);
    var rows = changed.map(function (c) { return ['CHG-' + Utilities.getUuid().slice(0, 8), String(matchId), c.col, c.before, c.after, adNow_(), 'ダッシュボード', String(reason || '')]; });
    hist.getRange(hist.getLastRow() + 1, 1, rows.length, rows[0].length).setValues(rows);
    // 日付・キックオフ・会場・延期／中止は、約3分後に両チームと運営クラブへ自動でメール（Schedule.gs）
    var notice = changed.some(function (c) { return ['開催予定日', 'キックオフ', '会場'].indexOf(c.col) >= 0 || (c.col === '試合状態' && /延期|中止/.test(c.before + c.after)); });
    if (notice && typeof schQueueNotice_ === 'function') schQueueNotice_(String(matchId));
    try { log_('ダッシュボードで試合を変更', '試合', matchId, null, up, String(reason || '')); } catch (e) {}
  } finally {
    lock.releaseLock();
  }
  if (patch.result) {
    if (typeof scheduleRecalc_ === 'function') scheduleRecalc_(); // 処分・順位表は約1分後にまとめて更新
  }
  if (typeof bumpPublicVersion_ === 'function') bumpPublicVersion_(); // ホームページの日程を最新にする
  var willMail = changed.some(function (c) { return ['開催予定日', 'キックオフ', '会場'].indexOf(c.col) >= 0 || (c.col === '試合状態' && /延期|中止/.test(c.before + c.after)); }) &&
    String(cfg_('日程変更の自動連絡') || '').trim() !== 'しない';
  return { ok: true, message: changed.map(function (c) { return c.col + '：' + (c.before || '（空）') + ' → ' + (c.after || '（空）'); }).join('\n') +
    (willMail ? '\n（約3分後に、両チームと運営クラブへ日程変更のメールを送ります）' : '') };
}

/** 承認画面のURLの土台（入口ページがあればそちら） */
function adApproveBase_() {
  var base = typeof webAppBaseUrl_ === 'function' ? webAppBaseUrl_() : '';
  return (typeof entryBase_ === 'function' && base && entryBase_()) || base;
}

/** 承認依頼メールが届いたか（試合ID|メール → 送信済／エラー）。いちばん新しい記録で判断 */
function adApprovalMailState_() {
  var o = {};
  adRead_('通知履歴').forEach(function (n) {
    if (!/公式記録承認依頼/.test(String(n['通知種別'] || ''))) return;
    var k = String(n['関連試合ID'] || '') + '|' + String(n['宛先'] || '').trim().toLowerCase();
    o[k] = String(n['送信状態'] || '') === 'エラー' ? 'エラー' : '送信済';
  });
  return o;
}

/** 運営による代理承認（メールが届かない・本人がリンクを開けないとき。電話などで本人に確認してから） */
function adminProxyApprove(tok, approvalId, by, reason) {
  adCheck_(tok);
  by = String(by || '').trim(); reason = String(reason || '').trim();
  if (!by) throw new Error('代理で承認する人（運営）の名前を入れてください');
  if (!reason) throw new Error('代理で承認する理由（本人に確認した方法など）を入れてください');
  var a = objs_(シート.承認).filter(function (x) { return String(x['承認ID']) === String(approvalId); })[0];
  if (!a) throw new Error('承認依頼が見つかりません');
  if (String(a['承認状態']) !== '未承認') throw new Error('この承認依頼は「' + a['承認状態'] + '」です。画面を開き直してください');
  var r = processApproval_(String(a['承認トークン']), 'approve', '【運営による代理承認】' + by + '：' + reason);
  try { if (typeof log_ === 'function') log_('公式記録の代理承認', '公式記録', String(a['試合ID'] || ''), null, null, a['承認者区分'] + '（' + (a['承認者名'] || '') + '）を ' + by + ' が代理承認：' + reason); } catch (e) {}
  return { ok: true, message: a['承認者区分'] + 'の承認を代理で記録しました' + (r && r.message ? '。' + r.message : '') };
}

/**
 * メールの1日の上限で届かなかった承認依頼を、送れるようになったら自動で送り直す
 *  （10分ごとの取り込み・1時間ごとの更新から呼ぶ。今日の残りが少ないときは送らない）
 */
function retryApprovalMails_() {
  var left = 0;
  try { left = MailApp.getRemainingDailyQuota(); } catch (e) { return ''; }
  if (left < 10) return '';
  var st = adApprovalMailState_();
  var recs = {};
  objs_(シート.公式記録).forEach(function (r) { recs[String(r['公式記録ID'])] = r; });
  var base = adApproveBase_(), sent = 0;
  objs_(シート.承認).forEach(function (a) {
    if (sent >= left - 8) return; // 本番の連絡のために少し残す
    if (String(a['承認状態']) !== '未承認') return;
    var rec = recs[String(a['対象公式記録ID'])];
    if (!rec || String(rec['記録状態']) !== '承認待ち') return;
    var to = String(a['承認者メール'] || '').trim(), mid = String(a['試合ID'] || '');
    if (!to || st[mid + '|' + to.toLowerCase()] !== 'エラー') return;
    var url = base + '?page=approve&token=' + encodeURIComponent(a['承認トークン']);
    mail_('公式記録承認依頼（自動再送）', to, '【承認のお願い】公式記録 ' + mid + '（版' + rec['版'] + '）',
      '<p>' + htmlEsc_(a['承認者名'] || '') + ' 様</p><p>公式記録の承認依頼です（送信の上限で届かなかったため、あらためてお送りします）。内容をご確認のうえ、承認または修正依頼をお願いします。</p>' +
      '<p><a href="' + url + '">承認画面を開く</a></p>', mid, '', 'NONE');
    sent++;
  });
  return sent ? '承認依頼を' + sent + '件送り直しました' : '';
}

/** 未承認の人へ、承認依頼をもう一度送る */
function adminRemindApprovals(tok, matchId) {
  adCheck_(tok);
  var rec = objs_(シート.公式記録).filter(function (r) { return String(r['試合ID']) === String(matchId); })
    .sort(function (a, b) { return Number(b['版']) - Number(a['版']); })[0];
  if (!rec || String(rec['記録状態']) !== '承認待ち') throw new Error('承認待ちの公式記録がありません');
  var base = typeof webAppBaseUrl_ === 'function' ? webAppBaseUrl_() : '';
  var sent = [], noMail = [];
  objs_(シート.承認).filter(function (a) { return String(a['対象公式記録ID']) === String(rec['公式記録ID']) && String(a['承認状態']) === '未承認'; })
    .forEach(function (a) {
      var to = String(a['承認者メール'] || '').trim();
      if (!to) { noMail.push(a['承認者区分']); return; }
      var url = base + '?page=approve&token=' + encodeURIComponent(a['承認トークン']);
      mail_('公式記録承認依頼（再送）', to, '【再送・承認のお願い】公式記録 ' + matchId + '（版' + rec['版'] + '）',
        '<p>' + htmlEsc_(a['承認者名'] || '') + ' 様</p><p>公式記録の承認がまだ済んでいません。内容をご確認のうえ、承認または修正依頼をお願いします。</p>' +
        '<p><a href="' + url + '">承認画面を開く</a></p>', matchId, '', 'NONE');
      sent.push(a['承認者区分']);
    });
  return { ok: true, message: (sent.length ? sent.join('・') + ' に再送しました' : '送れる相手がいません') + (noMail.length ? '（メール未登録：' + noMail.join('・') + '）' : '') };
}

// ─────────────────────── 登録 ───────────────────────

/** 高速化：読むだけの処理は同じシートを1回だけ読む */
function adminRequests(tok) {
  return withReadMemo_(function () { return adminRequestsRead_(tok); });
}

function adminRequestsRead_(tok) {
  adCheck_(tok);
  var detail = {};
  adRead_('一括登録の明細').forEach(function (d) { (detail[String(d['申請ID'])] = detail[String(d['申請ID'])] || []).push(d); });
  var list = adRead_('選手登録申請').map(function (r) {
    var o = {};
    ['申請ID', '申請日時', '区分', '申請種別', 'クラブ名', '対象大会', 'Iリーグのチーム', '選手名', 'フリガナ', '生年月日', '背番号', '位置', '選手登録番号', '役職', 'チーム責任者', 'スタッフメール', '申請者名', '申請者メール', '備考', '確認メモ', '申請状態', '運営コメント', '確認者', '承認日時', '反映内容']
      .forEach(function (k) { var v = r[k]; o[k] = v instanceof Date ? Utilities.formatDate(v, Session.getScriptTimeZone() || 'Asia/Tokyo', 'yyyy-MM-dd HH:mm') : String(v == null ? '' : v); });
    o.details = (detail[o['申請ID']] || []).map(function (d) {
      return { kind: String(d['区分']), row: String(d['行']), no: String(d['背番号'] || ''), name: String(d['氏名'] || ''), kana: String(d['フリガナ'] || ''), grade: String(d['生年月日'] || ''), pos: String(d['位置'] || ''), regno: String(d['選手登録番号'] || ''), role: String(d['役職'] || ''), status: String(d['判定'] || ''), memo: String(d['メモ'] || '') };
    });
    return o;
  });
  list.sort(function (a, b) {
    var pa = a['申請状態'] === '確認待ち' ? 0 : 1, pb = b['申請状態'] === '確認待ち' ? 0 : 1;
    return pa - pb || (a['申請日時'] < b['申請日時'] ? 1 : -1);
  });
  var status = [];
  if (typeof bkRegistrationStatus_ === 'function') {
    adRead_('大会マスター').forEach(function (c) {
      var id = String(c['大会ID'] || '');
      if (AD_SKIP.test(id) || !bkCompLabel_(id)) return;
      status.push({ comp: id, name: String(c['大会名'] || id), deadline: bkYmd_(c['登録締切日']), teams: bkRegistrationStatus_(id) });
    });
  }
  return { requests: list.slice(0, 200), status: status };
}

function adminDecideRequest(tok, reqId, action, comment) {
  adCheck_(tok);
  if (['承認', '却下'].indexOf(action) < 0) throw new Error('操作が正しくありません');
  var r = objs_(シート.選手登録申請).filter(function (x) { return String(x['申請ID']) === String(reqId); })[0];
  if (!r) throw new Error('申請が見つかりません');
  if (String(r['申請状態']) !== '確認待ち') throw new Error('この申請はすでに「' + r['申請状態'] + '」です');
  update_(シート.選手登録申請, r._row, { '申請状態': action, '運営コメント': String(comment || ''), '確認者': 'ダッシュボード' });
  var msg = applyApprovedRegistrations('ダッシュボード');
  var after = objs_(シート.選手登録申請).filter(function (x) { return String(x['申請ID']) === String(reqId); })[0] || {};
  return { ok: String(after['申請状態']) !== '確認待ち', message: String(after['反映内容'] || msg) };
}

function adminSaveDeadline(tok, compId, ymd) {
  adCheck_(tok);
  ensureHeader_(シート.大会, ['登録締切日']);
  if (ymd && !/^\d{4}-\d{2}-\d{2}$/.test(ymd)) throw new Error('日付は 2027-04-10 の形で入力してください');
  var c = objs_(シート.大会).filter(function (x) { return String(x['大会ID']) === String(compId); })[0];
  if (!c) throw new Error('大会が見つかりません');
  update_(シート.大会, c._row, { '登録締切日': ymd ? "'" + ymd : '' });
  var hasTrigger = ScriptApp.getProjectTriggers().some(function (t) { return t.getHandlerFunction() === 'sendRegistrationReminders'; });
  if (ymd && !hasTrigger && typeof sendRegistrationReminders === 'function') {
    ScriptApp.newTrigger('sendRegistrationReminders').timeBased().everyDays(1).atHour(9).create();
    if (!String(cfg_('登録リマインド（締切の何日前）') || '')) setCfg_('登録リマインド（締切の何日前）', '7,3,1', '登録締切の何日前にリマインドを送るか（カンマ区切り。0は締切当日）');
  }
  return { ok: true, message: ymd ? '登録締切日を ' + ymd + ' にしました。締切の7日前・3日前・前日の朝9時に未提出クラブへリマインドが届きます。' : '登録締切日を消しました' };
}

// ─────────────────────── 処分 ───────────────────────

/** 高速化：読むだけの処理は同じシートを1回だけ読む */
function adminSanctions(tok) {
  return withReadMemo_(function () { return adminSanctionsRead_(tok); });
}

function adminSanctionsRead_(tok) {
  adCheck_(tok);
  var tn = adTeamNames_();
  var pn = {};
  adRead_('選手マスター').forEach(function (p) { pn[String(p['選手ID'])] = String(p['氏名'] || ''); });
  return adRead_('処分管理').filter(function (s) { return !AD_SKIP.test(String(s['大会ID'] || '')); }).map(function (s) {
    var o = {};
    ['処分ID', '処分種別', '大会ID', '発生試合ID', '停止試合数', '残り試合数', '対象試合', '処分状態', '根拠条文', '認定事実', '委員会確認', '確認者', '確認コメント'].forEach(function (k) { o[k] = String(s[k] == null ? '' : s[k]); });
    o.player = pn[String(s['選手ID'])] || String(s['選手ID'] || '');
    o.team = tn[String(s['チームID'])] || String(s['チームID'] || '');
    var kind = o['処分種別'];
    o.pending = !(o['委員会確認'] === '確認済' || /決定/.test(o['処分状態'])) && Number(o['残り試合数']) !== 0 &&
      ['一発退場', '警告2枚による退場', '警告累積'].indexOf(kind) >= 0;
    return o;
  }).sort(function (a, b) { return (b.pending - a.pending) || (a['発生試合ID'] < b['発生試合ID'] ? 1 : -1); });
}

function adminSanctionAction(tok, sid, action, games, comment) {
  adCheck_(tok);
  if (typeof submitSanctionConfirm !== 'function' || typeof rvToken_ !== 'function') throw new Error('ReviewNotify.gs がありません');
  return submitSanctionConfirm(sid, rvToken_(sid), action, games, '運営（ダッシュボード）', comment || '');
}

// ─────────────────────── 取込の確認 ───────────────────────

function adImportRows_() {
  var sh = adSs_().getSheetByName('結果取込の確認');
  if (!sh || sh.getLastRow() < 2) return [];
  var v = sh.getDataRange().getDisplayValues(), h = v[0];
  return v.slice(1).map(function (a, i) {
    var r = {};
    h.forEach(function (k, j) { r[k] = a[j]; });
    r._blank = !a.join('');
    return r;
  }).map(function (r, i) {
    var note = String(r['注意'] || ''), chk = String(r['確認'] || '');
    return { row: i + 2, matchId: String(r['試合ID'] || ''), comp: String(r['大会・節'] || ''), date: adDate_(r['試合日']), home: String(r['ホーム'] || ''),
      score: String(r['スコア'] || ''), away: String(r['アウェイ'] || ''), homeScorers: String(r['ホーム得点者'] || ''), awayScorers: String(r['アウェイ得点者'] || ''),
      note: note, check: chk, needs: /要確認/.test(chk) || (!!note && !/確認済/.test(chk)), blank: r._blank };
  }).filter(function (r) { return !r.blank; });
}

function adNameReviews_() {
  var out = [];
  [['選手名寄せの確認', 'merge'], ['選手名簿の照合', 'roster']].forEach(function (x) {
    var sh = adSs_().getSheetByName(x[0]);
    if (!sh || sh.getLastRow() < 2) return;
    var v = sh.getDataRange().getDisplayValues();
    var h = v[0];
    var ci = h.indexOf('確認');
    v.slice(1).forEach(function (r, i) {
      if (!r.join('')) return;
      out.push({ sheet: x[0], kind: x[1], row: i + 2, cells: r.filter(function (_, j) { return j !== ci; }), headers: h.filter(function (_, j) { return j !== ci; }),
        check: ci >= 0 ? r[ci] : '', done: ci >= 0 && /確認済|OK|済/.test(r[ci]) });
    });
  });
  return out;
}

/** 高速化：読むだけの処理は同じシートを1回だけ読む */
function adminImports(tok) {
  return withReadMemo_(function () { return adminImportsRead_(tok); });
}

function adminImportsRead_(tok) {
  adCheck_(tok);
  return { results: adImportRows_(), names: adNameReviews_() };
}

function adminMarkChecked(tok, sheet, row, value) {
  adCheck_(tok);
  if (['結果取込の確認', '選手名寄せの確認', '選手名簿の照合'].indexOf(sheet) < 0) throw new Error('シートが正しくありません');
  var sh = adSs_().getSheetByName(sheet);
  var h = sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0].map(String);
  var c = h.indexOf('確認');
  if (c < 0) { c = h.length; sh.getRange(1, c + 1).setValue('確認'); }
  sh.getRange(Number(row), c + 1).setValue(value === '' ? '' : (value || '確認済') + ' ' + adToday_());
  return { ok: true };
}

// ─────────────────────── チーム ───────────────────────

/** 高速化：読むだけの処理は同じシートを1回だけ読む */
function adminTeams(tok) {
  return withReadMemo_(function () { return adminTeamsRead_(tok); });
}

function adminTeamsRead_(tok) {
  adCheck_(tok);
  var regs = {};
  adRead_('選手登録').forEach(function (r) { if (String(r['登録状態']) === '有効') regs[String(r['チームID'])] = (regs[String(r['チームID'])] || 0) + 1; });
  var base = typeof webAppBaseUrl_ === 'function' ? webAppBaseUrl_() : '';
  return adRead_('チームマスター').filter(function (t) { return !AD_SKIP.test(String(t['大会ID'] || '')); }).map(function (t) {
    var code = typeof rgTeamCode_ === 'function' ? rgTeamCode_(t['チームID']) : '';
    return {
      id: String(t['チームID']), comp: String(t['大会ID']), univ: String(t['クラブ名'] || ''), name: String(t['チーム名'] || ''), short: String(t['略称'] || ''),
      coach: String(t['監督名'] || ''), coachMail: String(t['監督メール'] || ''), resp: String(t['チーム責任者'] || ''), respMail: String(t['責任者メール'] || ''),
      players: regs[String(t['チームID'])] || 0,
      bulk: base && code && typeof bkToken_ === 'function' ? base + '?page=bulk&u=' + encodeURIComponent(code) + '&t=' + bkToken_(code) : ''
    };
  });
}

function adminSaveTeam(tok, teamId, p) {
  adCheck_(tok);
  p = p || {};
  var mail = function (v) { v = String(v || '').trim(); if (v && !/^[^@\s]+@[^@\s]+$/.test(v)) throw new Error('メールアドレスを確認してください：' + v); return v; };
  ensureHeader_(シート.チーム, ['監督名', '監督メール', 'チーム責任者', '責任者メール']);
  var t = objs_(シート.チーム).filter(function (x) { return String(x['チームID']) === String(teamId); })[0];
  if (!t) throw new Error('チームが見つかりません');
  var up = { '監督名': String(p.coach || '').trim(), '監督メール': mail(p.coachMail), 'チーム責任者': String(p.resp || '').trim(), '責任者メール': mail(p.respMail) };
  update_(シート.チーム, t._row, up);
  // 同じクラブの他の大会のチームにも反映（空欄のところだけ）
  var n = 0;
  if (p.applyAll) {
    objs_(シート.チーム).forEach(function (x) {
      if (String(x['クラブ名']) !== String(t['クラブ名']) || String(x['チームID']) === String(teamId) || AD_SKIP.test(String(x['大会ID']))) return;
      var fill = {};
      Object.keys(up).forEach(function (k) { if (up[k] && !String(x[k] || '').trim()) fill[k] = up[k]; });
      if (Object.keys(fill).length) { update_(シート.チーム, x._row, fill); n++; }
    });
  }
  return { ok: true, message: '保存しました' + (n ? '（同じクラブの他のチーム ' + n + '件の空欄にも入れました）' : '') };
}

function adminRunUpdate(tok) {
  adCheck_(tok);
  runHourlyUpdate();
  return { ok: true, message: '処分・順位表・ダッシュボードを更新しました' };
}

// ─────────────────────── 処分通知（NoticeFlow.gs） ───────────────────────

/** 高速化：読むだけの処理は同じシートを1回だけ読む */
function adminNotices(tok) {
  return withReadMemo_(function () { return adminNoticesRead_(tok); });
}

function adminNoticesRead_(tok) {
  adCheck_(tok);
  if (typeof ntList_ !== 'function') throw new Error('NoticeFlow.gs がありません');
  return ntList_().filter(function (x) { return !/TEST|KIRIN/i.test(x.origin); });
}

/** 公式記録の版の履歴と、前の版からの変更点（Revision.gs） */
function adminRecordHistory(tok, matchId) {
  adCheck_(tok);
  if (typeof revHistory_ !== 'function') throw new Error('Revision.gs が古い版です。最新版に差し替えてください');
  return withReadMemo_(function () { return revHistory_(matchId); });
}

/** これまでの決定通知（履歴） */
function adminNoticeHistory(tok) {
  adCheck_(tok);
  return typeof ntHistory_ === 'function' ? withReadMemo_(function () { return ntHistory_(); }) : [];
}

/** 出場停止中の処分ごとの決定通知の状況（作られていない理由） */
function adminNoticeCheck(tok) {
  adCheck_(tok);
  return typeof ntDiagnose_ === 'function' ? withReadMemo_(function () { return ntDiagnose_(); }) : [];
}

function adminNoticeAction(tok, nid, action, data) {
  adCheck_(tok);
  data = data || {};
  if (action === 'build') {
    var made = buildNoticeDrafts();
    var errs = typeof NT_LAST_ERRORS !== 'undefined' ? NT_LAST_ERRORS : [];
    var msg = made.length ? made.length + '件の決定通知を作成しました。\n' + (typeof NT_LAST_SEND !== 'undefined' ? NT_LAST_SEND : '') : '新しく作る決定通知はありません（下の「出場停止中の処分と決定通知」で理由を確認できます）';
    if (errs.length) msg += '\n' + errs.join('\n');
    return { ok: !errs.length, message: msg };
  }
  if (action === 'redo') return { ok: true, message: redoPreSystemNotices(nid ? [nid] : null) };
  var r = ntRows_().filter(function (x) { return String(x['通知ID']) === String(nid); })[0];
  if (!r) throw new Error('通知が見つかりません');
  if (action === 'request') {
    if (String(r['状態']) !== '承認待ち') throw new Error('承認待ちの通知ではありません');
    var res = ntRequestApproval_([nid]) || {};
    return { ok: !!res.ok, message: res.summary || (res.ok ? '規律委員会へ承認依頼を送りました' : '送信できませんでした：' + res.error) };
  }
  if (action === 'rebuild') return { ok: true, message: ntEditAndRebuild_(nid, data.basis, data.fact) };
  if (action === 'send') {
    if (String(r['状態']) !== '承認') throw new Error('規律委員会の承認が済んだ通知だけ送れます');
    return { ok: true, message: sendSanctionNoticesFor(String(r['対象試合日'])) };
  }
  throw new Error('操作が正しくありません');
}

;
// ==== live.gs
/**
 * Live.gs v1
 * 試合中の記録（第4の審判がスマホで「交代」「得点」「警告・退場」をその場で記録する）
 *
 *  ・ページ：WebアプリURL?page=live&match=試合ID&t=合言葉（試合ごと）
 *    リンクは、運営クラブが「審判団の連絡先」に第4の審判のメールを入れると、スタメンと一緒に届く（LineupFlow.gs）。
 *    運営クラブのページ・運営ダッシュボードからも開ける（メールがないときは、運営クラブがリンクを渡す）。
 *  ・選手は、運営クラブが確認したスタメン（なければ、その日に有効な登録選手）から選ぶ。
 *  ・時間は、各時間帯の「開始」を押した時刻からの経過分を自動で入れる（直すこともできる）。
 *  ・記録は「ライブ記録」タブに残る。公式記録の入力画面で「第4の審判の記録を取り込む」を押すと、
 *    得点・交代・警告退場に入る（記録担当が確認・修正してから提出する）。
 *  ・電波が弱いときは端末にためておき、つながったら送る（同じ記録を二重に入れない）。
 */

var LV = {
  SHEET: 'ライブ記録',
  COLS: ['記録ID', '試合ID', '種類', '時間帯', '時間', 'チームID', '選手ID', '選手ID2', '種別', '理由', '入力者', '入力日時', '状態'],
  KINDS: { goal: '得点', sub: '交代', card: '懲戒', start: '開始' },
  PERIODS: ['前半', '後半', '延長前半', '延長後半']
};

function lvToken_(mid) { return rvToken_('LIVE:' + mid); }
function lvAuth_(mid, t) {
  if (!mid || String(t || '') !== lvToken_(mid)) throw new Error('リンクが正しくありません。メールのリンクから開き直してください');
  return findMatch_(mid);
}
function lvRows_() { lnSheet_(LV.SHEET, LV.COLS); return objs_(LV.SHEET); }
function lvNow_() { return Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm:ss'); }

/** この試合の記録ページのURL */
function liveUrl_(mid) {
  var base = (typeof linkBase_ === 'function' && linkBase_()) || webAppBaseUrl_();
  return base ? base + '?page=live&match=' + encodeURIComponent(mid) + '&t=' + lvToken_(mid) : '';
}

function livePage(e) {
  var p = (e && e.parameter) || {};
  var tpl = HtmlService.createTemplateFromFile('Live');
  tpl.liveMatch = String(p.match || '');
  tpl.liveToken = String(p.t || '');
  return tpl.evaluate().setTitle('試合中の記録')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1, viewport-fit=cover')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

/** ページを開いたとき：試合・両チームの選手・これまでの記録 */
function liveContext(mid, t) {
  return withReadMemo_(function () {
    var m = lvAuth_(mid, t);
    var info = lnMatchInfo_(m);
    var L = typeof lnForRecord_ === 'function' ? lnForRecord_(mid) : null;
    var side = function (tid, x) {
      var list = [];
      if (x && (x.starters || []).length) {
        (x.starters || []).forEach(function (p) { list.push({ pid: String(p.pid), no: String(p.no || ''), name: String(p.name || ''), pos: String(p.pos || ''), st: 's' }); });
        (x.bench || []).forEach(function (p) { list.push({ pid: String(p.pid), no: String(p.no || ''), name: String(p.name || ''), pos: String(p.pos || ''), st: 'b' }); });
      } else {
        // スタメンが出ていないとき：その日に有効な登録選手（先発・控えは画面で分からないので全員「控え」扱い）
        (typeof eligible_ === 'function' ? eligible_(tid, info.date) : []).forEach(function (p) {
          list.push({ pid: String(p.playerId), no: String(p.number || ''), name: String(p.name || ''), pos: '', st: 'b' });
        });
      }
      return { id: String(tid), name: info[tid === info.homeId ? 'home' : 'away'], short: lnTeamName_(tid), lineup: !!(x && (x.starters || []).length), players: list };
    };
    var comp = objs_(シート.大会).filter(function (c) { return String(c['大会ID']) === String(m['大会ID']); })[0] || {};
    return {
      match: info, home: side(info.homeId, L && L.home), away: side(info.awayId, L && L.away),
      extraTime: String(comp['延長戦'] || '') === 'あり',
      events: lvEvents_(mid), now: Date.now()
    };
  });
}

function lvEvents_(mid) {
  return lvRows_().filter(function (r) { return String(r['試合ID']) === String(mid) && String(r['状態']) !== '取消'; }).map(function (r) {
    return {
      id: String(r['記録ID']), kind: Object.keys(LV.KINDS).filter(function (k) { return LV.KINDS[k] === String(r['種類']); })[0] || '',
      period: String(r['時間帯'] || ''), time: String(r['時間'] || ''), teamId: String(r['チームID'] || ''),
      p1: String(r['選手ID'] || ''), p2: String(r['選手ID2'] || ''), type: String(r['種別'] || ''), reason: String(r['理由'] || ''),
      by: String(r['入力者'] || ''), at: r['入力日時'] instanceof Date ? r['入力日時'].getTime() : (Date.parse(String(r['入力日時'] || '').replace(' ', 'T') + '+09:00') || 0)
    };
  });
}

/** 記録を1件入れる（cid：端末で付けた番号。同じ番号は二重に入れない） */
function liveAdd(mid, t, ev) {
  lvAuth_(mid, t);
  ev = ev || {};
  var kind = String(ev.kind || '');
  if (!LV.KINDS[kind]) throw new Error('記録の種類が正しくありません');
  var cid = String(ev.cid || '').replace(/[^\w-]/g, '').slice(0, 40);
  if (!cid) throw new Error('記録の番号がありません');
  var period = String(ev.period || '');
  if (LV.PERIODS.indexOf(period) < 0) throw new Error('時間帯を選んでください');
  var time = String(ev.time || '').trim();
  if (kind !== 'start' && !/^\d{1,2}$/.test(time)) throw new Error('時間（その時間帯の経過分）を入れてください');
  if (kind === 'goal' && ev.type !== 'オウンゴール' && !ev.p1) throw new Error('得点者を選んでください');
  if (kind === 'sub' && (!ev.p1 || !ev.p2)) throw new Error('OUTとINの選手を選んでください');
  if (kind === 'card' && !ev.p1) throw new Error('選手を選んでください');
  var lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    var id = 'LV-' + cid;
    if (!lvRows_().some(function (r) { return String(r['記録ID']) === id; })) {
      append_(LV.SHEET, {
        '記録ID': id, '試合ID': "'" + mid, '種類': LV.KINDS[kind], '時間帯': period, '時間': kind === 'start' ? '' : "'" + time,
        'チームID': "'" + String(ev.teamId || ''), '選手ID': "'" + String(ev.p1 || ''), '選手ID2': "'" + String(ev.p2 || ''),
        '種別': String(ev.type || ''), '理由': String(ev.reason || ''), '入力者': String(ev.by || '').slice(0, 40), '入力日時': kind === 'start' && ev.at ? Utilities.formatDate(new Date(Number(ev.at)), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm:ss') : lvNow_(), '状態': '有効'
      });
    }
  } finally { lock.releaseLock(); }
  return { ok: true, events: lvEvents_(mid) };
}

/** 記録を取り消す */
function liveCancel(mid, t, id) {
  lvAuth_(mid, t);
  var r = lvRows_().filter(function (x) { return String(x['記録ID']) === String(id) && String(x['試合ID']) === String(mid); })[0];
  if (!r) throw new Error('記録が見つかりません');
  update_(LV.SHEET, r._row, { '状態': '取消' });
  return { ok: true, events: lvEvents_(mid) };
}

/** 最新の記録だけ（ほかの端末で入れた分を取り込む） */
function liveEvents(mid, t) {
  lvAuth_(mid, t);
  return { events: lvEvents_(mid), now: Date.now() };
}

/** 公式記録の入力画面へ：第4の審判の記録を、得点・交代・警告退場の形にして渡す */
function liveEventsForRecord_(mid) {
  try {
    if (!ss_().getSheetByName(LV.SHEET)) return null;
    var ev = lvEvents_(mid).filter(function (e) { return e.kind !== 'start'; });
    if (!ev.length) return null;
    var out = { goals: [], subs: [], cards: [] };
    ev.forEach(function (e) {
      var base = { id: 'lv_' + e.id.replace(/^LV-/, ''), period: e.period, time: e.time, teamId: e.teamId };
      if (e.kind === 'goal') out.goals.push(Object.assign(base, { scorerId: e.type === 'オウンゴール' ? '' : e.p1, assistId: e.p2 || '',
        goalType: e.type === 'PK' ? 'PK' : e.type === 'オウンゴール' ? 'オウンゴール' : 'シュート', startType: e.type === 'PK' ? 'PK' : '流れの中', seq: [] }));
      if (e.kind === 'sub') out.subs.push(Object.assign(base, { outId: e.p1, inId: e.p2 }));
      if (e.kind === 'card') out.cards.push(Object.assign(base, { playerId: e.p1, type: e.type === '一発退場' ? '一発退場' : '警告', reason: e.reason || '' }));
    });
    return out;
  } catch (e) { return null; }
}

;
// ==== mcreport.gs
/**
 * McReport.gs v1
 * マッチコミッショナー報告書（HKFAの様式）と、マッチコミッショナー緊急報告書を、スマホから入力する
 *
 *  ページ：WebアプリURL?page=mc（入口ページ経由：…github.io/hsl/?page=mc）
 *    試合を選ぶ → 大会名・チーム・競技場・審判員・結果・キックオフ・天候などは公式記録・日程から自動で入る
 *    評価（○△× ／ ◎○△×）はボタンで選ぶ。入力途中はスマホに自動保存
 *  提出すると
 *    「MC報告書」タブに記録、PDF（報告書＋緊急報告があれば緊急報告書）を書類フォルダの大会ごと「MC報告書」に保存
 *    緊急報告があれば、規律委員会のLINEへすぐ知らせる（ReviewNotify.gs。一発退場・問題事項と同じ送り先）
 *    事務局ページの「問題事項」タブ（MC報告書）と、試合の詳細から見られる
 *  同じ試合をもう一度提出すると、前のものは「差し替え」になる
 *  対象の試合：北海道リーグ・ブロックリーグ・決勝大会の全試合と、MC が決まっている上位大会の試合（mcTarget_）
 *
 *  新しいシステム：リーグシステムで入力 → 全体システムへ取り込み（Sync.gs）→ 全体システムが緊急報告をLINEで知らせる
 */

var MC = { SHEET: 'MC報告書' };
var MC_COLS = ['報告ID', '試合ID', '大会名', '節', 'マッチNo', '対戦A', '対戦B', '試合日', '会場', 'MC氏名',
  '緊急報告', '緊急報告内容', '内容（JSON）', 'PDF URL', '状態', '提出日時'];

/** 評価項目（様式の並び） */
var MC_ITEMS = {
  ops: ['運営担当は適切に任務を果たしていたか', 'スケジュール設定、進行は適切か', 'MCに対する協力は適切か',
    '担架要員、ボールパーソンの行動は適切か', 'メディア関係者への対応は適切か', '試合中のフィールド上の人員は適切か'],
  game: ['競技中のベンチスタッフのマナーは適切か', '選手は審判員の判定に素直に従っていたか', 'テクニカルエリアの使用は適切か', '選手は無用な反則を犯していなかったか'],
  sec: ['観客の安全は守られていたか', '選手、審判員の安全は守られていたか', '観客はサッカーを楽しんだか', 'サポーターのマナー及び応援態度は適切か'],
  main: ['試合のコントロールは適切か', '副審、第4の審判員との協力は適切か', '判定は一貫しているか', '姿勢・態度は毅然としていたか',
    'アドバンテージの適用は適切か', 'ホイッスル・ジェスチャーは分かり易かったか', '警告・退場は適切か', 'スタミナ・スピードは十分であったか',
    '選手とのコミュニケーションは適切か', 'ポジショニングは適切か'],
  ar: ['ポジショニングは適切か', '判定・シグナルは適切か', '姿勢・態度は毅然としていたか', '主審との協力は適切か'],
  fourth: ['ベンチコントロールは適切か', '交替選手の手続きは適切か', '主審・副審との協力は適切か', 'アディショナルタイムの表示は適切か']
};

/**
 * MC報告書を作る試合か
 *  北海道リーグ・3つのブロックリーグ・ブロックリーグ決勝大会：全試合（各要項「マッチコミッショナー」）
 *  上位大会の予選（社会人・クラブ・北海道選手権）：試合マスターの「マッチコミッショナー」に名前が入っている試合
 */
function mcTarget_(m, compName) {
  var cid = String(m['大会ID'] || ''), name = String(compName || '');
  if (/-(TOP|SD|DN|DT|BF)$/.test(cid) || /北海道サッカーリーグ|ブロックリーグ/.test(name)) return true;
  return String(m['マッチコミッショナー'] || '').trim() !== '';
}

function mcSheet_() { return lnSheet_(MC.SHEET, MC_COLS); }
function mcRows_() { mcSheet_(); return objs_(MC.SHEET); }
function mcNow_() { return Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm:ss'); }
function mcStr_(v, fmt) { return v instanceof Date ? Utilities.formatDate(v, 'Asia/Tokyo', fmt) : String(v == null ? '' : v); }
function mcEsc_(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function mcLatest_(mid) {
  var l = mcRows_().filter(function (r) { return String(r['試合ID']) === String(mid) && String(r['状態']) !== '差し替え'; });
  return l[l.length - 1] || null;
}

function mcPage(e) {
  return HtmlService.createTemplateFromFile('McReport').evaluate()
    .setTitle('マッチコミッショナー報告書')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1, viewport-fit=cover')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

/** 試合の一覧（昨日以降のすべて。試合日から2日以上たったもの・中止は出さない） */
function mcBootstrap() {
  return withReadMemo_(function () {
    var from = Utilities.formatDate(new Date(Date.now() - 1 * 86400000), 'Asia/Tokyo', 'yyyy-MM-dd');
    var to = '9999-12-31';
    var done = {};
    mcRows_().forEach(function (r) { if (String(r['状態']) !== '差し替え') done[String(r['試合ID'])] = true; });
    var comps = {};
    objs_(シート.大会).forEach(function (c) { comps[String(c['大会ID'])] = String(c['大会名'] || c['大会ID']); });
    var list = objs_(シート.試合).filter(function (m) {
      var d = matchDateYmd_(m);
      return d && d >= from && d <= to && String(m['試合状態'] || '') !== '中止' && !/TEST|KIRIN/i.test(String(m['大会ID'] || '')) &&
        mcTarget_(m, comps[String(m['大会ID'])]) &&
        (typeof isLeague_ !== 'function' || !isLeague_() || inMyComps_(m['試合ID']));
    }).map(function (m) {
      var info = lnMatchInfo_(m);
      return { id: info.id, compId: String(m['大会ID'] || ''), date: info.date, kickoff: info.kickoff, comp: comps[String(m['大会ID'])] || info.comp, round: info.round, no: info.no,
        home: info.home, away: info.away, venue: info.venue, done: !!done[info.id] };
    }).sort(function (a, b) { return (a.date + a.kickoff + a.no < b.date + b.kickoff + b.no) ? -1 : 1; });
    return { matches: list, items: MC_ITEMS };
  });
}

/** 試合の情報（公式記録・日程から）と、提出済みの内容 */
function mcMatchDetail(mid) {
  return withReadMemo_(function () {
    var m = findMatch_(mid);
    var info = lnMatchInfo_(m);
    var c = objs_(シート.大会).filter(function (x) { return String(x['大会ID']) === String(m['大会ID']); })[0] || {};
    var rec = typeof latestOfficialRecordForMatch_ === 'function' ? latestOfficialRecordForMatch_(mid) : null;
    var R = function (k) { return rec ? String(rec[k] == null ? '' : rec[k]) : ''; };
    var n = function (k) { var v = rec ? rec[k] : ''; return v === '' || v == null ? '' : String(v); };
    // 審判員：公式記録 → 運営クラブが入れた審判連絡先 → 日程
    var ref = (typeof lnRefRows_ === 'function' ? lnRefRows_() : []).filter(function (r) { return String(r['試合ID']) === String(mid); })[0] || {};
    var ars = String(m['副審'] || '').split(/[・、,／\/]/);
    var refs = {
      main: R('主審') || String(ref['主審'] || '') || String(m['主審'] || ''),
      ar1: R('副審1') || String(ref['副審1'] || '') || (ars[0] || ''),
      ar2: R('副審2') || String(ref['副審2'] || '') || (ars[1] || ''),
      fourth: R('第4の審判') || String(ref['第4の審判'] || '') || String(m['第4審'] || '')
    };
    var hs = m['ホーム得点'], as = m['アウェイ得点'];
    var score = rec ? {
      h1: [n('前半ホーム得点'), n('前半アウェイ得点')], h2: [n('後半ホーム得点'), n('後半アウェイ得点')],
      et: [n('延長ホーム得点'), n('延長アウェイ得点')], pk: [n('PK戦ホーム'), n('PK戦アウェイ')]
    } : { h1: ['', ''], h2: ['', ''], et: ['', ''], pk: [String(m['ホームPK'] == null ? '' : m['ホームPK']), String(m['アウェイPK'] == null ? '' : m['アウェイPK'])] };
    score.total = [hs === '' || hs == null ? '' : String(hs), as === '' || as == null ? '' : String(as)];
    var last = mcLatest_(mid);
    var saved = null;
    if (last) { try { saved = JSON.parse(String(last['内容（JSON）'] || '')); } catch (e) {} }
    return {
      match: { id: info.id, comp: String(c['正式名称'] || c['大会名'] || info.comp), round: info.round, no: info.no, home: info.home, away: info.away,
        date: info.date, kickoff: info.kickoff, venue: R('会場名') || info.venue },
      prefill: { refs: refs, score: score, weather: R('天候'), pitch: R('ピッチ状態'),
        ko1: R('前半キックオフ時刻') || '', ko2: R('後半キックオフ時刻') || '' },
      saved: saved, submittedAt: last ? mcStr_(last['提出日時'], 'yyyy-MM-dd HH:mm') : '', pdf: last ? String(last['PDF URL'] || '') : ''
    };
  });
}

/** 提出（d：入力内容。mcName 必須） */
function mcSubmit(mid, d) {
  d = d || {};
  var name = String(d.mcName || '').trim();
  if (!name) throw new Error('MC氏名を入力してください');
  if (d.emergency && d.emergency.on && !String(d.emergency.text || '').trim()) throw new Error('緊急報告の内容を書いてください');
  var m = findMatch_(mid);
  var c0 = objs_(シート.大会).filter(function (x) { return String(x['大会ID']) === String(m['大会ID']); })[0] || {};
  if (!mcTarget_(m, c0['大会名'])) throw new Error('この試合はマッチコミッショナー報告書の対象ではありません（北海道リーグ・ブロックリーグ・決勝大会の全試合と、マッチコミッショナーが決まっている試合が対象です）');
  var det = mcMatchDetail(mid);
  var M = det.match;
  var pdf = null;
  try { pdf = mcCreatePdf_(M, d); } catch (e) { try { log_('MC報告書PDFエラー', 'MC報告書', mid, null, null, String(e && e.message || e)); } catch (x) {} }
  var lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    mcRows_().forEach(function (r) { if (String(r['試合ID']) === String(mid) && String(r['状態']) !== '差し替え') update_(MC.SHEET, r._row, { '状態': '差し替え' }); });
    var em = d.emergency && d.emergency.on;
    var vals = {
      '報告ID': id_('MCR'), '試合ID': String(mid), '大会名': M.comp, '節': M.round, 'マッチNo': M.no, '対戦A': M.home, '対戦B': M.away,
      '試合日': "'" + M.date, '会場': M.venue, 'MC氏名': name, '緊急報告': em ? 'あり' : '', '緊急報告内容': em ? String(d.emergency.text).trim() : '',
      '内容（JSON）': JSON.stringify(d), 'PDF URL': pdf ? pdf.getUrl() : '', '状態': '提出', '提出日時': "'" + mcNow_()
    };
    mcSheet_().appendRow(MC_COLS.map(function (k) { return vals[k] == null ? '' : vals[k]; }));
    if (typeof memoForget_ === 'function') memoForget_(MC.SHEET);
  } finally { lock.releaseLock(); }
  if (d.emergency && d.emergency.on && typeof icNotifySoon_ === 'function') icNotifySoon_();
  return { ok: true, pdf: pdf ? pdf.getUrl() : '', message: 'マッチコミッショナー報告書を提出しました' + (d.emergency && d.emergency.on ? '。緊急報告を規律委員会へ知らせます' : '') + '。' };
}

// ─────────────────────── PDF（スプレッドシートの様式に書き込む） ───────────────────────
/*
 *  様式は、このスプレッドシートのタブ（MC_TPL）。{{項目名}} の所に入力内容が入る。
 *  罫線・文字の大きさ・並びはタブの上で自由に直してよい（{{ }} を消さなければ動く）。
 *  タブが無いときは自動で作る。メニュー「MC報告書の様式を作り直す」で初期の形に戻せる。
 *  PDF：一時的なスプレッドシートに様式を写して書き込み → PDFにして → 一時ファイルは削除
 */
var MC_TPL = { p1: 'MC報告書テンプレート1', p2: 'MC報告書テンプレート2', em: 'MC緊急報告書テンプレート' };

function mcRoundNo_(r) { var m = String(r || '').match(/第?\s*(\d+)\s*(節|回戦)/); return m ? m[1] : String(r || ''); }
function mcJDate_(ymd) {
  var m = String(ymd || '').match(/(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return '';
  var dt = new Date(+m[1], +m[2] - 1, +m[3]);
  return m[1] + '年 ' + (+m[2]) + '月 ' + (+m[3]) + '日 （' + '日月火水木金土'.charAt(dt.getDay()) + '）';
}

/** {{項目名}} → 値 */
function mcFillMap_(M, d) {
  var S = d.score || {}, K = d.ko || {}, k1 = K.h1 || {}, k2 = K.h2 || {}, R = d.refs || {}, D = d.delay || {};
  var pair = function (k) { var a = S[k] || []; var x = a[0] == null ? '' : String(a[0]), y = a[1] == null ? '' : String(a[1]); return x === '' && y === '' ? '' : x + ' ： ' + y; };
  var f = {
    '大会名': M.comp, '節': mcRoundNo_(M.round), 'MC氏名': d.mcName, '左チーム': M.home, '右チーム': M.away, '競技場名': M.venue,
    '合計': pair('total'), '前半': pair('h1'), '後半': pair('h2'), '延長': pair('et'), 'PK': pair('pk'),
    '開催日': mcJDate_(M.date), '試合日時': mcJDate_(M.date) + '　' + (k1.actual || M.kickoff || ''),
    '前半KO': k1.actual, '前半指定': k1.scheduled, '前半AT': k1.add, '後半KO': k2.actual, '後半指定': k2.scheduled, '後半AT': k2.add,
    '遅延前半': D.h1, '遅延後半': D.h2, '審判アセッサー': d.assessor,
    '主審': R.main, '副審1': R.ar1, '副審2': R.ar2, '第4': R.fourth,
    '入場者数': d.attendance, '天候': d.weather, '気温': d.temp, '湿度': d.humidity, 'ピッチ状況': d.pitch, '競技場の状態': d.stadium,
    '運営コメント': d.opsNote, '競技コメント': d.gameNote, 'セキュリティコメント': d.secNote, '審判員コメント': d.refNote, '特記事項': d.notes,
    '緊急報告内容': (d.emergency || {}).text, '報告日': mcJDate_(mcNow_().slice(0, 10)).replace(/\s*（.）$/, ''), '署名': d.mcName
  };
  var ev = function (group, key, cols) {
    var g = d[group] || {};
    (MC_ITEMS[group] || []).forEach(function (it, i) {
      if (cols) cols.forEach(function (c, j) { f[key + (i + 1) + ['L', 'R'][j]] = (g[it] || {})[c] || ''; });
      else f[key + (i + 1)] = g[it] || '';
    });
  };
  ev('ops', '運営'); ev('game', '競技', ['左', '右']); ev('sec', 'セキュリティ', ['左', '右']);
  ev('main', '主審'); ev('ar', '副審', ['A1', 'A2']); ev('fourth', '第4の');
  Object.keys(f).forEach(function (k) { f[k] = f[k] == null ? '' : String(f[k]); });
  return f;
}

function mcCreatePdf_(M, d) {
  var ss = ss_();
  mcEnsureTemplates_(false);
  var names = [MC_TPL.p1, MC_TPL.p2].concat(d.emergency && d.emergency.on ? [MC_TPL.em] : []);
  var map = mcFillMap_(M, d);
  var tmp = SpreadsheetApp.create('MC報告書_作業用_' + M.id);
  try {
    var first = tmp.getSheets()[0];
    names.forEach(function (n, i) {
      var sh = ss.getSheetByName(n).copyTo(tmp).setName('p' + (i + 1));
      var rg = sh.getDataRange(), v = rg.getValues();
      var changed = v.map(function (row) {
        return row.map(function (x) { return typeof x === 'string' && x.indexOf('{{') >= 0 ? x.replace(/\{\{([^}]+)\}\}/g, function (_, k) { return map[k] != null ? map[k] : ''; }) : x; });
      });
      rg.setValues(changed);
    });
    tmp.deleteSheet(first);
    SpreadsheetApp.flush();
    var url = 'https://docs.google.com/spreadsheets/d/' + tmp.getId() + '/export?format=pdf&size=A4&portrait=true&fitw=true' +
      '&gridlines=false&printtitle=false&sheetnames=false&pagenum=UNDEFINED&fzr=false' +
      '&top_margin=0.45&bottom_margin=0.45&left_margin=0.5&right_margin=0.5&horizontal_alignment=CENTER&vertical_alignment=TOP';
    var res = UrlFetchApp.fetch(url, { headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken() }, muteHttpExceptions: true });
    if (res.getResponseCode() !== 200) throw new Error('PDFの作成に失敗しました（' + res.getResponseCode() + '）');
    var name = (typeof docMatchName_ === 'function' ? docMatchName_(M.id, 'MC報告書') : 'MC報告書_' + M.id + '.pdf');
    var pdf = DriveApp.createFile(res.getBlob().setName(name));
    if (typeof fileDoc_ === 'function') fileDoc_(pdf, String(M.id).replace(/-[^-]+$/, ''), 'MC報告書', name);
    return pdf;
  } finally {
    try { DriveApp.getFileById(tmp.getId()).setTrashed(true); } catch (e) {}
  }
}

/** メニュー：様式を作り直す（いまのタブは「_旧」を付けて残す） */
function rebuildMcTemplates() {
  var msg = mcEnsureTemplates_(true);
  try { SpreadsheetApp.getUi().alert('MC報告書の様式', msg, SpreadsheetApp.getUi().ButtonSet.OK); } catch (e) {}
  return msg;
}

/** 様式のタブがなければ作る（force：作り直す） */
function mcEnsureTemplates_(force) {
  var ss = ss_(), made = [];
  [[MC_TPL.p1, mcBuildPage1_], [MC_TPL.p2, mcBuildPage2_], [MC_TPL.em, mcBuildEmergency_]].forEach(function (x) {
    var sh = ss.getSheetByName(x[0]);
    if (sh && !force) return;
    if (sh) sh.setName(x[0] + '_旧_' + Utilities.formatDate(new Date(), 'Asia/Tokyo', 'MMdd_HHmm'));
    sh = ss.insertSheet(x[0], ss.getSheets().length);
    mcGridInit_(sh);
    var last = x[1](mcPainter_(sh));
    if (last && sh.getMaxRows() > last) sh.deleteRows(last + 1, sh.getMaxRows() - last); // 余った行は消す（PDFに空白のページを出さない）
    made.push(x[0]);
  });
  return made.length ? '様式のタブを作りました：' + made.join('、') + '\n罫線・文字の大きさなどはタブの上で直せます（{{ }} の所に入力内容が入ります）' : '様式のタブはそろっています';
}

var MC_GRID = { cols: 24, w: 28, h: 21 };

function mcGridInit_(sh) {
  if (sh.getMaxColumns() > MC_GRID.cols) sh.deleteColumns(MC_GRID.cols + 1, sh.getMaxColumns() - MC_GRID.cols);
  if (sh.getMaxColumns() < MC_GRID.cols) sh.insertColumnsAfter(sh.getMaxColumns(), MC_GRID.cols - sh.getMaxColumns());
  sh.setColumnWidths(1, MC_GRID.cols, MC_GRID.w);
  var all = sh.getRange(1, 1, sh.getMaxRows(), MC_GRID.cols);
  all.setFontFamily('Noto Sans JP').setFontSize(9).setVerticalAlignment('middle').setNumberFormat('@').setFontColor('#222222');
  sh.setRowHeights(1, sh.getMaxRows(), MC_GRID.h);
  sh.setHiddenGridlines(true);
}

/** 書き込み用の道具（r：行、c1〜c2：列） */
function mcPainter_(sh) {
  var P = {
    sh: sh, row: 1,
    cell: function (r, c1, c2, text, o) {
      o = o || {};
      var rg = sh.getRange(r, c1, o.rows || 1, (c2 || c1) - c1 + 1);
      if ((c2 || c1) > c1 || (o.rows || 1) > 1) rg.merge();
      if (text != null) rg.getCell(1, 1).setValue(text);
      if (o.size) rg.setFontSize(o.size);
      if (o.bold) rg.setFontWeight('bold');
      rg.setHorizontalAlignment(o.align || 'left');
      if (o.valign) rg.setVerticalAlignment(o.valign);
      if (o.wrap) rg.setWrap(true);
      if (o.line) rg.setBorder(null, null, true, null, null, null, '#222222', SpreadsheetApp.BorderStyle.SOLID);
      if (o.box) rg.setBorder(true, true, true, true, null, null, '#222222', SpreadsheetApp.BorderStyle.SOLID);
      if (o.boxThick) rg.setBorder(true, true, true, true, null, null, '#222222', SpreadsheetApp.BorderStyle.SOLID_MEDIUM);
      return rg;
    },
    label: function (r, text, o) { P.cell(r, 1, 4, text, Object.assign({ size: (o && o.size) || 9 }, o || {})); P.cell(r, 5, 5, '：', { align: 'center' }); },
    height: function (r, h) { sh.setRowHeight(r, h); },
    /** 評価の並び（左右2列）：items＝様式の並び、key＝{{key1}}…、cols＝['L','R'] など */
    evalRows: function (r, items, key, cols, small) {
      for (var i = 0; i < items.length; i += 2) {
        [0, 1].forEach(function (k) {
          var it = items[i + k]; if (!it) return;
          var base = k ? 14 : 2, n = i + k + 1;
          if (cols) {
            P.cell(r, base, base, '{{' + key + n + 'L}}', { align: 'center', box: true, size: 10 });
            P.cell(r, base + 1, base + 1, '{{' + key + n + 'R}}', { align: 'center', box: true, size: 10 });
            P.cell(r, base + 2, base + 10, it, { size: small ? 7.5 : 8.5 });
          } else {
            P.cell(r, base, base + 1, '{{' + key + n + '}}', { align: 'center', box: true, size: 10 });
            P.cell(r, base + 2, base + 10, it, { size: 8.5 });
          }
        });
        P.height(r, 24);
        r++;
      }
      return r;
    },
    colHead: function (r, a, b) {
      [2, 14].forEach(function (c) { P.cell(r, c, c, a, { align: 'center', size: 7 }); P.cell(r, c + 1, c + 1, b, { align: 'center', size: 7 }); });
      P.height(r, 14);
    },
    noteLines: function (r, key, n) {
      var rg = P.cell(r, 2, 24, '{{' + key + '}}', { rows: n, wrap: true, valign: 'top', size: 9 });
      rg.setBorder(true, true, true, true, null, null, '#888888', SpreadsheetApp.BorderStyle.SOLID);
      return r + n;
    }
  };
  return P;
}

