function adminMcReports(tok) {
  adCheck_(tok);
  return withReadMemo_(function () {
    return mcRows_().filter(function (r) { return String(r['状態']) !== '差し替え'; }).map(function (r) {
      return { id: String(r['報告ID']), matchId: String(r['試合ID']), comp: String(r['大会名'] || ''), round: String(r['節'] || ''), no: String(r['マッチNo'] || ''),
        home: String(r['対戦A'] || ''), away: String(r['対戦B'] || ''), date: mcStr_(r['試合日'], 'yyyy-MM-dd'), venue: String(r['会場'] || ''),
        mc: String(r['MC氏名'] || ''), emergency: String(r['緊急報告'] || '') === 'あり', emergencyText: String(r['緊急報告内容'] || ''),
        pdf: String(r['PDF URL'] || ''), at: mcStr_(r['提出日時'], 'yyyy-MM-dd HH:mm') };
    }).sort(function (a, b) { return a.date < b.date ? 1 : -1; });
  });
}

/** 試合ごとのMC報告書のPDF（試合一覧用） */
function mcPdfByMatch_() {
  var o = {};
  mcRows_().forEach(function (r) { if (String(r['状態']) !== '差し替え') o[String(r['試合ID'])] = { pdf: String(r['PDF URL'] || ''), emergency: String(r['緊急報告'] || '') === 'あり' }; });
  return o;
}

;
// ==== newsadmin.gs
/**
 * NewsAdmin.gs v7
 * ホームページの管理画面（連盟用・クラブ用）
 *  v7：クラブの担当者は「メールのリンクでログイン」（1回だけ・15分有効）。責任者と広報担当の権限。保存した人を「更新者」に残す
 *      担当者（メールアドレス・クラブ・役割）はスクリプトプロパティ NEWSADMIN_MEMBERS に保存（シートには書かない）
 *      広報担当：チームニュース・ギャラリーだけ／責任者：クラブの画面すべて＋自分のクラブの広報担当の登録・停止
 *      クラブごとの合言葉は、移行のあいだ「合言葉でログイン」から使える（責任者の扱い）
 *  v6：チーム紹介の「理念」「歴史」「入部案内」「入部の問い合わせ」、クラブの「ギャラリー」「スポンサー」
 *  v5：チーム紹介の「エンブレム（暗い背景用）」
 *  v4：トップ写真の「大会」
 *  v3：連盟の「トップ写真」、お知らせの「写真」
 *  v2：クラブ専用管理画面（チーム紹介・選手名鑑・チームニュース）／クラブアカウント
 *
 *  ・WebアプリのURL ＋ ?page=newsadmin で開く（画面は NewsAdmin.html）
 *  ・ログイン：「連盟」またはクラブ名を選んで合言葉
 *      連盟 … setupNewsAdmin で決めた合言葉。すべて編集でき、クラブアカウントを発行・停止できる
 *      クラブ … 連盟が管理画面の「クラブアカウント」で発行した合言葉。自分のクラブの分だけ編集できる
 *    合言葉はハッシュにしてスクリプトプロパティに保存（シートには書かない）
 *  ・クラブが保存した内容はすぐ公開。連盟は「連盟による非公開」でいつでも止められる（クラブからは解除できない）
 *  ・選手名鑑の背番号・氏名・ポジション・生年月日は公式登録（選手登録・選手マスター）のまま。クラブは写真・出身校・ひとこと・掲載の有無だけ
 *  ・選手写真は「本人の同意を得ています」にチェックがないと保存できない
 *
 *  最初に1回：スプレッドシートのメニュー「ホームページ管理画面の合言葉を決める」（setupNewsAdmin）で連盟の合言葉を決める
 *    ※エディタから実行すると、合言葉の入力欄がスプレッドシート側に出るため「不明なエラー」になることがある
 *  Code.gs の doGet に1行：  if (e && e.parameter && e.parameter.page === 'newsadmin') return newsAdminPage_(e);
 *  コードを変えたら「デプロイを管理」→ 新バージョン
 */

var NADM = {
  passKey: 'NEWSADMIN_PASS_HASH', accKey: 'NEWSADMIN_UNIV_ACCOUNTS', folderKey: 'NEWSADMIN_FOLDER_ID', memKey: 'NEWSADMIN_MEMBERS', linkTtl: 900,
  folderName: 'ホームページ用ファイル', ttl: 21600, maxFails: 8, lockSec: 600, maxUpload: 10 * 1024 * 1024
};
var TEAMNEWS_SHEET = 'チームニュース';
var TEAMNEWS_HEADS = ['クラブ名', '日付', '種類', 'タイトル', '本文', '写真', 'リンク', '公開', '連盟による非公開', '更新日'];
var TEAMNEWS_KINDS = ['試合告知', '活動報告', '部員募集', 'その他'];
var SUPP_SHEET = '選手名鑑補足';
var SUPP_HEADS = ['選手ID', 'クラブ名', '氏名', '掲載', '写真', '写真同意', '出身校', 'コメント', '連盟による非公開', '更新日'];
var PROFILE_EXTRA_HEADS = ['チーム写真', 'プレビュー用キー']; // プレビュー用キー：独自ホームページを公開前に見るための合言葉（画面には出さない）

// News.gs がなくても・古くても動くように、この画面で使うものはここで用意する
function nadmSs_() { return typeof ss_ === 'function' ? ss_() : SpreadsheetApp.getActiveSpreadsheet(); }
function nadmToday_() { return Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd'); }
function nadmNewsSheet_() { return typeof NEWS_SHEET !== 'undefined' ? NEWS_SHEET : 'お知らせ'; }
function nadmAboutSheet_() { return typeof ABOUT_SHEET !== 'undefined' ? ABOUT_SHEET : '連盟ページ'; }
function nadmHeroSheet_() { return typeof HERO_SHEET !== 'undefined' ? HERO_SHEET : 'トップ写真'; }
function nadmHeroHeads_() { return typeof HERO_HEADS !== 'undefined' ? HERO_HEADS : ['写真', 'キャプション', '撮影者', 'リンク', '並び順', '写真同意', '公開', '更新日', '大会']; }
function nadmHeroAll_() { return typeof HERO_ALL !== 'undefined' ? HERO_ALL : 'すべての大会'; }
function nadmAboutKinds_() { return typeof ABOUT_KINDS !== 'undefined' ? ABOUT_KINDS : { '概要': 'overview', '書類': 'documents', 'リンク': 'links', '問い合わせ': 'contact' }; }

// ─────────────────────── 画面 ───────────────────────

function newsAdminPage_(e) {
  var t = HtmlService.createTemplateFromFile('NewsAdmin');
  var site = '';
  try { site = String(publicSiteUrl_() || '').replace(/results\/?$/, 'new/'); } catch (err) {}
  t.siteUrl = site;
  t.loginToken = String((e && e.parameter && e.parameter.login) || '').replace(/[^0-9a-f-]/gi, '').slice(0, 60);
  return t.evaluate().setTitle('ホームページ管理｜' + orgName_())
    .addMetaTag('viewport', 'width=device-width, initial-scale=1');
}

/** 最初に1回：連盟の合言葉を決める（変えるときも同じ） */
function setupNewsAdmin() {
  var ui;
  try { ui = SpreadsheetApp.getUi(); } catch (e) {
    throw new Error('スプレッドシートを開いて、メニューの「ホームページ管理画面の合言葉を決める」から実行してください');
  }
  var r = ui.prompt('ホームページ管理画面（連盟）の合言葉', '連盟の担当者が管理画面に入るための合言葉を決めてください（8文字以上）。', ui.ButtonSet.OK_CANCEL);
  if (r.getSelectedButton() !== ui.Button.OK) return;
  var p = String(r.getResponseText() || '');
  if (p.length < 8) { ui.alert('8文字以上にしてください'); return; }
  PropertiesService.getScriptProperties().setProperty(NADM.passKey, nadmHash_('連盟', p));
  if (typeof setupNewsSheets === 'function') { try { setupNewsSheets(); } catch (e) {} }
  var url = '';
  try { url = ScriptApp.getService().getUrl() + '?page=newsadmin'; } catch (e) {}
  ui.alert('合言葉を保存しました', '管理画面：' + (url || 'WebアプリのURL＋?page=newsadmin') +
    '\n\nクラブの合言葉は、管理画面の「クラブアカウント」から発行します。', ui.ButtonSet.OK);
}

// ─────────────────────── ログイン ───────────────────────

/** ログイン画面の選択肢（クラブ名は公開情報） */
function nadmLoginOptions() { return { univs: nadmUnivs_() }; }

function nadmLogin(who, pass) {
  who = String(who || '連盟');
  var cache = CacheService.getScriptCache(), fk = 'nadm:fails:' + nadmHash_('k', who).slice(0, 16);
  var fails = Number(cache.get(fk) || 0);
  if (fails >= NADM.maxFails) throw new Error('合言葉の入力に何度も失敗したため、10分ほど待ってからお試しください');
  Utilities.sleep(400);
  var ok = false;
  if (who === '連盟') {
    var h = PropertiesService.getScriptProperties().getProperty(NADM.passKey);
    if (!h) throw new Error('連盟の合言葉が設定されていません（setupNewsAdmin を実行してください）');
    ok = nadmHash_('連盟', String(pass || '')) === h;
  } else {
    var a = nadmAccounts_()[who];
    if (!a || !a.hash) throw new Error('このクラブのアカウントはまだ発行されていません。連盟にお問い合わせください');
    if (a.active === false) throw new Error('このクラブのアカウントは停止中です。連盟にお問い合わせください');
    ok = nadmHash_(who, String(pass || '')) === a.hash;
  }
  if (!ok) { cache.put(fk, String(fails + 1), NADM.lockSec); throw new Error('合言葉が違います'); }
  if (who !== '連盟') nadmTouch_(who);
  var sess = { role: who === '連盟' ? 'admin' : 'univ', univ: who === '連盟' ? '' : who, perm: who === '連盟' ? '' : 'lead', name: who };
  return nadmStartSession_(sess);
}

function nadmStartSession_(sess) {
  var token = Utilities.getUuid();
  CacheService.getScriptCache().put('nadm:t:' + token, JSON.stringify(sess), NADM.ttl);
  var T = nadmTables_(sess);
  return { token: token, who: sess.role === 'admin' ? '連盟' : sess.univ, name: sess.name || '', role: sess.role, perm: sess.perm || '',
    tables: Object.keys(T).map(function (k) { return { key: k, name: T[k].name, kind: T[k].kind || 'table' }; }) };
}

// ─────────────────────── メールのリンクでログイン ───────────────────────

/** ログイン用のリンクをメールで送る。登録の有無はわからないように、いつも同じ答えを返す */
function nadmSendLink(email) {
  email = nadmEmail_(email);
  if (!email) throw new Error('メールアドレスを正しく入れてください');
  var done = { ok: true, message: '登録されているアドレスなら、ログイン用のリンクを送りました。メールを開いて、15分以内にリンクを押してください（届かないときは迷惑メールのフォルダも見てください）。' };
  var cache = CacheService.getScriptCache(), rk = 'nadm:send:' + nadmHash_('k', email).slice(0, 16);
  if (cache.get(rk)) return done; // 同じアドレスへは1分に1回まで
  cache.put(rk, '1', 60);
  Utilities.sleep(300);
  var m = nadmMembers_()[email];
  if (!m || m.active === false) return done;
  var url = '';
  try { url = ScriptApp.getService().getUrl(); } catch (e) {}
  if (!url) throw new Error('管理画面のURLがわかりません（Webアプリとしてデプロイされているか確かめてください）');
  var tok = Utilities.getUuid();
  cache.put('nadm:link:' + tok, email, NADM.linkTtl);
  var link = url + '?page=newsadmin&login=' + tok;
  var roleName = m.role === 'pr' ? '広報担当' : '責任者';
  MailApp.sendEmail({
    to: email,
    subject: '【' + orgName_() + '】ホームページ管理画面のログイン',
    body: (m.name ? m.name + ' さん\n\n' : '') + 'ホームページ管理画面（' + m.univ + '・' + roleName + '）にログインするには、次のリンクを押してください。\n\n' + link +
      '\n\n・このリンクは15分間、1回だけ使えます。\n・心当たりがない場合は、このメールを消してください（何もしなければログインされません）。\n\n' + orgName_(),
    name: orgName_()
  });
  return done;
}

/** メールのリンクを押したとき：1回だけ使えるリンクを確かめてログイン */
function nadmLinkLogin(tok) {
  tok = String(tok || '').replace(/[^0-9a-f-]/gi, '');
  var cache = CacheService.getScriptCache(), key = 'nadm:link:' + tok;
  var email = tok ? cache.get(key) : null;
  if (!email) throw new Error('このリンクは使えません（15分を過ぎたか、すでに使われています）。もう一度メールアドレスを入れて、リンクを受け取ってください');
  cache.remove(key);
  var lock = LockService.getScriptLock(); lock.waitLock(20000);
  var m;
  try {
    var all = nadmMembers_(); m = all[email];
    if (!m || m.active === false) throw new Error('この担当者は登録されていないか、停止されています。クラブの責任者か連盟にお問い合わせください');
    m.last = Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm');
    nadmSaveMembers_(all);
  } finally { lock.releaseLock(); }
  return nadmStartSession_({ role: 'univ', univ: m.univ, perm: m.role === 'pr' ? 'pr' : 'lead', member: email, name: m.name || email });
}

// ─────────────────────── 担当者（メールアドレス・クラブ・役割） ───────────────────────

function nadmEmail_(v) { v = String(v || '').trim().toLowerCase(); return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v) && v.length <= 120 ? v : ''; }
function nadmMembers_() { try { return JSON.parse(PropertiesService.getScriptProperties().getProperty(NADM.memKey) || '{}'); } catch (e) { return {}; } }
function nadmSaveMembers_(m) { PropertiesService.getScriptProperties().setProperty(NADM.memKey, JSON.stringify(m)); }
function nadmWho_(sess) { return sess.role === 'admin' ? '連盟' : (sess.name || sess.univ) + (sess.member ? '' : '（合言葉）'); }
/** 担当者を管理できるか：連盟はすべて、クラブの責任者は自分のクラブの広報担当だけ */
function nadmCanManage_(sess, m) {
  if (sess.role === 'admin') return true;
  return sess.role === 'univ' && sess.perm === 'lead' && m.univ === sess.univ && m.role === 'pr';
}

function nadmMembersList(token) {
  var sess = nadmAuth_(token);
  if (sess.role !== 'admin' && sess.perm !== 'lead') throw new Error('責任者だけが使えます');
  var all = nadmMembers_();
  var rows = Object.keys(all).map(function (e) {
    var m = all[e];
    return { email: e, univ: m.univ, role: m.role === 'pr' ? 'pr' : 'lead', name: m.name || '', active: m.active !== false, added: m.added || '', last: m.last || '', can: nadmCanManage_(sess, m) };
  }).filter(function (r) { return sess.role === 'admin' || r.univ === sess.univ; })
    .sort(function (a, b) { return a.univ.localeCompare(b.univ, 'ja') || (a.role === b.role ? 0 : a.role === 'lead' ? -1 : 1) || a.email.localeCompare(b.email); });
  return { rows: rows, univs: sess.role === 'admin' ? nadmUnivs_() : [sess.univ], admin: sess.role === 'admin' };
}

/** 担当者を登録・変更（メールアドレスで1人）。クラブの責任者は、自分のクラブの広報担当だけ */
function nadmMemberSave(token, v) {
  var sess = nadmAuth_(token);
  var email = nadmEmail_(v && v.email);
  if (!email) throw new Error('メールアドレスを正しく入れてください');
  var m = { univ: String(v.univ || ''), role: v.role === 'lead' ? 'lead' : 'pr', name: String(v.name || '').trim().slice(0, 40) };
  if (sess.role !== 'admin') { m.univ = sess.univ; m.role = 'pr'; }
  if (nadmUnivs_().indexOf(m.univ) < 0) throw new Error('クラブを選んでください');
  var lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    var all = nadmMembers_(), cur = all[email];
    if (cur && !nadmCanManage_(sess, cur)) throw new Error('このアドレスは、ほかのクラブか責任者として登録されています。連盟にお問い合わせください');
    if (!nadmCanManage_(sess, m)) throw new Error('この担当者は登録できません');
    if (!cur && Object.keys(all).filter(function (e) { return all[e].univ === m.univ; }).length >= 20) throw new Error('1つのクラブに登録できるのは20人までです');
    all[email] = { univ: m.univ, role: m.role, name: m.name, active: cur ? cur.active !== false : true, added: (cur && cur.added) || nadmToday_(), last: (cur && cur.last) || '', by: nadmWho_(sess) };
    nadmSaveMembers_(all);
  } finally { lock.releaseLock(); }
  return { ok: true };
}

function nadmMemberActive(token, email, on) {
  var sess = nadmAuth_(token);
  email = nadmEmail_(email);
  var lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    var all = nadmMembers_(), m = all[email];
    if (!m || !nadmCanManage_(sess, m)) throw new Error('この担当者は変更できません');
    m.active = !!on; nadmSaveMembers_(all);
  } finally { lock.releaseLock(); }
  return { ok: true };
}

function nadmMemberRemove(token, email) {
  var sess = nadmAuth_(token);
  email = nadmEmail_(email);
  var lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    var all = nadmMembers_(), m = all[email];
    if (!m || !nadmCanManage_(sess, m)) throw new Error('この担当者は削除できません');
    delete all[email]; nadmSaveMembers_(all);
  } finally { lock.releaseLock(); }
  return { ok: true };
}


function nadmLogout(token) { CacheService.getScriptCache().remove('nadm:t:' + token); return true; }

